INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-1', 0, 'Chào hỏi & xưng hô', '[{"hanzi":"你","pinyin":"nǐ","hanViet":"NỄ","meaning":"bạn, anh/chị","pos":"Đại từ","example":{"zh":"你好。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chào bạn."}},{"hanzi":"你们","pinyin":"nǐmen","hanViet":"NỄ MÔN","meaning":"các bạn","pos":"Đại từ","example":{"zh":"你们好。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"们","py":"men"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chào các bạn."}},{"hanzi":"您","pinyin":"nín","hanViet":"NÂM","meaning":"anh/chị (xưng hô lịch sự)","pos":"Đại từ","example":{"zh":"您好。","pinyinPerChar":[{"c":"您","py":"nín"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chào anh/chị."}},{"hanzi":"我","pinyin":"wǒ","hanViet":"NGÃ","meaning":"tôi","pos":"Đại từ","example":{"zh":"我是我。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Tôi là tôi."}},{"hanzi":"我们","pinyin":"wǒmen","hanViet":"NGÃ MÔN","meaning":"chúng tôi","pos":"Danh từ","example":{"zh":"我们是朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"是","py":"shì"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Chúng tôi là bạn bè."}},{"hanzi":"他","pinyin":"tā","hanViet":"THA","meaning":"cậu ấy, anh ấy","pos":"Đại từ","example":{"zh":"他是学生。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Anh ấy là học sinh."}},{"hanzi":"他们","pinyin":"tāmen","hanViet":"THA MÔN","meaning":"họ, những người","pos":"Đại từ","example":{"zh":"他们是老师。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Họ là giáo viên."}},{"hanzi":"她","pinyin":"tā","hanViet":"THA","meaning":"cô ấy","pos":"Đại từ","example":{"zh":"她是学生。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Cô ấy là học sinh."}},{"hanzi":"她们","pinyin":"tāmen","hanViet":"THA MÔN","meaning":"họ (các cô gái/các cô)","pos":"Đại từ","example":{"zh":"她们是学生。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"们","py":"men"},{"c":"是","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Họ là học sinh."}},{"hanzi":"先生","pinyin":"xiānsheng","hanViet":"TIÊN SINH","meaning":"ông","pos":"Danh từ","example":{"zh":"我是先生。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"是","py":"shì"},{"c":"先","py":"xiān"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Tôi là ông."}},{"hanzi":"小姐","pinyin":"xiǎojiě","hanViet":"TIỂU TỶ","meaning":"cô gái, cô","pos":"Danh từ","example":{"zh":"这个小姐很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"姐","py":"jiě"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Cô gái này rất xinh đẹp."}},{"hanzi":"名字","pinyin":"míngzi","hanViet":"DANH TỰ","meaning":"tên","pos":"Danh từ","example":{"zh":"你的名字是什么？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"名","py":"míng"},{"c":"字","py":"zì"},{"c":"是","py":"shì"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"？","py":"？"}],"vi":"Tên của bạn là gì?"}},{"hanzi":"叫","pinyin":"jiào","hanViet":"KHIẾU","meaning":"gọi, tên","pos":"Động từ","example":{"zh":"你叫什么名字？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"叫","py":"jiào"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"名","py":"míng"},{"c":"字","py":"zì"},{"c":"？","py":"？"}],"vi":"Bạn gọi tên là gì?"}},{"hanzi":"吧","pinyin":"ba","hanViet":"BA","meaning":"phó từ đề nghị","pos":"Phó từ","example":{"zh":"我们走吧。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"走","py":"zǒu"},{"c":"吧","py":"ba"},{"c":"。","py":"。"}],"vi":"Chúng ta đi thôi."}},{"hanzi":"吗","pinyin":"ma","hanViet":"MA","meaning":"phó từ đặt sau câu hỏi","pos":"Phó từ","example":{"zh":"你好吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"好","py":"hǎo"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn có khỏe không?"}},{"hanzi":"呢","pinyin":"ne","hanViet":"NI","meaning":"vấn đề, câu hỏi ngắn","pos":"Phó từ","example":{"zh":"你呢？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"呢","py":"ne"},{"c":"？","py":"？"}],"vi":"Cậu ấy thì sao?"}},{"hanzi":"请","pinyin":"qǐng","hanViet":"THỈNH","meaning":"Mời, xin","pos":"Động từ","example":{"zh":"请我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Mời tôi."}},{"hanzi":"请进","pinyin":"qǐng jìn","hanViet":"THỈNH TIẾN","meaning":"Mời vào","pos":"Cụm từ","example":{"zh":"请进。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"进","py":"jìn"},{"c":"。","py":"。"}],"vi":"Mời vào."}},{"hanzi":"请坐","pinyin":"qǐng zuò","hanViet":"THỈNH TOẠ","meaning":"Mời ngồi","pos":"Cụm từ","example":{"zh":"请坐。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"坐","py":"zuò"},{"c":"。","py":"。"}],"vi":"Mời ngồi."}},{"hanzi":"请问","pinyin":"qǐngwèn","hanViet":"THỈNH VẤN","meaning":"Xin hỏi","pos":"Cụm từ","example":{"zh":"请问你好。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"问","py":"wèn"},{"c":"你","py":"nǐ"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Xin hỏi bạn khỏe không."}},{"hanzi":"不客气","pinyin":"bù kèqì","hanViet":"BẤT KHÁCH KHÍ","meaning":"không sao, không cần xấu hổ","pos":"Phó từ","example":{"zh":"你别客气。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"别","py":"bié"},{"c":"客","py":"kè"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Bạn đừng xấu hổ."}},{"hanzi":"对不起","pinyin":"duìbuqǐ","hanViet":"ĐỐI BẤT KHỞI","meaning":"xin lỗi","pos":"Thán từ","example":{"zh":"对不起。","pinyinPerChar":[{"c":"对","py":"duì"},{"c":"不","py":"bù"},{"c":"起","py":"qǐ"},{"c":"。","py":"。"}],"vi":"Xin lỗi."}},{"hanzi":"没关系","pinyin":"méi guānxi","hanViet":"MỘT QUAN HỆ","meaning":"không sao, không vấn đề","pos":"Cụm từ","example":{"zh":"没关系。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"关","py":"guān"},{"c":"系","py":"xì"},{"c":"。","py":"。"}],"vi":"Không sao."}},{"hanzi":"没什么","pinyin":"méi shénme","hanViet":"MỘT THẬM MA","meaning":"không có gì, không nhiều","pos":"Cụm từ","example":{"zh":"没什么。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"。","py":"。"}],"vi":"Không có gì."}},{"hanzi":"再见","pinyin":"zàijiàn","hanViet":"TÁI KIẾN","meaning":"tạm biệt","pos":"Liên từ","example":{"zh":"再见！","pinyinPerChar":[{"c":"再","py":"zài"},{"c":"见","py":"jiàn"},{"c":"！","py":"！"}],"vi":"Tạm biệt!"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-2', 1, 'Chào hỏi & xưng hô & Đại từ & từ để hỏi', '[{"hanzi":"介绍","pinyin":"jièshào","hanViet":"GIỚI THIỆU","meaning":"giới thiệu","pos":"Động từ","example":{"zh":"请介绍你自己。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"介","py":"jiè"},{"c":"绍","py":"shào"},{"c":"你","py":"nǐ"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"。","py":"。"}],"vi":"Xin hãy giới thiệu bản thân bạn."}},{"hanzi":"开玩笑","pinyin":"kāi wánxiào","hanViet":"KHAI NGOẠN TIẾU","meaning":"nói đùa","pos":"Cụm từ","example":{"zh":"他开玩笑。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"开","py":"kāi"},{"c":"玩","py":"wán"},{"c":"笑","py":"xiào"},{"c":"。","py":"。"}],"vi":"Anh ấy nói đùa."}},{"hanzi":"谁","pinyin":"shéi/shuí","hanViet":"THUỲ","meaning":"ai","pos":"Đại từ","example":{"zh":"谁是老师？","pinyinPerChar":[{"c":"谁","py":"shuí"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"？","py":"？"}],"vi":"Ai là giáo viên?"}},{"hanzi":"什么","pinyin":"shénme","hanViet":"THẬM MA","meaning":"gì","pos":"Đại từ","example":{"zh":"你什么时候回家？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"时","py":"shí"},{"c":"候","py":"hòu"},{"c":"回","py":"huí"},{"c":"家","py":"jiā"},{"c":"？","py":"？"}],"vi":"Bạn vào lúc nào về nhà?"}},{"hanzi":"哪","pinyin":"nǎ","hanViet":"NẢ","meaning":"nào","pos":"Đại từ","example":{"zh":"你去哪里？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"去","py":"qù"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Bạn đi đâu?"}},{"hanzi":"哪儿","pinyin":"nǎr","hanViet":"NẢ NHI","meaning":"đâu","pos":"Đại từ","example":{"zh":"你在哪儿？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"儿","py":"ér"},{"c":"？","py":"？"}],"vi":"Bạn ở đâu?"}},{"hanzi":"哪里","pinyin":"nǎlǐ","hanViet":"NẢ LÝ","meaning":"đâu","pos":"Đại từ","example":{"zh":"你在哪里？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Bạn ở đâu?"}},{"hanzi":"哪些","pinyin":"nǎxiē","hanViet":"NẢ TA","meaning":"những cái nào","pos":"Đại từ","example":{"zh":"你喜欢哪些水果？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"哪","py":"nǎ"},{"c":"些","py":"xiē"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"？","py":"？"}],"vi":"Bạn thích loại trái cây nào?"}},{"hanzi":"那","pinyin":"nà","hanViet":"NA","meaning":"đó","pos":"Đại từ","example":{"zh":"那是书。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"是","py":"shì"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Đó là sách."}},{"hanzi":"这","pinyin":"zhè","hanViet":"GIÁ","meaning":"đây, này","pos":"Đại từ","example":{"zh":"这本书很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cuốn sách này rất tốt."}},{"hanzi":"那边","pinyin":"nàbiān","hanViet":"NA BIÊN","meaning":"khu bên đó","pos":"Danh từ","example":{"zh":"我在那边。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"那","py":"nà"},{"c":"边","py":"biān"},{"c":"。","py":"。"}],"vi":"Tôi ở bên kia."}},{"hanzi":"这边","pinyin":"zhèbiān","hanViet":"GIÁ BIÊN","meaning":"bên này","pos":"Danh từ","example":{"zh":"请到这边来。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"到","py":"dào"},{"c":"这","py":"zhè"},{"c":"边","py":"biān"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Hãy đến bên này."}},{"hanzi":"那里","pinyin":"nàlǐ","hanViet":"NA LÝ","meaning":"khu ở đó","pos":"Danh từ","example":{"zh":"我在那里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"那","py":"nà"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi ở đấy."}},{"hanzi":"这里","pinyin":"zhèlǐ","hanViet":"GIÁ LÝ","meaning":"đây, chỗ này","pos":"Danh từ","example":{"zh":"我在这里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi ở đây."}},{"hanzi":"那儿","pinyin":"nàr","hanViet":"NA NHI","meaning":"khu ở đó","pos":"Đại từ","example":{"zh":"我在那儿。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"那","py":"nà"},{"c":"儿","py":"ér"},{"c":"。","py":"。"}],"vi":"Tôi ở đấy."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-3', 2, 'Đại từ & từ để hỏi & Gia đình & con người', '[{"hanzi":"那些","pinyin":"nàxiē","hanViet":"NA TA","meaning":"những cái đó","pos":"Đại từ","example":{"zh":"那些是我的。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"些","py":"xiē"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Đó là của tôi."}},{"hanzi":"这些","pinyin":"zhèxiē","hanViet":"GIÁ TA","meaning":"những cái này","pos":"Đại từ","example":{"zh":"这些是我的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"些","py":"xiē"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Đây là của tôi."}},{"hanzi":"爸爸|爸","pinyin":"bàba|bà","hanViet":"BA BA  BA","meaning":"cha","pos":"Danh từ","example":{"zh":"我爸爸很忙。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"爸","py":"bà"},{"c":"爸","py":"bà"},{"c":"很","py":"hěn"},{"c":"忙","py":"máng"},{"c":"。","py":"。"}],"vi":"Tôi cha rất bận."}},{"hanzi":"妈妈|妈","pinyin":"māma|mā","hanViet":"MÁ MÁ  MÁ","meaning":"mẹ","pos":"Danh từ","example":{"zh":"我的妈妈很好。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"妈","py":"mā"},{"c":"妈","py":"mā"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Mẹ tôi rất tốt."}},{"hanzi":"哥哥|哥","pinyin":"gēge|gē","hanViet":"CA CA  CA","meaning":"anh, cậu, anh trai","pos":"Đại từ","example":{"zh":"我哥哥很高。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"哥","py":"gē"},{"c":"哥","py":"gē"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Anh trai tôi rất cao."}},{"hanzi":"姐姐|姐","pinyin":"jiějie|jiě","hanViet":"TỶ TỶ  TỶ","meaning":"chị","pos":"Danh từ","example":{"zh":"我有一个姐姐。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"姐","py":"jiě"},{"c":"姐","py":"jiě"},{"c":"。","py":"。"}],"vi":"Tôi có một chị."}},{"hanzi":"弟弟|弟","pinyin":"dìdi|dì","hanViet":"ĐỆ ĐỆ  ĐỆ","meaning":"em trai","pos":"Danh từ","example":{"zh":"我