INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-5', 4, 'Số & lượng từ', '[{"hanzi":"一","pinyin":"yī","hanViet":"NHẤT","meaning":"một","pos":"Số từ","example":{"zh":"我有一个苹果。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Tôi có một quả táo."}},{"hanzi":"二","pinyin":"èr","hanViet":"NHỊ","meaning":"hai","pos":"Số từ","example":{"zh":"我有二个朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"二","py":"èr"},{"c":"个","py":"gè"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi có hai người bạn."}},{"hanzi":"三","pinyin":"sān","hanViet":"TAM","meaning":"số 3","pos":"Số từ","example":{"zh":"他有三本书。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"三","py":"sān"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Anh ấy có ba quyển sách."}},{"hanzi":"四","pinyin":"sì","hanViet":"TỨ","meaning":"bốn","pos":"Số từ","example":{"zh":"我有四本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"四","py":"sì"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi có bốn cuốn sách."}},{"hanzi":"五","pinyin":"wǔ","hanViet":"NGŨ","meaning":"năm","pos":"Số từ","example":{"zh":"我有五本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"五","py":"wǔ"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi có năm quyển sách."}},{"hanzi":"六","pinyin":"liù","hanViet":"LỤC","meaning":"sáu","pos":"Số từ","example":{"zh":"六个人。","pinyinPerChar":[{"c":"六","py":"liù"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Sáu người."}},{"hanzi":"七","pinyin":"qī","hanViet":"THẤT","meaning":"Số 7","pos":"Số từ","example":{"zh":"七个人。","pinyinPerChar":[{"c":"七","py":"qī"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Bảy người."}},{"hanzi":"八","pinyin":"bā","hanViet":"BÁT","meaning