INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-7', 6, 'Thời gian', '[{"hanzi":"上午","pinyin":"shàngwǔ","hanViet":"THƯỢNG NGỌ","meaning":"buổi sáng, từ 6 giờ sáng đến 12 giờ trưa","pos":"Danh từ","example":{"zh":"我上午学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"上","py":"shàng"},{"c":"午","py":"wǔ"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Tôi học vào buổi sáng."}},{"hanzi":"下午","pinyin":"xiàwǔ","hanViet":"HẠ NGỌ","meaning":"chiều","pos":"Danh từ","example":{"zh":"我下午去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"下","py":"xià"},{"c":"午","py":"wǔ"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi trường học vào chiều."}},{"hanzi":"晚上","pinyin":"wǎnshang","hanViet":"VÃN THƯỢNG","meaning":"đêm","pos":"Danh từ","example":{"zh":"我晚上去。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"晚","py":"wǎn"},{"c":"上","py":"shàng"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Tôi đi đêm."}},{"hanzi":"中午","pinyin":"zhōngwǔ","hanViet":"TRUNG NGỌ","meaning":"trưa, giữa ngày","pos":"Danh từ","example":{"zh":"我中午吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"中","py":"zhōng"},{"c":"午","py":"wǔ"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi ăn trưa."}},{"hanzi":"早上","pinyin":"zǎoshang","hanViet":"TẢO THƯỢNG","meaning":"buổi sáng","pos":"Danh từ","example":{"zh":"我早上去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"早","py":"zǎo"},{"c":"上","py":"shàng"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi trường lúc sáng."}},{"hanzi":"早","pinyin":"zǎo","hanViet":"TẢO","meaning":"sớm, buổi sáng","pos":"Tính từ","example":{"zh":"我早起。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"早","py":"zǎo"},{"c":"起","py":"qǐ"},{"c":"。","py":"。"}],"vi":"Tôi dậy sớm."}},{"hanzi":"晚","pinyin":"wǎn","hanViet":"VÃN","meaning":"đêm, muộn","pos":"Tính từ","example":{"zh":"晚上。","pinyinPerChar":[{"c":"晚","py":"wǎn"},{"c":"上","py":"s