INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-9', 8, 'Học tập & trường lớp (phần 2)', '[{"hanzi":"小学","pinyin":"xiǎoxué","hanViet":"TIỂU HỌC","meaning":"trường tiểu học","pos":"Danh từ","example":{"zh":"我去小学。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"小","py":"xiǎo"},{"c":"学","py":"xué"},{"c":"。","py":"。"}],"vi":"Tôi đi đến trường tiểu học."}},{"hanzi":"考","pinyin":"kǎo","hanViet":"KHẢO","meaning":"thi, kiểm tra","pos":"Động từ","example":{"zh":"我考试。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"。","py":"。"}],"vi":"Tôi thi."}},{"hanzi":"试","pinyin":"shì","hanViet":"THÍ","meaning":"thử, thí","pos":"Động từ","example":{"zh":"我试一下。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"试","py":"shì"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Tôi thử một lần."}},{"hanzi":"考试","pinyin":"kǎoshì","hanViet":"KHẢO THÍ","meaning":"kiểm tra, thi","pos":"Danh từ","example":{"zh":"考试很难。","pinyinPerChar":[{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"很","py":"hěn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Kiểm tra rất khó."}},{"hanzi":"上课","pinyin":"shàngkè","hanViet":"THƯỢNG KHOÁ","meaning":"đi học, bắt đầu lớp","pos":"Động từ","example":{"zh":"我上课。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"上","py":"shàng"},{"c":"课","py":"kè"},{"c":"。","py":"。"}],"vi":"Tôi đi học."}},{"hanzi":"下课","pinyin":"xiàkè","hanViet":"HẠ KHOÁ","meaning":"kết thúc giờ học","pos":"Động từ","example":{"zh":"老师下课。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"下","py":"xià"},{"c":"课","py":"kè"},{"c":"。","py":"。"}],"vi":"Thầy giáo kết thúc giờ học."}},{"hanzi":"上学","pinyin":"shàngxué","hanViet":"THƯỢNG HỌC","meaning":"đi học","pos":"Động từ","example":{"zh":"他上学去。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"上","py":"shàng"},{"c":"学","py":"xué"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Anh ấy đi học."}},{"hanzi":"放学","pinyin":"fàngxué","hanViet":"PHÓNG HỌC","meaning":"chết học, kết thúc giờ học","pos":"Động từ","example":{"zh":"老师放学了。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"放","py":"fàng"},{"c":"学","py":"xué"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Thầy giáo đã chết học."}},{"hanzi":"班","pinyin":"bān","hanViet":"BAN","meaning":"lớp, nhóm","pos":"Danh từ","example":{"zh":"我班有二十个人。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"班","py":"bān"},{"c":"有","py":"yǒu"},{"c":"二","py":"èr"},{"c":"十","py":"shí"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Lớp tôi có hai mươi người."}},{"hanzi":"知识","pinyin":"zhīshi","hanViet":"TRI THỨC","meaning":"kiến thức, tri thức","pos":"Danh từ","example":{"zh":"我学知识。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"学","py":"xué"},{"c":"知","py":"zhī"},{"c":"识","py":"shí"},{"c":"。","py":"。"}],"vi":"Tôi học kiến thức."}},{"hanzi":"图书馆","pinyin":"túshūguǎn","hanViet":"ĐỒ THƯ QUÁN","meaning":"thư viện","pos":"Danh từ","example":{"zh":"我去图书馆。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"图","py":"tú"},{"c":"书","py":"shū"},{"c":"馆","py":"guǎn"},{"c":"。","py":"。"}],"vi":"Tôi đi thư viện."}},{"hanzi":"教学楼","pinyin":"jiàoxuélóu","hanViet":"GIÁO HỌC LÂU","meaning":"tòa nhà học tập, tòa nhà lớp học","pos":"Danh từ","example":{"zh":"我在教学楼上课。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"教","py":"jiào"},{"c":"学","py":"xué"},{"c":"楼","py":"lóu"},{"c":"上","py":"shàng"},{"c":"课","py":"kè"},{"c":"。","py":"。"}],"vi":"Tôi học bài ở tòa nhà lớp học."}},{"hanzi":"忘","pinyin":"wàng","hanViet":"VONG","meaning":"quên","pos":"Động từ","example":{"zh":"我忘。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"忘","py":"wàng"},{"c":"。","py":"。"}],"vi":"Tôi quên."}},{"hanzi":"忘记","pinyin":"wàngjì","hanViet":"VONG KÝ","meaning":"quên","pos":"Động từ","example":{"zh":"我忘记。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"忘","py":"wàng"},{"c":"记","py":"jì"},{"c":"。","py":"。"}],"vi":"Tôi quên."}},{"hanzi":"记","pinyin":"jì","hanViet":"KÝ","meaning":"gh