INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-21', 20, 'Từ nối & ngữ pháp', '[{"hanzi":"从","pinyin":"cóng","hanViet":"TÒNG","meaning":"từ","pos":"Đại từ","example":{"zh":"我从学校来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"从","py":"cóng"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi đến từ trường."}},{"hanzi":"跟","pinyin":"gēn","hanViet":"CÂN","meaning":"với, cùng với, theo","pos":"Động từ","example":{"zh":"我跟朋友去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"跟","py":"gēn"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi cùng bạn đến trường."}},{"hanzi":"和","pinyin":"hé","hanViet":"HOÀ","meaning":"Kết hợp, cùng với","pos":"Liên từ","example":{"zh":"我和朋友去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"和","py":"hé"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi và bạn đi đến trường."}},{"hanzi":"给","pinyin":"gěi","hanViet":"CẤP","meaning":"tặng, cho, dành cho","pos":"Động từ","example":{"zh":"我给你一本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"给","py":"gěi"},{"c":"你","py":"nǐ"},{"c":"一","py":"yī"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi tặng cho bạn một quyển sách."}},{"hanzi":"了","pinyin":"le","hanViet":"LIỄU","meaning":"kết thúc, hoàn thành, biểu hiện thay đổi","pos":"Phó từ","example":{"zh":"我吃了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"吃","py":"chī"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tôi đã ăn xong."}},{"hanzi":"的","pinyin":"de","hanViet":"ĐÍCH","meaning":"mạo từ chỉ sở hữu, chỉ thuộc tính","pos":"Trợ từ","example":{"zh":"这是我的书。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Đây là cuốn sách của tôi."}},{"hanzi":"过","pinyin":"guò","hanViet":"QUÁ","meaning":"qua, đã (trong thời gian)","pos":"Động từ","example":{"zh":"我去过中国。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"过","py":"guò"},{"c":"中","py":"zhōng"},{"c":"国","py":"guó"},{"c":"。","py":"。"}],"vi":"Tôi đã đi Trung Quốc."}},{"hanzi":"着","pinyin":"zhe","hanViet":"TRỨ","meaning":"thể hoàn thành, đang","pos":"Phó từ","example":{"zh":"他穿着红衣服。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"穿","py":"chuān"},{"c":"着","py":"zhe"},{"c":"红","py":"hóng"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"。","py":"。"}],"vi":"Anh ấy mặc áo đỏ."}},{"hanzi":"是","pinyin":"shì","hanViet":"THỊ","meaning":"là","pos":"Động từ","example":{"zh":"我是学生。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"是","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Tôi là học sinh."}},{"hanzi":"是不是","pinyin":"shì bu shì","hanViet":"THỊ BẤT THỊ","meaning":"có phải không, đúng không","pos":"Liên từ","example":{"zh":"这是不是你的书？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"不","py":"bù"},{"c":"是","py":"shì"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"书","py":"shū"},{"c":"？","py":"？"}],"vi":"Đây có phải là cuốn sách của bạn không?"}},{"hanzi":"不","pinyin":"bù","hanViet":"BẤT","meaning":"không, chẳng","pos":"Phó từ","example":{"zh":"我不吃。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Tôi không ăn."}},{"hanzi":"没","pinyin":"méi","hanViet":"MỘT","meaning":"không, chẳng, chưa","pos":"Phó từ","example":{"zh":"我没去。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"没","py":"méi"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Tôi không đi."}},{"hanzi":"没有","pinyin":"méiyǒu","hanViet":"MỘT HỮU","meaning":"không có, chưa","pos":"Động từ","example":{"zh":"我没有书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi không có sách."}},{"hanzi":"别","pinyin":"bié","hanViet":"BIỆT","meaning":"đừng, tránh","pos":"Động từ","example":{"zh":"别走。","pinyinPerChar":[{"c":"别","py":"bié"},{"c":"走","py":"zǒu"},{"c":"。","py":"。"}],"vi":"Đừng đi."}},{"hanzi":"会","pinyin":"huì","hanViet":"HỘI","meaning":"Sẽ, biết làm được","pos":"Động từ","example":{"zh":"我会说中文。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"会","py":"huì"},{"c":"说","py":"shuō"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"。","py":"。"}],"vi":"Tôi sẽ nói tiếng Trung."}},{"hanzi":"能","pinyin":"néng","hanViet":"NĂNG","meaning":"có thể, đủ điều kiện","pos":"Động từ","example":{"zh":"我能吃。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"能","py":"néng"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Tôi có thể ăn."}},{"hanzi":"要","pinyin":"yào","hanViet":"YẾU","meaning":"cần, phải","pos":"Động từ","example":{"zh":"我要水。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Tôi cần nước."}},{"hanzi":"想","pinyin":"xiǎng","hanViet":"TƯỞNG","meaning":"muốn","pos":"Động từ","example":{"zh":"我想书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi muốn sách."}},{"hanzi":"怎么","pinyin":"zěnme","hanViet":"CHẨM MA","meaning":"thế nào, làm sao","pos":"Liên từ","example":{"zh":"你怎么去？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"去","py":"qù"},{"c":"？","py":"？"}],"vi":"Bạn đi thế nào?"}},{"hanzi":"干什么","pinyin":"gàn shénme","hanViet":"CÁN THẬM MA","meaning":"làm gì","pos":"Động từ","example":{"zh":"你干什么？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"干","py":"gàn"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"？","py":"？"}],"vi":"Bạn làm gì?"}},{"hanzi":"正","pinyin":"zhèng","hanViet":"CHÍNH","meaning":"đang, đúng","pos":"Tính từ","example":{"zh":"我正吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"正","py":"zhèng"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi đang ăn cơm."}},{"hanzi":"正在","pinyin":"zhèngzài","hanViet":"CHÍNH TẠI","meaning":"đang, đang làm","pos":"Tính từ","example":{"zh":"他正在看书。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"看","py":"kàn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Anh ấy đang đọc sách."}},{"hanzi":"在","pinyin":"zài","hanViet":"TẠI","meaning":"ở, có mặt","pos":"Động từ","example":{"zh":"我在家。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Tôi ở nhà."}},{"hanzi":"还有","pinyin":"hái yǒu","hanViet":"HOÀN HỮU","meaning":"vẫn còn, và có thêm","pos":"Liên từ","example":{"zh":"我还有书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"还","py":"hái"},{"c":"有","py":"yǒu"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi vẫn còn sách."}},{"hanzi":"不用","pinyin":"bùyòng","hanViet":"BẤT DỤNG","meaning":"không cần, không phải","pos":"Động từ","example":{"zh":"不用谢。","pinyinPerChar":[{"c":"不","py":"bù"},{"c":"用","py":"yòng"},{"c":"谢","py":"xiè"},{"c":"。","py":"。"}],"vi":"Không cần cám ơn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-22', 21, 'Từ nối & ngữ pháp & Động từ & hoạt động thường ngày', '[{"hanzi":"不大","pinyin":"bù dà","hanViet":"BẤT ĐẠI","meaning":"không lớn, không nhiều","pos":"Tính từ","example":{"zh":"他不大。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Cậu ấy không lớn."}},{"hanzi":"行","pinyin":"xíng","hanViet":"HÀNH","meaning":"được, ổn","pos":"Tính từ","example":{"zh":"这可以行。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Điều này được."}},{"hanzi":"帮","pinyin":"bāng","hanViet":"BANG","meaning":"giúp đỡ","pos":"Động từ","example":{"zh":"我帮你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"帮","py":"bāng"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi giúp bạn."}},{"hanzi":"帮忙","pinyin":"bāngmáng","hanViet":"BANG MANG","meaning":"cứu giúp","pos":"Động từ","example":{"zh":"你帮我一下。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"帮","py":"bāng"},{"c":"我","py":"wǒ"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Bạn giúp tôi một chút."}},{"hanzi":"出去","pinyin":"chūqù","hanViet":"XUẤT KHỨ","meaning":"đi ra ngoài","pos":"Động từ","example":{"zh":"我们出去。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"出","py":"chū"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi ra ngoài."}},{"hanzi":"穿","pinyin":"chuān","hanViet":"XUYÊN","meaning":"mặc","pos":"Động từ","example":{"zh":"我穿衣服。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"穿","py":"chuān"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"。","py":"。"}],"vi":"Tôi mặc quần áo."}},{"hanzi":"打","pinyin":"dǎ","hanViet":"ĐẢ","meaning":"đánh, làm","pos":"Động từ","example":{"zh":"我打球。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"打","py":"dǎ"},{"c":"球","py":"qiú"},{"c":"。","py":"。"}],"vi":"Tôi chơi bóng."}},{"hanzi":"打开","pinyin":"dǎkāi","hanViet":"ĐẢ KHAI","meaning":"mở","pos":"Động từ","example":{"zh":"我打开门。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"打","py":"dǎ"},{"c":"开","py":"kāi"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Tôi mở cửa."}},{"hanzi":"放","pinyin":"fàng","hanViet":"PHÓNG","meaning":"đặt, để, thả","pos":"Động từ","example":{"zh":"我放书在桌子上。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"放","py":"fàng"},{"c":"书","py":"shū"},{"c":"在","py":"zài"},{"c":"桌","py":"zhuō"},{"c":"子","py":"zi"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Tôi để sách trên bàn."}},{"hanzi":"关","pinyin":"guān","hanViet":"QUAN","meaning":"mở, đóng, quan tâm","pos":"Động từ","example":{"zh":"请关门。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"关","py":"guān"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Xin đóng cửa."}},{"hanzi":"关上","pinyin":"guānshang","hanViet":"QUAN THƯỢNG","meaning":"đóng (cửa, cửa sổ...)","pos":"Động từ","example":{"zh":"请关上门。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"关","py":"guān"},{"c":"上","py":"shàng"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Xin đóng cửa."}},{"hanzi":"回","pinyin":"huí","hanViet":"HỒI","meaning":"Quay lại, trở lại","pos":"Động từ","example":{"zh":"我要回家。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"回","py":"huí"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Tôi muốn về nhà."}},{"hanzi":"回到","pinyin":"huídào","hanViet":"HỒI ĐÁO","meaning":"Quay trở lại","pos":"Động từ","example":{"zh":"我们回到家。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"回","py":"huí"},{"c":"到","py":"dào"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Chúng tôi quay về nhà."}},{"hanzi":"回家","pinyin":"huí jiā","hanViet":"HỒI GIA","meaning":"Về nhà","pos":"Động từ","example":{"zh":"我回家吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"回","py":"huí"},{"c":"家","py":"jiā"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi về nhà ăn cơm."}},{"hanzi":"回来","pinyin":"huílái","hanViet":"HỒI LAI","meaning":"Trở về, đến lại","pos":"Động từ","example":{"zh":"他回来了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"回","py":"huí"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cậu ấy đã trở về."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-23', 22, 'Động từ & hoạt động thường ngày', '[{"hanzi":"回去","pinyin":"huíqù","hanViet":"HỒI KHỨ","meaning":"Đi lại, trở về","pos":"Động từ","example":{"zh":"我回去看看。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"回","py":"huí"},{"c":"去","py":"qù"},{"c":"看","py":"kàn"},{"c":"看","py":"kàn"},{"c":"。","py":"。"}],"vi":"Tôi đi lại xem."}},{"hanzi":"开","pinyin":"kāi","hanViet":"KHAI","meaning":"mở, khởi động","pos":"Động từ","example":{"zh":"开车。","pinyinPerChar":[{"c":"开","py":"kāi"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Lái xe."}},{"hanzi":"来","pinyin":"lái","hanViet":"LAI","meaning":"đến, đến, đến từ","pos":"Động từ","example":{"zh":"你来吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"来","py":"lái"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn có đến không?"}},{"hanzi":"来到","pinyin":"láidào","hanViet":"LAI ĐÁO","meaning":"đến, đến chỗ","pos":"Động từ","example":{"zh":"他来到学校。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"来","py":"lái"},{"c":"到","py":"dào"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Anh ấy đến trường."}},{"hanzi":"起","pinyin":"qǐ","hanViet":"KHỞI","meaning":"Bắt đầu, dậy","pos":"Động từ","example":{"zh":"起床。","pinyinPerChar":[{"c":"起","py":"qǐ"},{"c":"床","py":"chuáng"},{"c":"。","py":"。"}],"vi":"Dậy."}},{"hanzi":"起床","pinyin":"qǐchuáng","hanViet":"KHỞI SÀNG","meaning":"Dậy","pos":"Cụm từ","example":{"zh":"我起床。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"起","py":"qǐ"},{"c":"床","py":"chuáng"},{"c":"。","py":"。"}],"vi":"Tôi dậy."}},{"hanzi":"起来","pinyin":"qǐlái","hanViet":"KHỞI LAI","meaning":"Bắt đầu, dậy","pos":"Động từ","example":{"zh":"我起来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"起","py":"qǐ"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi dậy."}},{"hanzi":"去","pinyin":"qù","hanViet":"KHỨ","meaning":"di chuyển đến nơi khác","pos":"Động từ","example":{"zh":"我去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":