INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-24', 23, 'Giao tiếp & suy nghĩ', '[{"hanzi":"说","pinyin":"shuō","hanViet":"THUYẾT","meaning":"nói","pos":"Động từ","example":{"zh":"我说中文。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"说","py":"shuō"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"。","py":"。"}],"vi":"Tôi nói tiếng Trung."}},{"hanzi":"说话","pinyin":"shuōhuà","hanViet":"THUYẾT THOẠI","meaning":"nói chuyện","pos":"Động từ","example":{"zh":"他们说话。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"说","py":"shuō"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Họ đang nói chuyện."}},{"hanzi":"问","pinyin":"wèn","hanViet":"VẤN","meaning":"hỏi","pos":"Động từ","example":{"zh":"我问。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"问","py":"wèn"},{"c":"。","py":"。"}],"vi":"Tôi hỏi."}},{"hanzi":"回答","pinyin":"huídá","hanViet":"HỒI ĐÁP","meaning":"Trả lời","pos":"Động từ","example":{"zh":"老师问问题，我回答。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"问","py":"wèn"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"回","py":"huí"},{"c":"答","py":"dá"},{"c":"。","py":"。"}],"vi":"Thầy giáo hỏi câu hỏi, tôi trả lời."}},{"hanzi":"见","pinyin":"jiàn","hanViet":"KIẾN","meaning":"gặp, xem","pos":"Động từ","example":{"zh":"我见你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"见","py":"jiàn"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi gặp bạn."}},{"hanzi":"见面","pinyin":"jiànmiàn","hanViet":"KIẾN DIỆN","meaning":"gặp mặt","pos":"Danh từ","example":{"zh":"我们明天见面。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"见","py":"jiàn"},{"c":"面","py":"miàn"},{"c":"。","py":"。"}],"vi":"Chúng ta gặp mặt vào ngày mai."}},{"hanzi":"告诉","pinyin":"gàosu","hanViet":"CÁO TỐ","meaning":"thông báo, nêu","pos":"Động từ","example":{"zh":"我告诉你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"告","py":"gào"},{"c":"诉","py":"sù"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi nói cho bạn."}},{"hanzi":"明白","pinyin":"míngbai","hanViet":"MINH BẠCH","meaning":"hiểu","pos":"Động từ","example":{"zh":"我明白。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"明","py":"míng"},{"c":"白","py":"bái"},{"c":"。","py":"。"}],"vi":"Tôi hiểu."}},{"hanzi":"知道","pinyin":"zhīdào","hanViet":"TRI ĐẠO","meaning":"biết, nắm bắt","pos":"Động từ","example":{"zh":"你知道吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn biết không?"}},{"hanzi":"认识","pinyin":"rènshi","hanViet":"NHẬN THỨC","meaning":"biết, quen","pos":"Động từ","example":{"zh":"我认识他。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"认","py":"rèn"},{"c":"识","py":"shí"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Tôi biết anh ấy."}},{"hanzi":"觉得","pinyin":"juéde","hanViet":"GIÁC ĐẮC","meaning":"có cảm giác, nghĩ","pos":"Động từ","example":{"zh":"我觉得好。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"觉","py":"jué"},{"c":"得","py":"dé"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Tôi thấy tốt."}},{"hanzi":"没事儿","pinyin":"méishìr","hanViet":"MỘT SỰ NHI","meaning":"không sao, không cần","pos":"Cụm từ","example":{"zh":"没事儿。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"事","py":"shì"},{"c":"儿","py":"ér"},{"c":"。","py":"。"}],"vi":"Không sao."}},{"hanzi":"谢谢","pinyin":"xièxie","hanViet":"TẠ TẠ","meaning":"cảm ơn","pos":"Phó từ","example":{"zh":"谢谢你。","pinyinPerChar":[{"c":"谢","py":"xiè"},{"c":"谢","py":"xiè"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Cảm ơn bạn."}},{"hanzi":"别的","pinyin":"biéde","hanViet":"BIỆT ĐÍCH","meaning":"khác, những thứ khác","pos":"Danh từ","example":{"zh":"我要别的。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"别","py":"bié"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Tôi muốn cái khác."}},{"hanzi":"别人","pinyin":"biérén","hanViet":"BIỆT NHÂN","meaning":"người khác","pos":"Danh từ","example":{"zh":"别人来了。","pinyinPerChar":[{"c":"别","py":"bié"},{"c":"人","py":"rén"},{"c":"来","p