INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-26', 25, 'Danh từ trừu tượng & Sở thích & hoạt động cá nhân', '[{"hanzi":"事","pinyin":"shì","hanViet":"SỰ","meaning":"việc, sự","pos":"Danh từ","example":{"zh":"这件事很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Việc này rất quan trọng."}},{"hanzi":"课","pinyin":"kè","hanViet":"KHOÁ","meaning":"môn học","pos":"Danh từ","example":{"zh":"语文课。","pinyinPerChar":[{"c":"语","py":"yǔ"},{"c":"文","py":"wén"},{"c":"课","py":"kè"},{"c":"。","py":"。"}],"vi":"Môn ngữ văn."}},{"hanzi":"间","pinyin":"jiān","hanViet":"GIAN","meaning":"phòng, khoảng","pos":"Lượng từ","example":{"zh":"这间房间很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"间","py":"jiān"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Phòng này rất lớn."}},{"hanzi":"教","pinyin":"jiāo","hanViet":"GIÁO","meaning":"dạy","pos":"Động từ","example":{"zh":"老师教我。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"教","py":"jiào"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Thầy giáo dạy tôi."}},{"hanzi":"页","pinyin":"yè","hanViet":"HIỆT","meaning":"trang, mặt","pos":"Danh từ","example":{"zh":"这页书很厚。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"页","py":"yè"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"厚","py":"hòu"},{"c":"。","py":"。"}],"vi":"Trang sách này rất dày."}},{"hanzi":"床","pinyin":"chuáng","hanViet":"SÀNG","meaning":"giường","pos":"Danh từ","example":{"zh":"我在床上。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"床","py":"chuáng"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Tôi đang trên giường."}},{"hanzi":"衣服","pinyin":"yīfu","hanViet":"Y PHỤC","meaning":"quần áo","pos":"Danh từ","example":{"zh":"我买新衣服。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"买","py":"mǎi"},{"c":"新","py":"xīn"},{"c":"衣","py":"yī