INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-27', 26, 'Sở thích & hoạt động cá nhân & Từ thông dụng khác', '[{"hanzi":"准备","pinyin":"zhǔnbèi","hanViet":"CHUẨN BỊ","meaning":"chuẩn bị","pos":"Động từ","example":{"zh":"我准备吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"准","py":"zhǔn"},{"c":"备","py":"bèi"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi chuẩn bị ăn cơm."}},{"hanzi":"请假","pinyin":"qǐngjià","hanViet":"THỈNH GIẢ","meaning":"Yêu cầu nghỉ","pos":"Cụm từ","example":{"zh":"请假。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"假","py":"jiǎ"},{"c":"。","py":"。"}],"vi":"Yêu cầu nghỉ."}},{"hanzi":"饭","pinyin":"fàn","hanViet":"PHẠN","meaning":"cơm, bữa ăn","pos":"Danh từ","example":{"zh":"我吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi ăn cơm."}},{"hanzi":"点","pinyin":"diǎn","hanViet":"ĐIỂM","meaning":"điểm, giờ","pos":"Danh từ","example":{"zh":"现在几点？","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"几","py":"jǐ"},{"c":"点","py":"diǎn"},{"c":"？","py":"？"}],"vi":"Bây giờ mấy giờ?"}},{"hanzi":"口","pinyin":"kǒu","hanViet":"KHẨU","meaning":"miệng, lỗ, cửa","pos":"Danh từ","example":{"zh":"这口锅很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"口","py":"kǒu"},{"c":"锅","py":"guō"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Cái nồi này rất to."}},{"hanzi":"少","pinyin":"shǎo","hanViet":"THIỂU","meaning":"ít, không nhiều","pos":"Tính từ","example":{"zh":"我少吃糖。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"少","py":"shǎo"},{"c":"吃","py":"chī"},{"c":"糖","py":"táng"},{"c":"。","py":"。"}],"vi":"Tôi ít ăn kẹo."}},{"hanzi":"话","pinyin":"huà","hanViet":"THOẠI","meaning":"Lời nói, chuyện","pos":"Danh từ","example":{"zh":"他说话很慢。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"话","py":"huà"},{"c":"很","py":"hěn"},{"c":"慢","py":"màn"},{"c":"。","py":"。"}],"vi":"Cậu ấy nói chuyện rất chậm."}},{"hanzi":