INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-1', 0, 'Chào hỏi & xưng hô', '[{"hanzi":"它","pinyin":"tā","hanViet":"THA","meaning":"nó","pos":"Đại từ","example":{"zh":"它很好。","pinyinPerChar":[{"c":"它","py":"tā"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Nó rất tốt."}},{"hanzi":"它们","pinyin":"tāmen","hanViet":"THA MÔN","meaning":"chúng nó","pos":"Đại từ","example":{"zh":"它们很可爱。","pinyinPerChar":[{"c":"它","py":"tā"},{"c":"们","py":"men"},{"c":"很","py":"hěn"},{"c":"可","py":"kě"},{"c":"爱","py":"ài"},{"c":"。","py":"。"}],"vi":"Chúng nó rất đáng yêu."}},{"hanzi":"咱","pinyin":"zán","hanViet":"TA","meaning":"ta, chúng tôi (gồm nghe nói)","pos":"Đại từ","example":{"zh":"咱们一起去吧。","pinyinPerChar":[{"c":"咱","py":"zán"},{"c":"们","py":"men"},{"c":"一","py":"yī"},{"c":"起","py":"qǐ"},{"c":"去","py":"qù"},{"c":"吧","py":"ba"},{"c":"。","py":"。"}],"vi":"Hãy đi cùng chúng tôi nhé."}},{"hanzi":"咱们","pinyin":"zánmen","hanViet":"TA MÔN","meaning":"chúng tôi, chúng ta (gồm nghe nói)","pos":"Đại từ","example":{"zh":"咱们今天去公园。","pinyinPerChar":[{"c":"咱","py":"zán"},{"c":"们","py":"men"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"去","py":"qù"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"。","py":"。"}],"vi":"Hôm nay chúng tôi đi công viên."}},{"hanzi":"自己","pinyin":"zìjǐ","hanViet":"TỰ KỶ","meaning":"tự, bản thân","pos":"Đại từ","example":{"zh":"他自己做。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"做","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy làm bằng chính mình."}},{"hanzi":"大家","pinyin":"dàjiā","hanViet":"ĐẠI GIA","meaning":"cả người, mọi người","pos":"Đại từ","example":{"zh":"大家都很高兴。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"都","py":"dōu"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xīng"},{"c":"。","py":"。"}],"vi":"Cả người đều rất vui."}},{"hanzi":"太太","pinyin":"tàitai","hanViet":"THÁI THÁI","meaning":"vợ, bà","pos":"Danh từ","example":{"zh":"她是太太。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"太","py":"tài"},{"c":"太","py":"tài"},{"c":"。","py":"。"}],"vi":"Anh ấy là vợ."}},{"hanzi":"姓名","pinyin":"xìngmíng","hanViet":"TÍNH DANH","meaning":"tên","pos":"Danh từ","example":{"zh":"请写你的姓名。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"写","py":"xiě"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"姓","py":"xìng"},{"c":"名","py":"míng"},{"c":"。","py":"。"}],"vi":"Xin hãy viết tên của bạn."}},{"hanzi":"姓","pinyin":"xìng","hanViet":"TÍNH","meaning":"tên họ","pos":"Động từ","example":{"zh":"你姓什么？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"姓","py":"xìng"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"？","py":"？"}],"vi":"Bạn tên họ là gì?"}},{"hanzi":"称1","pinyin":"chēng","hanViet":"XƯNG ","meaning":"nêu tên, gọi","pos":"Động từ","example":{"zh":"他称自己是医生。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"称","py":"chēng"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"是","py":"shì"},{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Anh ta tự gọi mình là bác sĩ."}},{"hanzi":"啊","pinyin":"a","hanViet":"A","meaning":"vần, biểu cảm, câu hỏi","pos":"Thán từ","example":{"zh":"啊！今天天气真好。","pinyinPerChar":[{"c":"啊","py":"a"},{"c":"！","py":"！"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"真","py":"zhēn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"À! Thời tiết hôm nay thật đẹp."}},{"hanzi":"喂","pinyin":"wèi","hanViet":"UỶ","meaning":"vừa, ơi (gọi điện)","pos":"Thán từ","example":{"zh":"喂，你在哪里？","pinyinPerChar":[{"c":"喂","py":"wèi"},{"c":"，","py":"，"},{"c":"你","py":"nǐ"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Vừa, bạn ở đâu?"}},{"hanzi":"晚安","pinyin":"wǎn''ān","hanViet":"VÃN AN","meaning":"chúc ngủ ngon","pos":"Thán từ","example":{"zh":"晚安，明天见。","pinyinPerChar":[{"c":"晚","py":"wǎn"},{"c":"安","py":"ān"},{"c":"，","py":"，"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"见","py":"jiàn"},{"c":"。","py":"