INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-2', 1, 'Đại từ & từ để hỏi & Gia đình & con người', '[{"hanzi":"什么样","pinyin":"shénmeyàng","hanViet":"THẬM MA DẠNG","meaning":"Như thế nào, thế nào","pos":"Đại từ","example":{"zh":"你觉得这件衣服什么样？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"觉","py":"jué"},{"c":"得","py":"dé"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"样","py":"yàng"},{"c":"？","py":"？"}],"vi":"Bạn thấy chiếc áo này như thế nào?"}},{"hanzi":"那","pinyin":"nà","hanViet":"NA","meaning":"đó, kia","pos":"Đại từ","example":{"zh":"那是书。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"是","py":"shì"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Đó là sách."}},{"hanzi":"这么","pinyin":"zhème","hanViet":"GIÁ MA","meaning":"nhiều, thế nào","pos":"Tính từ","example":{"zh":"这么多书。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"么","py":"me"},{"c":"多","py":"duō"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Nhiều sách như vậy."}},{"hanzi":"那么","pinyin":"nàme","hanViet":"NA MA","meaning":"như vậy, thế thì","pos":"Phó từ","example":{"zh":"那么好。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"么","py":"me"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Thế thì tốt."}},{"hanzi":"那样","pinyin":"nàyàng","hanViet":"NA DẠNG","meaning":"như vậy, thế này","pos":"Tính từ","example":{"zh":"他这样做。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"这","py":"zhè"},{"c":"样","py":"yàng"},{"c":"做","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy làm vậy."}},{"hanzi":"这样","pinyin":"zhèyàng","hanViet":"GIÁ DẠNG","meaning":"như vậy, cách này","pos":"Tính từ","example":{"zh":"这样可以。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"样","py":"yàng"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"。","py":"。"}],"vi":"Cách này được."}},{"hanzi":"这时候|这时","pinyin":"zhè shíhou|zhè shí","hanViet":"GIÁ THỜI HẬU  GIÁ THỜI","meaning":"lúc này, lúc ấy","pos":"Danh từ","example":{"zh":"这时候我很忙。","pinyinPerC