INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-3', 2, 'Gia đình & con người & Số & lượng từ', '[{"hanzi":"主人","pinyin":"zhǔrén","hanViet":"CHỦ NHÂN","meaning":"người chủ, chủ nhà","pos":"Danh từ","example":{"zh":"他是房子的主人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"的","py":"de"},{"c":"主","py":"zhǔ"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy là chủ của căn nhà."}},{"hanzi":"爱人","pinyin":"àiren","hanViet":"ÁI NHÂN","meaning":"người yêu, vợ/chồng","pos":"Danh từ","example":{"zh":"我爱我的爱人。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"爱","py":"ài"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"爱","py":"ài"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Tôi yêu người yêu của tôi."}},{"hanzi":"大人","pinyin":"dàren","hanViet":"ĐẠI NHÂN","meaning":"người lớn, người lớn tuổi","pos":"Danh từ","example":{"zh":"请尊重大人。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"尊","py":"zūn"},{"c":"重","py":"zhòng"},{"c":"大","py":"dà"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Xin lễ trọng người lớn."}},{"hanzi":"青年","pinyin":"qīngnián","hanViet":"THANH NIÊN","meaning":"thanh niên, người trẻ","pos":"Danh từ","example":{"zh":"他是青年。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"青","py":"qīng"},{"c":"年","py":"nián"},{"c":"。","py":"。"}],"vi":"Anh ấy là thanh niên."}},{"hanzi":"青少年","pinyin":"qīng-shàonián","hanViet":"THANH THIỂU NIÊN","meaning":"thanh thiếu niên","pos":"Danh từ","example":{"zh":"青少年喜欢运动。","pinyinPerChar":[{"c":"青","py":"qīng"},{"c":"少","py":"shǎo"},{"c":"年","py":"nián"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Thanh thiếu niên thích thể thao."}},{"hanzi":"少年","pinyin":"shàonián","hanViet":"THIỂU NIÊN","meaning":"Cậu bé, thanh niên trẻ","pos":"Danh từ","example":{"zh":"这个少年很聪明。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"少","py":"shǎo"},{"c":"年","py