INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-4', 3, 'Số & lượng từ', '[{"hanzi":"亿","pinyin":"yì","hanViet":"ỨC","meaning":"tỷ, một số rất lớn","pos":"Số từ","example":{"zh":"这座楼有一亿块钱。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"楼","py":"lóu"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"亿","py":"yì"},{"c":"块","py":"kuài"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Tòa nhà này có một tỷ đồng."}},{"hanzi":"两","pinyin":"liǎng","hanViet":"LƯỠNG","meaning":"hai, cặp","pos":"Số từ","example":{"zh":"我有两本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"两","py":"liǎng"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi có hai quyển sách."}},{"hanzi":"分","pinyin":"fēn","hanViet":"PHÂN","meaning":"phân, phần","pos":"Danh từ","example":{"zh":"这件事要分两部分。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"要","py":"yào"},{"c":"分","py":"fēn"},{"c":"两","py":"liǎng"},{"c":"部","py":"bù"},{"c":"分","py":"fēn"},{"c":"。","py":"。"}],"vi":"Việc này phải chia thành hai phần."}},{"hanzi":"角","pinyin":"jiǎo","hanViet":"GIÁC","meaning":"góc","pos":"Danh từ","example":{"zh":"房间有四个角。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"有","py":"yǒu"},{"c":"四","py":"sì"},{"c":"个","py":"gè"},{"c":"角","py":"jiǎo"},{"c":"。","py":"。"}],"vi":"Phòng có bốn góc."}},{"hanzi":"公斤","pinyin":"gōngjīn","hanViet":"CÔNG CÂN","meaning":"kilôgam","pos":"Lượng từ","example":{"zh":"这苹果重一公斤。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"重","py":"zhòng"},{"c":"一","py":"yī"},{"c":"公","py":"gōng"},{"c":"斤","py":"jīn"},{"c":"。","py":"。"}],"vi":"Quả táo này nặng một kilôgam."}},{"hanzi":"斤","pinyin":"jīn","hanViet":"CÂN","meaning":"Đơn vị cân nặng 500g","pos":"Lượng từ","example":{"zh":"这斤肉很贵。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"斤","py":"jīn"},{"c":"肉","py":"ròu"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Con thịt này đắt tiền."}},{"hanzi":"克","pinyin":"kè","hanViet":"KHẮC","meaning":"kilogam","pos":"Lượng từ","example":{"zh":"这个苹果三块五。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"三","py":"sān"},{"c":"块","py":"kuài"},{"c":"五","py":"wǔ"},{"c":"。","py":"。"}],"vi":"Quả táo này ba năm năm."}},{"hanzi":"千克","pinyin":"qiānkè","hanViet":"THIÊN KHẮC","meaning":"kilôgam","pos":"Lượng từ","example":{"zh":"这个重一千克。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"重","py":"zhòng"},{"c":"一","py":"yī"},{"c":"千","py":"qiān"},{"c":"克","py":"kè"},{"c":"。","py":"。"}],"vi":"Cái này nặng một kilôgam."}},{"hanzi":"公里","pinyin":"gōnglǐ","hanViet":"CÔNG LÝ","meaning":"kilô mét","pos":"Lượng từ","example":{"zh":"学校离这里五公里。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"离","py":"lí"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"五","py":"wǔ"},{"c":"公","py":"gōng"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Trường học cách đây đây năm kilô mét."}},{"hanzi":"米","pinyin":"mǐ","hanViet":"MỄ","meaning":"gạo","pos":"Danh từ","example":{"zh":"我吃米。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"吃","py":"chī"},{"c":"米","py":"mǐ"},{"c":"。","py":"。"}],"vi":"Tôi ăn gạo."}},{"hanzi":"度","pinyin":"dù","hanViet":"ĐỘ","meaning":"mức độ, độ","pos":"Danh từ","example":{"zh":"温度的度。","pinyinPerChar":[{"c":"温","py":"wēn"},{"c":"度","py":"dù"},{"c":"的","py":"de"},{"c":"度","py":"dù"},{"c":"。","py":"。"}],"vi":"Độ của nhiệt độ."}},{"hanzi":"只","pinyin":"zhǐ","hanViet":"CHỈ","meaning":"chỉ, chỉ có","pos":"Đại từ","example":{"zh":"我只吃苹果。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"只","py":"zhǐ"},{"c":"吃","py":"chī"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Tôi chỉ ăn táo."}},{"hanzi":"条","pinyin":"tiáo","hanViet":"ĐIỀU","meaning":"mảnh, con, dòng","pos":"Đại từ","example":{"zh":"这条路很长。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Con đường này rất dài."}},{"hanzi":"件","pinyin":"jiàn","hanViet":"KIỆN","meaning":"món, việc","pos":"Danh từ","example":{"zh":"这件衣服很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Quần áo này rất tốt."}},{"hanzi":"封","pinyin":"fēng","hanViet":"PHONG","meaning":"lần, chiếc (thư, phong bì)","pos":"Danh từ","example":{"zh":"我写了一封信。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"写","py":"xiě"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"封","py":"fēng"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Tôi đã viết một lá thư."}},{"hanzi":"份","pinyin":"fèn","hanViet":"PHẦN","meaning":"lần, phần, tờ","pos":"Danh từ","example":{"zh":"请给我一份菜单。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"一","py":"yī"},{"c":"份","py":"fèn"},{"c":"菜","py":"cài"},{"c":"单","py":"dān"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi một tờ/thanh toán."}},{"hanzi":"套","pinyin":"tào","hanViet":"SÁO","meaning":"túm, bộ, bộ đồ","pos":"Danh từ","example":{"zh":"这套衣服很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"套","py":"tào"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Túm áo này rất đẹp."}},{"hanzi":"篇","pinyin":"piān","hanViet":"THIÊN","meaning":"bài, trang","pos":"Lượng từ","example":{"zh":"这是一篇文章。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"篇","py":"piān"},{"c":"文","py":"wén"},{"c":"章","py":"zhāng"},{"c":"。","py":"。"}],"vi":"Đây là một bài văn."}},{"hanzi":"段","pinyin":"duàn","hanViet":"ĐOẠN","meaning":"mảnh, phần","pos":"Danh từ","example":{"zh":"这段路很长。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"段","py":"duàn"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Quanh đường này rất dài."}},{"hanzi":"辆","pinyin":"liàng","hanViet":"LƯỢNG","meaning":"cái (dùng cho xe)","pos":"Lượng từ","example":{"zh":"我有一辆车。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"辆","py":"liàng"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Tôi có một chiếc xe."}},{"hanzi":"座","pinyin":"zuò","hanViet":"TOẠ","meaning":"ghế, chỗ ngồi, vị trí","pos":"Danh từ","example":{"zh":"我坐一座。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"坐","py":"zuò"},{"c":"一","py":"yī"},{"c":"座","py":"zuò"},{"c":"。","py":"。"}],"vi":"Tôi ngồi một chỗ."}},{"hanzi":"瓶","pinyin":"píng","hanViet":"BÌNH","meaning":"chai, lọ","pos":"Danh từ","example":{"zh":"这个瓶子很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"瓶","py":"píng"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Chai này rất to."}},{"hanzi":"碗","pinyin":"wǎn","hanViet":"OẢN","meaning":"cái bát, cái tách","pos":"Danh từ","example":{"zh":"这个碗很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"碗","py":"wǎn"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Cái bát này to lắm."}},{"hanzi":"一点点","pinyin":"yī diǎndiǎn","hanViet":"NHẤT ĐIỂM ĐIỂM","meaning":"một chút, rất ít","pos":"Đại từ","example":{"zh":"我想喝一点点水。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"喝","py":"hē"},{"c":"一","py":"yī"},{"c":"点","py":"diǎn"},{"c":"点","py":"diǎn"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Tôi muốn uống một chút nước."}},{"hanzi":"部分","pinyin":"bùfen","hanViet":"BỘ PHÂN","meaning":"một phần, một bộ phận","pos":"Danh từ","example":{"zh":"这部分很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"分","py":"fēn"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Phần này rất quan trọng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-5', 4, 'Số & lượng từ & Thời gian', '[{"hanzi":"一部分","pinyin":"yī bùfen","hanViet":"NHẤT BỘ PHÂN","meaning":"một phần","pos":"Danh từ","example":{"zh":"我是一部分。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"部","py":"bù"},{"c":"分","py":"fēn"},{"c":"。","py":"。"}],"vi":"Tôi là một phần."}},{"hanzi":"大部分","pinyin":"dàbùfen","hanViet":"ĐẠI BỘ PHÂN","meaning":"phần lớn","pos":"Tính từ","example":{"zh":"大部分学生都来了。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"部","py":"bù"},{"c":"分","py":"fēn"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"都","py":"dōu"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Phần lớn học sinh đã đến."}},{"hanzi":"多数","pinyin":"duōshù","hanViet":"ĐA SỐ","meaning":"phần lớn","pos":"Danh từ","example":{"zh":"多数人喜欢这个电影。","pinyinPerChar":[{"c":"多","py":"duō"},{"c":"数","py":"shù"},{"c":"人","py":"rén"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"。","py":"。"}],"vi":"Phần lớn người thích bộ phim này."}},{"hanzi":"大多数","pinyin":"dàduōshù","hanViet":"ĐẠI ĐA SỐ","meaning":"hầu hết","pos":"Tính từ","example":{"zh":"大多数人喜欢音乐。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"多","py":"duō"},{"c":"数","py":"shù"},{"c":"人","py":"rén"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"音","py":"yīn"},{"c":"乐","py":"lè"},{"c":"。","py":"。"}],"vi":"Hầu hết người thích âm nhạc."}},{"hanzi":"少数","pinyin":"shǎoshù","hanViet":"THIỂU SỐ","meaning":"Một số ít, ít người","pos":"Tính từ","example":{"zh":"少数人知道这件事。","pinyinPerChar":[{"c":"少","py":"shǎo"},{"c":"数","py":"shù"},{"c":"人","py":"rén"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Ít người biết chuyện này."}},{"hanzi":"全部","pinyin":"quánbù","hanViet":"TOÀN BỘ","meaning":"toàn bộ, tất cả","pos":"Danh từ","example":{"zh":"全部完成。","pinyinPerChar":[{"c":"全","py":"quán"},{"c":"部","py":"bù"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"。","py":"。"}],"vi":"Hoàn thành tất cả."}},{"hanzi":"全","pinyin":"quán","hanViet":"TOÀN","meaning":"toàn, tất cả","pos":"Tính từ","example":{"zh":"全班都来了。","pinyinPerChar":[{"c":"全","py":"quán"},{"c":"班","py":"bān"},{"c":"都","py":"dōu"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Toàn lớp đều đến."}},{"hanzi":"所有","pinyin":"suǒyǒu","hanViet":"SỞ HỮU","meaning":"tất cả","pos":"Danh từ","example":{"zh":"所有人都来了。","pinyinPerChar":[{"c":"所","py":"suǒ"},{"c":"有","py":"yǒu"},{"c":"人","py":"rén"},{"c":"都","py":"dōu"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tất cả mọi người đã đến."}},{"hanzi":"不少","pinyin":"bù shǎo","hanViet":"BẤT THIỂU","meaning":"nhiều, không ít","pos":"Tính từ","example":{"zh":"这里有不少人。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"不","py":"bù"},{"c":"少","py":"shǎo"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Ở đây có nhiều người."}},{"hanzi":"满","pinyin":"mǎn","hanViet":"MÃN","meaning":"đầy, đủ","pos":"Tính từ","example":{"zh":"房间里很满。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"满","py":"mǎn"},{"c":"。","py":"。"}],"vi":"Phòng có đầy người."}},{"hanzi":"不够","pinyin":"bùgòu","hanViet":"BẤT CÚ","meaning":"không đủ, chưa đủ","pos":"Tính từ","example":{"zh":"你的汉字写得不够好。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"汉","py":"hàn"},{"c":"字","py":"zì"},{"c":"写","py":"xiě"},{"c":"得","py":"dé"},{"c":"不","py":"bù"},{"c":"够","py":"gòu"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cách viết chữ Hán của bạn chưa đủ tốt."}},{"hanzi":"够","pinyin":"gòu","hanViet":"CÚ","meaning":"đủ","pos":"Tính từ","example":{"zh":"这够好了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"够","py":"gòu"},{"c":"好","py":"hǎo"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Điều này đủ tốt rồi."}},{"hanzi":"超过","pinyin":"chāoguò","hanViet":"SIÊU QUÁ","meaning":"vượt quá","pos":"Động từ","example":{"zh":"他超过我。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"超","py":"chāo"},{"c":"过","py":"guò"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Anh ấy vượt qua tôi."}},{"hanzi":"月份","pinyin":"yuèfèn","hanViet":"NGUYỆT PHẦN","meaning":"tháng","pos":"Danh từ","example":{"zh":"现在是几月份？","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"是","py":"shì"},{"c":"几","py":"jǐ"},{"c":"月","py":"yuè"},{"c":"份","py":"fèn"},{"c":"？","py":"？"}],"vi":"Bây giờ là tháng mấy?"}},{"hanzi":"周","pinyin":"zhōu","hanViet":"CHU","meaning":"vòng, tuần, quanh","pos":"Danh từ","example":{"zh":"他每周去公园。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"周","py":"zhōu"},{"c":"去","py":"qù"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"。","py":"。"}],"vi":"Anh ấy đi công viên mỗi tuần."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-6', 5, 'Thời gian', '[{"hanzi":"周末","pinyin":"zhōumò","hanViet":"CHU MẠT","meaning":"cuối tuần","pos":"Danh từ","example":{"zh":"我周末不上班。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"周","py":"zhōu"},{"c":"末","py":"mò"},{"c":"不","py":"bù"},{"c":"上","py":"shàng"},{"c":"班","py":"bān"},{"c":"。","py":"。"}],"vi":"Tôi không đi làm cuối tuần."}},{"hanzi":"周年","pinyin":"zhōunián","hanViet":"CHU NIÊN","meaning":"năm kỷ niệm","pos":"Danh từ","example":{"zh":"这是周年纪念。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"周","py":"zhōu"},{"c":"年","py":"nián"},{"c":"纪","py":"jì"},{"c":"念","py":"niàn"},{"c":"。","py":"。"}],"vi":"Đây là dịp kỷ niệm."}},{"hanzi":"夜","pinyin":"yè","hanViet":"DẠ","meaning":"đêm","pos":"Danh từ","example":{"zh":"现在是夜。","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"是","py":"shì"},{"c":"夜","py":"yè"},{"c":"。","py":"。"}],"vi":"Hiện giờ là đêm."}},{"hanzi":"夜里","pinyin":"yèlǐ","hanViet":"DẠ LÝ","meaning":"trong đêm","pos":"Danh từ","example":{"zh":"夜里很安静。","pinyinPerChar":[{"c":"夜","py":"yè"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"安","py":"ān"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Đêm rất yên tĩnh."}},{"hanzi":"半夜","pinyin":"bànyè","hanViet":"BÁN DẠ","meaning":"giữa đêm, nửa đêm","pos":"Danh từ","example":{"zh":"他半夜回家。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"半","py":"bàn"},{"c":"夜","py":"yè"},{"c":"回","py":"huí"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Anh ấy về nhà lúc giữa đêm."}},{"hanzi":"早晨","pinyin":"zǎochen","hanViet":"TẢO THẦN","meaning":"sáng hôm nay, buổi sáng","pos":"Danh từ","example":{"zh":"早晨我去学校。","pinyinPerChar":[{"c":"早","py":"zǎo"},{"c":"晨","py":"chén"},{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Sáng nay tôi đi trường."}},{"hanzi":"分钟","pinyin":"fēnzhōng","hanViet":"PHÂN CHUNG","meaning":"phút","pos":"Danh từ","example":{