thường đi học."}},{"hanzi":"平常","pinyin":"píngcháng","hanViet":"BÌNH THƯỜNG","meaning":"thường, bình thường","pos":"Tính từ","example":{"zh":"他平常很忙。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"平","py":"píng"},{"c":"常","py":"cháng"},{"c":"很","py":"hěn"},{"c":"忙","py":"máng"},{"c":"。","py":"。"}],"vi":"Anh ấy thường bận."}},{"hanzi":"当时","pinyin":"dāngshí","hanViet":"ĐƯƠNG THỜI","meaning":"lúc đó, lúc đó","pos":"Danh từ","example":{"zh":"当时我二十岁。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"时","py":"shí"},{"c":"我","py":"wǒ"},{"c":"二","py":"èr"},{"c":"十","py":"shí"},{"c":"岁","py":"suì"},{"c":"。","py":"。"}],"vi":"Lúc đó tôi mới hai mươi tuổi."}},{"hanzi":"后来","pinyin":"hòulái","hanViet":"HẬU LAI","meaning":"sau này, sau đó","pos":"Phó từ","example":{"zh":"他后来来了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"后","py":"hòu"},{"c":"来","py":"lái"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cậu ấy sau này đến."}},{"hanzi":"不久","pinyin":"bùjiǔ","hanViet":"BẤT CỬU","meaning":"không lâu, sớm","pos":"Danh từ","example":{"zh":"我不久后回来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"久","py":"jiǔ"},{"c":"后","py":"hòu"},{"c":"回","py":"huí"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi sẽ quay lại không lâu."}},{"hanzi":"今后","pinyin":"jīnhòu","hanViet":"KIM HẬU","meaning":"Từ nay, trong tương lai","pos":"Danh từ","example":{"zh":"今后我要努力。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"后","py":"hòu"},{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Từ nay tôi sẽ cố gắng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-7', 6, 'Thời gian & Học tập & trường lớp', '[{"hanzi":"最近","pinyin":"zuìjìn","hanViet":"TỐI CẬN","meaning":"gần đây, gần đây","pos":"Phó từ","example":{"zh":"我最近很忙。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"最","py":"zuì"},{"c":"近","py":"jìn"},{"c":"很","py":"hěn"},{"c":"忙","py":"máng"},{"c":"。","py":"。"}],"vi":"Tôi gần đây rất bận."}},{"hanzi":"从小","pinyin":"cóngxiǎo","hanViet":"TÒNG TIỂU","meaning":"từ nhỏ","pos":"Liên từ","example":{"zh":"从小我就喜欢读书。","pinyinPerChar":[{"c":"从","py":"cóng"},{"c":"小","py":"xiǎo"},{"c":"我","py":"wǒ"},{"c":"就","py":"jiù"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"读","py":"dú"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Từ nhỏ tôi đã thích đọc sách."}},{"hanzi":"一会儿","pinyin":"yīhuìr","hanViet":"NHẤT HỘI NHI","meaning":"một lúc, chốc lát","pos":"Danh từ","example":{"zh":"一会儿后。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"会","py":"huì"},{"c":"儿","py":"ér"},{"c":"后","py":"hòu"},{"c":"。","py":"。"}],"vi":"Sau một lúc."}},{"hanzi":"不一会儿","pinyin":"bù yīhuìr","hanViet":"BẤT NHẤT HỘI NHI","meaning":"chỉ trong một chút thời gian","pos":"Phó từ","example":{"zh":"不一会儿就下雨了。","pinyinPerChar":[{"c":"不","py":"bù"},{"c":"一","py":"yī"},{"c":"会","py":"huì"},{"c":"儿","py":"ér"},{"c":"就","py":"jiù"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Chỉ trong một chút thời gian là đã mưa rồi."}},{"hanzi":"一直","pinyin":"yīzhí","hanViet":"NHẤT TRỰC","meaning":"liên tục, suốt","pos":"Phó từ","example":{"zh":"我一直在等你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"一","py":"yī"},{"c":"直","py":"zhí"},{"c":"在","py":"zài"},{"c":"等","py":"děng"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi đang đợi cậu ấy liên tục."}},{"hanzi":"节","pinyin":"jié","hanViet":"TIẾT","meaning":"Tiết, lễ, mốt","pos":"Danh từ","example":{"zh":"这个节日很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"节","py":"jié"},{"c":"日","py":"rì"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Ngày lễ này rất quan trọng."}},{"hanzi":"节日","pinyin":"jiérì","hanViet":"TIẾT NHẬT","meaning":"Ngày lễ, tết","pos":"Danh từ","example":{"zh":"春节是中国的节日。","pinyinPerChar":[{"c":"春","py":"chūn"},{"c":"节","py":"jié"},{"c":"是","py":"shì"},{"c":"中","py":"zhōng"},{"c":"国","py":"guó"},{"c":"的","py":"de"},{"c":"节","py":"jié"},{"c":"日","py":"rì"},{"c":"。","py":"。"}],"vi":"Tết Nguyên đán là ngày lễ của Trung Quốc."}},{"hanzi":"春节","pinyin":"Chūnjié","hanViet":"XUÂN TIẾT","meaning":"Tết Nguyên đán","pos":"Danh từ","example":{"zh":"春节很热闹。","pinyinPerChar":[{"c":"春","py":"chūn"},{"c":"节","py":"jié"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"闹","py":"nào"},{"c":"。","py":"。"}],"vi":"Tết Nguyên đán rất sôi động."}},{"hanzi":"过年","pinyin":"guònián","hanViet":"QUÁ NIÊN","meaning":"ăn Tết","pos":"Động từ","example":{"zh":"我们过年。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"过","py":"guò"},{"c":"年","py":"nián"},{"c":"。","py":"。"}],"vi":"Chúng tôi ăn Tết."}},{"hanzi":"就要","pinyin":"jiùyào","hanViet":"TỰU YẾU","meaning":"sắp, sắp xếp","pos":"Tính từ","example":{"zh":"他就要走了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"就","py":"jiù"},{"c":"要","py":"yào"},{"c":"走","py":"zǒu"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cậu ấy sắp đi rồi."}},{"hanzi":"快要","pinyin":"kuàiyào","hanViet":"KHOÁI YẾU","meaning":"sắp, gần như","pos":"Liên từ","example":{"zh":"天快要下雨了。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"快","py":"kuài"},{"c":"要","py":"yào"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Trời sắp mưa."}},{"hanzi":"随时","pinyin":"suíshí","hanViet":"TUỲ THỜI","meaning":"lúc nào, bất cứ lúc nào","pos":"Phó từ","example":{"zh":"随时可以。","pinyinPerChar":[{"c":"随","py":"suí"},{"c":"时","py":"shí"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"。","py":"。"}],"vi":"Bất cứ lúc nào cũng được."}},{"hanzi":"留学生","pinyin":"liúxuéshēng","hanViet":"LƯU HỌ