INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-8', 7, 'Học tập & trường lớp', '[{"hanzi":"课堂","pinyin":"kètáng","hanViet":"KHOÁ ĐƯỜNG","meaning":"lớp học","pos":"Danh từ","example":{"zh":"我们在课堂上学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"课","py":"kè"},{"c":"堂","py":"táng"},{"c":"上","py":"shàng"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Chúng tôi học ở lớp học."}},{"hanzi":"笔","pinyin":"bǐ","hanViet":"BÚT","meaning":"bút, mũi tên","pos":"Danh từ","example":{"zh":"我有一支笔。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"支","py":"zhī"},{"c":"笔","py":"bǐ"},{"c":"。","py":"。"}],"vi":"Tôi có một cây bút."}},{"hanzi":"笔记","pinyin":"bǐjì","hanViet":"BÚT KÝ","meaning":"ghi chép, lưu trữ lại những gì nghe thấy","pos":"Danh từ","example":{"zh":"我每天晚上做笔记。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"晚","py":"wǎn"},{"c":"上","py":"shàng"},{"c":"做","py":"zuò"},{"c":"笔","py":"bǐ"},{"c":"记","py":"jì"},{"c":"。","py":"。"}],"vi":"Tôi ghi chép mỗi tối."}},{"hanzi":"笔记本","pinyin":"bǐjìběn","hanViet":"BÚT KÝ BẢN","meaning":"sách ghi chép, máy tính xách tay","pos":"Danh từ","example":{"zh":"我带笔记本去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"带","py":"dài"},{"c":"笔","py":"bǐ"},{"c":"记","py":"jì"},{"c":"本","py":"běn"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi mang sổ ghi chép đến trường."}},{"hanzi":"纸","pinyin":"zhǐ","hanViet":"CHỈ","meaning":"giấy","pos":"Danh từ","example":{"zh":"这张纸很白。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"张","py":"zhāng"},{"c":"纸","py":"zhǐ"},{"c":"很","py":"hěn"},{"c":"白","py":"bái"},{"c":"。","py":"。"}],"vi":" tờ giấy này rất trắng."}},{"hanzi":"英语","pinyin":"Yīngyǔ","hanViet":"ANH NGỮ","meaning":"tiếng Anh","pos":"Danh từ","example":{"zh":"我学英语。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"学","py":"xué"},{"c":"英","py