INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-11', 10, 'Công việc & mua sắm', '[{"hanzi":"办","pinyin":"bàn","hanViet":"BIỆN","meaning":"xử lý, làm, thực hiện","pos":"Động từ","example":{"zh":"我办事很快。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"办","py":"bàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Tôi làm việc rất nhanh."}},{"hanzi":"办法","pinyin":"bànfǎ","hanViet":"BIỆN PHÁP","meaning":"cách, phương pháp, biện pháp","pos":"Danh từ","example":{"zh":"没有办法了。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"办","py":"bàn"},{"c":"法","py":"fǎ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Không có cách nào."}},{"hanzi":"方法","pinyin":"fāngfǎ","hanViet":"PHƯƠNG PHÁP","meaning":"cách, phương pháp","pos":"Danh từ","example":{"zh":"有很多方法解决问题。","pinyinPerChar":[{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"方","py":"fāng"},{"c":"法","py":"fǎ"},{"c":"解","py":"jiě"},{"c":"决","py":"jué"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Có nhiều cách giải quyết vấn đề."}},{"hanzi":"出租","pinyin":"chūzū","hanViet":"XUẤT TÔ","meaning":"cho thuê","pos":"Động từ","example":{"zh":"这辆车可以出租。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"辆","py":"liàng"},{"c":"车","py":"chē"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"出","py":"chū"},{"c":"租","py":"zū"},{"c":"。","py":"。"}],"vi":"Xe này có thể cho thuê."}},{"hanzi":"打工","pinyin":"dǎgōng","hanViet":"ĐẢ CÔNG","meaning":"làm việc part-time","pos":"Động từ","example":{"zh":"学生们打工赚钱。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"们","py":"men"},{"c":"打","py":"dǎ"},{"c":"工","py":"gōng"},{"c":"赚","py":"zhuàn"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Học sinh làm việc để kiếm tiền."}},{"hanzi":"干活儿","pinyin":"gànhuór","hanViet":"CÁN HOẠT NHI","meaning":"làm việc, cày xới","pos":"Động từ","example":{"zh":"我们今天干活儿。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"me