INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-13', 12, 'Phương vị & nơi chốn', '[{"hanzi":"东方","pinyin":"dōngfāng","hanViet":"ĐÔNG PHƯƠNG","meaning":"phương đông","pos":"Danh từ","example":{"zh":"太阳从东方升起。","pinyinPerChar":[{"c":"太","py":"tài"},{"c":"阳","py":"yáng"},{"c":"从","py":"cóng"},{"c":"东","py":"dōng"},{"c":"方","py":"fāng"},{"c":"升","py":"shēng"},{"c":"起","py":"qǐ"},{"c":"。","py":"。"}],"vi":"Mặt trời mọc từ phương đông."}},{"hanzi":"西方","pinyin":"xīfāng","hanViet":"TÂY PHƯƠNG","meaning":"phía Tây","pos":"Danh từ","example":{"zh":"太阳从东方升起。","pinyinPerChar":[{"c":"太","py":"tài"},{"c":"阳","py":"yáng"},{"c":"从","py":"cóng"},{"c":"东","py":"dōng"},{"c":"方","py":"fāng"},{"c":"升","py":"shēng"},{"c":"起","py":"qǐ"},{"c":"。","py":"。"}],"vi":"Mặt trời mọc từ phía đông."}},{"hanzi":"南方","pinyin":"nánfāng","hanViet":"NAM PHƯƠNG","meaning":"miền nam","pos":"Danh từ","example":{"zh":"我去南方。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"南","py":"nán"},{"c":"方","py":"fāng"},{"c":"。","py":"。"}],"vi":"Tôi đi miền nam."}},{"hanzi":"北方","pinyin":"běifāng","hanViet":"BẮC PHƯƠNG","meaning":"miền Bắc","pos":"Danh từ","example":{"zh":"他住在北方。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"北","py":"běi"},{"c":"方","py":"fāng"},{"c":"。","py":"。"}],"vi":"Anh ấy sống ở miền Bắc."}},{"hanzi":"中心","pinyin":"zhōngxīn","hanViet":"TRUNG TÂM","meaning":"trung tâm, trung điểm","pos":"Danh từ","example":{"zh":"图书馆在中心。","pinyinPerChar":[{"c":"图","py":"tú"},{"c":"书","py":"shū"},{"c":"馆","py":"guǎn"},{"c":"在","py":"zài"},{"c":"中","py":"zhōng"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Thư viện ở trung tâm."}},{"hanzi":"边","pinyin":"biān","hanViet":"BIÊN","meaning":"mép, bờ, phía","pos":"Tính từ","example":{"zh":"这座山很高。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"山","py":"shān"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Tỉnh này rất cao."}},{"hanzi":"对面","pinyin":"duìmiàn","hanViet":"ĐỐI DIỆN","meaning":"bên kia, đối diện","pos":"Danh từ","example":{"zh":"学校在对面。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"在","py":"zài"},{"c":"对","py":"duì"},{"c":"面","py":"miàn"},{"c":"。","py":"。"}],"vi":"Trường học ở bên kia."}},{"hanzi":"面前","pinyin":"miànqián","hanViet":"DIỆN TIỀN","meaning":"trước mặt, trước","pos":"Danh từ","example":{"zh":"他站在面前。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"站","py":"zhàn"},{"c":"在","py":"zài"},{"c":"面","py":"miàn"},{"c":"前","py":"qián"},{"c":"。","py":"。"}],"vi":"Anh ấy đứng trước mặt."}},{"hanzi":"路边","pinyin":"lù biān","hanViet":"LỘ BIÊN","meaning":"bờ đường","pos":"Danh từ","example":{"zh":"车停在路边。","pinyinPerChar":[{"c":"车","py":"chē"},{"c":"停","py":"tíng"},{"c":"在","py":"zài"},{"c":"路","py":"lù"},{"c":"边","py":"biān"},{"c":"。","py":"。"}],"vi":"Ô tô dừng ở bờ đường."}},{"hanzi":"身边","pinyin":"shēnbiān","hanViet":"THÂN BIÊN","meaning":"Xung quanh, gần người","pos":"Danh từ","example":{"zh":"他身边有很多朋友。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"身","py":"shēn"},{"c":"边","py":"biān"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Anh ấy có nhiều bạn bè xung quanh."}},{"hanzi":"心里","pinyin":"xīnlǐ","hanViet":"TÂM LÝ","meaning":"trong lòng, trong tâm trí","pos":"Danh từ","example":{"zh":"我心里很高兴。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"心","py":"xīn"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xīng"},{"c":"。","py":"。"}],"vi":"Tôi rất vui trong lòng."}},{"hanzi":"心中","pinyin":"xīnzhōng","hanViet":"TÂM TRUNG","meaning":"trong lòng, trong tâm trí","pos":"Danh từ","example":{"zh":"他心中想着家人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"心","py":"xīn"},{"c":"中","py":"zhōng"},{"c":"想","py":"xiǎng"},{"c":"着","py":"zhe"},{"c":"家","py":"jiā"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy đang nghĩ về gia đình."}},{"hanzi":"头（里头）","pinyin":"tou (lǐtou)","