INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-14', 13, 'Phương vị & nơi chốn & Giao thông & đi lại', '[{"hanzi":"地铁站","pinyin":"dìtiězhàn","hanViet":"ĐỊA THIẾT TRẠM","meaning":"nhà ga đường sắt điện","pos":"Danh từ","example":{"zh":"地铁站在哪里？","pinyinPerChar":[{"c":"地","py":"dì"},{"c":"铁","py":"tiě"},{"c":"站","py":"zhàn"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Nhà ga đường sắt điện ở đâu?"}},{"hanzi":"停车场","pinyin":"tíngchēchǎng","hanViet":"ĐÌNH XA TRƯỜNG","meaning":"bãi đỗ xe","pos":"Danh từ","example":{"zh":"停车场很大。","pinyinPerChar":[{"c":"停","py":"tíng"},{"c":"车","py":"chē"},{"c":"场","py":"chǎng"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Bãi đỗ xe rất lớn."}},{"hanzi":"体育场","pinyin":"tǐyùchǎng","hanViet":"THỂ DỤC TRƯỜNG","meaning":"sân vận động","pos":"Danh từ","example":{"zh":"我们在体育场看比赛。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"体","py":"tǐ"},{"c":"育","py":"yù"},{"c":"场","py":"chǎng"},{"c":"看","py":"kàn"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"。","py":"。"}],"vi":"Chúng ta ở sân vận động xem trận đấu."}},{"hanzi":"体育馆","pinyin":"tǐyùguǎn","hanViet":"THỂ DỤC QUÁN","meaning":"sân vận động, nhà thể thao","pos":"Danh từ","example":{"zh":"他在体育馆练习。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"体","py":"tǐ"},{"c":"育","py":"yù"},{"c":"馆","py":"guǎn"},{"c":"练","py":"liàn"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Anh ấy tập luyện ở nhà thể thao."}},{"hanzi":"国际","pinyin":"guójì","hanViet":"QUỐC TẾ","meaning":"quốc tế","pos":"Tính từ","example":{"zh":"这是一个国际城市。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"国","py":"guó"},{"c":"际","py":"jì"},{"c":"城","py":"chéng"},{"c":"市","py":"shì"},{"c":"。","py":"。"}],"vi":"Đây là một thành phố quốc tế."}},{"hanzi":"住房","pinyin":"zhùfáng","hanViet":"TRÚ PHÒNG","meaning":"căn nhà ở","pos":"Danh từ","example":{"zh":"他找住房。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"找","py":"zhǎo"},{"c":"住","py":"zhù"},{"c":"房","py":"fáng"},{"c":"。","py":"。"}],"vi":"Anh ấy tìm nhà ở."}},{"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","hanViet":"CÔNG CỘNG KHÍ XA","meaning":"xe buýt","pos":"Danh từ","example":{"zh":"我坐公共汽车去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"坐","py":"zuò"},{"c":"公","py":"gōng"},{"c":"共","py":"gòng"},{"c":"汽","py":"qì"},{"c":"车","py":"chē"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi học bằng xe buýt."}},{"hanzi":"公交车","pinyin":"gōngjiāochē","hanViet":"CÔNG GIAO XA","meaning":"xe buýt","pos":"Danh từ","example":{"zh":"公交车很方便。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"交","py":"jiāo"},{"c":"车","py":"chē"},{"c":"很","py":"hěn"},{"c":"方","py":"fāng"},{"c":"便","py":"biàn"},{"c":"。","py":"。"}],"vi":"Xe buýt rất tiện lợi."}},{"hanzi":"船","pinyin":"chuán","hanViet":"THUYỀN","meaning":"tàu, con thuyền","pos":"Danh từ","example":{"zh":"这是一艘船。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"艘","py":"sōu"},{"c":"船","py":"chuán"},{"c":"。","py":"。"}],"vi":"Đây là một con tàu."}},{"hanzi":"自行车","pinyin":"zìxíngchē","hanViet":"TỰ HÀNH XA","meaning":"xe đạp","pos":"Danh từ","example":{"zh":"我坐自行车。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"坐","py":"zuò"},{"c":"自","py":"zì"},{"c":"行","py":"xíng"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Tôi đi bằng xe đạp."}},{"hanzi":"地铁","pinyin":"dìtiě","hanViet":"ĐỊA THIẾT","meaning":"đường sắt điện dưới đất","pos":"Danh từ","example":{"zh":"我坐地铁去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"坐","py":"zuò"},{"c":"地","py":"dì"},{"c":"铁","py":"tiě"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi bằng đường sắt điện để đến trường."}},{"hanzi":"出租车","pinyin":"chūzūchē","hanViet":"XUẤT TÔ XA","meaning":"xe taxi","pos":"Danh từ","example":{"zh":"我坐出租车去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"坐","py":"zuò"},{"c":"出","py":"chū"},{"c":"租","py":"zū"},{"c":"车","py":"chē"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi bằng xe taxi đến trường."}},{"hanzi":"骑","pinyin":"qí","hanViet":"KỴ","meaning":"cưỡi, ngồi lái","pos":"Động từ","example":{"zh":"我骑自行车。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"骑","py":"qí"},{"c":"自","py":"zì"},{"c":"行","py":"xíng"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Tôi cưỡi xe đạp."}},{"hanzi":"骑车","pinyin":"qí chē","hanViet":"KỴ XA","meaning":"cưỡi xe","pos":"Động từ","example":{"zh":"他骑车去学校。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"骑","py":"qí"},{"c":"车","py":"chē"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Anh ấy cưỡi xe đi học."}},{"hanzi":"停车","pinyin":"tíngchē","hanViet":"ĐÌNH XA","meaning":"đỗ xe","pos":"Danh từ","example":{"zh":"请在这里停车。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"停","py":"tíng"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Làm ơn đỗ xe ở đây."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-15', 14, 'Giao thông & đi lại', '[{"hanzi":"爬","pinyin":"pá","hanViet":"BÒ","meaning":"lên, bò lên","pos":"Động từ","example":{"zh":"我爬树。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"爬","py":"pá"},{"c":"树","py":"shù"},{"c":"。","py":"。"}],"vi":"Tôi leo cây."}},{"hanzi":"爬山","pinyin":"pá shān","hanViet":"BÒ SƠN","meaning":"đi leo núi","pos":"Động từ","example":{"zh":"我们周末爬山。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"周","py":"zhōu"},{"c":"末","py":"mò"},{"c":"爬","py":"pá"},{"c":"山","py":"shān"},{"c":"。","py":"。"}],"vi":"Chúng tôi leo núi cuối tuần."}},{"hanzi":"起飞","pinyin":"qǐfēi","hanViet":"KHỞI PHI","meaning":"cất cánh, lên đường bay","pos":"Động từ","example":{"zh":"飞机起飞了。","pinyinPerChar":[{"c":"飞","py":"fēi"},{"c":"机","py":"jī"},{"c":"起","py":"qǐ"},{"c":"飞","py":"fēi"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Máy bay đã cất cánh."}},{"hanzi":"公路","pinyin":"gōnglù","hanViet":"CÔNG LỘ","meaning":"đường công cộng","pos":"Danh từ","example":{"zh":"他们开车上公路。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"开","py":"kāi"},{"c":"车","py":"chē"},{"c":"上","py":"shàng"},{"c":"公","py":"gōng"},{"c":"路","py":"lù"},{"c":"。","py":"。"}],"vi":"Họ đi đường công cộng."}},{"hanzi":"街","pinyin":"jiē","hanViet":"NHAI","meaning":"Đường, phố","pos":"Danh từ","example":{"zh":"这条街很长。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"街","py":"jiē"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Đường này rất dài."}},{"hanzi":"道","pinyin":"dào","hanViet":"ĐẠO","meaning":"lối, con đường","pos":"Danh từ","example":{"zh":"这条路很长。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Con đường này rất dài."}},{"hanzi":"道路","pinyin":"dàolù","hanViet":"ĐẠO LỘ","meaning":"đường, con đường","pos":"Danh từ","example":{"zh":"我们走道路去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"走","py":"zǒu"},{"c":"道","py":"dào"},{"c":"路","py":"lù"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi đường đến trường."}},{"hanzi":"过来","pinyin":"guòlái","hanViet":"QUÁ LAI","meaning":"đến từ nơi khác","pos":"Động từ","example":{"zh":"请过来。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"过","py":"guò"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Hãy đến đây."}},{"hanzi":"过去","pinyin":"guòqù","hanViet":"QUÁ KHỨ","meaning":"vượt qua","pos":"Động từ","example":{"zh":"他过去了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"过","py":"guò"},{"c":"去","py":"qù"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đã vượt qua."}},{"hanzi":"走过","pinyin":"zǒuguò","hanViet":"TẨU QUÁ","meaning":"đi qua, trải qua","pos":"Động từ","example":{"zh":"他走过这里。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"过","py":"guò"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy đi qua đây."}},{"hanzi":"走进","pinyin":"zǒujìn","hanViet":"TẨU TIẾN","meaning":"vào trong","pos":"Động từ","example":{"zh":"他走进房间。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"进","py":"jìn"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Anh ấy vào trong phòng."}},{"hanzi":"走开","pinyin":"zǒukāi","hanViet":"TẨU KHAI","meaning":"rời xa, đi xa","pos":"Động từ","example":{"zh":"他走开。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"开","py":"kāi"},{"c":"。","py":"。"}],"vi":"Anh ấy đi xa."}},{"hanzi":"离","pinyin":"lí","hanViet":"LY","meaning":"từ, cách, rời","pos":"Động từ","example":{"zh":"学校离家很远。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"离","py":"lí"},{"c":"家","py":"jiā"},{"c":"很","py":"hěn"},{"c":"远","py":"yuǎn"},{"c":"。","py":"。"}],"vi":"Trường học cách nhà rất xa."}},{"hanzi":"离开","pinyin":"líkāi","hanViet":"LY KHAI","meaning":"rời khỏi, đi ra ngoài","pos":"Động từ","example":{"zh":"他离开学校。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"离","py":"lí"},{"c":"开","py":"kāi"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Anh ấy rời khỏi trường học."}},{"hanzi":"近","pinyin":"jìn","hanViet":"CẬN","meaning":"Gần, gần","pos":"Tính từ","example":{"zh":"这家店很近。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"家","py":"jiā"},{"c":"店","py":"diàn"},{"c":"很","py":"hěn"},{"c":"近","py":"jìn"},{"c":"。","py":"。"}],"vi":"Cửa hàng này gần."}},{"hanzi":"站","pinyin":"zhàn","hanViet":"TRẠM","meaning":"đứng, đặt chỗ","pos":"Động từ","example":{"zh":"我站在这里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"站","py":"zhàn"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi đứng ở đây."}},{"hanzi":"站住","pinyin":"zhànzhù","hanViet":"TRẠM TRÚ","meaning":"đứng lại, dừng lại","pos":"Động từ","example":{"zh":"请站住。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"站","py":"zhàn"},{"c":"住","py":"zhù"},{"c":"。","py":"。"}],"vi":"Hãy đứng lại."}},{"hanzi":"停","pinyin":"tíng","hanViet":"ĐÌNH","meaning":"dừng lại, ngừng","pos":"Động từ","example":{"zh":"请停一下。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"停","py":"tíng"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Làm ơn dừng lại một chút."}},{"hanzi":"交通","pinyin":"jiāotōng","hanViet":"GIAO THÔNG","meaning":"giao thông","pos":"Danh từ","example":{"zh":"这座城市交通很方便。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"城","py":"chéng"},{"c":"市","py":"shì"},{"c":"交","py":"jiāo"},{"c":"通","py":"tōng"},{"c":"很","py":"hěn"},{"c":"方","py":"fāng"},{"c":"便","py":"biàn"},{"c":"。","py":"。"}],"vi":"Thành phố này giao thông rất thuận tiện."}},{"hanzi":"旅客","pinyin":"lǚkè","hanViet":"LỮ KHÁCH","meaning":"người đi du lịch","pos":"Danh từ","example":{"zh":"旅客在车站等车。","pinyinPerChar":[{"c":"旅","py":"lǚ"},{"c":"客","py":"kè"},{"c":"在","py":"zài"},{"c":"车","py":"chē"},{"c":"站","py":"zhàn"},{"c":"等","py":"děng"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Người đi du lịch đang chờ xe tại nhà ga."}},{"hanzi":"旅游","pinyin":"lǚyóu","hanViet":"LỮ DU","meaning":"du lịch","pos":"Danh từ","example":{"zh":"她喜欢旅游。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"旅","py":"lǚ"},{"c":"游","py":"yóu"},{"c":"。","py":"。"}],"vi":"Cô ấy thích du lịch."}},{"hanzi":"旅行","pinyin":"lǚxíng","hanViet":"LỮ HÀNH","meaning":"đi du lịch","pos":"Động từ","example":{"zh":"他们周末旅行。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"周","py":"zhōu"},{"c":"末","py":"mò"},{"c":"旅","py":"lǚ"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Họ đi du lịch cuối tuần."}},{"hanzi":"游客","pinyin":"yóukè","hanViet":"DU KHÁCH","meaning":"người du lịch","pos":"Danh từ","example":{"zh":"这里有很多游客。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"游","py":"yóu"},{"c":"客","py":"kè"},{"c":"。","py":"。"}],"vi":"Nơi đây có nhiều người du lịch."}},{"hanzi":"护照","pinyin":"hùzhào","hanViet":"HỘ CHIẾU","meaning":"giấy tờ công dân, hộ chiếu","pos":"Danh từ","example":{"zh":"我带了护照。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"带","py":"dài"},{"c":"了","py":"le"},{"c":"护","py":"hù"},{"c":"照","py":"zhào"},{"c":"。","py":"。"}],"vi":"Tôi mang theo hộ chiếu."}},{"hanzi":"方向","pinyin":"fāngxiàng","hanViet":"PHƯƠNG HƯỚNG","meaning":"hướng, phương hướng","pos":"Danh từ","example":{"zh":"他不知道前面的方向。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"前","py":"qián"},{"c":"面","py":"miàn"},{"c":"的","py":"de"},{"c":"方","py":"fāng"},{"c":"向","py":"xiàng"},{"c":"。","py":"。"}],"vi":"Anh ấy không biết hướng phía trước."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-16', 15, 'Giao thông & đi lại & Ăn uống', '[{"hanzi":"问路","pinyin":"wènlù","hanViet":"VẤN LỘ","meaning":"hỏi đường, hỏi đường đi","pos":"Động từ","example":{"zh":"我问路。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"问","py":"wèn"},{"c":"路","py":"lù"},{"c":"。","py":"。"}],"vi":"Tôi hỏi đường."}},{"hanzi":"拉","pinyin":"lā","hanViet":"LẠP","meaning":"kéo","pos":"Động từ","example":{"zh":"他拉我的手。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"拉","py":"lā"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"手","py":"shǒu"},{"c":"。","py":"。"}],"vi":"Anh ấy kéo tay tôi."}},{"hanzi":"推","pinyin":"tuī","hanViet":"SUY","meaning":"kéo, đẩy","pos":"Động từ","example":{"zh":"他推开门。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"推","py":"tuī"},{"c":"开","py":"kāi"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Anh ấy mở cửa bằng cách đẩy."}},{"hanzi":"举","pinyin":"jǔ","hanViet":"CỬ","meaning":"nâng, nâng lên","pos":"Động từ","example":{"zh":"他举手。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"举","py":"jǔ"},{"c":"手","py":"shǒu"},{"c":"。","py":"。"}],"vi":"Cậu ấy nâng tay."}},{"hanzi":"举手","pinyin":"jǔshǒu","hanViet":"CỬ THỦ","meaning":"nâng tay","pos":"Danh từ","example":{"zh":"老师叫他举手。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"叫","py":"jiào"},{"c":"他","py":"tā"},{"c":"举","py":"jǔ"},{"c":"手","py":"shǒu"},{"c":"。","py":"。"}],"vi":"Giáo viên gọi cậu ấy nâng tay."}},{"hanzi":"碰","pinyin":"pèng","hanViet":"BÍNH","meaning":"chạm, gặp","pos":"Động từ","example":{"zh":"我碰到朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"碰","py":"pèng"},{"c":"到","py":"dào"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi gặp bạn."}},{"hanzi":"碰到","pinyin":"pèngdào","hanViet":"BÍNH ĐÁO","meaning":"gặp, chạm vào","pos":"Động từ","example":{"zh":"他碰到我的书。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"碰","py":"pèng"},{"c":"到","py":"dào"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"书","py":"