INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-17', 16, 'Ăn uống', '[{"hanzi":"菜单","pinyin":"càidān","hanViet":"THÁI ĐƠN","meaning":"menu","pos":"Danh từ","example":{"zh":"请看菜单。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"看","py":"kàn"},{"c":"菜","py":"cài"},{"c":"单","py":"dān"},{"c":"。","py":"。"}],"vi":"Xin xem menu."}},{"hanzi":"饺子","pinyin":"jiǎozi","hanViet":"CẢO TỬ","meaning":"bánh gối","pos":"Danh từ","example":{"zh":"我喜欢吃饺子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"饺","py":"jiǎo"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn bánh gối."}},{"hanzi":"方便面","pinyin":"fāngbiànmiàn","hanViet":"PHƯƠNG TIỆN DIỆN","meaning":"mì xào, mì gói","pos":"Danh từ","example":{"zh":"我喜欢吃方便面。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"方","py":"fāng"},{"c":"便","py":"biàn"},{"c":"面","py":"miàn"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn mì xào."}},{"hanzi":"快餐","pinyin":"kuàicān","hanViet":"KHOÁI XAN","meaning":"cơm nhanh","pos":"Danh từ","example":{"zh":"我喜欢吃快餐。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"快","py":"kuài"},{"c":"餐","py":"cān"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn cơm nhanh."}},{"hanzi":"西餐","pinyin":"xīcān","hanViet":"TÂY XAN","meaning":"cơm Tây","pos":"Danh từ","example":{"zh":"我喜欢吃西餐。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"西","py":"xī"},{"c":"餐","py":"cān"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn cơm Tây."}},{"hanzi":"中餐","pinyin":"zhōngcān","hanViet":"TRUNG XAN","meaning":"cơm Trung Hoa, bữa ăn Trung Quốc","pos":"Danh từ","example":{"zh":"我喜欢中餐。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"中","py":"zhōng"},{"c":"餐","py":"cān"},{"c":"。","py":"。"}],"vi":"Tôi thích cơm Trung Hoa."}},{"hanzi":"味道","pinyin":"w