INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-20', 19, 'Cảm xúc & thái độ & Thời tiết & màu sắc', '[{"hanzi":"感觉","pinyin":"gǎnjué","hanViet":"CẢM GIÁC","meaning":"cảm giác, cảm nhận","pos":"Danh từ","example":{"zh":"我有点感觉累。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"感","py":"gǎn"},{"c":"觉","py":"jué"},{"c":"累","py":"lèi"},{"c":"。","py":"。"}],"vi":"Tôi có cảm giác hơi mệt."}},{"hanzi":"感到","pinyin":"gǎndào","hanViet":"CẢM ĐÁO","meaning":"cảm thấy","pos":"Động từ","example":{"zh":"我感到很高兴。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"感","py":"gǎn"},{"c":"到","py":"dào"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xīng"},{"c":"。","py":"。"}],"vi":"Tôi cảm thấy rất vui."}},{"hanzi":"感动","pinyin":"gǎndòng","hanViet":"CẢM ĐỘNG","meaning":"động lòng, xúc động","pos":"Động từ","example":{"zh":"她感动了。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"感","py":"gǎn"},{"c":"动","py":"dòng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cô ấy xúc động."}},{"hanzi":"感谢","pinyin":"gǎnxiè","hanViet":"CẢM TẠ","meaning":"cảm ơn","pos":"Động từ","example":{"zh":"谢谢你，我感谢你。","pinyinPerChar":[{"c":"谢","py":"xiè"},{"c":"谢","py":"xiè"},{"c":"你","py":"nǐ"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"感","py":"gǎn"},{"c":"谢","py":"xiè"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Cảm ơn bạn, tôi cảm ơn bạn."}},{"hanzi":"满意","pinyin":"mǎnyì","hanViet":"MÃN Ý","meaning":"hài lòng","pos":"Tính từ","example":{"zh":"我很满意。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"满","py":"mǎn"},{"c":"意","py":"yì"},{"c":"。","py":"。"}],"vi":"Tôi rất hài lòng."}},{"hanzi":"有意思","pinyin":"yǒu yìsi","hanViet":"HỮU Ý TƯ","meaning":"thú vị, hay","pos":"Tính từ","example":{"zh":"这本书很有意思。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Cuốn sách này rất thú vị."}}