INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-21', 20, 'Thời tiết & màu sắc', '[{"hanzi":"阴","pinyin":"yīn","hanViet":"ÂM","meaning":"mưa, trời mù","pos":"Tính từ","example":{"zh":"今天天气阴。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"阴","py":"yīn"},{"c":"。","py":"。"}],"vi":"Hôm nay thời tiết mù."}},{"hanzi":"下雪","pinyin":"xià xuě","hanViet":"HẠ TUYẾT","meaning":"tuyết rơi","pos":"Động từ","example":{"zh":"今天下雪。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"下","py":"xià"},{"c":"雪","py":"xuě"},{"c":"。","py":"。"}],"vi":"Hôm nay có tuyết rơi."}},{"hanzi":"雪","pinyin":"xuě","hanViet":"TUYẾT","meaning":"tuyết","pos":"Danh từ","example":{"zh":"今天下雪了。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"下","py":"xià"},{"c":"雪","py":"xuě"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Hôm nay mưa tuyết."}},{"hanzi":"云","pinyin":"yún","hanViet":"VÂN","meaning":"mây, hình ảnh mây","pos":"Danh từ","example":{"zh":"天上有很多云。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"上","py":"shàng"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"云","py":"yún"},{"c":"。","py":"。"}],"vi":"Trên trời có nhiều mây."}},{"hanzi":"阴天","pinyin":"yīntiān","hanViet":"ÂM THIÊN","meaning":"ngày mù, ngày mưa","pos":"Danh từ","example":{"zh":"阴天不适合出户。","pinyinPerChar":[{"c":"阴","py":"yīn"},{"c":"天","py":"tiān"},{"c":"不","py":"bù"},{"c":"适","py":"shì"},{"c":"合","py":"hé"},{"c":"出","py":"chū"},{"c":"户","py":"hù"},{"c":"。","py":"。"}],"vi":"Ngày mù không thích hợp ra ngoài."}},{"hanzi":"晴天","pinyin":"qíngtiān","hanViet":"TÌNH THIÊN","meaning":"ngày đẹp trời","pos":"Danh từ","example":{"zh":"我们去公园玩。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"玩","py":"wán"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi công viên chơi."}},{"hanzi":"气温","pinyin":"qìwēn","hanViet":"KHÍ ÔN"