INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-22', 21, 'Tính từ & mô tả', '[{"hanzi":"长","pinyin":"zhǎng","hanViet":"TRƯỞNG","meaning":"dài","pos":"Tính từ","example":{"zh":"这条河很长。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"河","py":"hé"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Con sông này rất dài."}},{"hanzi":"短","pinyin":"duǎn","hanViet":"ĐOẢN","meaning":"ngắn","pos":"Tính từ","example":{"zh":"这条裤子很短。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"裤","py":"kù"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"短","py":"duǎn"},{"c":"。","py":"。"}],"vi":"Cặp quần này rất ngắn."}},{"hanzi":"低","pinyin":"dī","hanViet":"ĐÊ","meaning":"thấp, thấp","pos":"Tính từ","example":{"zh":"这个价格很低。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"价","py":"jià"},{"c":"格","py":"gé"},{"c":"很","py":"hěn"},{"c":"低","py":"dī"},{"c":"。","py":"。"}],"vi":"Giá cả này rất thấp."}},{"hanzi":"老","pinyin":"lǎo","hanViet":"LÃO","meaning":"cũ, già, người lớn","pos":"Tính từ","example":{"zh":"他是老师。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Anh ấy là giáo viên."}},{"hanzi":"好","pinyin":"hǎo","hanViet":"HẢO","meaning":"tốt, vui","pos":"Tính từ","example":{"zh":"今天天气好。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Thời tiết hôm nay tốt."}},{"hanzi":"不错","pinyin":"bùcuò","hanViet":"BẤT THÁC","meaning":"không xấu, khá, tốt","pos":"Tính từ","example":{"zh":"这道菜不错。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"道","py":"dào"},{"c":"菜","py":"cài"},{"c":"不","py":"bù"},{"c":"错","py":"cuò"},{"c":"。","py":"。"}],"vi":"Món ăn này không xấu."}},{"hanzi":"凉","pinyin":"liáng","hanViet":"LƯƠNG","meaning":"lạnh, mát","pos":"Tính từ","example":{"zh":"今天很凉。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c"