os":"Tính từ","example":{"zh":"我听清楚了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"听","py":"tīng"},{"c":"清","py":"qīng"},{"c":"楚","py":"chǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tôi nghe rõ."}},{"hanzi":"轻","pinyin":"qīng","hanViet":"KHINH","meaning":"nhẹ, nhẹ nhàng","pos":"Tính từ","example":{"zh":"这本书很轻。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"轻","py":"qīng"},{"c":"。","py":"。"}],"vi":"Cuốn sách này rất nhẹ."}},{"hanzi":"方便","pinyin":"fāngbiàn","hanViet":"PHƯƠNG TIỆN","meaning":"tiện lợi","pos":"Tính từ","example":{"zh":"这个地方很方便。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"地","py":"dì"},{"c":"方","py":"fāng"},{"c":"很","py":"hěn"},{"c":"方","py":"fāng"},{"c":"便","py":"biàn"},{"c":"。","py":"。"}],"vi":"Nơi này rất tiện lợi."}},{"hanzi":"合适","pinyin":"héshì","hanViet":"HỢP THÍCH","meaning":"phù hợp, thích hợp","pos":"Tính từ","example":{"zh":"这个杯子很合适。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"杯","py":"bēi"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"合","py":"hé"},{"c":"适","py":"shì"},{"c":"。","py":"。"}],"vi":"Cái ly này rất hợp."}},{"hanzi":"正常","pinyin":"zhèngcháng","hanViet":"CHÍNH THƯỜNG","meaning":"bình thường, ổn","pos":"Tính từ","example":{"zh":"今天天气正常。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"正","py":"zhèng"},{"c":"常","py":"cháng"},{"c":"。","py":"。"}],"vi":"Thời tiết hôm nay bình thường."}},{"hanzi":"正确","pinyin":"zhèngquè","hanViet":"CHÍNH XÁC","meaning":"đúng, chính xác","pos":"Tính từ","example":{"zh":"答案正确。","pinyinPerChar":[{"c":"答","py":"dá"},{"c":"案","py":"àn"},{"c":"正","py":"zhèng"},{"c":"确","py":"què"},{"c":"。","py":"。"}],"vi":"Đáp án đúng."}},{"hanzi":"准确","pinyin":"zhǔnquè","hanViet":"CHUẨN XÁC","meaning":"đúng, chính xác","pos":"Tính từ","example":{"zh":"答案准确。","pinyinPerChar":[{"c":"答","py":"dá"},{"c":"案","py":"àn"},{"c":"准","py":"zhǔn"},{"c":"确","py":"què"},{"c":"。","py":"。"}],"vi":"Đáp án đúng."}},{"hanzi":"对","pinyin":"duì","hanViet":"ĐỐI","meaning":"đúng, đối","pos":"Động từ","example":{"zh":"你说得对。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"说","py":"shuō"},{"c":"得","py":"dé"},{"c":"对","py":"duì"},{"c":"。","py":"。"}],"vi":"Bạn nói đúng."}},{"hanzi":"平","pinyin":"píng","hanViet":"BÌNH","meaning":"bình thường, bằng nhau","pos":"Tính từ","example":{"zh":"这很平。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"很","py":"hěn"},{"c":"平","py":"píng"},{"c":"。","py":"。"}],"vi":"Điều này bình thường."}},{"hanzi":"平等","pinyin":"píngděng","hanViet":"BÌNH ĐẲNG","meaning":"có bằng cấp, bình đẳng","pos":"Tính từ","example":{"zh":"人人平等。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"人","py":"rén"},{"c":"平","py":"píng"},{"c":"等","py":"děng"},{"c":"。","py":"。"}],"vi":"Mọi người bình đẳng."}},{"hanzi":"公平","pinyin":"gōngpíng","hanViet":"CÔNG BÌNH","meaning":"công bằng","pos":"Tính từ","example":{"zh":"规则要公平。","pinyinPerChar":[{"c":"规","py":"guī"},{"c":"则","py":"zé"},{"c":"要","py":"yào"},{"c":"公","py":"gōng"},{"c":"平","py":"píng"},{"c":"。","py":"。"}],"vi":"Quy tắc phải công bằng."}},{"hanzi":"普通","pinyin":"pǔtōng","hanViet":"PHỔ THÔNG","meaning":"thông thường, bình thường","pos":"Tính từ","example":{"zh":"他说普通话。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"普","py":"pǔ"},{"c":"通","py":"tōng"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Anh ấy nói tiếng Trung thông thường."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-23', 22, 'Tính từ & mô tả & Thiên nhiên & động vật', '[{"hanzi":"一般","pinyin":"yībān","hanViet":"NHẤT BAN","meaning":"thông thường, bình thường","pos":"Tính từ","example":{"zh":"一般。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"般","py":"bān"},{"c":"。","py":"。"}],"vi":"Thông thường."}},{"hanzi":"特别","pinyin":"tèbié","hanViet":"ĐẶC BIỆT","meaning":"riêng, đặc biệt","pos":"Tính từ","example":{"zh":"今天天气特别好。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"特","py":"tè"},{"c":"别","py":"bié"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Hôm nay thời tiết rất tốt."}},{"hanzi":"挺","pinyin":"tǐng","hanViet":"ĐĨNH","meaning":"khá, rất","pos":"Tính từ","example":{"zh":"这个苹果挺好吃。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"挺","py":"tǐng"},{"c":"好","py":"hǎo"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Quả táo này khá ngon."}},{"hanzi":"十分","pinyin":"shífēn","hanViet":"THẬP PHÂN","meaning":"rất, rất","pos":"Tính từ","example":{"zh":"他十分高兴。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"十","py":"shí"},{"c":"分","py":"fēn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xīng"},{"c":"。","py":"。"}],"vi":"Cậu ấy rất vui vẻ."}},{"hanzi":"更","pinyin":"gèng","hanViet":"CÀNG","meaning":"hơn, càng","pos":"Tính từ","example":{"zh":"这本书更有意思。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"更","py":"gèng"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Cuốn sách này thú vị hơn."}},{"hanzi":"越","pinyin":"yuè","hanViet":"VIỆT","meaning":"càng","pos":"Liên từ","example":{"zh":"天气越来越热。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"越","py":"yuè"},{"c":"来","py":"lái"},{"c":"越","py":"yuè"},{"c":"热","py":"rè"},{"c":"。","py":"。"}],"vi":"Thời tiết càng ngày càng nóng."}},{"hanzi":"越来越","pinyin":"yuè 