INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-26', 25, 'Giải trí & thể thao & Từ nối & ngữ pháp', '[{"hanzi":"晚会","pinyin":"wǎnhuì","hanViet":"VÃN HỘI","meaning":"tiệc, sự kiện, chương trình tối","pos":"Danh từ","example":{"zh":"他们参加晚会。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"晚","py":"wǎn"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Họ tham gia tiệc."}},{"hanzi":"活动","pinyin":"huódòng","hanViet":"HOẠT ĐỘNG","meaning":"sự kiện, hoạt động","pos":"Danh từ","example":{"zh":"学校有活动。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"有","py":"yǒu"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Trường học có hoạt động."}},{"hanzi":"才","pinyin":"cái","hanViet":"TÀI","meaning":"mới, chỉ","pos":"Đại từ","example":{"zh":"我才来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"才","py":"cái"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi mới đến."}},{"hanzi":"又","pinyin":"yòu","hanViet":"HỰU","meaning":"và, lại, cũng","pos":"Liên từ","example":{"zh":"他又高又帅。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"又","py":"yòu"},{"c":"高","py":"gāo"},{"c":"又","py":"yòu"},{"c":"帅","py":"shuài"},{"c":"。","py":"。"}],"vi":"Anh ấy vừa cao vừa đẹp."}},{"hanzi":"已经","pinyin":"yǐjīng","hanViet":"DĨ KINH","meaning":"đã, đã rồi","pos":"Động từ","example":{"zh":"已经吃。","pinyinPerChar":[{"c":"已","py":"yǐ"},{"c":"经","py":"jīng"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Đã ăn."}},{"hanzi":"经常","pinyin":"jīngcháng","hanViet":"KINH THƯỜNG","meaning":"Thường xuyên, thường","pos":"Phó từ","example":{"zh":"我经常去公园。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"经","py":"jīng"},{"c":"常","py":"cháng"},{"c":"去","py":"qù"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"。","py":"。"}],"vi":"Tôi thường xuyên đi công viên."}},{"hanzi":"老是","pinyin":"lǎoshì","hanViet":"LÃO THỊ","meaning":"luôn luôn, thường xuyên","pos":"Phó từ","example":{"zh":"我老是忘记带钥匙。","pinyi