,"hanViet":"HƯỚNG","meaning":"về hướng, hướng tới","pos":"Đại từ","example":{"zh":"他向我问问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"向","py":"xiàng"},{"c":"我","py":"wǒ"},{"c":"问","py":"wèn"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Cậu ấy hỏi tôi câu hỏi."}},{"hanzi":"往","pinyin":"wǎng","hanViet":"VÃNG","meaning":"về phía, hướng tới","pos":"Động từ","example":{"zh":"我往前走。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"往","py":"wǎng"},{"c":"前","py":"qián"},{"c":"走","py":"zǒu"},{"c":"。","py":"。"}],"vi":"Tôi đi về phía trước."}},{"hanzi":"为","pinyin":"wèi","hanViet":"VỊ","meaning":"làm, vì","pos":"Động từ","example":{"zh":"他为朋友工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"为","py":"wèi"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy làm việc cho bạn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-27', 26, 'Từ nối & ngữ pháp', '[{"hanzi":"为什么","pinyin":"wèi shénme","hanViet":"VỊ THẬM MA","meaning":"tại sao","pos":"Liên từ","example":{"zh":"为什么你不来？","pinyinPerChar":[{"c":"为","py":"wèi"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"你","py":"nǐ"},{"c":"不","py":"bù"},{"c":"来","py":"lái"},{"c":"？","py":"？"}],"vi":"Tại sao bạn không đến?"}},{"hanzi":"因为","pinyin":"yīnwèi","hanViet":"NHÂN VỊ","meaning":"vì, bởi vì","pos":"Liên từ","example":{"zh":"因为下雨，所以我不去。","pinyinPerChar":[{"c":"因","py":"yīn"},{"c":"为","py":"wèi"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"，","py":"，"},{"c":"所","py":"suǒ"},{"c":"以","py":"yǐ"},{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Vì trời mưa nên tôi không đi."}},{"hanzi":"所以","pinyin":"suǒyǐ","hanViet":"SỞ DĨ","meaning":"vì vậy, do đó","pos":"Liên từ","example":{"zh":"我累，所以休息。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"累","py":"lèi"},{"c":"，","py":"，"},{"c":"所","py":"suǒ"},{"c":"以","py":"yǐ"},{"c":"休","py":"xiū"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Tôi mệt, nên nghỉ."}},{"hanzi":"但是","pinyin":"dànshì","hanViet":"ĐÃN THỊ","meaning":"nhưng, nhưng","pos":"Liên từ","example":{"zh":"他很累，但是他还要工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"累","py":"lèi"},{"c":"，","py":"，"},{"c":"但","py":"dàn"},{"c":"是","py":"shì"},{"c":"他","py":"tā"},{"c":"还","py":"hái"},{"c":"要","py":"yào"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy rất mệt, nhưng anh ấy vẫn phải làm việc."}},{"hanzi":"但","pinyin":"dàn","hanViet":"ĐÃN","meaning":"nhưng, nhưng","pos":"Liên từ","example":{"zh":"我想去，但我很忙。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"去","py":"qù"},{"c":"，","py":"，"},{"c":"但","py":"dàn"},{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"忙","py":"máng"},{"c":"。","py":"。"}],"vi":"Tôi muốn đi, nhưng tôi bận rộn."}},{"hanzi":"不过","pinyin":"bùguò","hanViet":"BẤT QUÁ","meaning":"tuy nhiên, nhưng","pos":"Liên từ","example":{"zh":"天气很热，不过我很开心。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"，","py":"，"},{"c":"不","py":"bù"},{"c":"过","py":"guò"},{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"开","py":"kāi"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Thời tiết rất nóng, nhưng tôi rất vui."}},{"hanzi":"虽然","pinyin":"suīrán","hanViet":"TUY NHIÊN","meaning":"dù, mặc dù","pos":"Liên từ","example":{"zh":"虽然很累，但我去。","pinyinPerChar":[{"c":"虽","py":"suī"},{"c":"然","py":"rán"},{"c":"很","py":"hěn"},{"c":"累","py":"lèi"},{"c":"，","py":"，"},{"c":"但","py":"dàn"},{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Dù rất mệt, nhưng tôi đi."}},{"hanzi":"而且","pinyin":"érqiě","hanViet":"NHI THẢ","meaning":"và hơn, thêm nữa","pos":"Liên từ","example":{"zh":"他很聪明，而且很努力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"聪","py":"cōng"},{"c":"明","py":"míng"},{"c":"，","py":"，"},{"c":"而","py":"ér"},{"c":"且","py":"qiě"},{"c":"很","py":"hěn"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Anh ấy rất thông minh, và còn rất chăm chỉ."}},{"hanzi":"或","pinyin":"huò","hanViet":"HOẶC","meaning":"hoặc","pos":"Liên từ","example":{"zh":"他或她来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"或","py":"huò"},{"c":"她","py":"tā"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy hoặc cô ấy sẽ đến."}},{"hanzi":"或者","pinyin":"huòzhě","hanViet":"HOẶC GIẢ","meaning":"hoặc","pos":"Liên từ","example":{"zh":"我或者去图书馆。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"或","py":"huò"},{"c":"者","py":"zhě"},{"c":"去","py":"qù"},{"c":"图","py":"tú"},{"c":"书","py":"shū"},{"c":"馆","py":"guǎn"},{"c":"。","py":"。"}],"vi":"Tôi hoặc đi thư viện."}},{"hanzi":"比如","pinyin":"bǐrú","hanViet":"TỶ NHƯ","meaning":"ví dụ, chẳng hạn","pos":"Phó từ","example":{"zh":"比如说，我喜欢苹果。","pinyinPerChar":[{"c":"比","py":"bǐ"},{"c":"如","py":"rú"},{"c":"说","py":"shuō"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Ví dụ, tôi thích táo."}},{"hanzi":"比如说","pinyin":"bǐrú shuō","hanViet":"TỶ NHƯ THUYẾT","meaning":"ví dụ, chẳng hạn","pos":"Phó từ","example":{"zh":"比如说，你可以试试。","pinyinPerChar":[{"c":"比","py":"bǐ"},{"c":"如","py":"rú"},{"c":"说","py":"shuō"},{"c":"，","py":"，"},{"c":"你","py":"nǐ"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"试","py":"shì"},{"c":"试","py":"shì"},{"c":"。","py":"。"}],"vi":"Ví dụ, bạn có thể thử."}},{"hanzi":"例如","pinyin":"lìrú","hanViet":"LỆ NHƯ","meaning":"ví dụ","pos":"Liên từ","example":{"zh":"我喜欢水果，例如苹果。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"，","py":"，"},{"c":"例","py":"lì"},{"c":"如","py":"rú"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Tôi thích trái cây, ví dụ như táo."}},{"hanzi":"例子","pinyin":"lìzi","hanViet":"LỆ TỬ","meaning":"ví dụ, mẫu","pos":"Danh từ","example":{"zh":"这是个好例子。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"个","py":"gè"},{"c":"好","py":"hǎo"},{"c":"例","py":"lì"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Đây là một ví dụ tốt."}},{"hanzi":"如果","pinyin":"rúguǒ","hanViet":"NHƯ QUẢ","meaning":"Nếu, giả định","pos":"Phó từ","example":{"zh":"如果你有时间，我可以去。","pinyinPerChar":[{"c":"如","py":"rú"},{"c":"果","py":"guǒ"},{"c":"你","py":"nǐ"},{"c":"有","py":"yǒu"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Nếu bạn có thời gian, tôi có thể đi."}},{"hanzi":"得","pinyin":"de","hanViet":"ĐẮC","meaning":"được, phải","pos":"Động từ","example":{"zh":"我得去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"得","py":"dé"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi phải đi trường."}},{"hanzi":"过","pinyin":"guo","hanViet":"QUÁ","meaning":"qua, trải qua","pos":"Động từ","example":{"zh":"我过了这段时间。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"过","py":"guò"},{"c":"了","py":"le"},{"c":"这","py":"zhè"},{"c":"段","py":"duàn"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Tôi đã trải qua khoảng thời gian này."}},{"hanzi":"让","pinyin":"ràng","hanViet":"NHƯỢNG","meaning":"để, cho phép","pos":"Động từ","example":{"zh":"让我试试。","pinyinPerChar":[{"c":"让","py":"ràng"},{"c":"我","py":"wǒ"},{"c":"试","py":"shì"},{"c":"试","py":"shì"},{"c":"。","py":"。"}],"vi":"Để tôi thử xem."}},{"hanzi":"会","pinyin":"huì","hanViet":"HỘI","meaning":"có thể, sẽ","pos":"Động từ","example":{"zh":"你会说中文吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"会","py":"huì"},{"c":"说","py":"shuō"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn có nói tiếng Trung không?"}},{"hanzi":"能够","pinyin":"nénggòu","hanViet":"NĂNG CÚ","meaning":"có thể, đủ điều","pos":"Động từ","example":{"zh":"我能够帮助你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"能","py":"néng"},{"c":"够","py":"gòu"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi có thể giúp bạn."}},{"hanzi":"可以","pinyin":"kěyǐ","hanViet":"KHẢ DĨ","meaning":"được, có thể","pos":"Động từ","example":{"zh":"你可以坐这儿。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"坐","py":"zuò"},{"c":"这","py":"zhè"},{"c":"儿","py":"ér"},{"c":"。","py":"。"}],"vi":"Bạn được ngồi đây."}},{"hanzi":"必须","pinyin":"bìxū","hanViet":"TẤT TU","meaning":"bắt buộc, không thể không làm","pos":"Tính từ","example":{"zh":"你必须学习。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"必","py":"bì"},{"c":"须","py":"xū"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Bạn phải học."}},{"hanzi":"应该","pinyin":"yīnggāi","hanViet":"ƯNG CAI","meaning":"nên, phải","pos":"Phó từ","example":{"zh":"你应该学习。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Bạn nên học."}},{"hanzi":"只要","pinyin":"zhǐyào","hanViet":"CHỈ YẾU","meaning":"miễn là, chỉ cần","pos":"Liên từ","example":{"zh":"只要你努力，就会成功。","pinyinPerChar":[{"c":"只","py":"zhǐ"},{"c":"要","py":"yào"},{"c":"你","py":"nǐ"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"，","py":"，"},{"c":"就","py":"jiù"},{"c":"会","py":"huì"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Miễn là bạn cố gắng, bạn sẽ thành công."}},{"hanzi":"只能","pinyin":"zhǐ néng","hanViet":"CHỈ NĂNG","meaning":"chỉ có thể","pos":"Động từ","example":{"zh":"我只能等。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"只","py":"zhǐ"},{"c":"能","py":"néng"},{"c":"等","py":"děng"},{"c":"。","py":"。"}],"vi":"Tôi chỉ có thể chờ."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-28', 27, 'Từ nối & ngữ pháp (phần 2)', '[{"hanzi":"不要","pinyin":"bùyào","hanViet":"BẤT YẾU","meaning":"không nên, đừng","pos":"Tính từ","example":{"zh":"不要吃太多糖。","pinyinPerChar":[{"c":"不","py":"bù"},{"c":"要","py":"yào"},{"c":"吃","py":"chī"},{"c":"太","py":"tài"},{"c":"多","py":"duō"},{"c":"糖","py":"táng"},{"c":"。","py":"。"}],"vi":"Đừng ăn quá nhiều kẹo."}},{"hanzi":"不行","pinyin":"bùxíng","hanViet":"BẤT HÀNH","meaning":"không được, không thể","pos":"Tính từ","example":{"zh":"这个方法不行。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"方","py":"fāng"},{"c":"法","py":"fǎ"},{"c":"不","py":"bù"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Phương pháp này không được."}},{"hanzi":"可能","pinyin":"kěnéng","hanViet":"KHẢ NĂNG","meaning":"có thể","pos":"Tính từ","example":{"zh":"他可能来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"可","py":"kě"},{"c":"能","py":"néng"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Cậu ấy có thể đến."}},{"hanzi":"也许","pinyin":"yěxǔ","hanViet":"DÃ HỨA","meaning":"có thể, có lẽ","pos":"Phó từ","example":{"zh":"也许他来。","pinyinPerChar":[{"c":"也","py":"yě"},{"c":"许","py":"xǔ"},{"c":"他","py":"tā"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Có thể anh ấy sẽ đến."}},{"hanzi":"挺好","pinyin":"tǐng hǎo","hanViet":"ĐĨNH HẢO","meaning":"khá tốt, rất tốt","pos":"Tính từ","example":{"zh":"天气挺好，适合散步。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"挺","py":"tǐng"},{"c":"好","py":"hǎo"},{"c":"，","py":"，"},{"c":"适","py":"shì"},{"c":"合","py":"hé"},{"c":"散","py":"sàn"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Thời tiết khá tốt, thích hợp để đi bộ."}},{"hanzi":"快点儿","pinyin":"kuài diǎnr","hanViet":"KHOÁI ĐIỂM NHI","meaning":"nhanh lên","pos":"Phó từ","example":{"zh":"快点儿，我们要走。","pinyinPerChar":[{"c":"快","py":"kuài"},{"c":"点","py":"diǎn"},{"c":"儿","py":"ér"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"走","py":"zǒu"},{"c":"。","py":"。"}],"vi":"Nhanh lên, chúng ta phải đi."}},{"hanzi":"怎么样","pinyin":"zěnmeyàng","hanViet":"CHẨM MA DẠNG","meaning":"tốt không? thế nào?","pos":"Cụm từ","example":{"zh":"这件衣服怎么样？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"样","py":"yàng"},{"c":"？","py":"？"}],"vi":"Cái áo này thế nào?"}},{"hanzi":"怎样","pinyin":"zěnyàng","hanViet":"CHẨM DẠNG","meaning":"thế nào, như thế nào","pos":"Cụm từ","example":{"zh":"你怎样学习？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"怎","py":"zěn"},{"c":"样","py":"yàng"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"？","py":"？"}],"vi":"Bạn học thế nào?"}},{"hanzi":"怎么办","pinyin":"zěnme bàn","hanViet":"CHẨM MA BIỆN","meaning":"cần làm gì?","pos":"Cụm từ","example":{"zh":"这件事怎么办？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"办","py":"bàn"},{"c":"？","py":"？"}],"vi":"Câu chuyện này phải làm sao?"}},{"hanzi":"一定","pinyin":"yīdìng","hanViet":"NHẤT ĐỊNH","meaning":"chắc chắn, nhất định","pos":"Tính từ","example":{"zh":"他一定来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"一","py":"yī"},{"c":"定","py":"dìng"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy chắc chắn sẽ đến."}},{"hanzi":"以上","pinyin":"yǐshàng","hanViet":"DĨ THƯỢNG","meaning":"trên cùng, trên","pos":"Danh từ","example":{"zh":"以上。","pinyinPerChar":[{"c":"以","py":"yǐ"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Trên cùng."}},{"hanzi":"以下","pinyin":"yǐxià","hanViet":"DĨ HẠ","meaning":"dưới cùng, dưới","pos":"Danh từ","example":{"zh":"以下。","pinyinPerChar":[{"c":"以","py":"yǐ"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Dưới cùng."}},{"hanzi":"以外","pinyin":"yǐwài","hanViet":"DĨ NGOẠI","meaning":"ngoài ra","pos":"Danh từ","example":{"zh":"以外。","pinyinPerChar":[{"c":"以","py":"yǐ"},{"c":"外","py":"wài"},{"c":"。","py":"。"}],"vi":"Ngoài ra."}},{"hanzi":"以为","pinyin":"yǐwéi","hanViet":"DĨ VỊ","meaning":"đã nghĩ, cho là","pos":"Động từ","example":{"zh":"我以为。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"以","py":"yǐ"},{"c":"为","py":"wèi"},{"c":"。","py":"。"}],"vi":"Tôi đã nghĩ."}},{"hanzi":"可是","pinyin":"kěshì","hanViet":"KHẢ THỊ","meaning":"nhưng, song","pos":"Liên từ","example":{"zh":"我想去，但可是下雨了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"去","py":"qù"},{"c":"，","py":"，"},{"c":"但","py":"dàn"},{"c":"可","py":"kě"},{"c":"是","py":"shì"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tôi muốn đi, nhưng trời đang mưa."}},{"hanzi":"不但","pinyin":"bùdàn","hanViet":"BẤT ĐÃN","meaning":"không chỉ, không đơn thuần","pos":"Phó từ","example":{"zh":"他不但聪明，还很努力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"但","py":"dàn"},{"c":"聪","py":"cōng"},{"c":"明","py":"míng"},{"c":"，","py":"，"},{"c":"还","py":"hái"},{"c":"很","py":"hěn"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Anh ấy không chỉ thông minh mà còn rất chăm chỉ."}},{"hanzi":"的话","pinyin":"dehuà","hanViet":"ĐÍCH THOẠI","meaning":"nếu nói đến, thì","pos":"Liên từ","example":{"zh":"如果你想去的话，告诉我。","pinyinPerChar":[{"c":"如","py":"rú"},{"c":"果","py":"guǒ"},{"c":"你","py":"nǐ"},{"c":"想","py":"xiǎng"},{"c":"去","py":"qù"},{"c":"的","py":"de"},{"c":"话","py":"huà"},{"c":"，","py":"，"},{"c":"告","py":"gào"},{"c":"诉","py":"sù"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Nếu bạn muốn đi thì nói cho tôi biết."}},{"hanzi":"该","pinyin":"gāi","hanViet":"CAI","meaning":"được, nên, phải","pos":"Phó từ","example":{"zh":"你该走了。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"该","py":"gāi"},{"c":"走","py":"zǒu"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Bạn đã nên đi rồi."}},{"hanzi":"其他","pinyin":"qítā","hanViet":"KỲ THA","meaning":"các cái khác, những thứ khác","pos":"Danh từ","example":{"zh":"我没有其他问题。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"其","py":"qí"},{"c":"他","py":"tā"},{"c":"