INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-30', 29, 'Động từ & hoạt động thường ngày', '[{"hanzi":"接","pinyin":"jiē","hanViet":"TIẾP","meaning":"Nhận, tiếp nhận, nối","pos":"Động từ","example":{"zh":"我接电话。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"接","py":"jiē"},{"c":"电","py":"diàn"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Tôi nhận điện thoại."}},{"hanzi":"接受","pinyin":"jiēshòu","hanViet":"TIẾP THỌ","meaning":"Chấp nhận, tiếp nhận","pos":"Động từ","example":{"zh":"他接受了挑战。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"接","py":"jiē"},{"c":"受","py":"shòu"},{"c":"了","py":"le"},{"c":"挑","py":"tiāo"},{"c":"战","py":"zhàn"},{"c":"。","py":"。"}],"vi":"Anh ấy chấp nhận thử thách."}},{"hanzi":"选","pinyin":"xuǎn","hanViet":"TUYỂN","meaning":"chọn","pos":"Động từ","example":{"zh":"我选这本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"选","py":"xuǎn"},{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi chọn cuốn sách này."}},{"hanzi":"养","pinyin":"yǎng","hanViet":"DƯỠNG","meaning":"chăm sóc, nuôi","pos":"Động từ","example":{"zh":"他养一只猫。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"养","py":"yǎng"},{"c":"一","py":"yī"},{"c":"只","py":"zhǐ"},{"c":"猫","py":"māo"},{"c":"。","py":"。"}],"vi":"Anh ấy nuôi một con mèo."}},{"hanzi":"装","pinyin":"zhuāng","hanViet":"TRANG","meaning":"điểm, trang trí","pos":"Tính từ","example":{"zh":"房间装修好。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"装","py":"zhuāng"},{"c":"修","py":"xiū"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Căn phòng được trang trí đẹp."}},{"hanzi":"占","pinyin":"zhàn","hanViet":"CHIẾM","meaning":"chiếm, dùng, dự đoán","pos":"Động từ","example":{"zh":"他占了座位。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"占","py":"zhàn"},{"c":"了","py":"le"},{"c":"座","py":"zuò"},{"c":"位","py":"wèi"},{"c":"。","py":"。"}],"vi":"Anh ấy đã chiếm chỗ."}},{"hanzi":"找出","pinyin":"zhǎochū","hanViet":"TRẢO XUẤT","meaning":"tìm ra, phát hiện","pos":"