"meaning":"xong, hoàn thành","pos":"Động từ","example":{"zh":"作业做完了。","pinyinPerChar":[{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"做","py":"zuò"},{"c":"完","py":"wán"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Bài tập đã làm xong."}},{"hanzi":"实现","pinyin":"shíxiàn","hanViet":"THỰC HIỆN","meaning":"thực hiện, thành đạt","pos":"Động từ","example":{"zh":"他实现了梦想。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"实","py":"shí"},{"c":"现","py":"xiàn"},{"c":"了","py":"le"},{"c":"梦","py":"mèng"},{"c":"想","py":"xiǎng"},{"c":"。","py":"。"}],"vi":"Cậu ấy thành đạt giấc mơ."}},{"hanzi":"提高","pinyin":"tígāo","hanViet":"ĐỀ CAO","meaning":"nâng cao, tăng lên","pos":"Động từ","example":{"zh":"我们要提高成绩。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"提","py":"tí"},{"c":"高","py":"gāo"},{"c":"成","py":"chéng"},{"c":"绩","py":"jì"},{"c":"。","py":"。"}],"vi":"Chúng ta cần nâng cao kết quả."}},{"hanzi":"改","pinyin":"gǎi","hanViet":"CẢI","meaning":"sửa, thay đổi","pos":"Động từ","example":{"zh":"请改这个字。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"改","py":"gǎi"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Hãy sửa chữ này."}},{"hanzi":"改变","pinyin":"gǎibiàn","hanViet":"CẢI BIẾN","meaning":"thay đổi","pos":"Động từ","example":{"zh":"他改变了主意。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"改","py":"gǎi"},{"c":"变","py":"biàn"},{"c":"了","py":"le"},{"c":"主","py":"zhǔ"},{"c":"意","py":"yì"},{"c":"。","py":"。"}],"vi":"Anh ấy đã thay đổi ý kiến."}},{"hanzi":"通过","pinyin":"tōngguò","hanViet":"THÔNG QUÁ","meaning":"thông qua, đạt được","pos":"Động từ","example":{"zh":"他通过了考试。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"通","py":"tōng"},{"c":"过","py":"guò"},{"c":"了","py":"le"},{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"。","py":"。"}],"vi":"Anh ấy đã đỗ kỳ thi."}},{"hanzi":"经过","pinyin":"jīngguò","hanViet":"KINH QUÁ","meaning":"Qua, trải qua","pos":"Động từ","example":{"zh":"他经过了很多地方。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"经","py":"jīng"},{"c":"过","py":"guò"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"地","py":"dì"},{"c":"方","py":"fāng"},{"c":"。","py":"。"}],"vi":"Anh ấy đã trải qua nhiều nơi."}},{"hanzi":"算","pinyin":"suàn","hanViet":"TOÁN","meaning":"tính, tính toán","pos":"Động từ","example":{"zh":"算一下。","pinyinPerChar":[{"c":"算","py":"suàn"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Tính một lần."}},{"hanzi":"数","pinyin":"shǔ","hanViet":"SỐ","meaning":"đếm, số","pos":"Danh từ","example":{"zh":"数一数，共有十个苹果。","pinyinPerChar":[{"c":"数","py":"shù"},{"c":"一","py":"yī"},{"c":"数","py":"shù"},{"c":"，","py":"，"},{"c":"共","py":"gòng"},{"c":"有","py":"yǒu"},{"c":"十","py":"shí"},{"c":"个","py":"gè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Đếm, có tổng cộng mười quả táo."}},{"hanzi":"吹","pinyin":"chuī","hanViet":"XUY","meaning":"thổi","pos":"Động từ","example":{"zh":"他吹蜡烛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"吹","py":"chuī"},{"c":"蜡","py":"là"},{"c":"烛","py":"zhú"},{"c":"。","py":"。"}],"vi":"Anh ta thổi nến."}},{"hanzi":"有空儿","pinyin":"yǒukòngr","hanViet":"HỮU KHÔNG NHI","meaning":"có thời gian","pos":"Cụm từ","example":{"zh":"你有空儿吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"有","py":"yǒu"},{"c":"空","py":"kōng"},{"c":"儿","py":"ér"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn có thời gian không?"}},{"hanzi":"有人","pinyin":"yǒu rén","hanViet":"HỮU NHÂN","meaning":"có người","pos":"Cụm từ","example":{"zh":"这里有人吗？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"人","py":"rén"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Nơi đây có người không?"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-31', 30, 'Động từ & hoạt động thường ngày & Giao tiếp & suy nghĩ', '[{"hanzi":"有（一）点儿","pinyin":"yǒu(yī)diǎnr","hanViet":"HỮU NHẤT ĐIỂM NHI","meaning":"hơi, một chút","pos":"Cụm từ","example":{"zh":"天气有点儿冷。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"儿","py":"ér"},{"c":"冷","py":"lěng"},{"c":"。","py":"。"}],"vi":"Thời tiết hơi lạnh."}},{"hanzi":"遍","pinyin":"biàn","hanViet":"BIẾN","meaning":"lần, lần lượt","pos":"Lượng từ","example":{"zh":"我看了这本书一遍。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"看","py":"kàn"},{"c":"了","py":"le"},{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"一","py":"yī"},{"c":"遍","py":"biàn"},{"c":"。","py":"。"}],"vi":"Tôi đọc cuốn sách này một lần."}},{"hanzi":"不好意思","pinyin":"bù hǎoyìsi","hanViet":"BẤT HẢO Ý TƯ","meaning":"xấu hổ, xin lỗi","pos":"Tính từ","example":{"zh":"对不起，我不好意思。","pinyinPerChar":[{"c":"对","py":"duì"},{"c":"不","py":"bù"},{"c":"起","py":"qǐ"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"好","py":"hǎo"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Xin lỗi, tôi xấu hổ."}},{"hanzi":"对话","pinyin":"duìhuà","hanViet":"ĐỐI THOẠI","meaning":"cuộc đối thoại","pos":"Danh từ","example":{"zh":"他们进行了一场对话。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"进","py":"jìn"},{"c":"行","py":"xíng"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"场","py":"chǎng"},{"c":"对","py":"duì"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Họ đã có một cuộc đối thoại."}},{"hanzi":"讲话","pinyin":"jiǎnghuà","hanViet":"GIẢNG THOẠI","meaning":"nói chuyện, phát biểu","pos":"Động từ","example":{"zh":"老师讲话。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"讲","py":"jiǎng"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Thầy giáo nói chuyện."}},{"hanzi":"商量","pinyin":"shāngliang","hanViet":"THƯƠNG LƯỢNG","meaning":"Thảo luận, trao đổi ý kiến","pos":"Động từ","example":{"zh":"我们商量一下吧。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"商","py":"shāng"},{"c":"量","py":"liàng"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"吧","py":"ba"},{"c":"。","py":"。"}],"vi":"Hãy cùng trao đổi thôi."}},{"hanzi":"讨论","pinyin":"tǎolùn","hanViet":"THẢO LUẬN","meaning":"thảo luận","pos":"Động từ","example":{"zh":"我们讨论问题。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"讨","py":"tǎo"},{"c":"论","py":"lùn"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Chúng tôi thảo luận vấn đề."}},{"hanzi":"答应","pinyin":"dāying","hanViet":"ĐÁP ƯNG","meaning":"đồng ý, hứa","pos":"Động từ","example":{"zh":"他答应帮我。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"答","py":"dá"},{"c":"应","py":"yīng"},{"c":"帮","py":"bāng"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Anh ấy đồng ý giúp tôi."}},{"hanzi":"请求","pinyin":"qǐngqiú","hanViet":"THỈNH CẦU","meaning":"yêu cầu, đề nghị","pos":"Danh từ","example":{"zh":"他提出一个请求。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"提","py":"tí"},{"c":"出","py":"chū"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"请","py":"qǐng"},{"c":"求","py":"qiú"},{"c":"。","py":"。"}],"vi":"Cô ấy đề xuất một yêu cầu."}},{"hanzi":"求","pinyin":"qiú","hanViet":"CẦU","meaning":"yêu cầu, cầu xin","pos":"Động từ","example":{"zh":"他求她帮帮他。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"求","py":"qiú"},{"c":"她","py":"tā"},{"c":"帮","py":"bāng"},{"c":"帮","py":"bāng"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Anh ấy nhờ cô ấy giúp đỡ."}},{"hanzi":"要求","pinyin":"yāoqiú","hanViet":"YẾU CẦU","meaning":"yêu cầu","pos":"Danh từ","example":{"zh":"老师提出一个要求。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"提","py":"tí"},{"c":"出","py":"chū"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"要","py":"yào"},{"c":"求","py":"qiú"},{"c":"。","py":"。"}],"vi":"Giáo viên đặt ra một yêu cầu."}},{"hanzi":"通知","pinyin":"tōngzhī","hanViet":"THÔNG TRI","meaning":"thông báo","pos":"Danh từ","example":{"zh":"老师发了一个通知。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"发","py":"fā"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"通","py":"tōng"},{"c":"知","py":"zhī"},{"c":"。","py":"。"}],"vi":"Giáo viên đã phát một thông báo."}},{"hanzi":"说明","pinyin":"shuōmíng","hanViet":"THUYẾT MINH","meaning":"giải thích, nêu rõ","pos":"Động từ","example":{"zh":"请说明原因。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"说","py":"shuō"},{"c":"明","py":"míng"},{"c":"原","py":"yuán"},{"c":"因","py":"yīn"},{"c":"。","py":"。"}],"vi":"Xin giải thích nguyên nhân."}},{"hanzi":"表示","pinyin":"biǎoshì","hanViet":"BIỂU THỊ","meaning":"nói rõ, thể hiện","pos":"Động từ","example":{"zh":"他表示同意。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"表","py":"biǎo"},{"c":"示","py":"shì"},{"c":"同","py":"tóng"},{"c":"意","py":"yì"},{"c":"。","py":"。"}],"vi":"Anh ấy bày tỏ sự đồng ý."}},{"hanzi":"意见","pinyin":"yìjiàn","hanViet":"Ý KIẾN","meaning":"ý kiến, quan điểm","pos":"Danh từ","example":{"zh":"请告诉我你的意见。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"告","py":"gào"},{"c":"诉","py":"sù"},{"c":"我","py":"wǒ"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi biết ý kiến của bạn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-32', 31, 'Giao tiếp & suy nghĩ & Thời gian & tần suất (bổ sung)', '[{"hanzi":"看法","pinyin":"kànfǎ","hanViet":"KHÁN PHÁP","meaning":"quan điểm, quan niệm","pos":"Danh từ","example":{"zh":"他有看法。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"看","py":"kàn"},{"c":"法","py":"fǎ"},{"c":"。","py":"。"}],"vi":"Cậu ấy có quan điểm."}},{"hanzi":"观点","pinyin":"guāndiǎn","hanViet":"QUAN ĐIỂM","meaning":"quan điểm","pos":"Danh từ","example":{"zh":"他的观点很有意思。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"观","py":"guān"},{"c":"点","py":"diǎn"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Quan điểm của anh ấy rất thú vị."}},{"hanzi":"想法","pinyin":"xiǎngfǎ","hanViet":"TƯỞNG PHÁP","meaning":"ý tưởng","pos":"Danh từ","example":{"zh":"他的想法很好。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"想","py":"xiǎng"},{"c":"法","py":"fǎ"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Ý tưởng của cậu ấy rất tốt."}},{"hanzi":"想到","pinyin":"xiǎngdào","hanViet":"TƯỞNG ĐÁO","meaning":"nhận ra, nhớ đến","pos":"Động từ","example":{"zh":"我想到你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"到","py":"dào"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi nhớ đến bạn."}},{"hanzi":"想起","pinyin":"xiǎngqǐ","hanViet":"TƯỞNG KHỞI","meaning":"nhớ lại","pos":"Động từ","example":{"zh":"我想起一件事。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"起","py":"qǐ"},{"c":"一","py":"yī"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Tôi nhớ lại một việc."}},{"hanzi":"相信","pinyin":"xiāngxìn","hanViet":"TƯƠNG TÍN","meaning":"tin tưởng","pos":"Động từ","example":{"zh":"我相信你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"相","py":"xiāng"},{"c":"信","py":"xìn"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi tin tưởng bạn."}},{"hanzi":"认为","pinyin":"r