INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-34', 33, 'Mức độ & lượng (bổ sung) & Danh từ trừu tượng', '[{"hanzi":"多云","pinyin":"duōyún","hanViet":"ĐA VÂN","meaning":"nhiều mây","pos":"Tính từ","example":{"zh":"今天天气多云。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"多","py":"duō"},{"c":"云","py":"yún"},{"c":"。","py":"。"}],"vi":"Hôm nay thời tiết nhiều mây."}},{"hanzi":"事情","pinyin":"shìqing","hanViet":"SỰ TÌNH","meaning":"việc, chuyện","pos":"Danh từ","example":{"zh":"这件事情很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"情","py":"qíng"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Việc này rất quan trọng."}},{"hanzi":"问题","pinyin":"wèntí","hanViet":"VẤN ĐỀ","meaning":"vấn đề, câu hỏi","pos":"Danh từ","example":{"zh":"这个问题很难。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"很","py":"hěn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Vấn đề này khó lắm."}},{"hanzi":"结果","pinyin":"jiéguǒ","hanViet":"KẾT QUẢ","meaning":"Kết quả, thành quả","pos":"Danh từ","example":{"zh":"学习有结果。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"有","py":"yǒu"},{"c":"结","py":"jié"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Học tập có kết quả."}},{"hanzi":"目的","pinyin":"mùdì","hanViet":"MỤC ĐÍCH","meaning":"mục đích","pos":"Danh từ","example":{"zh":"这是目的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"目","py":"mù"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Đây là mục đích."}},{"hanzi":"机会","pinyin":"jīhuì","hanViet":"CƠ HỘI","meaning":"dịp, cơ hội","pos":"Danh từ","example":{"zh":"这是一个好机会。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"好","py":"hǎo"},{"c":"机","py":"jī"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Đây là một cơ hội 