},{"c":"小","py":"xiǎo"},{"c":"。","py":"。"}],"vi":"Hỏi kích thước."}},{"hanzi":"个子","pinyin":"gèzi","hanViet":"CÁ TỬ","meaning":"chiều cao cơ thể","pos":"Danh từ","example":{"zh":"她个子不高。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"个","py":"gè"},{"c":"子","py":"zi"},{"c":"不","py":"bù"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Cô ấy không cao."}},{"hanzi":"名","pinyin":"míng","hanViet":"DANH","meaning":"tên, danh hiệu","pos":"Danh từ","example":{"zh":"他的名叫小明。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"名","py":"míng"},{"c":"叫","py":"jiào"},{"c":"小","py":"xiǎo"},{"c":"明","py":"míng"},{"c":"。","py":"。"}],"vi":"Tên của anh ấy là Xuân Minh."}},{"hanzi":"名称","pinyin":"míngchēng","hanViet":"DANH XƯNG","meaning":"tên gọi, danh hiệu","pos":"Danh từ","example":{"zh":"这个名称很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"名","py":"míng"},{"c":"称","py":"chēng"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Tên gọi này rất quan trọng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-35', 34, 'Danh từ trừu tượng', '[{"hanzi":"名单","pinyin":"míngdān","hanViet":"DANH ĐƠN","meaning":"danh sách tên","pos":"Danh từ","example":{"zh":"请把名单给我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"名","py":"míng"},{"c":"单","py":"dān"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi danh sách tên."}},{"hanzi":"理想","pinyin":"lǐxiǎng","hanViet":"LÝ TƯỞNG","meaning":"ý tưởng, ước mơ","pos":"Danh từ","example":{"zh":"我的理想是当医生。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"理","py":"lǐ"},{"c":"想","py":"xiǎng"},{"c":"是","py":"shì"},{"c":"当","py":"dāng"},{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Ước mơ của tôi là làm bác sĩ."}},{"hanzi":"意思","pinyin":"yìsi","hanViet":"Ý TƯ","meaning":"ý nghĩa, ý đồ","pos":"Danh từ","example":{"zh":"你说什么意思？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"说","py":"shuō"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"？","py":"？"}],"vi":"Bạn nói ý nghĩa gì?"}},{"hanzi":"原因","pinyin":"yuányīn","hanViet":"NGUYÊN NHÂN","meaning":"nguyên nhân","pos":"Danh từ","example":{"zh":"请说清楚原因。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"说","py":"shuō"},{"c":"清","py":"qīng"},{"c":"楚","py":"chǔ"},{"c":"原","py":"yuán"},{"c":"因","py":"yīn"},{"c":"。","py":"。"}],"vi":"Hãy nói rõ nguyên nhân."}},{"hanzi":"好处","pinyin":"hǎochù","hanViet":"HẢO XỨ","meaning":"lợi ích","pos":"Danh từ","example":{"zh":"这个好处很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"好","py":"hǎo"},{"c":"处","py":"chù"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Lợi ích này rất lớn."}},{"hanzi":"坏处","pinyin":"huàichù","hanViet":"HOẠI XỨ","meaning":"nhược điểm, khuyết điểm","pos":"Danh từ","example":{"zh":"这个坏处是什么？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"坏","py":"huài"},{"c":"处","py":"chù"},{"c":"是","py":"shì"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"？","py":"？"}],"vi":"Điểm xấu của cái này là gì?"}},{"hanzi":"好人","pinyin":"hǎorén","hanViet":"HẢO NHÂN","meaning":"người tốt","pos":"Danh từ","example":{"zh":"他是好人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"好","py":"hǎo"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy là người tốt."}},{"hanzi":"好事","pinyin":"hǎoshì","hanViet":"HẢO SỰ","meaning":"công việc tốt, may mắn","pos":"Danh từ","example":{"zh":"这是一个好事。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"好","py":"hǎo"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Đây là một việc tốt."}},{"hanzi":"坏人","pinyin":"huàirén","hanViet":"HOẠI NHÂN","meaning":"người xấu, kẻ ác","pos":"Danh từ","example":{"zh":"他不是坏人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"是","py":"shì"},{"c":"坏","py":"huài"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Cậu ấy không phải người xấu."}},{"hanzi":"水平","pinyin":"shuǐpíng","hanViet":"THUỶ BÌNH","meaning":"trình độ, năng lực","pos":"Danh từ","example":{"zh":"他的水平很高。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"水","py":"shuǐ"},{"c":"平","py":"píng"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Trình độ của anh ấy rất cao."}},{"hanzi":"作用","pinyin":"zuòyòng","hanViet":"TÁC DỤNG","meaning":"chức năng, vai trò","pos":"Danh từ","example":{"zh":"这有作用。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"有","py":"yǒu"},{"c":"作","py":"zuò"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Điều này có chức năng."}},{"hanzi":"影响","pinyin":"yǐngxiǎng","hanViet":"ẢNH HƯỞNG","meaning":"ảnh hưởng","pos":"Danh từ","example":{"zh":"这会影响我的生活。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"会","py":"huì"},{"c":"影","py":"yǐng"},{"c":"响","py":"xiǎng"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"。","py":"。"}],"vi":"Điều này sẽ ảnh hưởng đến cuộc sống của tôi."}},{"hanzi":"信心","pinyin":"xìnxīn","hanViet":"TÍN TÂM","meaning":"niềm tin, sự tự tin","pos":"Danh từ","example":{"zh":"她有信心。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"有","py":"yǒu"},{"c":"信","py":"xìn"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Cô ấy có niềm tin."}},{"hanzi":"行为","pinyin":"xíngwéi","hanViet":"HÀNH VỊ","meaning":"hành vi","pos":"Danh từ","example":{"zh":"他的行为很奇怪。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"行","py":"xíng"},{"c":"为","py":"wèi"},{"c":"很","py":"hěn"},{"c":"奇","py":"qí"},{"c":"怪","py":"guài"},{"c":"。","py":"。"}],"vi":"Hành vi của anh ấy rất lạ."}},{"hanzi":"行动","pinyin":"xíngdòng","hanViet":"HÀNH ĐỘNG","meaning":"hành động","pos":"Danh từ","example":{"zh":"他做一个大行动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"做","py":"zuò"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"大","py":"dà"},{"c":"行","py":"xíng"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Anh ấy sẽ thực hiện một hành động lớn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-36', 35, 'Học tập & ngôn ngữ (bổ sung) & Đồ dùng & quần áo', '[{"hanzi":"报名","pinyin":"bàomíng","hanViet":"BÁO DANH","meaning":"đăng ký, đăng ký tham gia","pos":"Động từ","example":{"zh":"他报名了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"报","py":"bào"},{"c":"名","py":"míng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đã đăng ký."}},{"hanzi":"高中","pinyin":"gāozhōng","hanViet":"CAO TRUNG","meaning":"trung học phổ thông","pos":"Danh từ","example":{"zh":"他读高中。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"读","py":"dú"},{"c":"高","py":"gāo"},{"c":"中","py":"zhōng"},{"c":"。","py":"。"}],"vi":"Anh ấy học trung học phổ thông."}},{"hanzi":"黑板","pinyin":"hēibǎn","hanViet":"HẮC BẢN","meaning":"tấm bảng đen","pos":"Danh từ","example":{"zh":"老师在黑板上写字。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"在","py":"zài"},{"c":"黑","py":"hēi"},{"c":"板","py":"bǎn"},{"c":"上","py":"shàng"},{"c":"写","py":"xiě"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Thầy giáo viết chữ trên bảng đen."}},{"hanzi":"听讲","pinyin":"tīngjiǎng","hanViet":"THÍNH GIẢNG","meaning":"lắng nghe bài giảng","pos":"Động từ","example":{"zh":"我听讲很认真。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"听","py":"tīng"},{"c":"讲","py":"jiǎng"},{"c":"很","py":"hěn"},{"c":"认","py":"rèn"},{"c":"真","py":"zhēn"},{"c":"。","py":"。"}],"vi":"Tôi nghe bài giảng rất cẩn thận."}},{"hanzi":"听说","pinyin":"tīngshuō","hanViet":"THÍNH THUYẾT","meaning":"được biết, nghe nói","pos":"Phó từ","example":{"zh":"我听说这家餐厅很好吃。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"听","py":"tīng"},{"c":"说","py":"shuō"},{"c":"这","py":"zhè"},{"c":"家","py":"jiā"},{"c":"餐","py":"cān"},{"c":"厅","py":"tīng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Tôi nghe nói nhà hàng này rất ngon."}},{"hanzi":"院长","pinyin":"yuànzhǎng","hanViet":"VIỆN TRƯỞNG","meaning":"giám đốc, chủ tịch","pos":"Danh từ","example":{"zh":"院长在这里。","pinyinPerChar":[{"c":"院","py":"yuàn"},{"c":"长","py":"zhǎng"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Giám đốc đang ở đây."}},{"hanzi":"语言","pinyin":"yǔyán","hanViet":"NGỮ NGÔN","meaning":"ngôn ngữ","pos":"Danh từ","example":{"zh":"中文是一种语言。","pinyinPerChar":[{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"种","py":"zhǒng"},{"c":"语","py":"yǔ"},{"c":"言","py":"yán"},{"c":"。","py":"。"}],"vi":"Tiếng Trung là một ngôn ngữ."}},{"hanzi":"鞋","pinyin":"xié","hanViet":"HÀI","meaning":"giầy","pos":"Danh từ","example":{"zh":"这双鞋很新。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"双","py":"shuāng"},{"c":"鞋","py":"xié"},{"c":"很","py":"hěn"},{"c":"新","py":"xīn"},{"c":"。","py":"。"}],"vi":"Cặp giầy này rất mới."}},{"hanzi":"大衣","pinyin":"dàyī","hanViet":"ĐẠI Y","meaning":"áo khoác","pos":"Danh từ","example":{"zh":"穿大衣。","pinyinPerChar":[{"c":"穿","py":"chuān"},{"c":"大","py":"dà"},{"c":"衣","py":"yī"},{"c":"。","py":"。"}],"vi":"Mặc áo khoác."}},{"hanzi":"手表","pinyin":"shǒubiǎo","hanViet":"THỦ BIỂU","meaning":"đồng hồ, đồng hồ đeo tay","pos":"Danh từ","example":{"zh":"这是一块手表。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"块","py":"kuài"},{"c":"手","py":"shǒu"},{"c":"表","py":"biǎo"},{"c":"。","py":"。"}],"vi":"Đây là một chiếc đồng hồ."}},{"hanzi":"瓶子","pinyin":"píngzi","hanViet":"BÌNH TỬ","meaning":"chai, lọ","pos":"Danh từ","example":{"zh":"我买了一个瓶子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"买","py":"mǎi"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"瓶","py":"píng"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi đã mua một chai."}},{"hanzi":"礼物","pinyin":"lǐwù","hanViet":"LỄ VẬT","meaning":"quà tặng","pos":"Danh từ","example":{"zh":"我给你礼物。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"给","py":"gěi"},{"c":"你","py":"nǐ"},{"c":"礼","py":"lǐ"},{"c":"物","py":"wù"},{"c":"。","py":"。"}],"vi":"Tôi cho bạn quà."}},{"hanzi":"卡","pinyin":"kǎ","hanViet":"CA","meaning":"thẻ","pos":"Danh từ","example":{"zh":"他有卡。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"卡","py":"kǎ"},{"c":"。","py":"。"}],"vi":"Cậu ấy có thẻ."}},{"hanzi":"油","pinyin":"yóu","hanViet":"DẦU","meaning":"dầu, chất béo","pos":"Danh từ","example":{"zh":"这个菜需要很多油。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"菜","py":"cài"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"油","py":"yóu"},{"c":"。","py":"。"}],"vi":"Món này cần nhiều dầu."}},{"hanzi":"洗衣机","pinyin":"xǐyījī","hanViet":"TẨY Y CƠ","meaning":"máy giặt","pos":"Danh từ","example":{"zh":"洗衣机很好用。","pinyinPerChar":[{"c":"洗","py":"xǐ"},{"c":"衣","py":"yī"},{"c":"机","py":"jī"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Máy giặt rất tiện dụng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-37', 36, 'Địa điểm & hành chính', '[{"hanzi":"场","pinyin":"chǎng","hanViet":"TRƯỜNG","meaning":"lượt, lần, trường","pos":"Danh từ","example":{"zh":"一场雨。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"场","py":"chǎng"},{"c":"雨","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Một cơn mưa."}},{"hanzi":"省","pinyin":"shěng","hanViet":"TỈNH","meaning":"tiểu bang, tỉnh","pos":"Danh từ","example":{"zh":"他来自山东省。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"来","py":"lái"},{"c":"自","py":"zì"},{"c":"山","py":"shān"},{"c":"东","py":"dōng"},{"c":"省","py":"shěng"},{"c":"。","py":"。"}],"vi":"Cậu ấy đến từ tỉnh Sơn Đông."}},{"hanzi":"市","pinyin":"shì","hanViet":"THỊ","meaning":"thành phố, thị","pos":"Danh từ","example":{"zh":"我住在市里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"市","py":"shì"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi ở trong thành phố."}},{"hanzi":"市长","pinyin":"shìzhǎng","hanViet":"THỊ TRƯỞNG","meaning":"giám đốc thành phố, thị trưởng","pos":"Danh từ","example":{"zh":"他是市长。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"市","py":"shì"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Cậu ấy là giám đốc thành phố."}},{"hanzi":"院","pinyin":"yuàn","hanViet":"VIỆN","meaning":"cảnh, sân, viện","pos":"Danh từ","example":{"zh":"学校有一个大院子。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"大","py":"dà"},{"c":"院","py":"yuàn"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Trường học có một khu vườn lớn."}},{"hanzi":"外地","pinyin":"wàidì","hanViet":"NGOẠI ĐỊA","meaning":"nơi khác, ngoài địa phương","pos":"Danh từ","example":{"zh":"他去外地工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"去","py":"qù"},{"c":"外","py":"wài"},{"c":"地","py":"dì"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy đi làm ở nơi khác."}},{"hanzi":"墙","pinyin":"qiáng","hanViet":"TƯỜNG","meaning":"tường, bức tường","pos":"Danh từ","example":{"zh":"这面墙很高。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"面","py":"miàn"},{"c":"墙","py":"qiáng"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Bức tường này cao."}},{"hanzi":"全国","pinyin":"quánguó","hanViet":"TOÀN QUỐC","meaning":"toàn quốc","pos":"Danh từ","example":{"zh":"全国都知道。","pinyinPerChar":[{"c":"全","py":"quán"},{"c":"国","py":"guó"},{"c":"都","py":"dōu"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"。","py":"。"}],"vi":"Toàn quốc đều biết."}},{"hanzi":"全身","pinyin":"quánshēn","hanViet":"TOÀN THÂN","meaning":"toàn thân, cả cơ thể","pos":"Danh từ","example":{"zh":"他全身都很热。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"全","py":"quán"},{"c":"身","py":"shēn"},{"c":"都","py":"dōu"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"。","py":"。"}],"vi":"Cậu ấy toàn thân rất nóng."}},{"hanzi":"全体","pinyin":"quántǐ","hanViet":"TOÀN THỂ","meaning":"toàn thể, tất cả mọi người","pos":"Danh từ","example":{"zh":"全体员工都来。","pinyinPerChar":[{"c":"全","py":"quán"},{"c":"体","py":"tǐ"},{"c":"员","py":"yuán"},{"c":"工","py":"gōng"},{"c":"都","py":"dōu"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Toàn thể nhân viên đều đến."}},{"hanzi":"司机","pinyin":"sījī","hanViet":"TI CƠ","meaning":"tài xế","pos":"Danh từ","example":{"zh":"他是司机。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"司","py":"sī"},{"c":"机","py":"jī"},{"c":"。","py":"。"}],"vi":"Anh ấy là tài xế."}},{"hanzi":"车辆","pinyin":"chēliàng","hanViet":"XA LƯỢNG","meaning":"phương tiện giao thông","pos":"Danh từ","example":{"zh":"这辆车是我的车辆。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"辆","py":"liàng"},{"c":"车","py":"chē"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"车","py":"chē"},{"c":"辆","py":"liàng"},{"c":"。","py":"。"}],"vi":"Xe này là phương tiện của tôi."}},{"hanzi":"行人","pinyin":"xíngrén","hanViet":"HÀNH NHÂN","meaning":"người đi bộ","pos":"Danh từ","example":{"zh":"行人要走在人行道上。","pinyinPerChar":[{"c":"行",