INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-38', 37, 'Động từ & trạng thái (bổ sung)', '[{"hanzi":"帮助","pinyin":"bāngzhù","hanViet":"BANG TRỢ","meaning":"giúp đỡ","pos":"Động từ","example":{"zh":"我帮助你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi giúp bạn."}},{"hanzi":"表","pinyin":"biǎo","hanViet":"BIỂU","meaning":"biểu thị, chỉ ra","pos":"Động từ","example":{"zh":"这张表显示很多信息。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"张","py":"zhāng"},{"c":"表","py":"biǎo"},{"c":"显","py":"xiǎn"},{"c":"示","py":"shì"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"信","py":"xìn"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Bảng này hiển thị nhiều thông tin."}},{"hanzi":"成","pinyin":"chéng","hanViet":"THÀNH","meaning":"trở thành, đạt","pos":"Động từ","example":{"zh":"他成为了老师。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"成","py":"chéng"},{"c":"为","py":"wèi"},{"c":"了","py":"le"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Anh ta trở thành giáo viên."}},{"hanzi":"成为","pinyin":"chéngwéi","hanViet":"THÀNH VỊ","meaning":"trở thành","pos":"Động từ","example":{"zh":"她成为医生。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"成","py":"chéng"},{"c":"为","py":"wèi"},{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Cô ấy trở thành bác sĩ."}},{"hanzi":"出国","pinyin":"chūguó","hanViet":"XUẤT QUỐC","meaning":"đi ra nước ngoài","pos":"Động từ","example":{"zh":"他出国学习。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"出","py":"chū"},{"c":"国","py":"guó"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Anh ta đi ra nước ngoài học tập."}},{"hanzi":"回国","pinyin":"huí guó","hanViet":"HỒI QUỐC","meaning":"quay về nước","pos":"Động từ","example":{"zh":"他们回国了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"回","py":"huí"},{"c":"国","py":"guó"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Họ đã quay về nước."}},{