INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-40', 39, 'Động từ & trạng thái (bổ sung) & Từ thông dụng khác', '[{"hanzi":"位","pinyin":"wèi","hanViet":"VỊ","meaning":"cái, người (lượng từ chỉ người)","pos":"Lượng từ","example":{"zh":"他是三位老师。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"三","py":"sān"},{"c":"位","py":"wèi"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Anh ấy là ba người giáo viên."}},{"hanzi":"片","pinyin":"piàn","hanViet":"PHIẾN","meaning":"mảnh, lát","pos":"Lượng từ","example":{"zh":"一片树叶。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"片","py":"piàn"},{"c":"树","py":"shù"},{"c":"叶","py":"yè"},{"c":"。","py":"。"}],"vi":"Một lá cây."}},{"hanzi":"气","pinyin":"qì","hanViet":"KHÍ","meaning":"khí, hơi, khí","pos":"Danh từ","example":{"zh":"我感到有点气。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"感","py":"gǎn"},{"c":"到","py":"dào"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Tôi cảm thấy hơi khó chịu."}},{"hanzi":"信","pinyin":"xìn","hanViet":"TÍN","meaning":"tờ thư, tin nhắn","pos":"Danh từ","example":{"zh":"我写了一封信。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"写","py":"xiě"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"封","py":"fēng"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Tôi đã viết một lá thư."}},{"hanzi":"数字","pinyin":"shùzì","hanViet":"SỐ TỰ","meaning":"số, chữ số","pos":"Danh từ","example":{"zh":"这个数字很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"数","py":"shù"},{"c":"字","py":"zì"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Số này rất quan trọng."}},{"hanzi":"饭馆","pinyin":"fànguǎn","hanViet":"PHẠN QUÁN","meaning":"nhà hàng, quán ăn","pos":"Danh từ","example":{"zh":"我们去饭馆吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"饭","py":"fàn"},{"c":"馆","py":"guǎn"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"