INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-1', 0, 'Gia đình & quan hệ (1)', '[{"hanzi":"白","pinyin":"bái","hanViet":"BẠCH","meaning":"trắng, không, chỉ trừ","pos":"Tính từ","example":{"zh":"天很白。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"很","py":"hěn"},{"c":"白","py":"bái"},{"c":"。","py":"。"}],"vi":"Trời rất sáng."}},{"hanzi":"办理","pinyin":"bànlǐ","hanViet":"BIỆN LÝ","meaning":"xử lý, thực hiện","pos":"Động từ","example":{"zh":"请办理手续。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"办","py":"bàn"},{"c":"理","py":"lǐ"},{"c":"手","py":"shǒu"},{"c":"续","py":"xù"},{"c":"。","py":"。"}],"vi":"Xin vui lòng xử lý giấy tờ."}},{"hanzi":"报告","pinyin":"bàogào","hanViet":"BÁO CÁO","meaning":"báo cáo, thông báo","pos":"Danh từ","example":{"zh":"老师给我们做报告。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"做","py":"zuò"},{"c":"报","py":"bào"},{"c":"告","py":"gào"},{"c":"。","py":"。"}],"vi":"Thầy giáo trình bày báo cáo cho chúng ta."}},{"hanzi":"播出","pinyin":"bōchū","hanViet":"BÁ XUẤT","meaning":"xem phát, phát sóng","pos":"Động từ","example":{"zh":"电视每天播出新闻。","pinyinPerChar":[{"c":"电","py":"diàn"},{"c":"视","py":"shì"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"播","py":"bō"},{"c":"出","py":"chū"},{"c":"新","py":"xīn"},{"c":"闻","py":"wén"},{"c":"。","py":"。"}],"vi":"Tivi phát sóng tin tức mỗi ngày."}},{"hanzi":"不必","pinyin":"bùbì","hanViet":"BẤT TẤT","meaning":"không cần","pos":"Phó từ","example":{"zh":"你不必担心。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"不","py":"bù"},{"c":"必","py":"bì"},{"c":"担","py":"dān"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Bạn không cần lo lắng."}},{"hanzi":"不安","pinyin":"bù''ān","hanViet":"BẤT AN","meaning":"lo lắng, không yên tâm","pos":"Tính từ","example":{"zh":"他对考试很不安。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"很","py":"hěn"},{"c":"不","py":"bù"},{"c":"安","py":"ān"},{"c":"。","py":"。"}],"vi":"Cô ấy rất lo lắng về kỳ thi."}},{"hanzi":"不得不","pinyin":"bùdébù","hanViet":"BẤT ĐẮC BẤT","meaning":"bắt buộc, không thể tránh khỏi","pos":"Liên từ","example":{"zh":"我不得不早睡。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"得","py":"dé"},{"c":"不","py":"bù"},{"c":"早","py":"zǎo"},{"c":"睡","py":"shuì"},{"c":"。","py":"。"}],"vi":"Tôi phải đi ngủ sớm."}},{"hanzi":"不光","pinyin":"bùguāng","hanViet":"BẤT QUANG","meaning":"không chỉ, không đơn thuần","pos":"Phó từ","example":{"zh":"他不光会唱歌，还会跳舞。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"光","py":"guāng"},{"c":"会","py":"huì"},{"c":"唱","py":"chàng"},{"c":"歌","py":"gē"},{"c":"，","py":"，"},{"c":"还","py":"hái"},{"c":"会","py":"huì"},{"c":"跳","py":"tiào"},{"c":"舞","py":"wǔ"},{"c":"。","py":"。"}],"vi":"Cậu ấy không chỉ biết hát mà còn biết múa."}},{"hanzi":"不仅","pinyin":"bùjǐn","hanViet":"BẤT CẬN","meaning":"không chỉ, không những","pos":"Liên từ","example":{"zh":"她不仅聪明，还很努力。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"不","py":"bù"},{"c":"仅","py":"jǐn"},{"c":"聪","py":"cōng"},{"c":"明","py":"míng"},{"c":"，","py":"，"},{"c":"还","py":"hái"},{"c":"很","py":"hěn"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Cô ấy không chỉ thông minh mà còn rất chăm chỉ."}},{"hanzi":"场合","pinyin":"chǎnghé","hanViet":"TRƯỜNG HỢP","meaning":"bối cảnh, dịp, occasion","pos":"Danh từ","example":{"zh":"这是一个重要的场合。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"的","py":"de"},{"c":"场","py":"chǎng"},{"c":"合","py":"hé"},{"c":"。","py":"。"}],"vi":"Đây là một dịp quan trọng."}},{"hanzi":"衬衫","pinyin":"chènshān","hanViet":"SẤN SAM","meaning":"áo phông, áo phông","pos":"Danh từ","example":{"zh":"他穿了一件衬衫。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"穿","py":"chuān"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"件","py":"jiàn"},{"c":"衬","py":"chèn"},{"c":"衫","py":"shān"},{"c":"。","py":"。"}],"vi":"Anh ấy mặc một chiếc áo phông."}},{"hanzi":"成功","pinyin":"chénggōng","hanViet":"THÀNH CÔNG","meaning":"thành công","pos":"Tính từ","example":{"zh":"他成功了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy thành công."}},{"hanzi":"成就","pinyin":"chéngjiù","hanViet":"THÀNH TỰU","meaning":"thành tựu, thành công","pos":"Danh từ","example":{"zh":"她有很多成就。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"成","py":"chéng"},{"c":"就","py":"jiù"},{"c":"。","py":"。"}],"vi":"Cô ấy có nhiều thành tựu."}},{"hanzi":"除了","pinyin":"chúle","hanViet":"TRỪ LIỄU","meaning":"ngoài, trừ","pos":"Liên từ","example":{"zh":"除了他，我都去。","pinyinPerChar":[{"c":"除","py":"chú"},{"c":"了","py":"le"},{"c":"他","py":"tā"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"都","py":"dōu"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Ngoài anh ấy, tất cả chúng tôi đều đi."}},{"hanzi":"当地","pinyin":"dāngdì","hanViet":"ĐƯƠNG ĐỊA","meaning":"địa phương, nơi đây","pos":"Danh từ","example":{"zh":"当地人很友好。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"地","py":"dì"},{"c":"人","py":"rén"},{"c":"很","py":"hěn"},{"c":"友","py":"yǒu"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Người địa phương rất thân thiện."}},{"hanzi":"等待","pinyin":"děngdài","hanViet":"ĐẲNG ĐÃI","meaning":"Chờ đợi, trông chờ","pos":"Động từ","example":{"zh":"请等待一会儿。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"等","py":"děng"},{"c":"待","py":"dài"},{"c":"一","py":"yī"},{"c":"会","py":"huì"},{"c":"儿","py":"ér"},{"c":"。","py":"。"}],"vi":"Xin đợi một chút nhé."}},{"hanzi":"地区","pinyin":"dìqū","hanViet":"ĐỊA KHU","meaning":"Khu vực, vùng miền","pos":"Danh từ","example":{"zh":"这个地区很安静。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"地","py":"dì"},{"c":"区","py":"qū"},{"c":"很","py":"hěn"},{"c":"安","py":"ān"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Khu vực này rất yên tĩnh."}},{"hanzi":"订","pinyin":"dìng","hanViet":"ĐÍNH","meaning":"Đặt, ký kết, cam kết","pos":"Động từ","example":{"zh":"我订了一张票。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"订","py":"dìng"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"票","py":"piào"},{"c":"。","py":"。"}],"vi":"Tôi đã đặt một vé."}},{"hanzi":"定期","pinyin":"dìngqī","hanViet":"ĐỊNH KỲ","meaning":"Định kỳ, theo kỳ hạn","pos":"Tính từ","example":{"zh":"我们定期开会。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"定","py":"dìng"},{"c":"期","py":"qī"},{"c":"开","py":"kāi"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Chúng tôi họp định kỳ."}},{"hanzi":"东部","pinyin":"dōngbù","hanViet":"ĐÔNG BỘ","meaning":"Phía đông, vùng phía đông","pos":"Danh từ","example":{"zh":"东部很繁华。","pinyinPerChar":[{"c":"东","py":"dōng"},{"c":"部","py":"bù"},{"c":"很","py":"hěn"},{"c":"繁","py":"fán"},{"c":"华","py":"huá"},{"c":"。","py":"。"}],"vi":"Vùng phía đông rất sôi động."}},{"hanzi":"发表","pinyin":"fābiǎo","hanViet":"PHÁT BIỂU","meaning":"Xuất bản, công bố","pos":"Động từ","example":{"zh":"他发表文章。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"发","py":"fā"},{"c":"表","py":"biǎo"},{"c":"文","py":"wén"},{"c":"章","py":"zhāng"},{"c":"。","py":"。"}],"vi":"Cậu ấy xuất bản bài viết."}},{"hanzi":"房东","pinyin":"fángdōng","hanViet":"PHÒNG ĐÔNG","meaning":"chủ nhà","pos":"Danh từ","example":{"zh":"我租房子给房东。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"租","py":"zū"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"给","py":"gěi"},{"c":"房","py":"fáng"},{"c":"东","py":"dōng"},{"c":"。","py":"。"}],"vi":"Tôi thuê nhà cho chủ nhà."}},{"hanzi":"否定","pinyin":"fǒudìng","hanViet":"PHỦ ĐỊNH","meaning":"câu từ phủ định, từ chối","pos":"Tính từ","example":{"zh":"他否定了自己的错误。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"否","py":"fǒu"},{"c":"定","py":"dìng"},{"c":"了","py":"le"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"错","py":"cuò"},{"c":"误","py":"wù"},{"c":"。","py":"。"}],"vi":"Anh ấy phủ nhận lỗi của mình."}},{"hanzi":"否认","pinyin":"fǒurèn","hanVi