INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-2', 1, 'Gia đình & quan hệ (2)', '[{"hanzi":"父亲","pinyin":"fùqīn","hanViet":"PHỤ THÂN","meaning":"cha","pos":"Danh từ","example":{"zh":"我父亲是老师。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"父","py":"fù"},{"c":"亲","py":"qīn"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Cha tôi là giáo viên."}},{"hanzi":"各地","pinyin":"gèdì","hanViet":"CÁC ĐỊA","meaning":"các nơi, mọi nơi","pos":"Danh từ","example":{"zh":"他们去了各地。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"了","py":"le"},{"c":"各","py":"gè"},{"c":"地","py":"dì"},{"c":"。","py":"。"}],"vi":"Họ đã đến các nơi."}},{"hanzi":"工夫","pinyin":"gōngfu","hanViet":"CÔNG PHU","meaning":"thời gian, công sức","pos":"Danh từ","example":{"zh":"你这件事要花多少工夫？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"要","py":"yào"},{"c":"花","py":"huā"},{"c":"多","py":"duō"},{"c":"少","py":"shǎo"},{"c":"工","py":"gōng"},{"c":"夫","py":"fū"},{"c":"？","py":"？"}],"vi":"Việc này của bạn sẽ mất bao nhiêu công sức?"}},{"hanzi":"工具","pinyin":"gōngjù","hanViet":"CÔNG CỤ","meaning":"công cụ","pos":"Danh từ","example":{"zh":"我用工具修电脑。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"工","py":"gōng"},{"c":"具","py":"jù"},{"c":"修","py":"xiū"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"。","py":"。"}],"vi":"Tôi dùng công cụ sửa máy tính."}},{"hanzi":"工业","pinyin":"gōngyè","hanViet":"CÔNG NGHIỆP","meaning":"công nghiệp","pos":"Danh từ","example":{"zh":"这个城市发展工业很快。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"城","py":"chéng"},{"c":"市","py":"shì"},{"c":"发","py":"fā"},{"c":"展","py":"zhǎn"},{"c":"工","py":"gōng"},{"c":"业","py":"yè"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Thành phố này phát triển công nghiệp rất nhanh."}},{"hanzi":"公布","pinyin":"gōngbù","hanViet":"CÔNG BỐ","meaning":"công bố","pos":"Động từ","example":{"zh":"他们公布结果。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"公","py":"gōng"},{"c":"布","py":"bù"},{"c":"结","py":"jié"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Họ công bố kết quả."}},{"hanzi":"公共","pinyin":"gōnggòng","hanViet":"CÔNG CỘNG","meaning":"công cộng, chung","pos":"Tính từ","example":{"zh":"这是公共场所。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"公","py":"gōng"},{"c":"共","py":"gòng"},{"c":"场","py":"chǎng"},{"c":"所","py":"suǒ"},{"c":"。","py":"。"}],"vi":"Đây là nơi công cộng."}},{"hanzi":"公开","pinyin":"gōngkāi","hanViet":"CÔNG KHAI","meaning":"công khai","pos":"Tính từ","example":{"zh":"信息必须公开。","pinyinPerChar":[{"c":"信","py":"xìn"},{"c":"息","py":"xī"},{"c":"必","py":"bì"},{"c":"须","py":"xū"},{"c":"公","py":"gōng"},{"c":"开","py":"kāi"},{"c":"。","py":"。"}],"vi":"Thông tin phải công khai."}},{"hanzi":"公民","pinyin":"gōngmín","hanViet":"CÔNG DÂN","meaning":"người công dân","pos":"Danh từ","example":{"zh":"他是公民。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"公","py":"gōng"},{"c":"民","py":"mín"},{"c":"。","py":"。"}],"vi":"Anh ấy là công dân."}},{"hanzi":"公务员","pinyin":"gōngwùyuán","hanViet":"CÔNG VỤ VIÊN","meaning":"cán bộ công chức","pos":"Danh từ","example":{"zh":"她是公务员。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"公","py":"gōng"},{"c":"务","py":"wù"},{"c":"员","py":"yuán"},{"c":"。","py":"。"}],"vi":"Cô ấy là cán bộ công chức."}},{"hanzi":"功夫","pinyin":"gōngfu","hanViet":"CÔNG PHU","meaning":"kỹ năng, công năng","pos":"Danh từ","example":{"zh":"他有很多功夫。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"功","py":"gōng"},{"c":"夫","py":"fū"},{"c":"。","py":"。"}],"vi":"Anh ấy có nhiều kỹ năng."}},{"hanzi":"关注","pinyin":"guānzhù","hanViet":"QUAN CHÚ","meaning":"quan tâm, chú ý","pos":"Động từ","example":{"zh":"我关注健康。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"关","py":"guān"},{"c":"注","py":"zhù"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"。","py":"。"}],"vi":"Tôi quan tâm đến sức khỏe."}},{"hanzi":"观察","pinyin":"guānchá","hanViet":"QUAN SÁT","meaning":"quan sát, xem xét","pos":"Động từ","example":{"zh":"老师观察学生。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"观","py":"guān"},{"c":"察","py":"chá"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Giáo viên quan sát học sinh."}},{"hanzi":"观看","pinyin":"guānkàn","hanViet":"QUAN KHÁN","meaning":"xem, theo dõi","pos":"Động từ","example":{"zh":"我观看电视。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"观","py":"guān"},{"c":"看","py":"kàn"},{"c":"电","py":"diàn"},{"c":"视","py":"shì"},{"c":"。","py":"。"}],"vi":"Tôi xem TV."}},{"hanzi":"观众","pinyin":"guānzhòng","hanViet":"QUAN CHÚNG","meaning":"khán giả, người xem","pos":"Danh từ","example":{"zh":"观众很多。","pinyinPerChar":[{"c":"观","py":"guān"},{"c":"众","py":"zhòng"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"。","py":"。"}],"vi":"Khán giả rất nhiều."}},{"hanzi":"广播","pinyin":"guǎngbō","hanViet":"QUẢNG BÁ","meaning":"xem sóng, phát thanh","pos":"Danh từ","example":{"zh":"我听广播。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"听","py":"tīng"},{"c":"广","py":"guǎng"},{"c":"播","py":"bō"},{"c":"。","py":"。"}],"vi":"Tôi nghe sóng."}},{"hanzi":"规定","pinyin":"guīdìng","hanViet":"QUY ĐỊNH","meaning":"quy định, chỉ định","pos":"Danh từ","example":{"zh":"规定很严。","pinyinPerChar":[{"c":"规","py":"guī"},{"c":"定","py":"dìng"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"。","py":"。"}],"vi":"Quy định rất nghiêm khắc."}},{"hanzi":"基本上","pinyin":"jīběnshàng","hanViet":"CƠ BẢN THƯỢNG","meaning":"thông thường, hầu như","pos":"Phó từ","example":{"zh":"我基本上每天都去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"基","py":"jī"},{"c":"本","py":"běn"},{"c":"上","py":"shàng"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"都","py":"dōu"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi hầu như mỗi ngày đều đi học."}},{"hanzi":"技术","pin