INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-3', 2, 'Gia đình & quan hệ (3)', '[{"hanzi":"据说","pinyin":"jùshuō","hanViet":"CỨ THUYẾT","meaning":"Theo đồn, theo thông tin","pos":"Phó từ","example":{"zh":"据说他很聪明。","pinyinPerChar":[{"c":"据","py":"jù"},{"c":"说","py":"shuō"},{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"聪","py":"cōng"},{"c":"明","py":"míng"},{"c":"。","py":"。"}],"vi":"Theo đồn, anh ấy rất thông minh."}},{"hanzi":"决定","pinyin":"juédìng","hanViet":"QUYẾT ĐỊNH","meaning":"lựa chọn, quyết định","pos":"Động từ","example":{"zh":"他决定明天去北京。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"决","py":"jué"},{"c":"定","py":"dìng"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"去","py":"qù"},{"c":"北","py":"běi"},{"c":"京","py":"jīng"},{"c":"。","py":"。"}],"vi":"Anh ấy quyết định đi Bắc Kinh ngày mai."}},{"hanzi":"看起来","pinyin":"kàn qǐlái","hanViet":"KHÁN KHỞI LAI","meaning":"trông có vẻ","pos":"Động từ","example":{"zh":"他看起来很高。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"看","py":"kàn"},{"c":"起","py":"qǐ"},{"c":"来","py":"lái"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Anh ấy trông có vẻ rất cao."}},{"hanzi":"看上去","pinyin":"kàn shàngqù","hanViet":"KHÁN THƯỢNG KHỨ","meaning":"trông có vẻ","pos":"Động từ","example":{"zh":"这件衣服看上去不错。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"看","py":"kàn"},{"c":"上","py":"shàng"},{"c":"去","py":"qù"},{"c":"不","py":"bù"},{"c":"错","py":"cuò"},{"c":"。","py":"。"}],"vi":"Quần áo này trông có vẻ không xấu."}},{"hanzi":"科技","pinyin":"kējì","hanViet":"KHOA KỸ","meaning":"công nghệ","pos":"Danh từ","example":{"zh":"科技很重要。","pinyinPerChar":[{"c":"科","py":"kē"},{"c":"技","py":"jì"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Công nghệ rất quan trọng."}},{"hanzi":"客观","pinyin":"kèguān","hanViet":"KHÁCH QUAN","meaning":"đối xứng, khách quan","pos":"Tính từ","example":{"zh":"看法很客观。","pinyinPerChar":[{"c":"看","py":"kàn"},{"c":"法","py":"fǎ"},{"c":"很","py":"hěn"},{"c":"客","py":"kè"},{"c":"观","py":"guān"},{"c":"。","py":"。"}],"vi":"Cách nhìn rất đối xứng."}},{"hanzi":"空","pinyin":"kōng","hanViet":"KHÔNG","meaning":"trống, không","pos":"Tính từ","example":{"zh":"房间很空。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"很","py":"hěn"},{"c":"空","py":"kōng"},{"c":"。","py":"。"}],"vi":"Phòng trống."}},{"hanzi":"老太太","pinyin":"lǎotàitai","hanViet":"LÃO THÁI THÁI","meaning":"cô già, bà già","pos":"Danh từ","example":{"zh":"那位老太太很友好。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"位","py":"wèi"},{"c":"老","py":"lǎo"},{"c":"太","py":"tài"},{"c":"太","py":"tài"},{"c":"很","py":"hěn"},{"c":"友","py":"yǒu"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cô già đó rất thân thiện."}},{"hanzi":"老头儿","pinyin":"lǎotóur","hanViet":"LÃO ĐẦU NHI","meaning":"cụ già, ông già","pos":"Danh từ","example":{"zh":"老头儿在公园散步。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"头","py":"tóu"},{"c":"儿","py":"ér"},{"c":"在","py":"zài"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"散","py":"sàn"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Cụ già đang đi dạo công viên."}},{"hanzi":"离婚","pinyin":"líhūn","hanViet":"LY HÔN","meaning":"ly hôn","pos":"Danh từ","example":{"zh":"他们离婚了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"离","py":"lí"},{"c":"婚","py":"hūn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Họ ly hôn."}},{"hanzi":"毛","pinyin":"máo","hanViet":"MAO","meaning":"lông, lông động vật","pos":"Danh từ","example":{"zh":"这只猫有毛。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"只","py":"zhǐ"},{"c":"猫","py":"māo"},{"c":"有","py":"yǒu"},{"c":"毛","py":"máo"},{"c":"。","py":"。"}],"vi":"Con mèo này có lông."}},{"hanzi":"没用","pinyin":"méiyòng","hanViet":"MỘT DỤNG","meaning":"không có ích, vô dụng","pos":"Tính từ","example":{"zh":"这个方法没用。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"方","py":"fāng"},{"c":"法","py":"fǎ"},{"c":"没","py":"méi"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Phương pháp này không có ích."}},{"hanzi":"媒体","pinyin":"méitǐ","hanViet":"MÔI THỂ","meaning":"phương tiện truyền thông","pos":"Danh từ","example":{"zh":"媒体报道了这件事。","pinyinPerChar":[{"c":"媒","py":"méi"},{"c":"体","py":"tǐ"},{"c":"报","py":"bào"},{"c":"道","py":"dào"},{"c":"了","py":"le"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Phương tiện truyền thông đã báo cáo việc này."}},{"hanzi":"面对","pinyin":"miànduì","hanViet":"DIỆN ĐỐI","meaning":"Chịu mặt, đối mặt","pos":"Động từ","example":{"zh":"我们要面对困难。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"面","py":"miàn"},{"c":"对","py":"duì"},{"c":"困","py":"kùn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Chúng ta phải đối mặt với khó khăn."}},{"hanzi":"母亲","pinyin":"mǔqīn","hanViet":"MẪU THÂN","meaning":"Mẹ","pos":"Danh từ","example":{"zh":"我爱我的母亲。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"爱","py":"ài"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"母","py":"mǔ"},{"c":"亲","py":"qīn"},{"c":"。","py":"。"}],"vi":"Tôi yêu mẹ của mình."}},{"hanzi":"男子","pinyin":"nánzǐ","hanViet":"NAM TỬ","meaning":"người đàn ông, nam giới","pos":"Danh từ","example":{"zh":"他是男子。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"男","py":"nán"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Anh ấy là người đàn ông."}},{"hanzi":"能不能","pinyin":"néng bu néng","hanViet":"NĂNG BẤT NĂNG","meaning":"có thể không, có được không","pos":"Liên từ","example":{"zh":"你能不能帮我？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"能","py":"néng"},{"c":"不","py":"bù"},{"c":"能","py":"néng"},{"c":"帮","py":"bāng"},{"c":"我","py":"wǒ"},{"c":"？","py":"？"}],"vi":"Bạn có thể giúp tôi không?"}},{"hanzi":"农村","pinyin":"nóngcūn","hanViet":"NÔNG THÔN","meaning":"nông thôn","pos":"Danh từ","example":{"zh":"他们住在农村。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"农","py":"nóng"},{"c":"村","py":"cūn"},{"c":"。","py":"。"}],"vi":"Họ sống ở nông thôn."}},{"hanzi":"农民","pinyin":"nóngmín","hanViet":"NÔNG DÂN","meaning":"người nông dân","pos":"Danh từ","example":{"zh":"农民很辛苦。","pinyinPerChar":[{"c":"农","py":"nóng"},{"c":"民","py":"mín"},{"c":"很","py":"hěn"},{"c":"辛","py":"xīn"},{"c":"苦","py":"kǔ"},{"c":"。","py":"。"}],"vi":"Người nông dân rất mệt nhọc."}},{"hanzi":"农业","pinyin":"nóngyè","hanViet":"NÔNG NGHIỆP","meaning":"nông nghiệp","pos":"Danh từ","example":{"zh":"农业很重要。","pinyinPerChar":[{"c":"农","py":"nóng"},{"c":"业","py":"yè"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Nông nghiệp rất quan trọng."}},{"hanzi":"派","pinyin":"pài","hanViet":"PHÁI","meaning":"phân công, phân ra","pos":"Động từ","example":{"zh":"老师派我们做作业。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"派","py":"pài"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"做","py":"zuò"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Thầy giáo phân công cho chúng tôi làm bài tập."}},{"hanzi":"亲","pinyin":"qīn","hanViet":"THÂN","meaning":"gần gũi, thân thiết","pos":"Tính từ","example":{"zh":"他们是亲兄弟。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"是","py":"shì"},{"c":"亲","py":"qīn"},{"c":"兄","py":"xiōng"},{"c":"弟","py":"dì"},{"c":"。","py":"。"}],"vi":"Họ là anh em cùng cha mẹ."}},{"hanzi":"亲人","pinyin":"qīnrén","hanViet":"THÂN NHÂN","meaning":"người thân","pos":"Danh từ","example":{"zh":"我的亲人都在家。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"亲","py":"qīn"},{"c":"人","py":"rén"},{"c":"都","py":"dōu"},{"c":"在","py":"zài"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Người thân của tôi đều ở nhà."}},{"hanzi":"缺少","pinyin":"quēshǎo","hanViet":"KHUYẾT THIỂU","meaning":"thiếu, không đủ","pos":"Động từ","example":{"zh":"这里缺少水。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"缺","py":"quē"},{"c":"少","py":"shǎo"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Đây thiếu nước."}},{"hanzi":"确定","pinyin":"quèdìng","hanViet":"XÁC ĐỊNH","meaning":"chắc chắn, xác nhận","pos":"Động từ","example":{"zh":"我确定这个答案是对的。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"确","py":"què"},{"c":"定","py":"dìng"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"答","py":"dá"},{"c":"案","py":"àn"},{"c":"是","py":"shì"},{"c":"对","py":"duì"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Tôi chắc chắn câu trả lời này là đúng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-4', 3, 'Gia đình & quan hệ (4)', '[{"hanzi":"人工","pinyin":"réngōng","hanViet":"NHÂN CÔNG","meaning":"nhân công, làm bằng tay","pos":"Tính từ","example":{"zh":"这件衣服是人工制作的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"是","py":"shì"},{"c":"人","py":"rén"},{"c":"工","py":"gōng"},{"c":"制","py":"zhì"},{"c":"作","py":"zuò"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Áo này làm bằng tay."}},{"hanzi":"人群","pinyin":"rénqún","hanViet":"NHÂN QUẦN","meaning":"tập thể người, đám đông","pos":"Danh từ","example":{"zh":"人群中传来欢呼声。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"群","py":"qún"},{"c":"中","py":"zhōng"},{"c":"传","py":"chuán"},{"c":"来","py":"lái"},{"c":"欢","py":"huān"},{"c":"呼","py":"hū"},{"c":"声","py":"shēng"},{"c":"。","py":"。"}],"vi":"Đám đông lan toả tiếng hò hào."}},{"hanzi":"声明","pinyin":"shēngmíng","hanViet":"THANH MINH","meaning":"lời tuyên bố, tuyên bố","pos":"Danh từ","example":{"zh":"他发表了声明。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"发","py":"fā"},{"c":"表","py":"biǎo"},{"c":"了","py":"le"},{"c":"声","py":"shēng"},{"c":"明","py":"míng"},{"c":"。","py":"。"}],"vi":"Anh ấy đã phát biểu tuyên bố."}},{"hanzi":"事业","pinyin":"shìyè","hanViet":"SỰ NGHIỆP","meaning":"sự nghiệp, công việc","pos":"Danh từ","example":{"zh":"他热爱自己的事业。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"热","py":"rè"},{"c":"爱","py":"ài"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"事","py":"shì"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Anh ấy yêu nghề của mình."}},{"hanzi":"收看","pinyin":"shōukàn","hanViet":"THU KHÁN","meaning":"Xem truyền hình","pos":"Động từ","example":{"zh":"我每天收看新闻。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"收","py":"shōu"},{"c":"看","py":"kàn"},{"c":"新","py":"xīn"},{"c":"闻","py":"wén"},{"c":"。","py":"。"}],"vi":"Tôi xem tin tức mỗi ngày."}},{"hanzi":"受","pinyin":"s