INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-6', 5, 'Tính cách & phẩm chất', '[{"hanzi":"本事","pinyin":"běnshi","hanViet":"BẢN SỰ","meaning":"kỹ năng, tài năng","pos":"Danh từ","example":{"zh":"你有什么本事？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"有","py":"yǒu"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"本","py":"běn"},{"c":"事","py":"shì"},{"c":"？","py":"？"}],"vi":"Bạn có kỹ năng gì không?"}},{"hanzi":"成熟","pinyin":"chéngshú","hanViet":"THÀNH THỤC","meaning":"trưởng thành, chín","pos":"Tính từ","example":{"zh":"这个孩子很成熟。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"成","py":"chéng"},{"c":"熟","py":"shú"},{"c":"。","py":"。"}],"vi":"Con này rất trưởng thành."}},{"hanzi":"成长","pinyin":"chéngzhǎng","hanViet":"THÀNH TRƯỞNG","meaning":"sự trưởng thành, phát triển","pos":"Danh từ","example":{"zh":"孩子们在成长。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"成","py":"chéng"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Con cái đang lớn lên."}},{"hanzi":"个性","pinyin":"gèxìng","hanViet":"CÁ TÍNH","meaning":"tính cách, tính cách riêng","pos":"Danh từ","example":{"zh":"他有个性很强。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"个","py":"gè"},{"c":"性","py":"xìng"},{"c":"很","py":"hěn"},{"c":"强","py":"qiáng"},{"c":"。","py":"。"}],"vi":"Cậu ấy có tính cách rất mạnh."}},{"hanzi":"好好","pinyin":"hǎohǎo","hanViet":"HẢO HẢO","meaning":"cẩn thận, chăm chỉ","pos":"Phó từ","example":{"zh":"你要好好学习。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"要","py":"yào"},{"c":"好","py":"hǎo"},{"c":"好","py":"hǎo"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Bạn nên học chăm chỉ."}},{"hanzi":"坚持","pinyin":"jiānchí","hanViet":"KIÊN TRÌ","meaning":"bám chấp, kiên trì","pos":"Động từ","example":{"zh":"他坚持工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"坚","py":"jiān"},{"c":"持","py":"chí"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy kiên trì làm việc."}},{"hanzi":"节约","pinyin":"jiéyuē","hanViet":"TIẾT ƯỚC","meaning":"tiết kiệm","pos":"Động từ","example":{"zh":"我们应该节约用水。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"节","py":"jié"},{"c":"约","py":"yuē"},{"c":"用","py":"yòng"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Chúng ta nên tiết kiệm nước."}},{"hanzi":"尽量","pinyin":"jǐnliàng","hanViet":"TẬN LƯỢNG","meaning":"cố gắng, càng nhiều càng tốt","pos":"Phó từ","example":{"zh":"请尽量快点。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"尽","py":"jǐn"},{"c":"量","py":"liàng"},{"c":"快","py":"kuài"},{"c":"点","py":"diǎn"},{"c":"。","py":"。"}],"vi":"Hãy cố gắng nhanh càng tốt."}},{"hanzi":"可靠","pinyin":"kěkào","hanViet":"KHẢ KHÁO","meaning":"đáng tin cậy","pos":"Tính từ","example":{"zh":"他很可靠。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"可","py":"kě"},{"c":"靠","py":"kào"},{"c":"。","py":"。"}],"vi":"Anh ấy rất đáng tin cậy."}},{"hanzi":"信","pinyin":"xìn","hanViet":"TÍN","meaning":"tin tưởng, tin cậy, thư","pos":"Danh từ","example":{"zh":"我写了一封信。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"写","py":"xiě"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"封","py":"fēng"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Tôi đã viết một lá thư."}},{"hanzi":"信任","pinyin":"xìnrèn","hanViet":"TÍN NHIỆM","meaning":"Sự tin tưởng, tin cậy","pos":"Danh từ","example":{"zh":"我信任我的朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"信","py":"xìn"},{"c":"任","py":"rèn"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi tin tưởng bạn của tôi."}},{"hanzi":"性（积极性）","pinyin":"xìng(jījíxìng)","hanViet":"TÍNH TÍCH CỰC TÍNH","meaning":"Tính chất, tính cách, tính tích cực","pos":"Danh từ","example":{"zh":"他的积极性很高。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"积","py":"jī"},{"c":"极","py":"jí"},{"c":"性","py":"xìng"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Tính tích cực của cậu ấy rất cao."}},{"hanzi":"性格","pinyin":"xìnggé","hanViet":"TÍNH CÁCH","meaning":"Tính cách, tính cách người","pos":"Danh từ","example":{"zh":"她的性格很开朗。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"性","py":"xìng"},{"c":"格","py":"gé"},{"c":"很","py":"hěn"},{"c":"开","py":"kāi"},{"c":"朗","py":"lǎng"},{"c":"。","py":"。"}],"vi":"Tính cách của cô ấy rất mở."}},{"hanzi":"争取","pinyin":"zhēngqǔ","hanViet":"TRANH THỦ","meaning":"đấu tranh, nỗ lực giành","pos":"Động từ","example":{"zh":"争取更好的未来。","pinyinPerChar":[{"c":"争","py":"zhēng"},{"c":"取","py":"qǔ"},{"c":"更","py":"gèng"},{"c":"好","py":"hǎo"},{"c":"的","py":"de"},{"c":"未","py":"wèi"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Đấu tranh để có tương lai tốt hơn."}},{"hanzi":"终于","pinyin":"zhōngyú","hanViet":"CHUNG Ư","meaning":"cuối cùng, sau nhiều lần cố gắng","pos":"Phó từ","example":{"zh":"他终于完成了作业。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"终","py":"zhōng"},{"c":"于","py":"yú"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"了","py":"le"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Cậu ấy cuối cùng đã hoàn thành bài tập."}},{"hanzi":"追","pinyin":"zhuī","hanViet":"TRUY","meaning":"theo đuổi, nỗ lực","pos":"Động từ","example":{"zh":"他追赶了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"追","py":"zhuī"},{"c":"赶","py":"gǎn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ta đuổi theo."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-7', 6, 'Công việc & văn phòng', '[{"hanzi":"安排","pinyin":"ānpái","hanViet":"AN BÀI","meaning":"sắp xếp, tổ chức","pos":"Động từ","example":{"zh":"老师安排了作业。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"安","py":"ān"},{"c":"排","py":"pái"},{"c":"了","py":"le"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Giáo viên đã sắp xếp bài tập."}},{"hanzi":"部","pinyin":"bù","hanViet":"BỘ","meaning":"phòng ban, bộ phận","pos":"Danh từ","example":{"zh":"他在公司工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Cậu ấy làm việc tại công ty."}},{"hanzi":"部长","pinyin":"bùzhǎng","hanViet":"BỘ TRƯỞNG","meaning":"giám đốc, bộ trưởng","pos":"Danh từ","example":{"zh":"他是部长。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"部","py":"bù"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Cậu ấy là giám đốc."}},{"hanzi":"创业","pinyin":"chuàngyè","hanViet":"SÁNG NGHIỆP","meaning":"khởi nghiệp","pos":"Động từ","example":{"zh":"他创业成功。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"创","py":"chuàng"},{"c":"业","py":"yè"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Anh ấy khởi nghiệp thành công."}},{"hanzi":"负责","pinyin":"fùzé","hanViet":"PHỤ TRÁCH","meaning":"trách nhiệm, đảm bảo","pos":"Động từ","example":{"zh":"他负责这个项目。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"负","py":"fù"},{"c":"责","py":"zé"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"项","py":"xiàng"},{"c":"目","py":"mù"},{"c":"。","py":"。"}],"vi":"Anh ấy chịu trách nhiệm dự án này."}},{"hanzi":"工资","pinyin":"gōngzī","hanViet":"CÔNG TƯ","meaning":"lương","pos":"Danh từ","example":{"zh":"他每月拿到工资。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"月","py":"yuè"},{"c":"拿","py":"ná"},{"c":"到","py":"dào"},{"c":"工","py":"gōng"},{"c":"资","py":"zī