INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-9', 8, 'Ăn uống & ẩm thực (1)', '[{"hanzi":"按","pinyin":"àn","hanViet":"ÁN","meaning":"theo, dựa trên","pos":"Động từ","example":{"zh":"按时间做。","pinyinPerChar":[{"c":"按","py":"àn"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"做","py":"zuò"},{"c":"。","py":"。"}],"vi":"Làm theo thời gian."}},{"hanzi":"按照","pinyin":"ànzhào","hanViet":"ÁN CHIẾU","meaning":"theo cách, theo quy định","pos":"Liên từ","example":{"zh":"按照计划工作。","pinyinPerChar":[{"c":"按","py":"àn"},{"c":"照","py":"zhào"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Làm việc theo kế hoạch."}},{"hanzi":"保存","pinyin":"bǎocún","hanViet":"BẢO TỒN","meaning":"lưu trữ, bảo quản","pos":"Động từ","example":{"zh":"保存文件。","pinyinPerChar":[{"c":"保","py":"bǎo"},{"c":"存","py":"cún"},{"c":"文","py":"wén"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Lưu trữ tài liệu."}},{"hanzi":"报","pinyin":"bào","hanViet":"BÁO","meaning":"báo, đăng báo, báo cáo","pos":"Động từ","example":{"zh":"我每天看报纸。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"看","py":"kàn"},{"c":"报","py":"bào"},{"c":"纸","py":"zhǐ"},{"c":"。","py":"。"}],"vi":"Tôi mỗi ngày đọc báo."}},{"hanzi":"报到","pinyin":"bàodào","hanViet":"BÁO ĐÁO","meaning":"đăng ký, báo cáo đến nơi","pos":"Động từ","example":{"zh":"他今天早上报到。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"早","py":"zǎo"},{"c":"上","py":"shàng"},{"c":"报","py":"bào"},{"c":"到","py":"dào"},{"c":"。","py":"。"}],"vi":"Anh ấy hôm nay sáng báo cáo đến nơi."}},{"hanzi":"报道","pinyin":"bàodào","hanViet":"BÁO ĐẠO","meaning":"báo cáo, tin tức, đăng báo","pos":"Danh từ","example":{"zh":"这篇报道很有意思。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"篇","py":"piān"},{"c":"报","py":"bào"},{"c":"道","py":"dào"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py"