INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-10', 9, 'Ăn uống & ẩm thực (2)', '[{"hanzi":"防止","pinyin":"fángzhǐ","hanViet":"PHÒNG CHỈ","meaning":"ngăn chặn, tránh","pos":"Động từ","example":{"zh":"请防止生病。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"防","py":"fáng"},{"c":"止","py":"zhǐ"},{"c":"生","py":"shēng"},{"c":"病","py":"bìng"},{"c":"。","py":"。"}],"vi":"Vui lòng tránh bệnh."}},{"hanzi":"概念","pinyin":"gàiniàn","hanViet":"KHÁI NIỆM","meaning":"khái niệm","pos":"Danh từ","example":{"zh":"这个概念很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"概","py":"gài"},{"c":"念","py":"niàn"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Khái niệm này rất quan trọng."}},{"hanzi":"干吗","pinyin":"gànmá","hanViet":"CÁN MA","meaning":"tại sao","pos":"Phó từ","example":{"zh":"你干吗不吃饭？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"干","py":"gàn"},{"c":"吗","py":"ma"},{"c":"不","py":"bù"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"？","py":"？"}],"vi":"Bạn tại sao không ăn cơm?"}},{"hanzi":"告别","pinyin":"gàobié","hanViet":"CÁO BIỆT","meaning":"tạm biệt","pos":"Động từ","example":{"zh":"他们告别了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"告","py":"gào"},{"c":"别","py":"bié"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Họ tạm biệt."}},{"hanzi":"个人","pinyin":"gèrén","hanViet":"CÁ NHÂN","meaning":"cá nhân, người","pos":"Danh từ","example":{"zh":"每个人都有自己的个人。","pinyinPerChar":[{"c":"每","py":"měi"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"都","py":"dōu"},{"c":"有","py":"yǒu"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Mỗi người đều có quyền cá nhân."}},{"hanzi":"各","pinyin":"gè","hanViet":"CÁC","meaning":"mỗi, các","pos":"Tính từ","example":{"zh":"各个国家都很大。","pinyinPerChar":[{"c":"各","py":"gè"},{"c":"个","py":"gè"},{"c":"国","py":"guó"},{"c":"家","py":"jiā"},{"c":"都","py":"dōu"},{"c"