INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-13', 12, 'Mua sắm & tiền bạc', '[{"hanzi":"底下","pinyin":"dǐxia","hanViet":"ĐỂ HẠ","meaning":"Dưới, phía dưới","pos":"Danh từ","example":{"zh":"书在桌子底下。","pinyinPerChar":[{"c":"书","py":"shū"},{"c":"在","py":"zài"},{"c":"桌","py":"zhuō"},{"c":"子","py":"zi"},{"c":"底","py":"dǐ"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Sách ở dưới bàn."}},{"hanzi":"费","pinyin":"fèi","hanViet":"PHÍ","meaning":"tiền, phí, tốn","pos":"Danh từ","example":{"zh":"这个东西很贵。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Món này đắt tiền."}},{"hanzi":"费用","pinyin":"fèiyong","hanViet":"PHÍ DỤNG","meaning":"chi phí","pos":"Danh từ","example":{"zh":"请带上所有费用。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"带","py":"dài"},{"c":"上","py":"shàng"},{"c":"所","py":"suǒ"},{"c":"有","py":"yǒu"},{"c":"费","py":"fèi"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Vui lòng mang theo tất cả chi phí."}},{"hanzi":"丰富","pinyin":"fēngfù","hanViet":"PHONG PHÚ","meaning":"giàu có, phong phú","pos":"Tính từ","example":{"zh":"这个地方很丰富。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"地","py":"dì"},{"c":"方","py":"fāng"},{"c":"很","py":"hěn"},{"c":"丰","py":"fēng"},{"c":"富","py":"fù"},{"c":"。","py":"。"}],"vi":"Nơi đây rất phong phú."}},{"hanzi":"富","pinyin":"fù","hanViet":"PHÚ","meaning":"giàu, phú","pos":"Tính từ","example":{"zh":"他很富有。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"富","py":"fù"},{"c":"有","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Anh ấy rất giàu có."}},{"hanzi":"后面","pinyin":"hòumiàn","hanViet":"HẬU DIỆN","meaning":"phía sau, sau","pos":"Danh từ","example":{"zh":"书在后面。","pinyinPerChar":[{"c":"书","py":"shū"},{"c":"在","py":"zài"},{"c":"后","py":"hòu"},{"c":"面","py":"miàn"},{"c":"。","py":"。"}],"vi":"Sách ở phía sau."}},{"hanzi":"价格","pinyin":"jiàgé","hanViet":"GIÁ CÁ