INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-14', 13, 'Du lịch & giao thông', '[{"hanzi":"爱心","pinyin":"àixīn","hanViet":"ÁI TÂM","meaning":"tình yêu, sự trân trọng","pos":"Danh từ","example":{"zh":"他有很爱心。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"爱","py":"ài"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Anh ấy rất yêu thương người khác."}},{"hanzi":"重","pinyin":"chóng","hanViet":"TRỌNG","meaning":"khối lượng lớn; quan trọng","pos":"Tính từ","example":{"zh":"这本书很重。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"。","py":"。"}],"vi":"Cuốn sách này rất nặng."}},{"hanzi":"飞行","pinyin":"fēixíng","hanViet":"PHI HÀNH","meaning":"bay, phóng bay","pos":"Động từ","example":{"zh":"飞机在天上飞行。","pinyinPerChar":[{"c":"飞","py":"fēi"},{"c":"机","py":"jī"},{"c":"在","py":"zài"},{"c":"天","py":"tiān"},{"c":"上","py":"shàng"},{"c":"飞","py":"fēi"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Máy bay bay trên trời."}},{"hanzi":"高速","pinyin":"gāosù","hanViet":"CAO TỐC","meaning":"tốc độ cao","pos":"Tính từ","example":{"zh":"这条路很高速。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"速","py":"sù"},{"c":"。","py":"。"}],"vi":"Con đường này rất cao tốc."}},{"hanzi":"高速公路","pinyin":"gāosù gōnglù","hanViet":"CAO TỐC CÔNG LỘ","meaning":"đường cao tốc","pos":"Danh từ","example":{"zh":"他们开车上高速公路。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"开","py":"kāi"},{"c":"车","py":"chē"},{"c":"上","py":"shàng"},{"c":"高","py":"gāo"},{"c":"速","py":"sù"},{"c":"公","py":"gōng"},{"c":"路","py":"lù"},{"c":"。","py":"。"}],"vi":"Họ lái xe lên đường cao tốc."}},{"hanzi":"立刻","pinyin":"lìkè","hanViet":"LẬP KHẮC","meaning":"ngay lập tức","pos":"Phó từ","example":{"zh":"我立刻明白了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"立","py":"lì"},{"c":"刻","py":"kè"},{"c":"明","py":"míng"},{"c":"白","py":"bái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tôi hiểu ngay lập tức."}},{"hanzi":"连忙","pinyin":"liánmáng","hanViet":"LIÊN MANG","meaning":"ngay lập tức, vội vã","pos":"Phó từ","example":{"zh":"他连忙跑了过去。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"连","py":"lián"},{"c":"忙","py":"máng"},{"c":"跑","py":"pǎo"},{"c":"了","py":"le"},{"c":"过","py":"guò"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Anh ấy vội vã chạy đến."}},{"hanzi":"路线","pinyin":"lùxiàn","hanViet":"LỘ TUYẾN","meaning":"đường đi, lộ trình","pos":"Danh từ","example":{"zh":"这条路线很安全。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"线","py":"xiàn"},{"c":"很","py":"hěn"},{"c":"安","py":"ān"},{"c":"全","py":"quán"},{"c":"。","py":"。"}],"vi":"Lộ trình này rất an toàn."}},{"hanzi":"旅馆","pinyin":"lǚguǎn","hanViet":"LỮ QUÁN","meaning":"nhà nghỉ, khách sạn","pos":"Danh từ","example":{"zh":"我们住在旅馆。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"旅","py":"lǚ"},{"c":"馆","py":"guǎn"},{"c":"。","py":"。"}],"vi":"Chúng tôi ở ở khách sạn."}},{"hanzi":"旅行社","pinyin":"lǚxíngshè","hanViet":"LỮ HÀNH XÃ","meaning":"xã hội du lịch","pos":"Danh từ","example":{"zh":"他们去旅行社买票。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"旅","py":"lǚ"},{"c":"行","py":"xíng"},{"c":"社","py":"shè"},{"c":"买","py":"mǎi"},{"c":"票","py":"piào"},{"c":"。","py":"。"}],"vi":"Họ đi chợ du lịch mua vé."}},{"hanzi":"配","pinyin":"pèi","hanViet":"PHỐI","meaning":"phối, hợp, phù hợp","pos":"Động từ","example":{"zh":"这件衣服配好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"配","py":"pèi"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cái áo này phu hợp."}},{"hanzi":"配合","pinyin":"pèihé","hanViet":"PHỐI HỢP","meaning":"phối hợp, cộng tác","pos":"Danh từ","example":{"zh":"他们配合得很好。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"配","py":"pèi"},{"c":"合","py":"hé"},{"c":"得","py":"dé"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Họ phối hợp rất tốt."}},{"hanzi":"强烈","pinyin":"qiángliè","hanViet":"CƯỜNG LIỆT","meaning":"Mạnh, gay gắt","pos":"Tính từ","example":{"zh":"他有强烈的愿望。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"强","py":"qiáng"},{"c":"烈","py":"liè"},{"c":"的","py":"de"},{"c":"愿","py":"yuàn"},{"c":"望","py":"wàng"},{"c":"。","py":"。"}],"vi":"Anh ấy có mong muốn rất mạnh."}},{"hanzi":"散步","pinyin":"sànbù","hanViet":"TÁN BỘ","meaning":"đi bộ","pos":"Động từ","example":{"zh":"我喜欢下午散步。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"下","py":"xià"},{"c":"午","py":"wǔ"},{"c":"散","py":"sàn"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Tôi thích đi bộ buổi chiều."}},{"hanzi":"速度","pinyin":"sùdù","hanViet":"TỐC ĐỘ","meaning":"tốc độ","pos":"Danh từ","example":{"zh":"他的跑步速度很快。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"跑","py":"pǎo"},{"c":"步","py":"bù"},{"c":"速","py":"sù"},{"c":"度","py":"dù"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Tốc độ chạy của anh ấy rất nhanh."}},{"hanzi":"图","pinyin":"tú","hanViet":"ĐỒ","meaning":"sẽ, định, vẽ, bản đồ","pos":"Danh từ","example":{"zh":"他画了一张图。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"画","py":"huà"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"图","py":"tú"},{"c":"。","py":"。"}],"vi":"Anh ấy vẽ một bức tranh."}},{"hanzi":"重大","pinyin":"zhòngdà","hanViet":"TRỌNG ĐẠI","meaning":"quan trọng, nghiêm trọng","pos":"Tính từ","example":{"zh":"这是一个重大事件。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"重","py":"zhòng"},{"c":"大","py":"dà"},{"c":"事","py":"shì"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Đây là một sự kiện quan trọng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-15', 14, 'Thời gian & lịch (1)', '[{"hanzi":"曾经","pinyin":"céngjīng","hanViet":"TỪNG KINH","meaning":"từng, đã từng","pos":"Phó từ","example":{"zh":"我曾经去过北京。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"曾","py":"céng"},{"c":"经","py":"jīng"},{"c":"去","py":"qù"},{"c":"过","py":"guò"},{"c":"北","py":"běi"},{"c":"京","py":"jīng"},{"c":"。","py":"。"}],"vi":"Tôi từng đi Bắc Kinh."}},{"hanzi":"持续","pinyin":"chíxù","hanViet":"TRÌ TỤC","meaning":"liên tục, kéo dài","pos":"Động từ","example":{"zh":"天气持续晴天。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"持","py":"chí"},{"c":"续","py":"xù"},{"c":"晴","py":"qíng"},{"c":"天","py":"tiān"},{"c":"。","py":"。"}],"vi":"Thời tiết tiếp tục đẹp trời."}},{"hanzi":"初（初一）","pinyin":"chū (chūyī)","hanViet":"SƠ SƠ NHẤT","meaning":"ngày đầu tiên trong tháng","pos":"Danh từ","example":{"zh":"今天是初一。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"是","py":"shì"},{"c":"初","py":"chū"},{"c":"一","py":"yī"},{"c":"。","py":"。"}],"vi":"Hôm nay là ngày đầu tiên của tháng."}},{"hanzi":"创作","pinyin":"chuàngzuò","hanViet":"SÁNG TÁC","meaning":"sáng tác, tạo tác","pos":"Động từ","example":{"zh":"他创作了一首诗。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"创","py":"chuàng"},{"c":"作","py":"zuò"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"首","py":"shǒu"},{"c":"诗","py":"shī"},{"c":"。","py":"。"}],"vi":"Anh ấy đã sáng tác một bài thơ."}},{"hanzi":"从来","pinyin":"cónglái","hanViet":"TÒNG LAI","meaning":"từ trước, bao giờ","pos":"Phó từ","example":{"zh":"我从来没有去过。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"从","py":"cóng"},{"c":"来","py":"lái"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"去","py":"qù"},{"c":"过","py":"guò"},{"c":"。","py":"。"}],"vi":"Tôi chưa bao giờ đi."}},{"hanzi":"大约","pinyin":"dàyuē","hanViet":"ĐẠI ƯỚC","meaning":"khoảng, khoảng thời gian","pos":"Phó từ","example":{"zh":"大约三天。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"约","py":"yuē"},{"c":"三","py":"sān"},{"c":"天","py":"tiān"},{"c":"。","py":"。"}],"vi":"Khoảng ba ngày."}},{"hanzi":"当初","pinyin":"dāngchū","hanViet":"ĐƯƠNG SƠ","meaning":"vào lúc đầu, lúc đó","pos":"Danh từ","example":{"zh":"当初我不知道。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"初","py":"chū"},{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"。","py":"。"}],"vi":"Lúc đầu tôi không biết."}},{"hanzi":"顿","pinyin":"dùn","hanViet":"ĐỐN","meaning":"Lần, khoảng thời gian","pos":"Danh từ","example":{"zh":"一顿饭。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"顿","py":"dùn"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Một bữa ăn."}},{"hanzi":"发明","pinyin":"fāmíng","hanViet":"PHÁT MINH","meaning":"Khám phá, sáng chế","pos":"Động từ","example":{"zh":"他发明新东西。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"发","py":"fā"},{"c":"明","py":"míng"},{"c":"新","py":"xīn"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"。","py":"。"}],"vi":"Cậu ấy khám phá vật phẩm mới."}},{"hanzi":"赶紧","pinyin":"gǎnjǐn","hanViet":"CẢN KHẨN","meaning":"vội vã, sớm","pos":"Phó từ","example":{"zh":"你赶紧走吧。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"赶","py":"gǎn"},{"c":"紧","py":"jǐn"},{"c":"走","py":"zǒu"},{"c":"吧","py":"ba"},{"c":"。","py":"。"}],"vi":"Bạn hãy đi nhanh đi."}},{"hanzi":"赶快","pinyin":"gǎnkuài","hanViet":"CẢN KHOÁI","meaning":"làm nhanh, sớm","pos":"Phó từ","example":{"zh":"我们赶快吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"赶","py":"gǎn"},{"c":"快","py":"kuài"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Chúng tôi hãy ăn nhanh."}},{"hanzi":"光","pinyin":"guāng","hanViet":"QUANG","meaning":"ánh sáng, chỉ một phần","pos":"Tính từ","example":{"zh":"光明天。","pinyinPerChar":[{"c":"光","py":"guāng"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"。","py":"。"}],"vi":"Ngày đẹp trời."}},{"hanzi":"光明","pinyin":"guāngmíng","hanViet":"QUANG MINH","meaning":"sáng, minh mẫn","pos":"Tính từ","example":{"zh":"光明的天气。","pinyinPerChar":[{"c":"光","py":"guāng"},{"c":"明","py":"míng"},{"c":"的","py":"de"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Thời tiết sáng sủa."}},{"hanzi":"国庆","pinyin":"guóqìng","hanViet":"QUỐC KHÁNH","meaning":"ngày lễ quốc gia","pos":"Danh từ","example":{"zh":"国庆快乐。","pinyinPerChar":[{"c":"国","py":"guó"},{"c":"庆","py":"qìng"},{"c":"快","py":"kuài"},{"c":"乐","py":"lè"},{"c":"。","py":"。"}],"vi":"Chúc mừng Quốc khánh."}},{"hanzi":"后年","pinyin":"hòunián","hanViet":"HẬU NIÊN","meaning":"năm sau năm nay","pos":"Danh từ","example":{"zh":"我后年结婚。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"后","py":"hòu"},{"c":"年","py":"nián"},{"c":"结","py":"jié"},{"c":"婚","py":"hūn"},{"c":"。","py":"。"}],"vi":"Tôi sẽ kết hôn năm sau năm nay."}},{"hanzi":"及时","pinyin":"jíshí","hanViet":"CẬP THỜI","meaning":"kịp thời, đúng lúc","pos":"Tính từ","example":{"zh":"请及时完成作业。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"及","py":"jí"},{"c":"时","py":"shí"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Vui lòng hoàn thành bài tập đúng thời gian."}},{"hanzi":"将来","pinyin":"jiānglái","hanViet":"TƯƠNG LAI","meaning":"tương lai, trong tương lai","pos":"Danh từ","example":{"zh":"将来我要当老师。","pinyinPerChar":[{"c":"将","py":"jiāng"},{"c":"来","py":"lái"},{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"当","py":"dāng"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Tôi sẽ làm giáo viên trong tương lai."}},{"hanzi":"紧","pinyin":"jǐn","hanViet":"KHẨN","meaning":"gấp gáp, khẩn cấp","pos":"Tính từ","example":{"zh":"他很紧张。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"紧","py":"jǐn"},{"c":"张","py":"zhāng"},{"c":"。","py":"。"}],"vi":"Cậu ấy rất gấp gáp."}},{"hanzi":"近期","pinyin":"jìnqī","hanViet":"CẬN KỲ","meaning":"gần đây, trong thời gian gần","pos":"Danh từ","example":{"zh":"近期有很多活动。","pinyinPerChar":[{"c":"近","py":"jìn"},{"c":"期","py":"qī"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Gần đây có nhiều hoạt động."}},{"hanzi":"空儿","pinyin":"kòngr","hanViet":"KHÔNG NHI","meaning":"khoảng thời gian trống rỗng, khoảng trống","pos":"Danh từ","example":{"zh":"你有空儿吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"有","py":"yǒu"},{"c":"空","py":"kōng"},{"c":"儿","py":"ér"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn có thời gian trống không?"}},{"hanzi":"落后","pinyin":"luòhòu","hanViet":"LẠC HẬU","meaning":"trễ, chậm, thua kém","pos":"Tính từ","example":{"zh":"他落后于别人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"落","py":"luò"},{"c":"后","py":"hòu"},{"c":"于","py":"yú"},{"c":"别","py":"bié"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy thua kém người khác."}},{"hanzi":"慢慢","pinyin":"mànmàn","hanViet":"MẠN MẠN","meaning":"chậm rãi, từ từ","pos":"Phó từ","example":{"zh":"慢慢走。","pinyinPerChar":[{"c":"慢","py":"màn"},{"c":"慢","py":"màn"},{"c":"走","py":"zǒu"},{"c":"。","py":"。"}],"vi":"Dần dần đi."}},{"hanzi":"目前","pinyin":"mùqián","hanViet":"MỤC TIỀN","meaning":"Hiện tại, hiện nay","pos":"Tính từ","example":{"zh":"目前没有问题。","pinyinPerChar":[{"c":"目","py":"mù"},{"c":"前","py":"qián"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Hiện tại không có vấn đề."}},{"hanzi":"年初","pinyin":"niánchū","hanViet":"NIÊN SƠ","meaning":"đầu năm","pos":"Danh từ","example":{"zh":"年初我去了北京。","pinyinPerChar":[{"c":"年","py":"nián"},{"c":"初","py":"chū"},{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"了","py":"le"},{"c":"北","py":"běi"},{"c":"京","py":"jīng"},{"c":"。","py":"。"}],"vi":"Đầu năm tôi đi Bắc Kinh."}},{"hanzi":"年代","pinyin":"niándài","hanViet":"NIÊN ĐẠI","meaning":"thời đại, thời gian","pos":"Danh từ","example":{"zh":"这个年代很快。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"年","py":"nián"},{"c":"代","py":"dài"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Thời đại này rất nhanh."}}]');
