INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-21', 20, 'Quần áo & màu sắc', '[{"hanzi":"保证","pinyin":"bǎozhèng","hanViet":"BẢO CHỨNG","meaning":"đảm bảo, cam kết","pos":"Danh từ","example":{"zh":"这件事他保证没错。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"他","py":"tā"},{"c":"保","py":"bǎo"},{"c":"证","py":"zhèng"},{"c":"没","py":"méi"},{"c":"错","py":"cuò"},{"c":"。","py":"。"}],"vi":"Việc này anh ấy bảo đảm không sai."}},{"hanzi":"必然","pinyin":"bìrán","hanViet":"TẤT NHIÊN","meaning":"chắc chắn, tất yếu","pos":"Tính từ","example":{"zh":"这件事必然会成功。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"必","py":"bì"},{"c":"然","py":"rán"},{"c":"会","py":"huì"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Việc này chắc chắn sẽ thành công."}},{"hanzi":"彩色","pinyin":"cǎisè","hanViet":"THÁI SẮC","meaning":"màu sắc","pos":"Tính từ","example":{"zh":"这件衣服很漂亮，颜色很彩色。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"，","py":"，"},{"c":"颜","py":"yán"},{"c":"色","py":"sè"},{"c":"很","py":"hěn"},{"c":"彩","py":"cǎi"},{"c":"色","py":"sè"},{"c":"。","py":"。"}],"vi":"áo này rất xinh, màu sắc rất đẹp."}},{"hanzi":"衬衣","pinyin":"chènyī","hanViet":"SẤN Y","meaning":"áo phông, áo lụa","pos":"Danh từ","example":{"zh":"她买了一件衬衣。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"买","py":"mǎi"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"件","py":"jiàn"},{"c":"衬","py":"chèn"},{"c":"衣","py":"yī"},{"c":"。","py":"。"}],"vi":"Cô ấy mua một chiếc áo phông."}},{"hanzi":"当然","pinyin":"dāngrán","hanViet":"ĐƯƠNG NHIÊN","meaning":"tất nhiên, chắc chắn","pos":"Phó từ","example":{"zh":"当然可以。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"然","py":"rán"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"。","py":"。"}],"vi":"Tất nhiên được."}},{"hanzi":"调","pinyin":"