INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-22', 21, 'Giao tiếp & lời nói', '[{"hanzi":"表明","pinyin":"biǎomíng","hanViet":"BIỂU MINH","meaning":"thể hiện","pos":"Động từ","example":{"zh":"他的眼睛表明他很高兴。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"眼","py":"yǎn"},{"c":"睛","py":"jīng"},{"c":"表","py":"biǎo"},{"c":"明","py":"míng"},{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xīng"},{"c":"。","py":"。"}],"vi":"Mắt anh ấy thể hiện anh ấy rất vui."}},{"hanzi":"传说","pinyin":"chuánshuō","hanViet":"TRUYỀN THUYẾT","meaning":"truyền thuyết, được nói đến","pos":"Danh từ","example":{"zh":"这是一个传说。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"传","py":"chuán"},{"c":"说","py":"shuō"},{"c":"。","py":"。"}],"vi":"Đây là một truyện cổ tích."}},{"hanzi":"打听","pinyin":"dǎting","hanViet":"ĐẢ THÍNH","meaning":"tìm hiểu, hỏi đáp","pos":"Động từ","example":{"zh":"我想打听一下。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"打","py":"dǎ"},{"c":"听","py":"tīng"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Tôi muốn tìm hiểu thêm."}},{"hanzi":"电视台","pinyin":"diànshìtái","hanViet":"ĐIỆN THỊ ĐÀI","meaning":"Trạm phát thanh, nhà máy truyền hình","pos":"Danh từ","example":{"zh":"电视台在哪里？","pinyinPerChar":[{"c":"电","py":"diàn"},{"c":"视","py":"shì"},{"c":"台","py":"tái"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Trạm phát thanh ở đâu?"}},{"hanzi":"电子邮件","pinyin":"diànzǐ yóujiàn","hanViet":"ĐIỆN TỬ BƯU KIỆN","meaning":"Thư điện tử, email","pos":"Danh từ","example":{"zh":"请给我发电子邮件。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"发","py":"fā"},{"c":"电","py":"diàn"},{"c":"子","py":"zi"},{"c":"邮","py":"yóu"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Vui lòng gửi cho tôi email."}},{"hanzi":"发言","pinyin":"fāyán","hanViet":"PHÁT NGÔN","meaning":"Nói, phát biểu","pos":"Động từ","example":{"zh":"他发言。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"发","py":"fā"},{"c":"言","py":"yán"},{"c":"。","py":"。"}],"vi":"Cậu ấy nói."}},{"hanzi":"反对","pinyin":"fǎnduì","hanViet":"PHẢN ĐỐI","meaning":"Phản đối","pos":"Động từ","example":{"zh":"他反对这个计划。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"反","py":"fǎn"},{"c":"对","py":"duì"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"。","py":"。"}],"vi":"Cậu ấy phản đối kế hoạch này."}},{"hanzi":"访问","pinyin":"fǎngwèn","hanViet":"PHỎNG VẤN","meaning":"đến thăm, thăm hỏi","pos":"Động từ","example":{"zh":"他访问了很多国家。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"访","py":"fǎng"},{"c":"问","py":"wèn"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"国","py":"guó"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Anh ấy đã thăm nhiều nước."}},{"hanzi":"话题","pinyin":"huàtí","hanViet":"THOẠI ĐỀ","meaning":"chủ đề, vấn đề thảo luận","pos":"Danh từ","example":{"zh":"这个话题很有意思。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"话","py":"huà"},{"c":"题","py":"tí"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Chủ đề này rất thú vị."}},{"hanzi":"建议","pinyin":"jiànyì","hanViet":"KIẾN NGHỊ","meaning":"gợi ý, đề xuất","pos":"Danh từ","example":{"zh":"他提出了一个建议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"提","py":"tí"},{"c":"出","py":"chū"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"建","py":"jiàn"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Anh ấy đã đưa ra một đề xuất."}},{"hanzi":"老百姓","pinyin":"lǎobǎixìng","hanViet":"LÃO BÁCH TÍNH","meaning":"người dân, người thường","pos":"Danh từ","example":{"zh":"老百姓生活很辛苦。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"百","py":"bǎi"},{"c":"姓","py":"xìng"},{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"很","py":"hěn"},{"c":"辛","py":"xīn"},{"c":"苦","py":"kǔ"},{"c":"。","py":"。"}],"vi":"Người dân sống rất vất vả."}},{"hanzi":"联系","pinyin":"liánxì","hanViet":"LIÊN HỆ","meaning":"liên hệ, liên lạc","pos":"Danh từ","example":{"zh":"请保持联系。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"保","py":"bǎo"},{"c":"持","py":"chí"},{"c":"联","py":"lián"},{"c":"系","py":"xì"},{"c":"。","py":"。"}],"vi":"Hãy giữ liên lạc."}},{"hanzi":"奇怪","pinyin":"qíguài","hanViet":"KỲ QUÁI","meaning":"Bất thường, lạ","pos":"Tính từ","example":{"zh":"这个问题很奇怪。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"很","py":"hěn"},{"c":"奇","py":"qí"},{"c":"怪","py":"guài"},{"c":"。","py":"。"}],"vi":"Câu hỏi này rất lạ."}},{"hanzi":"请教","pinyin":"qǐngjiào","hanViet":"THỈNH GIÁO","meaning":"nhờ hỏi, xin ý kiến","pos":"Động từ","example":{"zh":"我请教您一个问题。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"请","py":"qǐng"},{"c":"教","py":"jiào"},{"c":"您","py":"nín"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Tôi xin hỏi anh ấy một câu."}},{"hanzi":"确实","pinyin":"quèshí","hanViet":"XÁC THỰC","meaning":"thật vậy, đúng như đã nói","pos":"Tính từ","example":{"zh":"这件衣服确实很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"确","py":"què"},{"c":"实","py":"shí"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Cái áo này thật đẹp."}},{"hanzi":"任","pinyin":"rèn","hanViet":"NHIỆM","meaning":"tuy nhiên, bất kể","pos":"Liên từ","example":{"zh":"任你怎么说，我都不信。","pinyinPerChar":[{"c":"任","py":"rèn"},{"c":"你","py":"nǐ"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"说","py":"shuō"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"都","py":"dōu"},{"c":"不","py":"bù"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Dù bạn nói thế nào, tôi cũng không tin."}},{"hanzi":"收听","pinyin":"shōutīng","hanViet":"THU THÍNH","meaning":"Nghe radio, nghe phát thanh","pos":"Động từ","example":{"zh":"她收听广播。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"收","py":"shōu"},{"c":"听","py":"tīng"},{"c":"广","py":"guǎng"},{"c":"播","py":"bō"},{"c":"。","py":"。"}],"vi":"Cô ấy nghe phát thanh."}},{"hanzi":"谈","pinyin":"tán","hanViet":"ĐÀM","meaning":"nói chuyện, thảo luận","pos":"Động từ","example":{"zh":"我们明天谈生意。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"谈","py":"tán"},{"c":"生","py":"shēng"},{"c":"意","py":"yì"},{"c":"。","py":"。"}],"vi":"Chúng tôi sẽ thảo luận về kinh doanh vào ngày mai."}},{"hanzi":"谈话","pinyin":"tánhuà","hanViet":"ĐÀM THOẠI","meaning":"cuộc trò chuyện, cuộc nói chuyện","pos":"Danh từ","example":{"zh":"他们进行了一次长谈话。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"进","py":"jìn"},{"c":"行","py":"xíng"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"次","py":"cì"},{"c":"长","py":"zhǎng"},{"c":"谈","py":"tán"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Họ đã có một cuộc trò chuyện dài."}},{"hanzi":"提问","pinyin":"tíwèn","hanViet":"ĐỀ VẤN","meaning":"nói câu hỏi","pos":"Động từ","example":{"zh":"老师提问了我们一个问题。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"提","py":"tí"},{"c":"问","py":"wèn"},{"c":"了","py":"le"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Giáo viên đã đặt câu hỏi cho chúng tôi."}},{"hanzi":"往往","pinyin":"wǎngwǎng","hanViet":"VÃNG VÃNG","meaning":"thường xuyên, thường","pos":"Phó từ","example":{"zh":"他往往迟到。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"往","py":"wǎng"},{"c":"往","py":"wǎng"},{"c":"迟","py":"chí"},{"c":"到","py":"dào"},{"c":"。","py":"。"}],"vi":"Anh ấy thường đến muộn."}},{"hanzi":"消息","pinyin":"xiāoxi","hanViet":"TIÊU TỨC","meaning":"tin tức, thông báo, thông tin","pos":"Danh từ","example":{"zh":"我收到消息。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"收","py":"shōu"},{"c":"到","py":"dào"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Tôi nhận được thông tin."}},{"hanzi":"迎接","pinyin":"yíngjiē","hanViet":"NGHÊNH TIẾP","meaning":"đón, chào đón","pos":"Động từ","example":{"zh":"他们迎接来客。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"迎","py":"yíng"},{"c":"接","py":"jiē"},{"c":"来","py":"lái"},{"c":"客","py":"kè"},{"c":"。","py":"。"}],"vi":"Họ đón khách đến."}},{"hanzi":"邮件","pinyin":"yóujiàn","hanViet":"BƯU KIỆN","meaning":"thư, tin nhắn, email","pos":"Danh từ","example":{"zh":"我收到了一封邮件。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"收","py":"shōu"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"封","py":"fēng"},{"c":"邮","py":"yóu"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Tôi nhận được một thư điện tử."}},{"hanzi":"邮箱","pinyin":"yóuxiāng","hanViet":"BƯU RƯƠNG","meaning":"hộp thư, thư điện tử","pos":"Danh từ","example":{"zh":"请把邮件发到我的邮箱。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"邮","py":"yóu"},{"c":"件","py":"jiàn"},{"c":"发","py":"fā"},{"c":"到","py":"dào"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"邮","py":"yóu"},{"c":"箱","py":"xiāng"},{"c":"。","py":"。"}],"vi":"Hãy gửi thư đến hộp thư của tôi."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-23', 22, 'Giải trí & thể thao', '[{"hanzi":"表演","pinyin":"biǎoyǎn","hanViet":"BIỂU DIỄN","meaning":"múa, trình diễn","pos":"Động từ","example":{"zh":"他们表演了一首歌。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"表","py":"biǎo"},{"c":"演","py":"yǎn"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"首","py":"shǒu"},{"c":"歌","py":"gē"},{"c":"。","py":"。"}],"vi":"Họ đã trình diễn một bài hát."}},{"hanzi":"吵架","pinyin":"chǎojià","hanViet":"SẢO GIÁ","meaning":"tranh cãi, khiếu nại","pos":"Động từ","example":{"zh":"我不想吵架。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"想","py":"xiǎng"},{"c":"吵","py":"chǎo"},{"c":"架","py":"jià"},{"c":"。","py":"。"}],"vi":"Tôi không muốn tranh cãi."}},{"hanzi":"代表团","pinyin":"dàibiǎotuán","hanViet":"ĐẠI BIỂU ĐOÀN","meaning":"đội đại biểu","pos":"Danh từ","example":{"zh":"代表团来了。","pinyinPerChar":[{"c":"代","py":"dài"},{"c":"表","py":"biǎo"},{"c":"团","py":"tuán"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Đội đại biểu đã đến."}},{"hanzi":"电视剧","pinyin":"diànshìjù","hanViet":"ĐIỆN THỊ KỊCH","meaning":"Truyện điện ảnh, phim truyền hình","pos":"Danh từ","example":{"zh":"我喜欢看电视剧。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"看","py":"kàn"},{"c":"电","py":"diàn"},{"c":"视","py":"shì"},{"c":"剧","py":"jù"},{"c":"。","py":"。"}],"vi":"Tôi thích xem phim truyền hình."}},{"hanzi":"发达","pinyin":"fādá","hanViet":"PHÁT ĐẠT","meaning":"Phát triển, thịnh vượng","pos":"Tính từ","example":{"zh":"这个城市很发达。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"城","py":"chéng"},{"c":"市","py":"shì"},{"c":"很","py":"hěn"},{"c":"发","py":"fā"},{"c":"达","py":"dá"},{"c":"。","py":"。"}],"vi":"Thành phố này rất phát triển."}},{"hanzi":"发展","pinyin":"fāzhǎn","hanViet":"PHÁT TRIỂN","meaning":"Phát triển","pos":"Động từ","example":{"zh":"经济发展。","pinyinPerChar":[{"c":"经","py":"jīng"},{"c":"济","py":"jì"},{"c":"发","py":"fā"},{"c":"展","py":"zhǎn"},{"c":"。","py":"。"}],"vi":"Kinh tế phát triển."}},{"hanzi":"歌迷","pinyin":"gēmí","hanViet":"CA MÊ","meaning":"người hâm mộ ca nhạc","pos":"Danh từ","example":{"zh":"他是个歌迷。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"个","py":"gè"},{"c":"歌","py":"gē"},{"c":"迷","py":"mí"},{"c":"。","py":"。"}],"vi":"Cậu ấy là một người hâm mộ ca nhạc."}},{"hanzi":"歌手","pinyin":"gēshǒu","hanViet":"CA THỦ","meaning":"ca sĩ","pos":"Danh từ","example":{"zh":"这位歌手很有名。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"位","py":"wèi"},{"c":"歌","py":"gē"},{"c":"手","py":"shǒu"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"名","py":"míng"},{"c":"。","py":"。"}],"vi":"Ca sĩ này rất nổi tiếng."}},{"hanzi":"话剧","pinyin":"huàjù","hanViet":"THOẠI KỊCH","meaning":"kịch bản, múa kịch","pos":"Danh từ","example":{"zh":"我们去看话剧。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"看","py":"kàn"},{"c":"话","py":"huà"},{"c":"剧","py":"jù"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi xem kịch."}},{"hanzi":"京剧","pinyin":"jīngjù","hanViet":"KINH KỊCH","meaning":"kịch Bắc Kinh","pos":"Danh từ","example":{"zh":"京剧很有意思。","pinyinPerChar":[{"c":"京","py":"jīng"},{"c":"剧","py":"jù"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Kịch Bắc Kinh rất thú vị."}},{"hanzi":"剧场","pinyin":"jùchǎng","hanViet":"KỊCH TRƯỜNG","meaning":"Rạp chiếu phim","pos":"Danh từ","example":{"zh":"我们去剧场。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"剧","py":"jù"},{"c":"场","py":"chǎng"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi rạp chiếu phim."}},{"hanzi":"开发","pinyin":"kāifā","hanViet":"KHAI PHÁT","meaning":"phát triển, khai thác","pos":"Động từ","example":{"zh":"公司开发新产品。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"开","py":"kāi"},{"c":"发","py":"fā"},{"c":"新","py":"xīn"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Công ty phát triển sản phẩm mới."}},{"hanzi":"开展","pinyin":"kāizhǎn","hanViet":"KHAI TRIỂN","meaning":"phát triển, triển khai","pos":"Động từ","example":{"zh":"他们开展活动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"开","py":"kāi"},{"c":"展","py":"zhǎn"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Họ triển khai hoạt động."}},{"hanzi":"连续剧","pinyin":"liánxùjù","hanViet":"LIÊN TỤC KỊCH","meaning":"truyện tranh, phim ảnh liên tục","pos":"Danh từ","example":{"zh":"这部连续剧很受欢迎。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"连","py":"lián"},{"c":"续","py":"xù"},{"c":"剧","py":"jù"},{"c":"很","py":"hěn"},{"c":"受","py":"shòu"},{"c":"欢","py":"huān"},{"c":"迎","py":"yíng"},{"c":"。","py":"。"}],"vi":"Truyện này rất được nhiều người thích."}},{"hanzi":"跑步","pinyin":"pǎobù","hanViet":"BÀO BỘ","meaning":"chạy bộ","pos":"Danh từ","example":{"zh":"我每天跑步。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"跑","py":"pǎo"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Tôi chạy bộ mỗi ngày."}},{"hanzi":"群","pinyin":"qún","hanViet":"QUẦN","meaning":"tập thể, đàn, nhóm","pos":"Tính từ","example":{"zh":"一群学生在教室里。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"群","py":"qún"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"在","py":"zài"},{"c":"教","py":"jiào"},{"c":"室","py":"shì"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Một nhóm học sinh trong lớp."}},{"hanzi":"跳","pinyin":"tiào","hanViet":"KHIÊU","meaning":"nhảy","pos":"Động từ","example":{"zh":"他会跳得很高。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"会","py":"huì"},{"c":"跳","py":"tiào"},{"c":"得","py":"dé"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Anh ấy có thể nhảy cao."}},{"hanzi":"跳高","pinyin":"tiàogāo","hanViet":"KHIÊU CAO","meaning":"nhảy cao","pos":"Động từ","example":{"zh":"她喜欢跳高。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"跳","py":"tiào"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"