INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-24', 23, 'Suy nghĩ & ý kiến', '[{"hanzi":"把握","pinyin":"bǎwò","hanViet":"BẢ ÁC","meaning":"nắm bắt, chắc chắn","pos":"Động từ","example":{"zh":"我把握不住。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"把","py":"bǎ"},{"c":"握","py":"wò"},{"c":"不","py":"bù"},{"c":"住","py":"zhù"},{"c":"。","py":"。"}],"vi":"Tôi không nắm bắt được."}},{"hanzi":"比较","pinyin":"bǐjiào","hanViet":"TỶ GIẢO","meaning":"so sánh, khá, hơi","pos":"Tính từ","example":{"zh":"这个苹果比较大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"比","py":"bǐ"},{"c":"较","py":"jiào"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Quả táo này hơi lớn."}},{"hanzi":"成果","pinyin":"chéngguǒ","hanViet":"THÀNH QUẢ","meaning":"kết quả, sản phẩm đạt được","pos":"Danh từ","example":{"zh":"我们取得了很多成果。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"取","py":"qǔ"},{"c":"得","py":"dé"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"成","py":"chéng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Chúng tôi đạt được nhiều kết quả."}},{"hanzi":"达到","pinyin":"dádào","hanViet":"ĐẠT ĐÁO","meaning":"đạt được, đạt tới","pos":"Động từ","example":{"zh":"他达到了目标。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"达","py":"dá"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"目","py":"mù"},{"c":"标","py":"biāo"},{"c":"。","py":"。"}],"vi":"Anh ấy đạt được mục tiêu."}},{"hanzi":"到底","pinyin":"dàodǐ","hanViet":"ĐÁO ĐỂ","meaning":"Cuối cùng, chắc chắn; hết mức","pos":"Liên từ","example":{"zh":"他到底来了吗？","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"到","py":"dào"},{"c":"底","py":"dǐ"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Anh ấy cuối cùng có đến không?"}},{"hanzi":"复杂","pinyin":"fùzá","hanViet":"PHỤC TẠP","meaning":"phức tạp","pos":"Tính từ","example":{"zh":"这个问题很复杂。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","p