INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-26', 25, 'Hành động & vận động (2)', '[{"hanzi":"环境","pinyin":"huánjìng","hanViet":"HOÀN CẢNH","meaning":"môi trường, điều kiện xung quanh","pos":"Danh từ","example":{"zh":"这里的环境很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"的","py":"de"},{"c":"环","py":"huán"},{"c":"境","py":"jìng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Môi trường ở đây rất tốt."}},{"hanzi":"加工","pinyin":"jiāgōng","hanViet":"GIA CÔNG","meaning":"xử lý, chế tạo","pos":"Động từ","example":{"zh":"工厂加工产品。","pinyinPerChar":[{"c":"工","py":"gōng"},{"c":"厂","py":"chǎng"},{"c":"加","py":"jiā"},{"c":"工","py":"gōng"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Nhà máy chế tạo sản phẩm."}},{"hanzi":"建立","pinyin":"jiànlì","hanViet":"KIẾN LẬP","meaning":"tạo ra, thiết lập","pos":"Động từ","example":{"zh":"他们建立了新的关系。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"建","py":"jiàn"},{"c":"立","py":"lì"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"的","py":"de"},{"c":"关","py":"guān"},{"c":"系","py":"xì"},{"c":"。","py":"。"}],"vi":"Họ đã tạo ra mối quan hệ mới."}},{"hanzi":"交流","pinyin":"jiāoliú","hanViet":"GIAO LƯU","meaning":"trao đổi, giao lưu","pos":"Động từ","example":{"zh":"我们经常交流语言。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"经","py":"jīng"},{"c":"常","py":"cháng"},{"c":"交","py":"jiāo"},{"c":"流","py":"liú"},{"c":"语","py":"yǔ"},{"c":"言","py":"yán"},{"c":"。","py":"。"}],"vi":"Chúng ta thường xuyên trao đổi ngôn ngữ."}},{"hanzi":"交往","pinyin":"jiāowǎng","hanViet":"GIAO VÃNG","meaning":"giao lưu, quan hệ","pos":"Động từ","example":{"zh":"他们经常交往。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"经","py":"jīng"},{"c":"常","py":"cháng"},{"c":"交","py":"jiāo"},{"c":"往","py":"wǎng"},{"c":"。","py":"。"}],"vi":"Họ thường xuyên giao lưu."}},{"hanzi":"解开","pinyin":"jiěkāi","hanViet":"GIẢI KHAI","meaning":"giải, mở khóa","pos":"Động từ","example":{"zh":"他解开了包。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"解","py":"jiě"},{"c":"开","py":"kāi"},{"c":"了","py":"le"},{"c":"包","py":"bāo"},{"c":"。","py":"。"}],"vi":"Cậu ấy đã mở ra bao bì."}},{"hanzi":"进一步","pinyin":"jìnyībù","hanViet":"TIẾN NHẤT BỘ","meaning":"tiến lên, sâu hơn","pos":"Liên từ","example":{"zh":"我们需要进一步讨论。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"进","py":"jìn"},{"c":"一","py":"yī"},{"c":"步","py":"bù"},{"c":"讨","py":"tǎo"},{"c":"论","py":"lùn"},{"c":"。","py":"。"}],"vi":"Chúng ta cần thảo luận sâu hơn."}},{"hanzi":"经历","pinyin":"jīnglì","hanViet":"KINH LỊCH","meaning":"Sự trải qua, trải nghiệm","pos":"Danh từ","example":{"zh":"他有很多经历。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"经","py":"jīng"},{"c":"历","py":"lì"},{"c":"。","py":"。"}],"vi":"Anh ấy có nhiều kinh nghiệm trải qua."}},{"hanzi":"就业","pinyin":"jiùyè","hanViet":"TỰU NGHIỆP","meaning":"Tìm việc làm","pos":"Danh từ","example":{"zh":"他就业了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"就","py":"jiù"},{"c":"业","py":"yè"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đã có việc làm."}},{"hanzi":"考验","pinyin":"kǎoyàn","hanViet":"KHẢO NGHIỆM","meaning":"kiểm tra, thử thách","pos":"Danh từ","example":{"zh":"这次考验很难。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"考","py":"kǎo"},{"c":"验","py":"yàn"},{"c":"很","py":"hěn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Bài kiểm tra này rất khó."}},{"hanzi":"克服","pinyin":"kèfú","hanViet":"KHẮC PHỤC","meaning":"vượt qua, khắc phục","pos":"Động từ","example":{"zh":"我们克服困难。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"克","py":"kè"},{"c":"服","py":"fú"},{"c":"困","py":"kùn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Chúng tôi vượt qua khó khăn."}},{"hanzi":"理论","pinyin":"lǐlùn","hanViet":"LÝ LUẬN","meaning":"lý thuyết, quan điểm","pos":"Danh từ","example":{"zh":"这个理论很有道理。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"理","py":"lǐ"},{"c":"论","py":"lùn"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"道","py":"dào"},{"c":"理","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Lý thuyết này rất có lý."}},{"hanzi":"了","pinyin":"liǎo","hanViet":"LIỄU","meaning":"kết thúc, đánh dấu hoàn thành","pos":"Hậu tố","example":{"zh":"我吃了饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"吃","py":"chī"},{"c":"了","py":"le"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi đã ăn xong."}},{"hanzi":"另外","pinyin":"lìngwài","hanViet":"LÁNH NGOẠI","meaning":"ngoài ra","pos":"Phó từ","example":{"zh":"我还要买另外一件。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"还","py":"hái"},{"c":"要","py":"yào"},{"c":"买","py":"mǎi"},{"c":"另","py":"lìng"},{"c":"外","py":"wài"},{"c":"一","py":"yī"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Tôi còn mua một món khác."}},{"hanzi":"难道","pinyin":"nándào","hanViet":"NAN ĐẠO","meaning":"câu hỏi phủ định, chắc chắn không","pos":"Liên từ","example":{"zh":"难道你不去吗？","pinyinPerChar":[{"c":"难","py":"nán"},{"c":"道","py":"dào"},{"c":"你","py":"nǐ"},{"c":"不","py":"bù"},{"c":"去","py":"qù"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Không phải bạn không đi à?"}},{"hanzi":"拍","pinyin":"pāi","hanViet":"PHÁCH","meaning":"vỗ, chụp, chạm","pos":"Động từ","example":{"zh":"她拍照。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"拍","py":"pāi"},{"c":"照","py":"zhào"},{"c":"。","py":"。"}],"vi":"Cô ấy chụp ảnh."}},{"hanzi":"评价","pinyin":"píngjià","hanViet":"BÌNH GIÁ","meaning":"đánh giá","pos":"Danh từ","example":{"zh":"老师评价学生。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"评","py":"píng"},{"c":"价","py":"jià"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Thầy giáo đánh giá học sinh."}},{"hanzi":"普及","pinyin":"pǔjí","hanViet":"PHỔ CẬP","meaning":"Mở rộng, lan rộng","pos":"Động từ","example":{"zh":"学校普及知识。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"普","py":"pǔ"},{"c":"及","py":"jí"},{"c":"知","py":"zhī"},{"c":"识","py":"shí"},{"c":"。","py":"。"}],"vi":"Trường học phổ cập kiến thức."}},{"hanzi":"期","pinyin":"qī","hanViet":"KỲ","meaning":"Lần, thời điểm","pos":"Danh từ","example":{"zh":"这个月的期末考试。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"月","py":"yuè"},{"c":"的","py":"de"},{"c":"期","py":"qī"},{"c":"末","py":"mò"},{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"。","py":"。"}],"vi":"Kiểm tra cuối tháng này."}},{"hanzi":"其实","pinyin":"qíshí","hanViet":"KỲ THỰC","meaning":"Thực ra, thật ra","pos":"Phó từ","example":{"zh":"我其实很累。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"其","py":"qí"},{"c":"实","py":"shí"},{"c":"很","py":"hěn"},{"c":"累","py":"lèi"},{"c":"。","py":"。"}],"vi":"Tôi thực ra rất mệt."}},{"hanzi":"前进","pinyin":"qiánjìn","hanViet":"TIỀN TIẾN","meaning":"Tiến lên, tiến bộ","pos":"Động từ","example":{"zh":"我们要前进。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"前","py":"qián"},{"c":"进","py":"jìn"},{"c":"。","py":"。"}],"vi":"Chúng ta phải tiến lên."}},{"hanzi":"前往","pinyin":"qiánwǎng","hanViet":"TIỀN VÃNG","meaning":"Đi đến","pos":"Động từ","example":{"zh":"他前往学校。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"前","py":"qián"},{"c":"往","py":"wǎng"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Anh ấy đi đến trường."}},{"hanzi":"去世","pinyin":"qùshì","hanViet":"KHỨ THẾ","meaning":"mất, qua đời","pos":"Động từ","example":{"zh":"爷爷去世了。","pinyinPerChar":[{"c":"爷","py":"yé"},{"c":"爷","py":"yé"},{"c":"去","py":"qù"},{"c":"世","py":"shì"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Bác đi mất."}},{"hanzi":"缺点","pinyin":"quēdiǎn","hanViet":"KHUYẾT ĐIỂM","meaning":"điểm yếu","pos":"Danh từ","example":{"zh":"他的缺点是太急躁。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"缺","py":"quē"},{"c":"点","py":"diǎn"},{"c":"是","py":"shì"},{"c":"太","py":"tài"},{"c":"急","py":"jí"},{"c":"躁","py":"zào"},{"c":"。","py":"。"}],"vi":"Điểm yếu của anh ấy là quá nhanh vui."}},{"hanzi":"认出","pinyin":"rènchū","hanViet":"NHẬN XUẤT","meaning":"nhận ra, nhận biết được","pos":"Động từ","example":{"zh":"我认出他是我的朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"认","py":"rèn"},{"c":"出","py":"chū"},{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi nhận ra anh ấy là bạn của tôi."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-27', 26, 'Hành động & vận động (3)', '[{"hanzi":"上来","pinyin":"shànglái","hanViet":"THƯỢNG LAI","meaning":"lên, đến trên (nơi)","pos":"Động từ","example":{"zh":"请上来坐。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"上","py":"shàng"},{"c":"来","py":"lái"},{"c":"坐","py":"zuò"},{"c":"。","py":"。"}],"vi":"Hãy lên đây ngồi."}},{"hanzi":"上去","pinyin":"shàngqù","hanViet":"THƯỢNG KHỨ","meaning":"lên, đi lên (nơi)","pos":"Động từ","example":{"zh":"我们上去看看。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"上","py":"shàng"},{"c":"去","py":"qù"},{"c":"看","py":"kàn"},{"c":"看","py":"kàn"},{"c":"。","py":"。"}],"vi":"Chúng tôi lên xem xem."}},{"hanzi":"深入","pinyin":"shēnrù","hanViet":"THÂM NHẬP","meaning":"sâu vào, đi sâu","pos":"Tính từ","example":{"zh":"我们深入研究了这个问题。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"深","py":"shēn"},{"c":"入","py":"rù"},{"c":"研","py":"yán"},{"c":"究","py":"jiū"},{"c":"了","py":"le"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Chúng tôi đã nghiên cứu sâu vào vấn đề này."}},{"hanzi":"生","pinyin":"shēng","hanViet":"SINH","meaning":"sinh, ra đời","pos":"Tính từ","example":{"zh":"他是个生病的人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"个","py":"gè"},{"c":"生","py":"shēng"},{"c":"病","py":"bìng"},{"c":"的","py":"de"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy là người đang ốm."}},{"hanzi":"生产","pinyin":"shēngchǎn","hanViet":"SINH SẢN","meaning":"sản xuất","pos":"Động từ","example":{"zh":"工厂生产很多产品。","pinyinPerChar":[{"c":"工","py":"gōng"},{"c":"厂","py":"chǎng"},{"c":"生","py":"shēng"},{"c":"产","py":"chǎn"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Nhà máy sản xuất nhiều sản phẩm."}},{"hanzi":"生长","pinyin":"shēngzhǎng","hanViet":"SINH TRƯỞNG","meaning":"sống và lớn lên","pos":"Động từ","example":{"zh":"孩子们在这里生长。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"生","py":"shēng"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Trẻ em ở đây lớn lên."}},{"hanzi":"失去","pinyin":"shīqù","hanViet":"THẤT KHỨ","meaning":"mất, mất đi","pos":"Động từ","example":{"zh":"他失去了机会。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"失","py":"shī"},{"c":"去","py":"qù"},{"c":"了","py":"le"},{"c":"机","py":"jī"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Anh ấy đã mất cơ hội."}},{"hanzi":"石头","pinyin":"shítou","hanViet":"THẠCH ĐẦU","meaning":"đá, đá","pos":"Danh từ","example":{"zh":"这个石头很重。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"石","py":"shí"},{"c":"头","py":"tóu"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"。","py":"。"}],"vi":"Đá này rất nặng."}},{"hanzi":"实际上","pinyin":"shíjìshàng","hanViet":"THỰC TẾ THƯỢNG","meaning":"thực tế, thực ra","pos":"Phó từ","example":{"zh":"实际上，他没来。","pinyinPerChar":[{"c":"实","py":"shí"},{"c":"际","py":"jì"},{"c":"上","py":"shàng"},{"c":"，","py":"，"},{"c":"他","py":"tā"},{"c":"没","py":"méi"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Thực tế, anh ấy không đến."}},{"hanzi":"事实上","pinyin":"shìshíshang","hanViet":"SỰ THỰC THƯỢNG","meaning":"thực ra, về bản chất","pos":"Phó từ","example":{"zh":"事实上，他不知道。","pinyinPerChar":[{"c":"事","py":"shì"},{"c":"实","py":"shí"},{"c":"上","py":"shàng"},{"c":"，","py":"，"},{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"。","py":"。"}],"vi":"Thực ra, anh ấy không biết."}},{"hanzi":"收音机","pinyin":"shōuyīnjī","hanViet":"THU ÂM CƠ","meaning":"Điều hòa, máy thu","pos":"Danh từ","example":{"zh":"我买了一台收音机。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"买","py":"mǎi"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"台","py":"tái"},{"c":"收","py":"shōu"},{"c":"音","py":"yīn"},{"c":"机","py":"jī"},{"c":"。","py":"。"}],"vi":"Tôi đã mua một chiếc điều hòa."}},{"hanzi":"属于","pinyin":"shǔyú","hanViet":"THUỘC Ư","meaning":"thuộc về, nằm trong","pos":"Động từ","example":{"zh":"这本书属于我。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"属","py":"shǔ"},{"c":"于","py":"yú"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Cuốn sách này thuộc về tôi."}},{"hanzi":"思想","pinyin":"sīxiǎng","hanViet":"TƯ TƯỞNG","meaning":"tư tưởng, quan điểm","pos":"Danh từ","example":{"zh":"他的思想很开放。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"思","py":"sī"},{"c":"想","py":"xiǎng"},{"c":"很","py":"hěn"},{"c":"开","py":"kāi"},{"c":"放","py":"fàng"},{"c":"。","py":"。"}],"vi":"Tư tưởng của anh ấy rất mở."}},{"hanzi":"所","pinyin":"suǒ","hanViet":"SỞ","meaning":"địa điểm, nơi làm gì","pos":"Đại từ","example":{"zh":"我所见过的地方都很美。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"所","py":"suǒ"},{"c":"见","py":"jiàn"},{"c":"过","py":"guò"},{"c":"的","py":"de"},{"c":"地","py":"dì"},{"c":"方","py":"fāng"},{"c":"都","py":"dōu"},{"c":"很","py":"hěn"},{"c":"美","py":"měi"},{"c":"。","py":"。"}],"vi":"Mọi nơi tôi đã từng thấy đều rất đẹp."}},{"hanzi":"体验","pinyin":"tǐyàn","hanViet":"THỂ NGHIỆM","meaning":"trải nghiệm","pos":"Danh từ","example":{"zh":"我喜欢这种体验。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"这","py":"zhè"},{"c":"种","py":"zhǒng"},{"c":"体","py":"tǐ"},{"c":"验","py":"yàn"},{"c":"。","py":"。"}],"vi":"Tôi thích loại trải nghiệm này."}},{"hanzi":"同意","pinyin":"tóngyì","hanViet":"ĐỒNG Ý","meaning":"có cùng quan điểm, chấp nhận","pos":"Động từ","example":{"zh":"他同意我的计划。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"同","py":"tóng"},{"c":"意","py":"yì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"。","py":"。"}],"vi":"Anh ấy đồng ý với kế hoạch của tôi."}},{"hanzi":"突出","pinyin":"tūchū","hanViet":"ĐỘT XUẤT","meaning":"trội hơn, nổi bật","pos":"Động từ","example":{"zh":"这件衣服很突出。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"