INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-29', 28, 'Bổ sung (1)', '[{"hanzi":"…极了","pinyin":"…jí le","hanViet":"CỰC LIỄU","meaning":"rất, cực kỳ","pos":"Hậu tố","example":{"zh":"这个电影很好看极了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"看","py":"kàn"},{"c":"极","py":"jí"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Phim này rất hay lắm."}},{"hanzi":"一方面","pinyin":"yīfāngmiàn","hanViet":"NHẤT PHƯƠNG DIỆN","meaning":"một mặt, một bên","pos":"Danh từ","example":{"zh":"一方面学习，一方面工作。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"方","py":"fāng"},{"c":"面","py":"miàn"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"，","py":"，"},{"c":"一","py":"yī"},{"c":"方","py":"fāng"},{"c":"面","py":"miàn"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Học một mặt, làm một mặt."}},{"hanzi":"下面","pinyin":"xiàmiàn","hanViet":"HẠ DIỆN","meaning":"dưới, dưới đây, sau","pos":"Danh từ","example":{"zh":"下面是书。","pinyinPerChar":[{"c":"下","py":"xià"},{"c":"面","py":"miàn"},{"c":"是","py":"shì"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Dưới đây là sách."}},{"hanzi":"不断","pinyin":"bùduàn","hanViet":"BẤT ĐOẠN","meaning":"liên tục","pos":"Tính từ","example":{"zh":"他不断学习。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"断","py":"duàn"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Anh ấy học liên tục."}},{"hanzi":"专业","pinyin":"zhuānyè","hanViet":"CHUYÊN NGHIỆP","meaning":"chuyên môn, chuyên ngành","pos":"Tính từ","example":{"zh":"他学习专业。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"专","py":"zhuān"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Anh ấy học chuyên ngành."}},{"hanzi":"专家","pinyin":"zhuānjiā","hanViet":"CHUYÊN GIA","meaning":"chuyên gia","pos":"Danh từ","example":{"zh":"他是医生专家。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"专","py":"zhuān"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Anh ấy là chuyên gia y tế."}},{"hanzi":"专题","pinyin":"zhuāntí","hanViet":"CHUYÊN ĐỀ","meaning":"chủ đề, chuyên đề","pos":"Danh từ","example":{"zh":"这节课是专题。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"节","py":"jié"},{"c":"课","py":"kè"},{"c":"是","py":"shì"},{"c":"专","py":"zhuān"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Buổi học này là chuyên đề."}},{"hanzi":"世界","pinyin":"shìjiè","hanViet":"THẾ GIỚI","meaning":"thế giới","pos":"Danh từ","example":{"zh":"我喜欢这个世界。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"世","py":"shì"},{"c":"界","py":"jiè"},{"c":"。","py":"。"}],"vi":"Tôi thích thế giới này."}},{"hanzi":"中部","pinyin":"zhōngbù","hanViet":"TRUNG BỘ","meaning":"miền giữa","pos":"Danh từ","example":{"zh":"公司设在中部。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"设","py":"shè"},{"c":"在","py":"zài"},{"c":"中","py":"zhōng"},{"c":"部","py":"bù"},{"c":"。","py":"。"}],"vi":"Công ty đặt ở trung phần."}},{"hanzi":"主任","pinyin":"zhǔrèn","hanViet":"CHỦ NHIỆM","meaning":"giám đốc, trưởng","pos":"Danh từ","example":{"zh":"他是主任。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"主","py":"zhǔ"},{"c":"任","py":"rèn"},{"c":"。","py":"。"}],"vi":"Cậu ấy là giám đốc."}},{"hanzi":"主意","pinyin":"zhǔyi","hanViet":"CHỦ Ý","meaning":"ý tưởng, ý kiến","pos":"Danh từ","example":{"zh":"你有什么主意？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"有","py":"yǒu"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"主","py":"zhǔ"},{"c":"意","py":"yì"},{"c":"？","py":"？"}],"vi":"Bạn có ý tưởng gì không?"}},{"hanzi":"主持","pinyin":"zhǔchí","hanViet":"CHỦ TRÌ","meaning":"trình diễn, chủ trì","pos":"Động từ","example":{"zh":"他主持会议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"主","py":"zhǔ"},{"c":"持","py":"chí"},{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Cậu ấy chủ trì cuộc họp."}},