INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-30', 29, 'Bổ sung (2)', '[{"hanzi":"仍然","pinyin":"réngrán","hanViet":"NHƯNG NHIÊN","meaning":"vẫn, vẫn","pos":"Phó từ","example":{"zh":"他仍然没来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"仍","py":"réng"},{"c":"然","py":"rán"},{"c":"没","py":"méi"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy vẫn chưa đến."}},{"hanzi":"从前","pinyin":"cóngqián","hanViet":"TÒNG TIỀN","meaning":"trước đây, từ trước","pos":"Danh từ","example":{"zh":"从前我住在这里。","pinyinPerChar":[{"c":"从","py":"cóng"},{"c":"前","py":"qián"},{"c":"我","py":"wǒ"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi từng ở đây trước đây."}},{"hanzi":"付","pinyin":"fù","hanViet":"PHÓ","meaning":"trả, nộp","pos":"Động từ","example":{"zh":"他付了钱。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"付","py":"fù"},{"c":"了","py":"le"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Anh ấy đã trả tiền."}},{"hanzi":"代","pinyin":"dài","hanViet":"ĐẠI","meaning":"thay thế, đại diện","pos":"Danh từ","example":{"zh":"这代人。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"代","py":"dài"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Thế hệ này."}},{"hanzi":"代表","pinyin":"dàibiǎo","hanViet":"ĐẠI BIỂU","meaning":"đại diện, biểu tượng","pos":"Tính từ","example":{"zh":"他代表公司。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"代","py":"dài"},{"c":"表","py":"biǎo"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"。","py":"。"}],"vi":"Anh ấy đại diện cho công ty."}},{"hanzi":"任何","pinyin":"rènhé","hanViet":"NHIỆM HÀ","meaning":"bất kỳ, bất cứ","pos":"Tính từ","example":{"zh":"任何人都可以参加。","pinyinPerChar":[{"c":"任","py":"rèn"},{"c":"何","py":"hé"},{"c":"人","py":"rén"},{"c":"都","py":"dōu"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"。","py":"。"}],"vi":"Bất kỳ ai cũng có thể tham gia."}},{"hanzi":"优势","pinyin":"yōushì","hanViet":"ƯU THẾ","meaning":"lợi thế, thế m