INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-31', 30, 'Bổ sung (3)', '[{"hanzi":"共有","pinyin":"gòngyǒu","hanViet":"CỘNG HỮU","meaning":"cùng sở hữu","pos":"Tính từ","example":{"zh":"这房子是共有。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"是","py":"shì"},{"c":"共","py":"gòng"},{"c":"有","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Ngôi nhà này là chung sở hữu."}},{"hanzi":"具有","pinyin":"jùyǒu","hanViet":"CỤ HỮU","meaning":"Có, sở hữu","pos":"Động từ","example":{"zh":"他具有经验。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"具","py":"jù"},{"c":"有","py":"yǒu"},{"c":"经","py":"jīng"},{"c":"验","py":"yàn"},{"c":"。","py":"。"}],"vi":"Anh ấy có kinh nghiệm."}},{"hanzi":"内","pinyin":"nèi","hanViet":"NỘI","meaning":"trong, nội","pos":"Tính từ","example":{"zh":"内心很平静。","pinyinPerChar":[{"c":"内","py":"nèi"},{"c":"心","py":"xīn"},{"c":"很","py":"hěn"},{"c":"平","py":"píng"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Tâm inside rất bình tĩnh."}},{"hanzi":"内容","pinyin":"nèiróng","hanViet":"NỘI DUNG","meaning":"nội dung, nội dung","pos":"Danh từ","example":{"zh":"内容很有意思。","pinyinPerChar":[{"c":"内","py":"nèi"},{"c":"容","py":"róng"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Nội dung rất thú vị."}},{"hanzi":"分组","pinyin":"fēn zǔ","hanViet":"PHÂN TỔ","meaning":"phân nhóm","pos":"Động từ","example":{"zh":"请把大家分组。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"分","py":"fēn"},{"c":"组","py":"zǔ"},{"c":"。","py":"。"}],"vi":"Vui lòng chia nhóm cho tất cả."}},{"hanzi":"分配","pinyin":"fēnpèi","hanViet":"PHÂN PHỐI","meaning":"phân bổ, phân chia","pos":"Động từ","example":{"zh":"老师分配了作业。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"分","py":"fēn"},{"c":"配","py":"pèi"},{"c":"了","py":"le"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Giáo viên đã phân công bài t