INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-32', 31, 'Bổ sung (4)', '[{"hanzi":"双","pinyin":"shuāng","hanViet":"SONG","meaning":"cặp, đôi","pos":"Số từ","example":{"zh":"他有两双鞋。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"两","py":"liǎng"},{"c":"双","py":"shuāng"},{"c":"鞋","py":"xié"},{"c":"。","py":"。"}],"vi":"Anh ấy có hai đôi giày."}},{"hanzi":"双方","pinyin":"shuāngfāng","hanViet":"SONG PHƯƠNG","meaning":"cả hai bên, hai bên","pos":"Danh từ","example":{"zh":"双方都同意这个计划。","pinyinPerChar":[{"c":"双","py":"shuāng"},{"c":"方","py":"fāng"},{"c":"都","py":"dōu"},{"c":"同","py":"tóng"},{"c":"意","py":"yì"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"。","py":"。"}],"vi":"Cả hai bên đều đồng ý với kế hoạch này."}},{"hanzi":"反复","pinyin":"fǎnfù","hanViet":"PHẢN PHỤC","meaning":"lặp lại nhiều lần","pos":"Tính từ","example":{"zh":"他反复问这个问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"反","py":"fǎn"},{"c":"复","py":"fù"},{"c":"问","py":"wèn"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Anh ấy lặp lại nhiều lần hỏi câu hỏi này."}},{"hanzi":"反应","pinyin":"fǎnyìng","hanViet":"PHẢN ƯNG","meaning":"lưu ý, phản ứng","pos":"Danh từ","example":{"zh":"他对这个消息反应很快。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"反","py":"fǎn"},{"c":"应","py":"yīng"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Anh ấy phản ứng rất nhanh với tin này."}},{"hanzi":"反正","pinyin":"fǎnzhèng","hanViet":"PHẢN CHÍNH","meaning":"dù sao cũng vậy","pos":"Liên từ","example":{"zh":"反正我不去。","pinyinPerChar":[{"c":"反","py":"fǎn"},{"c":"正","py":"zhèng"},{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Dù sao cũng không đi."}},{"hanzi":"发动","pinyin":"fādòng","hanViet":"PHÁT ĐỘNG","meaning":"Bắt đầu, kích động","pos":"Động từ","example":{"zh":"他发动车。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"发","py":"fā"},{"c":"动","py":"dòng"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Cậu ấy khởi động xe."}},{"hanzi":"取消","pinyin":"qǔxiāo","hanViet":"THỦ TIÊU","meaning":"xóa bỏ, hủy","pos":"Động từ","example":{"zh":"取消会议。","pinyinPerChar":[{"c":"取","py":"qǔ"},{"c":"消","py":"xiāo"},{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Hủy cuộc họp."}},{"hanzi":"变化","pinyin":"biànhuà","hanViet":"BIẾN HOÁ","meaning":"thay đổi","pos":"Danh từ","example":{"zh":"天气变化很快。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"变","py":"biàn"},{"c":"化","py":"huà"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Thời tiết thay đổi rất nhanh."}},{"hanzi":"另一方面","pinyin":"lìng yīfāngmiàn","hanViet":"LÁNH NHẤT PHƯƠNG DIỆN","meaning":"mặt khác","pos":"Liên từ","example":{"zh":"另一方面，我们也要注意安全。","pinyinPerChar":[{"c":"另","py":"lìng"},{"c":"一","py":"yī"},{"c":"方","py":"fāng"},{"c":"面","py":"miàn"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"也","py":"yě"},{"c":"要","py":"yào"},{"c":"注","py":"zhù"},{"c":"意","py":"yì"},{"c":"安","py":"ān"},{"c":"全","py":"quán"},{"c":"。","py":"。"}],"vi":"Mặt khác, chúng ta cũng cần chú ý an toàn."}},{"hanzi":"只","pinyin":"zhī","hanViet":"CHỈ","meaning":"chỉ, chỉ có, chỉ","pos":"Đại từ","example":{"zh":"我只吃水果。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"只","py":"zhǐ"},{"c":"吃","py":"chī"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Tôi chỉ ăn trái cây."}},{"hanzi":"只是","pinyin":"zhǐshì","hanViet":"CHỈ THỊ","meaning":"chỉ, chỉ là","pos":"Phó từ","example":{"zh":"我只是听说过这个。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"只","py":"zhǐ"},{"c":"是","py":"shì"},{"c":"听","py":"tīng"},{"c":"说","py":"shuō"},{"c":"过","py":"guò"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"。","py":"。"}],"vi":"Tôi chỉ nghe nói về điều này."}},{"hanzi":"只有","pinyin":"zhǐyǒu","hanViet":"CHỈ HỮU","meaning":"chỉ có, chỉ","pos":"Đại từ","example":{"zh":"只有我知道答案。","pinyinPerChar":[{"c":"只","py":"zhǐ"},{"c":"有","py":"yǒu"},{"c":"我","py":"wǒ"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"答","py":"dá"},{"c":"案","py":"àn"},{"c":"。","py":"。"}],"vi":"Chỉ tôi mới biết câu trả lời."}},{"hanzi":"叫","pinyin":"jiào","hanViet":"KHIẾU","meaning":"gọi, mời","pos":"Động từ","example":{"zh":"请叫我李明。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"叫","py":"jiào"},{"c":"我","py":"wǒ"},{"c":"李","py":"lǐ"},{"c":"明","py":"míng"},{"c":"。","py":"。"}],"vi":"Xin gọi tôi là Lý Minh."}},{"hanzi":"各自","pinyin":"gèzì","hanViet":"CÁC TỰ","meaning":"mỗi một, riêng","pos":"Tính từ","example":{"zh":"他们各自回家。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"各","py":"gè"},{"c":"自","py":"zì"},{"c":"回","py":"huí"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Họ mỗi người về nhà."}},{"hanzi":"合法","pinyin":"héfǎ","hanViet":"HỢP PHÁP","meaning":"có hiệu lực, hợp pháp","pos":"Tính từ","example":{"zh":"这件事合法。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"合","py":"hé"},{"c":"法","py":"fǎ"},{"c":"。","py":"。"}],"vi":"Việc này hợp pháp."}},{"hanzi":"员工","pinyin":"yuángōng","hanViet":"VIÊN CÔNG","meaning":"nhân viên","pos":"Danh từ","example":{"zh":"公司有很多员工。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"员","py":"yuán"},{"c":"工","py":"gōng"},{"c":"。","py":"。"}],"vi":"Công ty có nhiều nhân viên."}},{"hanzi":"因此","pinyin":"yīncǐ","hanViet":"NHÂN THỬ","meaning":"do vậy, vì vậy","pos":"Liên từ","example":{"zh":"他生病了，因此没来上课。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"生","py":"shēng"},{"c":"病","py":"bìng"},{"c":"了","py":"le"},{"c":"，","py":"，"},{"c":"因","py":"yīn"},{"c":"此","py":"cǐ"},{"c":"没","py":"méi"},{"c":"来","py":"lái"},{"c":"上","py":"shàng"},{"c":"课","py":"kè"},{"c":"。","py":"。"}],"vi":"Anh ấy bệnh nên không đến lớp."}},{"hanzi":"团","pinyin":"tuán","hanViet":"ĐOÀN","meaning":"một khối, đoàn, đoàn thể","pos":"Danh từ","example":{"zh":"他们组成一个团。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"组","py":"zǔ"},{"c":"成","py":"chéng"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"团","py":"tuán"},{"c":"。","py":"。"}],"vi":"Họ thành lập một đoàn."}},{"hanzi":"团结","pinyin":"tuánjié","hanViet":"ĐOÀN KẾT","meaning":"thống nhất, gắn bó","pos":"Động từ","example":{"zh":"我们要团结起来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"团","py":"tuán"},{"c":"结","py":"jié"},{"c":"起","py":"qǐ"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Chúng tôi cần đoàn kết."}},{"hanzi":"场所","pinyin":"chǎngsuǒ","hanViet":"TRƯỜNG SỞ","meaning":"nơi ở, nơi làm việc","pos":"Danh từ","example":{"zh":"这家公司是我的工作场所。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"家","py":"jiā"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"场","py":"chǎng"},{"c":"所","py":"suǒ"},{"c":"。","py":"。"}],"vi":"Công ty này là nơi làm việc của tôi."}},{"hanzi":"处理","pinyin":"chǔlǐ","hanViet":"XỨ LÝ","meaning":"xử lý, giải quyết","pos":"Động từ","example":{"zh":"请处理这个问题。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"处","py":"chù"},{"c":"理","py":"lǐ"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Xin hãy giải quyết vấn đề này."}},{"hanzi":"复印","pinyin":"fùyìn","hanViet":"PHỤC ẤN","meaning":"chụp, phôt","pos":"Động từ","example":{"zh":"我要复印这份文件。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"复","py":"fù"},{"c":"印","py":"yìn"},{"c":"这","py":"zhè"},{"c":"份","py":"fèn"},{"c":"文","py":"wén"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Tôi muốn chụp bản sao tài liệu này."}},{"hanzi":"外面","pinyin":"wàimiàn","hanViet":"NGOẠI DIỆN","meaning":"bên ngoài, bên ngoài nơi này","pos":"Danh từ","example":{"zh":"书在外面。","pinyinPerChar":[{"c":"书","py":"shū"},{"c":"在","py":"zài"},{"c":"外","py":"wài"},{"c":"面","py":"miàn"},{"c":"。","py":"。"}],"vi":"Sách ở bên ngoài."}},{"hanzi":"女子","pinyin":"nǚzǐ","hanViet":"TỬ","meaning":"người phụ nữ, nữ giới","pos":"Danh từ","example":{"zh":"她是女子。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"女","py":"nǚ"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Cô ấy là người phụ nữ."}},{"hanzi":"好奇","pinyin":"hàoqí","hanViet":"HẢO KỲ","meaning":"tò mò, tò mò biết nhiều","pos":"Tính từ","example":{"zh":"孩子们很好奇。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"奇","py":"qí"},{"c":"。","py":"。"}],"vi":"Trẻ em rất tò mò."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-33', 32, 'Bổ sung (5)', '[{"hanzi":"如何","pinyin":"rúhé","hanViet":"NHƯ HÀ","meaning":"thế nào, như thế nào","pos":"Liên từ","example":{"zh":"你如何学习中文？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"如","py":"rú"},{"c":"何","py":"hé"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"？","py":"？"}],"vi":"Bạn học tiếng Trung như thế nào?"}},{"hanzi":"子女","pinyin":"zǐnǚ","hanViet":"TỬ","meaning":"con cái","pos":"Danh từ","example":{"zh":"有子女。","pinyinPerChar":[{"c":"有","py":"yǒu"},{"c":"子","py":"zi"},{"c":"女","py":"nǚ"},{"c":"。","py":"。"}],"vi":"Có con."}},{"hanzi":"存","pinyin":"cún","hanViet":"TỒN","meaning":"giữ, lưu trữ","pos":"Động từ","example":{"zh":"他每天存钱。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"存","py":"cún"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Anh ấy tiết kiệm tiền mỗi ngày."}},{"hanzi":"存在","pinyin":"cúnzài","hanViet":"TỒN TẠI","meaning":"tồn tại, có mặt","pos":"Động từ","example":{"zh":"问题仍然存在。","pinyinPerChar":[{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"仍","py":"réng"},{"c":"然","py":"rán"},{"c":"存","py":"cún"},{"c":"在","py":"zài"},{"c":"。","py":"。"}],"vi":"Vấn đề vẫn còn tồn tại."}},{"hanzi":"学费","pinyin":"xuéfèi","hanViet":"HỌC PHÍ","meaning":"Học phí","pos":"Danh từ","example":{"zh":"学费很贵。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"费","py":"fèi"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Học phí rất đắt."}},{"hanzi":"完善","pinyin":"wánshàn","hanViet":"HOÀN THIỆN","meaning":"hoàn thiện, cải thiện","pos":"Động từ","example":{"zh":"我们要完善制度。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"完","py":"wán"},{"c":"善","py":"shàn"},{"c":"制","py":"zhì"},{"c":"度","py":"dù"},{"c":"。","py":"。"}],"vi":"Chúng tôi cần hoàn thiện chế độ."}},{"hanzi":"实行","pinyin":"shíxíng","hanViet":"THỰC HÀNH","meaning":"thực hiện, áp dụng","pos":"Động từ","example":{"zh":"我们要实行新计划。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"实","py":"shí"},{"c":"行","py":"xíng"},{"c":"新","py":"xīn"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"。","py":"。"}],"vi":"Chúng tôi sẽ thực hiện kế hoạch mới."}},{"hanzi":"容易","pinyin":"róngyì","hanViet":"DUNG DỊCH","meaning":"dễ dàng, dễ","pos":"Tính từ","example":{"zh":"这道题很容易。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"道","py":"dào"},{"c":"题","py":"tí"},{"c":"很","py":"hěn"},{"c":"容","py":"róng"},{"c":"易","py":"yì"},{"c":"。","py":"。"}],"vi":"Câu hỏi này rất dễ."}},{"hanzi":"对待","pinyin":"duìdài","hanViet":"ĐỐI ĐÃI","meaning":"Xử lý, đối xử","pos":"Động từ","example":{"zh":"我们要对待朋友好。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"对","py":"duì"},{"c":"待","py":"dài"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chúng ta phải đối xử tốt với bạn bè."}},{"hanzi":"对手","pinyin":"duìshǒu","hanViet":"ĐỐI THỦ","meaning":"Đối thủ, đối lập","pos":"Danh từ","example":{"zh":"他是我的对手。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"对","py":"duì"},{"c":"手","py":"shǒu"},{"c":"。","py":"。"}],"vi":"Cậu ấy là đối thủ của tôi."}},{"hanzi":"对象","pinyin":"duìxiàng","hanViet":"ĐỐI TƯỢNG","meaning":"Đối tượng, người","pos":"Danh từ","example":{"zh":"这是对象。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"对","py":"duì"},{"c":"象","py":"xiàng"},{"c":"。","py":"。"}],"vi":"Đây là đối tượng."}},{"hanzi":"将近","pinyin":"jiāngjìn","hanViet":"TƯƠNG CẬN","meaning":"gần, gần như","pos":"Tính từ","example":{"zh":"他将近三十岁了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"将","py":"jiāng"},{"c":"近","py":"jìn"},{"c":"三","py":"sān"},{"c":"十","py":"shí"},{"c":"岁","py":"suì"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy gần ba mươi tuổi rồi."}},{"hanzi":"就是","pinyin":"jiùshì","hanViet":"TỰU THỊ","meaning":"Chính là, đúng là","pos":"Liên từ","example":{"zh":"这是我的书。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Đây là quyển sách của tôi."}},{"hanzi":"属","pinyin":"shǔ","hanViet":"THUỘC","meaning":"thuộc, là một phần của","pos":"Động từ","example":{"zh":"他属于这个小组。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"属","py":"shǔ"},{"c":"于","py":"yú"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"组","py":"zǔ"},{"c":"。","py":"。"}],"vi":"Anh ấy thuộc nhóm nhỏ này."}},{"hanzi":"布","pinyin":"bù","hanViet":"BỐ","meaning":"vải, vải dệt","pos":"Danh từ","example":{"zh":"这块布很软。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"块","py":"kuài"},{"c":"布","py":"bù"},{"c":"很","py":"hěn"},{"c":"软","py":"ruǎn"},{"c":"。","py":"。"}],"vi":"Miếng vải này rất mềm."}},{"hanzi":"带领","pinyin":"dàilǐng","hanViet":"ĐỚI LÃNH","meaning":"lãnh đạo, dẫn đầu","pos":"Động từ","example":{"zh":"他带领团队。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"带","py":"dài"},{"c":"领","py":"lǐng"},{"c":"团","py":"tuán"},{"c":"队","py":"duì"},{"c":"。","py":"。"}],"vi":"Anh ấy dẫn đầu nhóm."}},{"hanzi":"并","pinyin":"bìng","hanViet":"TỊNH","meaning":"và","pos":"Liên từ","example":{"zh":"他并没有来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"并","py":"bìng"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy không đến."}},{"hanzi":"并且","pinyin":"bìngqiě","hanViet":"TỊNH THẢ","meaning":"và, đồng thời","pos":"Liên từ","example":{"zh":"他很聪明并且很努力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"聪","py":"cōng"},{"c":"明","py":"míng"},{"c":"并","py":"bìng"},{"c":"且","py":"qiě"},{"c":"很","py":"hěn"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Anh ấy rất thông minh và rất chăm chỉ."}},{"hanzi":"幸福","pinyin":"xìngfú","hanViet":"HẠNH PHÚC","meaning":"Hạnh phúc, may mắn","pos":"Tính từ","example":{"zh":"他们过着幸福的生活。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"过","py":"guò"},{"c":"着","py":"zhe"},{"c":"幸","py":"xìng"},{"c":"福","py":"fú"},{"c":"的","py":"de"},{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"。","py":"。"}],"vi":"Họ sống một cuộc sống hạnh phúc."}},{"hanzi":"幸运","pinyin":"xìngyùn","hanViet":"HẠNH VẬN","meaning":"May mắn","pos":"Tính từ","example":{"zh":"他今天很幸运。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"很","py":"hěn"},{"c":"幸","py":"xìng"},{"c":"运","py":"yùn"},{"c":"。","py":"。"}],"vi":"Cậu ấy hôm nay rất may mắn."}},{"hanzi":"广大","pinyin":"guǎngdà","hanViet":"QUẢNG ĐẠI","meaning":"rộng lớn, rộng khắp","pos":"Tính từ","example":{"zh":"广大地区。","pinyinPerChar":[{"c":"广","py":"guǎng"},{"c":"大","py":"dà"},{"c":"地","py":"dì"},{"c":"区","py":"qū"},{"c":"。","py":"。"}],"vi":"Khu vực rộng lớn."}},{"hanzi":"庆祝","pinyin":"qìngzhù","hanViet":"KHÁNH CHÚC","meaning":"tưởng niệm, mừng","pos":"Động từ","example":{"zh":"我们庆祝生日。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"庆","py":"qìng"},{"c":"祝","py":"zhù"},{"c":"生","py":"shēng"},{"c":"日","py":"rì"},{"c":"。","py":"。"}],"vi":"Chúng tôi mừng sinh nhật."}},{"hanzi":"应当","pinyin":"yīngdāng","hanViet":"ƯNG ĐƯƠNG","meaning":"phải, nên, phải làm","pos":"Động từ","example":{"zh":"我们应当遵守规则。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"应","py":"yīng"},{"c":"当","py":"dāng"},{"c":"遵","py":"zūn"},{"c":"守","py":"shǒu"},{"c":"规","py":"guī"},{"c":"则","py":"zé"},{"c":"。","py":"。"}],"vi":"Chúng ta phải tuân thủ quy tắc."}},{"hanzi":"应用","pinyin":"yìngyòng","hanViet":"ƯNG DỤNG","meaning":"sử dụng, ứng dụng","pos":"Danh từ","example":{"zh":"科技有很多应用。","pinyinPerChar":[{"c":"科","py":"kē"},{"c":"技","py":"jì"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"应","py":"yīng"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Công nghệ có nhiều ứng dụng."}},{"hanzi":"建","pinyin":"jiàn","hanViet":"KIẾN","meaning":"lập, xây dựng","pos":"Động từ","example":{"zh":"我们要建一座学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"建","py":"jiàn"},{"c":"一","py":"yī"},{"c":"座","py":"zuò"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Chúng tôi muốn xây dựng một ngôi trường."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-34', 33, 'Bổ sung (6)', '[{"hanzi":"建设","pinyin":"jiànshè","hanViet":"KIẾN THIẾT","meaning":"xây dựng, phát triển","pos":"Động từ","example":{"zh":"我们要建设家乡。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"建","py":"jiàn"},{"c":"设","py":"shè"},{"c":"家","py":"jiā"},{"c":"乡","py":"xiāng"},{"c":"。","py":"。"}],"vi":"Chúng ta cần xây dựng quê hương."}},{"hanzi":"开始","pinyin":"kāishǐ","hanViet":"KHAI THUỶ","meaning":"bắt đầu","pos":"Động từ","example":{"zh":"课程开始了。","pinyinPerChar":[{"c":"课","py":"kè"},{"c":"程","py":"chéng"},{"c":"开","py":"kāi"},{"c":"始","py":"shǐ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Giờ học bắt đầu rồi."}},{"hanzi":"强","pinyin":"qiáng","hanViet":"CƯỜNG","meaning":"Mạnh, mạnh mẽ","pos":"Tính từ","example":{"zh":"他很强。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"强","py":"qiáng"},{"c":"。","py":"。"}],"vi":"Anh ấy rất mạnh."}},{"hanzi":"强大","pinyin":"qiángdà","hanViet":"CƯỜNG ĐẠI","meaning":"Mạnh mẽ, vĩ đại","pos":"Tính từ","example":{"zh":"这个国家很强大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"国","py":"guó"},{"c":"家","py":"jiā"},{"c":"很","py":"hěn"},{"c":"强","py":"qiáng"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Quốc gia này rất mạnh mẽ."}},{"hanzi":"强调","pinyin":"qiángdiào","hanViet":"CƯỜNG ĐIỆU","meaning":"Nhấn mạnh","pos":"Động từ","example":{"zh":"老师强调了这个问题。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"强","py":"qiáng"},{"c":"调","py":"diào"},{"c":"了","py":"le"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Giáo viên nhấn mạnh vấn đề này."}},{"hanzi":"当中","pinyin":"dāngzhōng","hanViet":"ĐƯƠNG TRUNG","meaning":"trong số, trong đó","pos":"Danh từ","example":{"zh":"当中有很多人。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"中","py":"zhōng"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Trong số đó có nhiều người."}},{"hanzi":"录","pinyin":"lù","hanViet":"LỤC","meaning":"ghi lại","pos":"Động từ","example":{"zh":"我在录视频。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"录","py":"lù"},{"c":"视","py":"shì"},{"c":"频","py":"pín"},{"c":"。","py":"。"}],"vi":"Tôi đang ghi video."}},{"hanzi":"录音","pinyin":"lùyīn","hanViet":"LỤC ÂM","meaning":"ghi âm","pos":"Danh từ","example":{"zh":"他在录音。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"录","py":"lù"},{"c":"音","py":"yīn"},{"c":"。","py":"。"}],"vi":"Anh ấy đang ghi âm."}},{"hanzi":"形状","pinyin":"xíngzhuàng","hanViet":"HÌNH TRẠNG","meaning":"Hình dáng, hình thức","pos":"Danh từ","example":{"zh":"这个球的形状很圆。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"球","py":"qiú"},{"c":"的","py":"de"},{"c":"形","py":"xíng"},{"c":"状","py":"zhuàng"},{"c":"很","py":"hěn"},{"c":"圆","py":"yuán"},{"c":"。","py":"。"}],"vi":"Hình dáng của quả bóng này rất tròn."}},{"hanzi":"形象","pinyin":"xíngxiàng","hanViet":"HÌNH TƯỢNG","meaning":"Hình ảnh, ngoại hình, hình tượng","pos":"Tính từ","example":{"zh":"他有很好的形象。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"的","py":"de"},{"c":"形","py":"xíng"},{"c":"象","py":"xiàng"},{"c":"。","py":"。"}],"vi":"Cậu ấy có hình ảnh rất tốt."}},{"hanzi":"影视","pinyin":"yǐngshì","hanViet":"ẢNH THỊ","meaning":"hình ảnh và điện ảnh","pos":"Danh từ","example":{"zh":"这部影视作品很受欢迎。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"影","py":"yǐng"},{"c":"视","py":"shì"},{"c":"作","py":"zuò"},{"c":"品","py":"pǐn"},{"c":"很","py":"hěn"},{"c":"受","py":"shòu"},{"c":"欢","py":"huān"},{"c":"迎","py":"yíng"},{"c":"。","py":"。"}],"vi":"Tác phẩm điện ảnh này rất được nhiều người quý thích."}},{"hanzi":"志愿","pinyin":"zhìyuàn","hanViet":"CHÍ NGUYỆN","meaning":"ý định, sứ mệnh","pos":"Danh từ","example":{"zh":"他报名参加志愿者活动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"报","py":"bào"},{"c":"名","py":"míng"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"志","py":"zhì"},{"c":"愿","py":"yuàn"},{"c":"者","py":"zhě"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Cô ấy đăng ký tham gia hoạt động tình nguyện."}},{"hanzi":"志愿者","pinyin":"zhìyuànzhě","hanViet":"CHÍ NGUYỆN GIẢ","meaning":"người làm tình nguyện","pos":"Danh từ","example":{"zh":"志愿者帮助了很多人。","pinyinPerChar":[{"c":"志","py":"zhì"},{"c":"愿","py":"yuàn"},{"c":"者","py":"zhě"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Người tình nguyện đã giúp rất nhiều người."}},{"hanzi":"快速","pinyin":"kuàisù","hanViet":"KHOÁI TỐC","meaning":"nhanh, nhanh chóng","pos":"Tính từ","example":{"zh":"他走得很快。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"得","py":"dé"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Anh ấy đi rất nhanh."}},{"hanzi":"怕","pinyin":"pà","hanViet":"PHẠ","meaning":"sợ, e ngại","pos":"Động từ","example":{"zh":"他怕冷。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"怕","py":"pà"},{"c":"冷","py":"lěng"},{"c":"。","py":"。"}],"vi":"Anh ấy sợ lạnh."}},{"hanzi":"情况","pinyin":"qíngkuàng","hanViet":"TÌNH HUỐNG","meaning":"tình hình, tình trạng","pos":"Danh từ","example":{"zh":"情况很好。","pinyinPerChar":[{"c":"情","py":"qíng"},{"c":"况","py":"kuàng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Tình hình rất tốt."}},{"hanzi":"意义","pinyin":"yìyì","hanViet":"Ý NGHĨA","meaning":"sự có ý nghĩa, giá trị","pos":"Danh từ","example":{"zh":"这件事有重要意义。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"有","py":"yǒu"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"意","py":"yì"},{"c":"义","py":"yì"},{"c":"。","py":"。"}],"vi":"Việc này có ý nghĩa quan trọng."}},{"hanzi":"意外","pinyin":"yìwài","hanViet":"Ý NGOẠI","meaning":"ngạc nhiên, bất ngờ","pos":"Tính từ","example":{"zh":"这件事很意外。","pinyinPerChar":[{