INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-36', 35, 'Bổ sung (8)', '[{"hanzi":"标题","pinyin":"biāotí","hanViet":"TIÊU ĐỀ","meaning":"tiêu đề","pos":"Danh từ","example":{"zh":"这篇文章标题很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"篇","py":"piān"},{"c":"文","py":"wén"},{"c":"章","py":"zhāng"},{"c":"标","py":"biāo"},{"c":"题","py":"tí"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Tiêu đề bài viết này rất hay."}},{"hanzi":"歌声","pinyin":"gēshēng","hanViet":"CA THANH","meaning":"âm thanh ca","pos":"Danh từ","example":{"zh":"她唱歌声很好听。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"唱","py":"chàng"},{"c":"歌","py":"gē"},{"c":"声","py":"shēng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"听","py":"tīng"},{"c":"。","py":"。"}],"vi":"Tiếng ca của cô ấy rất hay nghe."}},{"hanzi":"正","pinyin":"zhèng","hanViet":"CHÍNH","meaning":"đúng, chính, hướng","pos":"Tính từ","example":{"zh":"正面。","pinyinPerChar":[{"c":"正","py":"zhèng"},{"c":"面","py":"miàn"},{"c":"。","py":"。"}],"vi":"Mặt trước."}},{"hanzi":"武术","pinyin":"wǔshù","hanViet":"VÕ THUẬT","meaning":"võ thuật","pos":"Danh từ","example":{"zh":"他练习武术。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"练","py":"liàn"},{"c":"习","py":"xí"},{"c":"武","py":"wǔ"},{"c":"术","py":"shù"},{"c":"。","py":"。"}],"vi":"Anh ấy tập võ thuật."}},{"hanzi":"死","pinyin":"sǐ","hanViet":"TỬ","meaning":"chết","pos":"Động từ","example":{"zh":"这只猫死了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"只","py":"zhǐ"},{"c":"猫","py":"māo"},{"c":"死","py":"sǐ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Con mèo này đã chết."}},{"hanzi":"每","pinyin":"měi","hanViet":"MỖI","meaning":"mỗi","pos":"Tính từ","example":{"zh":"每天都很忙。","pinyinPerChar":[{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"都","py":"dōu"},{"c":"很","py":"hěn"},{"c":"忙","py":"máng"},{"c":"。","py":"。"}],"vi":"Mỗi ngày đều rất bận."}},{"hanzi":"比例","pinyin":"bǐlì","hanViet":"TỶ LỆ","meaning":"tỷ lệ, tỷ lệ phần trăm","pos":"Danh từ","example":{"zh":"男生和女生的比例是多少？","pinyinPerChar":[{"c":"男","py":"nán"},{"c":"生","py":"shēng"},{"c":"和","py":"hé"},{"c":"女","py":"nǚ"},{"c":"生","py":"shēng"},{"c":"的","py":"de"},{"c":"比","py":"bǐ"},{"c":"例","py":"lì"},{"c":"是","py":"shì"},{"c":"多","py":"duō"},{"c":"少","py":"shǎo"},{"c":"？","py":"？"}],"vi":"Tỷ lệ nam và nữ là bao nhiêu?"}},{"hanzi":"民族","pinyin":"mínzú","hanViet":"DÂN TỘC","meaning":"Dân tộc","pos":"Danh từ","example":{"zh":"他是中国民族。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"中","py":"zhōng"},{"c":"国","py":"guó"},{"c":"民","py":"mín"},{"c":"族","py":"zú"},{"c":"。","py":"。"}],"vi":"Anh ấy là người Trung Quốc."}},{"hanzi":"民间","pinyin":"mínjiān","hanViet":"DÂN GIAN","meaning":"Dân gian, của người dân","pos":"Tính từ","example":{"zh":"民间故事很有趣。","pinyinPerChar":[{"c":"民","py":"mín"},{"c":"间","py":"jiān"},{"c":"故","py":"gù"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"趣","py":"qù"},{"c":"。","py":"。"}],"vi":"Truyện cổ của người dân rất thú vị."}},{"hanzi":"注意","pinyin":"zhùyì","hanViet":"CHÚ Ý","meaning":"có ý thức, lưu ý","pos":"Động từ","example":{"zh":"请注意安全。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"注","py":"zhù"},{"c":"意","py":"yì"},{"c":"安","py":"ān"},{"c":"全","py":"quán"},{"c":"。","py":"。"}],"vi":"Xin hãy chú ý an toàn."}},{"hanzi":"深","pinyin":"shēn","hanViet":"THÂM","meaning":"sâu, sâu","pos":"Tính từ","example":{"zh":"这条河很深。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"河","py":"hé"},{"c":"很","py":"hěn"},{"c":"深","py":"shēn"},{"c":"。","py":"。"}],"vi":"Con sông này rất sâu."}},{"hanzi":"温暖","pinyin":"wēnnuǎn","hanViet":"ÔN NOÃN","meaning":"ấm, ấm áp","pos":"Tính từ","example":{"zh":"天气很温暖。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"温","py":"wēn"},{"c":"暖","py":"nuǎn"},{"c":"。","py":"。"}],"vi":"Thời tiết rất ấm."}},{"hanzi":"游","pinyin":"yóu","hanViet":"DU","meaning":"chơi, đi du lịch, bơi","pos":"Động từ","example":{"zh":"他们去游泳。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"游","py":"yóu"},{"c":"泳","py":"yǒng"},{"c":"。","py":"。"}],"vi":"Họ đi bơi."}},{"hanzi":"游戏","pinyin":"yóuxì","hanViet":"DU HÍ","meaning":"trò chơi","pos":"Danh từ","example":{"zh":"孩子们喜欢玩游戏。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"玩","py":"wán"},{"c":"游","py":"yóu"},{"c":"戏","py":"xì"},{"c":"。","py":"。"}],"vi":"Trẻ em thích chơi trò chơi."}},{"hanzi":"游泳","pinyin":"yóuyǒng","hanViet":"DU VỊNH","meaning":"bơi","pos":"Động từ","example":{"zh":"我每天晚上游泳。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"晚","py":"wǎn"},{"c":"上","py":"shàng"},{"c":"游","py":"yóu"},{"c":"泳","py":"yǒng"},{"c":"。","py":"。"}],"vi":"Tôi bơi mỗi tối."}},{"hanzi":"满足","pinyin":"mǎnzú","hanViet":"MÃN TÚC","meaning":"thỏa mãn, hài lòng","pos":"Động từ","example":{"zh":"我很满足。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"满","py":"mǎn"},{"c":"足","py":"zú"},{"c":"。","py":"。"}],"vi":"Tôi rất hài lòng."}},{"hanzi":"演出","pinyin":"yǎnchū","hanViet":"DIỄN XUẤT","meaning":"trình diễn, biểu diễn","pos":"Danh từ","example":{"zh":"这场演出很精彩。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"场","py":"chǎng"},{"c":"演","py":"yǎn"},{"c":"出","py":"chū"},{"c":"很","py":"hěn"},{"c":"精","py":"jīng"},{"c":"彩","py":"cǎi"},{"c":"。","py":"。"}],"vi":"Buổi trình diễn này rất hay."}},{"hanzi":"演员","pinyin":"yǎnyuán","hanViet":"DIỄN VIÊN","meaning":"diễn viên","pos":"Danh từ","example":{"zh":"他是演员。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"演","py":"yǎn"},{"c":"员","py":"yuán"},{"c":"。","py":"。"}],"vi":"Anh ấy là diễn viên."}},{"hanzi":"演唱","pinyin":"yǎnchàng","hanViet":"DIỄN XƯỚNG","meaning":"hát, trình diễn bài hát","pos":"Động từ","example":{"zh":"她会演唱歌曲。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"会","py":"huì"},{"c":"演","py":"yǎn"},{"c":"唱","py":"chàng"},{"c":"歌","py":"gē"},{"c":"曲","py":"qū"},{"c":"。","py":"。"}],"vi":"Cô ấy có thể hát bài hát."}},{"hanzi":"演唱会","pinyin":"yǎnchànghuì","hanViet":"DIỄN XƯỚNG HỘI","meaning":"buổi biểu diễn nhạc, buổi hòa nhạc","pos":"Danh từ","example":{"zh":"他们去看演唱会。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"看","py":"kàn"},{"c":"演","py":"yǎn"},{"c":"唱","py":"chàng"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Họ đi xem buổi biểu diễn nhạc."}},{"hanzi":"照","pinyin":"zhào","hanViet":"CHIẾU","meaning":"chiếu, chụp ảnh, nhìn","pos":"Động từ","example":{"zh":"照相机。","pinyinPerChar":[{"c":"照","py":"zhào"},{"c":"相","py":"xiāng"},{"c":"机","py":"jī"},{"c":"。","py":"。"}],"vi":"Máy chụp ảnh."}},{"hanzi":"熟人","pinyin":"shúrén","hanViet":"THỤC NHÂN","meaning":"Người quen, người biết","pos":"Danh từ","example":{"zh":"我认识很多熟人。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"认","py":"rèn"},{"c":"识","py":"shí"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"熟","py":"shú"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Tôi biết nhiều người quen."}},{"hanzi":"牛","pinyin":"niú","hanViet":"NGƯU","meaning":"tuyệt vời, rất","pos":"Tính từ","example":{"zh":"这件事很牛。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"牛","py":"niú"},{"c":"。","py":"。"}],"vi":"Câu chuyện này rất tuyệt vời."}},{"hanzi":"特色","pinyin":"tèsè","hanViet":"ĐẶC SẮC","meaning":"đặc trưng, nét riêng","pos":"Danh từ","example":{"zh":"这座城市有很多特色。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"城","py":"chéng"},{"c":"市","py":"shì"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"特","py":"tè"},{"c":"色","py":"sè"},{"c":"。","py":"。"}],"vi":"Thành phố này có nhiều nét đặc trưng."}},{"hanzi":"状态","pinyin":"zhuàngtài","hanViet":"TRẠNG THÁI","meaning":"tình trạng, trạng thái","pos":"Danh từ","example":{"zh":"状态正常。","pinyinPerChar":[{"c":"状","py":"zhuàng"},{"c":"态","py":"tài"},{"c":"正","py":"zhèng"},{"c":"常","py":"cháng"},{"c":"。","py":"。"}],"vi":"Trạng thái bình thường.