INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-37', 36, 'Bổ sung (9)', '[{"hanzi":"猪","pinyin":"zhū","hanViet":"TRƯ","meaning":"heo","pos":"Danh từ","example":{"zh":"猪在吃饭。","pinyinPerChar":[{"c":"猪","py":"zhū"},{"c":"在","py":"zài"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Heo đang ăn."}},{"hanzi":"现代","pinyin":"xiàndài","hanViet":"HIỆN ĐẠI","meaning":"thời đại hiện nay, hiện đại","pos":"Danh từ","example":{"zh":"他是现代人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"现","py":"xiàn"},{"c":"代","py":"dài"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy là người hiện đại."}},{"hanzi":"现场","pinyin":"xiànchǎng","hanViet":"HIỆN TRƯỜNG","meaning":"sân khấu, hiện trường, hiện trường","pos":"Danh từ","example":{"zh":"他们在现场表演。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"现","py":"xiàn"},{"c":"场","py":"chǎng"},{"c":"表","py":"biǎo"},{"c":"演","py":"yǎn"},{"c":"。","py":"。"}],"vi":"Họ biểu diễn tại hiện trường."}},{"hanzi":"现实","pinyin":"xiànshí","hanViet":"HIỆN THỰC","meaning":"thực tế, hiện thực","pos":"Tính từ","example":{"zh":"这件事很现实。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"现","py":"xiàn"},{"c":"实","py":"shí"},{"c":"。","py":"。"}],"vi":"Việc này rất thực tế."}},{"hanzi":"现象","pinyin":"xiànxiàng","hanViet":"HIỆN TƯỢNG","meaning":"hiện tượng, dấu hiệu","pos":"Danh từ","example":{"zh":"天气变化是现象。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"变","py":"biàn"},{"c":"化","py":"huà"},{"c":"是","py":"shì"},{"c":"现","py":"xiàn"},{"c":"象","py":"xiàng"},{"c":"。","py":"。"}],"vi":"Thay đổi thời tiết là hiện tượng."}},{"hanzi":"球迷","pinyin":"qiúmí","hanViet":"CẦU MÊ","meaning":"người hâm mộ bóng","pos":"Danh từ","example":{"zh":"他是足球迷。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"足","py":"zú"},{"c":"球","py":"qiú"},{"c":"迷","py":"mí"},{"c":"。","py":"。"}],"vi":"Anh ấy là người hâm mộ bóng đá."}},{"hanzi":"理解","pinyin":"lǐjiě","hanViet":"LÝ GIẢI","meaning":"hiểu, thấu hiểu","pos":"Động từ","example":{"zh":"我理解你的意思。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"理","py":"lǐ"},{"c":"解","py":"jiě"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Tôi hiểu ý của bạn."}},{"hanzi":"生动","pinyin":"shēngdòng","hanViet":"SINH ĐỘNG","meaning":"sống động, sinh động","pos":"Tính từ","example":{"zh":"这幅画非常生动。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"幅","py":"fú"},{"c":"画","py":"huà"},{"c":"非","py":"fēi"},{"c":"常","py":"cháng"},{"c":"生","py":"shēng"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Bức tranh này rất sống động."}},{"hanzi":"生存","pinyin":"shēngcún","hanViet":"SINH TỒN","meaning":"sống sót, tồn tại","pos":"Động từ","example":{"zh":"动物需要生存。","pinyinPerChar":[{"c":"动","py":"dòng"},{"c":"物","py":"wù"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"生","py":"shēng"},{"c":"存","py":"cún"},{"c":"。","py":"。"}],"vi":"Động vật cần sống sót."}},{"hanzi":"由","pinyin":"yóu","hanViet":"DO","meaning":"do, bởi","pos":"Liên từ","example":{"zh":"这件事由他负责。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"由","py":"yóu"},{"c":"他","py":"tā"},{"c":"负","py":"fù"},{"c":"责","py":"zé"},{"c":"。","py":"。"}],"vi":"Việc này do anh ấy chịu trách nhiệm."}},{"hanzi":"由于","pinyin":"yóuyú","hanViet":"DO Ư","meaning":"do, vì","pos":"Liên từ","example":{"zh":"由于下雨，比赛取消了。","pinyinPerChar":[{"c":"由","py":"yóu"},{"c":"于","py":"yú"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"，","py":"，"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"取","py":"qǔ"},{"c":"消","py":"xiāo"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Do mưa nên trận thi bị hủy."}},{"hanzi":"痛苦","pinyin":"tòngkǔ","hanViet":"THỐNG KHỔ","meaning":"buồn bã, đau đớn trong tâm hồn","pos":"Tính từ","example":{"zh":"她经历了很多痛苦。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"经","py":"jīng"},{"c":"历","py":"lì"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"痛","py":"tòng"},{"c":"苦","py":"kǔ"},{"c":"。","py":"。"}],"vi":"Cô ấy trải qua nhiều đau khổ."}},{"hanzi":"白菜","pinyin":"báicài","hanViet":"BẠCH THÁI","meaning":"bắp cải","pos":"Danh từ","example":{"zh":"我喜欢吃白菜。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"白","py":"bái"},{"c":"菜","py":"cài"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn bắp cải."}},{"hanzi":"目标","pinyin":"mùbiāo","hanViet":"MỤC TIÊU","meaning":"Mục tiêu","pos":"Danh từ","example":{"zh":"我们有明确目标。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"有","py":"yǒu"},{"c":"明","py":"míng"},{"c":"确","py":"què"},{"c":"目","py":"mù"},{"c":"标","py":"biāo"},{"c":"。","py":"。"}],"vi":"Chúng ta có mục tiêu rõ ràng."}},{"hanzi":"直","pinyin":"zhí","hanViet":"TRỰC","meaning":"thẳng, trực","pos":"Tính từ","example":{"zh":"这条路很直。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"直","py":"zhí"},{"c":"。","py":"。"}],"vi":"Con đường này rất thẳng."}},{"hanzi":"直播","pinyin":"zhíbō","hanViet":"TRỰC BÁ","meaning":"phát trực tiếp","pos":"Danh từ","example":{"zh":"他们正在直播比赛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"直","py":"zhí"},{"c":"播","py":"bō"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"。","py":"。"}],"vi":"Họ đang phát trực tiếp cuộc thi."}},{"hanzi":"相似","pinyin":"xiāngsì","hanViet":"TƯƠNG TỰ","meaning":"giống nhau, tương tự","pos":"Tính từ","example":{"zh":"这两件衣服很相似。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"两","py":"liǎng"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"很","py":"hěn"},{"c":"相","py":"xiāng"},{"c":"似","py":"shì"},{"c":"。","py":"。"}],"vi":"Hai bộ quần áo này rất giống nhau."}},{"hanzi":"相当","pinyin":"xiāngdāng","hanViet":"TƯƠNG ĐƯƠNG","meaning":"rất, tương đương, khá","pos":"Tính từ","example":{"zh":"这本书相当好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"相","py":"xiāng"},{"c":"当","py":"dāng"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cuốn sách này khá tốt."}},{"hanzi":"相比","pinyin":"xiāngbǐ","hanViet":"TƯƠNG TỶ","meaning":"so sánh với, đối chiếu với","pos":"Động từ","example":{"zh":"我相比他更努力。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"相","py":"xiāng"},{"c":"比","py":"bǐ"},{"c":"他","py":"tā"},{"c":"更","py":"gèng"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Tôi siêng năng hơn anh ấy."}},{"hanzi":"短期","pinyin":"duǎnqī","hanViet":"ĐOẢN KỲ","meaning":"Ngắn hạn","pos":"Tính từ","example":{"zh":"我们计划短期旅行。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"短","py":"duǎn"},{"c":"期","py":"qī"},{"c":"旅","py":"lǚ"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Chúng tôi định đi du lịch ngắn hạn."}},{"hanzi":"社会","pinyin":"shèhuì","hanViet":"XÃ HỘI","meaning":"xã hội","pos":"Danh từ","example":{"zh":"社会发展很快。","pinyinPerChar":[{"c":"社","py":"shè"},{"c":"会","py":"huì"},{"c":"发","py":"fā"},{"c":"展","py":"zhǎn"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Xã hội phát triển rất nhanh."}},{"hanzi":"祝","pinyin":"zhù","hanViet":"CHÚC","meaning":"chúc, mời","pos":"Động từ","example":{"zh":"祝你生日快乐。","pinyinPerChar":[{"c":"祝","py":"zhù"},{"c":"你","py":"nǐ"},{"c":"生","py":"shēng"},{"c":"日","py":"rì"},{"c":"快","py":"kuài"},{"c":"乐","py":"lè"},{"c":"。","py":"。"}],"vi":"Chúc bạn sinh nhật vui vẻ."}},{"hanzi":"种","pinyin":"zhǒng","hanViet":"CHỦNG","meaning":"loại, giống","pos":"Tính từ","example":{"zh":"这是一种好种。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"种","py":"zhǒng"},{"c":"好","py":"hǎo"},{"c":"种","py":"zhǒng"},{"c":"。","py":"。"}],"vi":"Đây là một loại giống tốt."}},{"hanzi":"积极","pinyin":"jījí","hanViet":"TÍCH CỰC","meaning":"tích cực","pos":"Tính từ","example":{"zh":"她积极学习。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"积","py":"jī"},{"c":"极","py":"jí"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Cô ấy tích cực học tập."}},{"hanzi":"称为","pinyin":"chēngwéi","hanViet":"XƯNG VỊ","meaning":"được gọi là, tròn với","pos":"Động từ","example":{"zh":"这座山称为富士山。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"山","py":"shān"},{"c":"称","py":"chēng"},{"c":"为","py":"wèi"},{"c":"富","py":"fù"},{"c":"士","py":"shì"},{"c":"山","py":"shān"},{"c":"。","py":"。"}],"vi":"Ngọn núi này được gọi là Phú Sĩ Sơn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-38', 37, 'Bổ sung (10)', '[{"hanzi":"简直","pinyin":"jiǎnzhí","hanViet":"GIẢN TRỰC","meaning":"rất, gần như","pos":"Phó từ","example":{"zh":"今天天气简直太热了。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"简","py":"jiǎn"},{"c":"直","py":"zhí"},{"c":"太","py":"tài"},{"c":"热","py":"rè"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Ngày hôm nay thời tiết gần như quá nóng."}},{"hanzi":"类","pinyin":"lèi","hanViet":"LOẠI","meaning":"loại, hạng, nhóm","pos":"Danh từ","example":{"zh":"这类东西很贵。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"类","py":"lèi"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Loại thứ này rất đắt."}},{"hanzi":"类似","pinyin":"lèisì","hanViet":"LOẠI TỰ","meaning":"giống, tương tự","pos":"Liên từ","example":{"zh":"这两个问题类似。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"两","py":"liǎng"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"类","py":"lèi"},{"c":"似","py":"shì"},{"c":"。","py":"。"}],"vi":"Hai vấn đề này giống nhau."}},{"hanzi":"精彩","pinyin":"jīngcǎi","hanViet":"TINH THÁI","meaning":"Rất hay, xuất sắc","pos":"Tính từ","example":{"zh":"演出很精彩。","pinyinPerChar":[{"c":"演","py":"yǎn"},{"c":"出","py":"chū"},{"c":"很","py":"hěn"},{"c":"精","py":"jīng"},{"c":"彩","py":"cǎi"},{"c":"。","py":"。"}],"vi":"Diễn xuất rất hay."}},{"hanzi":"系","pinyin":"xì","hanViet":"HỆ","meaning":"kế, hệ thống, bộ môn","pos":"Danh từ","example":{"zh":"他是系主任。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"系","py":"xì"},{"c":"主","py":"zhǔ"},{"c":"任","py":"rèn"},{"c":"。","py":"。"}],"vi":"Anh ấy là giám đốc bộ môn."}},{"hanzi":"紧急","pinyin":"jǐnjí","hanViet":"KHẨN CẤP","meaning":"khẩn cấp","pos":"Tính từ","example":{"zh":"这件事很紧急。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"紧","py":"jǐn"},{"c":"急","py":"jí"},{"c":"。","py":"。"}],"vi":"Việc này khẩn cấp."}},{"hanzi":"纪录","pinyin":"jìlù","hanViet":"KỶ LỤC","meaning":"ghi lại, lưu trữ","pos":"Động từ","example":{"zh":"摄影师纪录了风景。","pinyinPerChar":[{"c":"摄","py":"shè"},{"c":"影","py":"yǐng"},{"c":"师","py":"shī"},{"c":"纪","py":"jì"},{"c":"录","py":"lù"},{"c":"了","py":"le"},{"c":"风","py":"fēng"},{"c":"景","py":"jǐng"},{"c":"。","py":"。"}],"vi":"Nhiếp ảnh gia đã ghi lại cảnh đẹp."}},{"hanzi":"组合","pinyin":"zǔhé","hanViet":"TỔ HỢP","meaning":"tổ hợp, kết hợp","pos":"Danh từ","example":{"zh":"这两种颜色很好组合。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"两","py":"liǎng"},{"c":"种","py":"zhǒng"},{"c":"颜","py":"yán"},{"c":"色","py":"sè"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"组","py":"zǔ"},{"c":"合","py":"hé"},{"c":"。","py":"。"}],"vi":"Màu sắc hai loại này hợp nhau rất tốt."}},{"hanzi":"结合","pinyin":"jiéhé","hanViet":"KẾT HỢP","meaning":"kết hợp","pos":"Động từ","example":{"zh":"这两种颜色结合得很好看。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"两","py":"liǎng"},{"c":"种","py":"zhǒng"},{"c":"颜","py":"yán"},{"c":"色","py":"sè"},{"c":"结","py":"jié"},{"c":"合","py":"hé"},{"c":"得","py":"dé"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"看","py":"kàn"},{"c":"。","py":"。"}],"vi":"Hai màu này kết hợp rất đẹp."}},{"hanzi":"结束","pinyin":"jiéshù","hanViet":"KẾT THÚC","meaning":"kết thúc","pos":"Động từ","example":{"zh":"课程结束了。","pinyinPerChar":[{"c":"课","py":"kè"},{"c":"程","py":"chéng"},{"c":"结","py":"jié"},{"c":"束","py":"shù"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Buổi học đã kết thúc."}},{"hanzi":"继续","pinyin":"jìxù","hanViet":"KẾ TỤC","meaning":"tiếp tục, làm tiếp","pos":"Động từ","example":{"zh":"我们继续学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"继","py":"jì"},{"c":"续","py":"xù"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Chúng tôi tiếp tục học tập."}},{"hanzi":"羊","pinyin":"yáng","hanViet":"DƯƠNG","meaning":"cừu, dê","pos":"Danh từ","example":{"zh":"羊很可爱。","pinyinPerChar":[{"c":"羊","py":"yáng"},{"c":"很","py":"hěn"},{"c":"可","py":"kě"},{"c":"爱","py":"ài"},{"c":"。","py":"。"}],"vi":"Cừu rất dễ thương."}},{"hanzi":"美","pinyin":"měi","hanViet":"MỸ","meaning":"xinh đẹp, Mỹ","pos":"Tính từ","example":{"zh":"这座山很美。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"山","py":"shān"},{"c":"很","py":"hěn"},{"c":"美","py":"měi"},{"c":"。","py":"。"}],"vi":"Núi này rất đẹp."}},{"hanzi":"美术","pinyin":"měishù","hanViet":"MỸ THUẬT","meaning":"Mỹ thuật","pos":"Danh từ","example":{"zh":"他喜欢美术。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"美","py":"měi"},{"c":"术","py":"shù"},{"c":"。","py":"。"}],"vi":"Anh ấy thích mỹ thuật."}},{"hanzi":"者（志愿者）","pinyin":"zhě (zhìyuànzhě)","hanViet":"GIẢ CHÍ NGUYỆN GIẢ","meaning":"người làm gì, người thực hiện","pos":"Danh từ","example":{"zh":"志愿者。","pinyinPerChar":[{"c":"志","py":"zhì"},{"c":"愿","py":"yuàn"},{"c":"者","py":"zhě"},{"c":"。","py":"。"}],"vi":"Người tình nguyện."}},{"hanzi":"职业","pinyin":"zhíyè","hanViet":"CHỨC NGHIỆP","meaning":"nghề nghiệp","pos":"Danh từ","example":{"zh":"她的职业是老师。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"职","py":"zhí"},{"c":"业","py":"yè"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Nghề nghiệp của cô ấy là giáo viên."}},{"hanzi":"联合国","pinyin":"Liánhéguó","hanViet":"LIÊN HỢP QUỐC","meaning":"Liên Hợp Quốc","pos":"Danh từ","example":{"zh":"联合国在维护和平。","pinyinPerChar":[{"c":"联","py":"lián"},{"c":"合","py":"hé"},{"c":"国","py":"guó"},{"c":"在","py":"zài"},{"c":"维","py":"wéi"},{"c":"护","py":"hù"},{"c":"和","py":"hé"},{"c":"平","py":"píng"},{"c":"。","py":"。"}],"vi":"Liên Hợp Quốc đang bảo vệ hòa bình."}},{"hanzi":"背后","pinyin":"bèihòu","hanViet":"BỐI HẬU","meaning":"đằng sau","pos":"Danh từ","example":{"zh":"我坐在他背后。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"坐","py":"zuò"},{"c":"在","py":"zài"},{"c":"他","py":"tā"},{"c":"背","py":"bèi"},{"c":"后","py":"hòu"},{"c":"。","py":"。"}],"vi":"Tôi ngồi đằ