INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-39', 38, 'Bổ sung (11)', '[{"hanzi":"范围","pinyin":"fànwéi","hanViet":"PHẠM VI","meaning":"mức độ, phạm vi","pos":"Danh từ","example":{"zh":"这个问题的范围很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"的","py":"de"},{"c":"范","py":"fàn"},{"c":"围","py":"wéi"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Phạm vi của vấn đề này rất lớn."}},{"hanzi":"补","pinyin":"bǔ","hanViet":"BỔ","meaning":"bổ sung","pos":"Động từ","example":{"zh":"我要补习中文。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"补","py":"bǔ"},{"c":"习","py":"xí"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"。","py":"。"}],"vi":"Tôi muốn học thêm tiếng Trung."}},{"hanzi":"补充","pinyin":"bǔchōng","hanViet":"BỔ SUNG","meaning":"bổ sung","pos":"Danh từ","example":{"zh":"请补充信息。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"补","py":"bǔ"},{"c":"充","py":"chōng"},{"c":"信","py":"xìn"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Vui lòng bổ sung thông tin."}},{"hanzi":"表格","pinyin":"biǎogé","hanViet":"BIỂU CÁCH","meaning":"bảng biểu","pos":"Danh từ","example":{"zh":"请填这个表格。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"填","py":"tián"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"表","py":"biǎo"},{"c":"格","py":"gé"},{"c":"。","py":"。"}],"vi":"Vui lòng điền bảng biểu này."}},{"hanzi":"表现","pinyin":"biǎoxiàn","hanViet":"BIỂU HIỆN","meaning":"hiển hiện","pos":"Động từ","example":{"zh":"她表现得很自信。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"表","py":"biǎo"},{"c":"现","py":"xiàn"},{"c":"得","py":"dé"},{"c":"很","py":"hěn"},{"c":"自","py":"zì"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Cô ấy thể hiện rất tự tin."}},{"hanzi":"表达","pinyin":"biǎodá","hanViet":"BIỂU ĐẠT","meaning":"biểu đạt","pos":"Động từ","example":{"zh":"他能表达自己的想法。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"能","py":"néng"},{"c":"表","py":"biǎo"},{"c":"达","py":"dá"},{"c":"自"