":{"zh":"这家超级市场很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"家","py":"jiā"},{"c":"超","py":"chāo"},{"c":"级","py":"jí"},{"c":"市","py":"shì"},{"c":"场","py":"chǎng"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Siêu thị này rất lớn."}},{"hanzi":"足够","pinyin":"zúgòu","hanViet":"TÚC CÚ","meaning":"đủ, đủ lượng","pos":"Tính từ","example":{"zh":"时间足够吗？","pinyinPerChar":[{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"足","py":"zú"},{"c":"够","py":"gòu"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Đủ thời gian không?"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-40', 39, 'Bổ sung (12)', '[{"hanzi":"足球","pinyin":"zúqiú","hanViet":"TÚC CẦU","meaning":"bóng đá","pos":"Danh từ","example":{"zh":"我喜欢踢足球。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"踢","py":"tī"},{"c":"足","py":"zú"},{"c":"球","py":"qiú"},{"c":"。","py":"。"}],"vi":"Tôi thích đá bóng."}},{"hanzi":"身份证","pinyin":"shēnfènzhèng","hanViet":"THÂN PHẦN CHỨNG","meaning":"giấy tờ nhận dạng","pos":"Danh từ","example":{"zh":"我带着身份证去银行。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"带","py":"dài"},{"c":"着","py":"zhe"},{"c":"身","py":"shēn"},{"c":"份","py":"fèn"},{"c":"证","py":"zhèng"},{"c":"去","py":"qù"},{"c":"银","py":"yín"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Tôi mang theo giấy tờ nhận dạng đi ngân hàng."}},{"hanzi":"转变","pinyin":"zhuǎnbiàn","hanViet":"CHUYỂN BIẾN","meaning":"thay đổi, biến đổi","pos":"Động từ","example":{"zh":"情况转变了。","pinyinPerChar":[{"c":"情","py":"qíng"},{"c":"况","py":"kuàng"},{"c":"转","py":"zhuǎn"},{"c":"变","py":"biàn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tình hình đã thay đổi."}},{"hanzi":"输","pinyin":"shū","hanViet":"THÂU","meaning":"Thua, chiếm","pos":"Động từ","example":{"zh":"他输了比赛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"输","py":"shū"},{"c":"了","py":"le"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"。","py":"。"}],"vi":"Anh ấy thua cuộc thi."}},{"hanzi":"输入","pinyin":"shūrù","hanViet":"THÂU NHẬP","meaning":"Nhập","pos":"Động từ","example":{"zh":"请输入你的名字。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"输","py":"shū"},{"c":"入","py":"rù"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"名","py":"míng"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Vui lòng nhập tên của bạn."}},{"hanzi":"进展","pinyin":"jìnzhǎn","hanViet":"TIẾN TRIỂN","meaning":"tiến triển","pos":"Danh từ","example":{"zh":"情况进展很快。","pinyinPerChar":[{"c":"情","py":"qíng"},{"c":"况","py":"kuàng"},{"c":"进","py":"jìn"},{"c":"展","py":"zhǎn"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Tình hình tiến triển rất nhanh."}},{"hanzi":"进步","pinyin":"jìnbù","hanViet":"TIẾN BỘ","meaning":"tiến bộ","pos":"Tính từ","example":{"zh":"他的汉语进步了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"汉","py":"hàn"},{"c":"语","py":"yǔ"},{"c":"进","py":"jìn"},{"c":"步","py":"bù"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tiếng Trung của cậu ấy đã tiến bộ."}},{"hanzi":"连","pinyin":"lián","hanViet":"LIÊN","meaning":"thậm chí, còn","pos":"Liên từ","example":{"zh":"他连名字都不会写。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"连","py":"lián"},{"c":"名","py":"míng"},{"c":"字","py":"zì"},{"c":"都","py":"dōu"},{"c":"不","py":"bù"},{"c":"会","py":"huì"},{"c":"写","py":"xiě"},{"c":"。","py":"。"}],"vi":"Anh ấy thậm chí không biết viết tên."}},{"hanzi":"连续","pinyin":"liánxù","hanViet":"LIÊN TỤC","meaning":"liên tiếp, liên tục","pos":"Tính từ","example":{"zh":"他连续工作了八小时。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"连","py":"lián"},{"c":"续","py":"xù"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"了","py":"le"},{"c":"八","py":"bā"},{"c":"小","py":"xiǎo"},{"c":"时","py":"shí"},{"c":"。","py":"。"}],"vi":"Anh ấy làm việc liên tiếp tám giờ."}},{"hanzi":"迷","pinyin":"mí","hanViet":"MÊ","meaning":"Người say, mê","pos":"Danh từ","example":{"zh":"他是足球迷。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"足","py":"zú"},{"c":"球","py":"qiú"},{"c":"迷","py":"mí"},{"c":"。","py":"。"}],"vi":"Anh ấy là người hâm mộ bóng đá."}},{"hanzi":"退出","pinyin":"tuìchū","hanViet":"THOÁI XUẤT","meaning":"rời bỏ, từ bỏ","pos":"Động từ","example":{"zh":"他退出比赛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"退","py":"tuì"},{"c":"出","py":"chū"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"。","py":"。"}],"vi":"Anh ấy rời bỏ cuộc thi."}},{"hanzi":"适合","pinyin":"shìhé","hanViet":"THÍCH HỢP","meaning":"Phù hợp","pos":"Động từ","example":{"zh":"这件衣服很适合你。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"f