INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-1', 0, 'Gia đình & quan hệ (1)', '[{"hanzi":"阿姨","pinyin":"āyí","hanViet":"A DI","meaning":"bà, cô","pos":"Danh từ","example":{"zh":"这是我的阿姨。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"阿","py":"ā"},{"c":"姨","py":"yí"},{"c":"。","py":"。"}],"vi":"Đây là bà của tôi."}},{"hanzi":"爱护","pinyin":"àihù","hanViet":"ÁI HỘ","meaning":"trân trọng, chăm sóc","pos":"Động từ","example":{"zh":"我们要爱护花草。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"爱","py":"ài"},{"c":"护","py":"hù"},{"c":"花","py":"huā"},{"c":"草","py":"cǎo"},{"c":"。","py":"。"}],"vi":"Chúng ta phải trân trọng hoa cây."}},{"hanzi":"安置","pinyin":"ānzhì","hanViet":"AN TRÍ","meaning":"cấp phát, bố trí","pos":"Động từ","example":{"zh":"他们安置了新房。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"安","py":"ān"},{"c":"置","py":"zhì"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"房","py":"fáng"},{"c":"。","py":"。"}],"vi":"Họ đã cấp phát căn nhà mới."}},{"hanzi":"败","pinyin":"bài","hanViet":"BẠI","meaning":"thua, thất bại","pos":"Tính từ","example":{"zh":"他比赛输了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"输","py":"shū"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ta thua cuộc thi."}},{"hanzi":"办事","pinyin":"bànshì","hanViet":"BIỆN SỰ","meaning":"công việc, xử lý việc","pos":"Động từ","example":{"zh":"他在公司办事。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"办","py":"bàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Anh ta làm việc tại công ty."}},{"hanzi":"宝宝","pinyin":"bǎobao","hanViet":"BẢO BẢO","meaning":"em bé, đứa trẻ","pos":"Danh từ","example":{"zh":"我的宝宝很可爱。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"宝","py":"bǎo"},{"c":"宝","py":"bǎo"},{"c":"很","py":"hěn"},{"c":"可","py":"kě"},{"c":"爱","py":"ài"},{"c":"。","py":"。"}],"vi":"Em bé của tôi rất đáng yêu."}},{"hanzi":"保密","pinyin":"bǎomì","hanViet":"BẢO MẬT","meaning":"giao thông tin bí mật","pos":"Động từ","example":{"zh":"请保密这个消息。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"保","py":"bǎo"},{"c":"密","py":"mì"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Vui lòng giữ bí mật thông tin này."}},{"hanzi":"别","pinyin":"bié","hanViet":"BIỆT","meaning":"đừng, không nên","pos":"Phó từ","example":{"zh":"别走了。","pinyinPerChar":[{"c":"别","py":"bié"},{"c":"走","py":"zǒu"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Đừng đi rồi."}},{"hanzi":"不要紧","pinyin":"bùyàojǐn","hanViet":"BẤT YẾU KHẨN","meaning":"không sao, không cần thiết","pos":"Cụm từ","example":{"zh":"没关系，不要紧。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"关","py":"guān"},{"c":"系","py":"xì"},{"c":"，","py":"，"},{"c":"不","py":"bù"},{"c":"要","py":"yào"},{"c":"紧","py":"jǐn"},{"c":"。","py":"。"}],"vi":"Không sao, không cần thiết."}},{"hanzi":"不在乎","pinyin":"bùzàihu","hanViet":"BẤT TẠI HỒ","meaning":"không coi thường, không quan tâm","pos":"Động từ","example":{"zh":"我不在乎他的意见。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"在","py":"zài"},{"c":"乎","py":"hū"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Tôi không quan tâm ý kiến của anh ấy."}},{"hanzi":"不然","pinyin":"bùrán","hanViet":"BẤT NHIÊN","meaning":"không thì, nếu không","pos":"Liên từ","example":{"zh":"不然怎么办？","pinyinPerChar":[{"c":"不","py":"bù"},{"c":"然","py":"rán"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"办","py":"bàn"},{"c":"？","py":"？"}],"vi":"Nếu không thì sao?"}},{"hanzi":"采访","pinyin":"cǎifǎng","hanViet":"THÁI PHỎNG","meaning":"được phỏng vấn, thu thập thông tin","pos":"Động từ","example":{"zh":"记者正在采访老师。","pinyinPerChar":[{"c":"记","py":"jì"},{"c":"者","py":"zhě"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"采","py":"cǎi"},{"c":"访","py":"fǎng"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Nhà báo đang phỏng vấn giáo viên."}},{"hanzi":"参考","pinyin":"cānkǎo","hanViet":"THAM KHẢO","meaning":"dùng để xem xét, tham khảo","pos":"Động từ","example":{"zh":"请参考这本书。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"参","py":"cān"},{"c":"考","py":"kǎo"},{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Xin hãy tham khảo cuốn sách này."}},{"hanzi":"常识","pinyin":"chángshí","hanViet":"THƯỜNG THỨC","meaning":"kiến thức thông thường","pos":"Danh từ","example":{"zh":"他有常识。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"常","py":"cháng"},{"c":"识","py":"shí"},{"c":"。","py":"。"}],"vi":"Anh ấy có kiến thức thông thường."}},{"hanzi":"沉默","pinyin":"chénmò","hanViet":"TRẦM MẶC","meaning":"không nói, im lặng","pos":"Tính từ","example":{"zh":"他很沉默。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"沉","py":"chén"},{"c":"默","py":"mò"},{"c":"。","py":"。"}],"vi":"Cậu ấy rất im lặng."}},{"hanzi":"承担","pinyin":"chéngdān","hanViet":"THỪA ĐẢM","meaning":"giảm, chịu trách nhiệm","pos":"Động từ","example":{"zh":"他承担了责任。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"承","py":"chéng"},{"c":"担","py":"dān"},{"c":"了","py":"le"},{"c":"责","py":"zé"},{"c":"任","py":"rèn"},{"c":"。","py":"。"}],"vi":"Cậu ấy chịu trách nhiệm."}},{"hanzi":"承认","pinyin":"chéngrèn","hanViet":"THỪA NHẬN","meaning":"thừa nhận, công nhận","pos":"Động từ","example":{"zh":"他承认了错误。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"承","py":"chéng"},{"c":"认","py":"rèn"},{"c":"了","py":"le"},{"c":"错","py":"cuò"},{"c":"误","py":"wù"},{"c":"。","py":"。"}],"vi":"Cậu ấy thừa nhận lỗi."}},{"hanzi":"承受","pinyin":"chéngshòu","hanViet":"THỪA THỌ","meaning":"chịu đựng, chịu được","pos":"Động từ","example":{"zh":"他承受不了压力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"承","py":"chéng"},{"c":"受","py":"shòu"},{"c":"不","py":"bù"},{"c":"了","py":"le"},{"c":"压","py":"yā"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Cậu ấy không chịu được