},{"c":"大","py":"dà"},{"c":"爷","py":"yé"},{"c":"。","py":"。"}],"vi":"Anh ấy là ông lớn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-2', 1, 'Gia đình & quan hệ (2)', '[{"hanzi":"大众","pinyin":"dàzhòng","hanViet":"ĐẠI CHÚNG","meaning":"cộng đồng, đông đảo người","pos":"Danh từ","example":{"zh":"这部电影很受大众欢迎。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"很","py":"hěn"},{"c":"受","py":"shòu"},{"c":"大","py":"dà"},{"c":"众","py":"zhòng"},{"c":"欢","py":"huān"},{"c":"迎","py":"yíng"},{"c":"。","py":"。"}],"vi":"Bộ phim này rất được cộng đồng đông đảo quý mến."}},{"hanzi":"地方","pinyin":"dìfāng","hanViet":"ĐỊA PHƯƠNG","meaning":"nơi chốn, địa điểm","pos":"Danh từ","example":{"zh":"请在这个地方坐一下。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"地","py":"dì"},{"c":"方","py":"fāng"},{"c":"坐","py":"zuò"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Hãy ngồi ở chỗ này nhé."}},{"hanzi":"地面","pinyin":"dìmiàn","hanViet":"ĐỊA DIỆN","meaning":"mặt đất, bề mặt đất","pos":"Danh từ","example":{"zh":"球滚到地面了。","pinyinPerChar":[{"c":"球","py":"qiú"},{"c":"滚","py":"gǔn"},{"c":"到","py":"dào"},{"c":"地","py":"dì"},{"c":"面","py":"miàn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Quả bóng đã lăn xuống mặt đất."}},{"hanzi":"地位","pinyin":"dìwèi","hanViet":"ĐỊA VỊ","meaning":"vị thế, địa vị","pos":"Danh từ","example":{"zh":"他在公司有很高的地位。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"的","py":"de"},{"c":"地","py":"dì"},{"c":"位","py":"wèi"},{"c":"。","py":"。"}],"vi":"Anh ấy có vị thế rất cao trong công ty."}},{"hanzi":"地下","pinyin":"dìxià","hanViet":"ĐỊA HẠ","meaning":"bên dưới mặt đất, hầm","pos":"Tính từ","example":{"zh":"我们去地下车库。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"地","py":"dì"},{"c":"下","py":"xià"},{"c":"车","py":"chē"},{"c":"库","py":"kù"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi xuống hầm xe dưới đất."}},{"hanzi":"地址","pinyin":"dìzhǐ","hanViet":"ĐỊA CHỈ","meaning":"địa chỉ","pos":"Danh từ","example":{"zh":"请告诉我你的地址。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"告","py":"gào"},{"c":"诉","py":"sù"},{"c":"我","py":"wǒ"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"地","py":"dì"},{"c":"址","py":"zhǐ"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi biết địa chỉ của bạn."}},{"hanzi":"定","pinyin":"dìng","hanViet":"ĐỊNH","meaning":"quyết định, ổn định","pos":"Tính từ","example":{"zh":"他决定去北京。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"决","py":"jué"},{"c":"定","py":"dìng"},{"c":"去","py":"qù"},{"c":"北","py":"běi"},{"c":"京","py":"jīng"},{"c":"。","py":"。"}],"vi":"Anh ấy quyết định đi Bắc Kinh."}},{"hanzi":"动摇","pinyin":"dòngyáo","hanViet":"ĐỘNG DAO","meaning":"lạc lối, không vững chắc","pos":"Động từ","example":{"zh":"他没有动摇。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"动","py":"dòng"},{"c":"摇","py":"yáo"},{"c":"。","py":"。"}],"vi":"Anh ấy không bị rơi ra khỏi niềm tin."}},{"hanzi":"儿童","pinyin":"értóng","hanViet":"NHI ĐỒNG","meaning":"trẻ em","pos":"Danh từ","example":{"zh":"儿童应该学习好。","pinyinPerChar":[{"c":"儿","py":"ér"},{"c":"童","py":"tóng"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Trẻ em nên học tập tốt."}},{"hanzi":"而是","pinyin":"ér shì","hanViet":"NHI THỊ","meaning":"không phải, mà là","pos":"Liên từ","example":{"zh":"我不是去看电影，而是去学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"是","py":"shì"},{"c":"去","py":"qù"},{"c":"看","py":"kàn"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"，","py":"，"},{"c":"而","py":"ér"},{"c":"是","py":"shì"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Tôi không đi xem phim, mà là đi học."}},{"hanzi":"法官","pinyin":"fǎguān","hanViet":"PHÁP QUAN","meaning":"Người làm công việc xét xử trong tòa án","pos":"Danh từ","example":{"zh":"法官在法庭上审理案件。","pinyinPerChar":[{"c":"法","py":"fǎ"},{"c":"官","py":"guān"},{"c":"在","py":"zài"},{"c":"法","py":"fǎ"},{"c":"庭","py":"tíng"},{"c":"上","py":"shàng"},{"c":"审","py":"shěn"},{"c":"理","py":"lǐ"},{"c":"案","py":"àn"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Công tố viên xét xử vụ án trong tòa."}},{"hanzi":"反而","pinyin":"fǎn''ér","hanViet":"PHẢN NHI","meaning":"Ngược lại, không như mong đợi","pos":"Phó từ","example":{"zh":"他没来，反而我去了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"没","py":"méi"},{"c":"来","py":"lái"},{"c":"，","py":"，"},{"c":"反","py":"fǎn"},{"c":"而","py":"ér"},{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy không đến, ngược lại tôi đã đi."}},{"hanzi":"反映","pinyin":"fǎnyìng","hanViet":"PHẢN ÁNH","meaning":"Biểu hiện, phản ánh, truyền đạt thông tin","pos":"Động từ","example":{"zh":"这件事反映了问题。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"反","py":"fǎn"},{"c":"映","py":"yìng"},{"c":"了","py":"le"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Vụ việc này phản ánh vấn đề."}},{"hanzi":"方","pinyin":"fāng","hanViet":"PHƯƠNG","meaning":"Hình vuông, phương, hướng","pos":"Tính từ","example":{"zh":"这是一个方形。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"方","py":"fāng"},{"c":"形","py":"xíng"},{"c":"。","py":"。"}],"vi":"Đây là một hình vuông."}},{"hanzi":"非","pinyin":"fēi","hanViet":"PHI","meaning":"Không, không phải","pos":"Tính từ","example":{"zh":"这不是非要的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"不","py":"bù"},{"c":"是","py":"shì"},{"c":"非","py":"fēi"},{"c":"要","py":"yào"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Điều này không cần thiết."}},{"hanzi":"分布","pinyin":"fēnbù","hanViet":"PHÂN BỐ","meaning":"Sắp xếp, phân bố","pos":"Động từ","example":{"zh":"人口分布在各地。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"口","py":"kǒu"},{"c":"分","py":"fēn"},{"c":"布","py":"bù"},{"c":"在","py":"zài"},{"c":"各","py":"gè"},{"c":"地","py":"dì"},{"c":"。","py":"。"}],"vi":"Dân số phân bố ở nhiều nơi."}},{"hanzi":"否则","pinyin":"fǒuzé","hanViet":"PHỦ TẮC","meaning":"nếu không, nếu không","pos":"Phó từ","example":{"zh":"你要好好学习，否则会失败。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"要","py":"yào"},{"c":"好","py":"hǎo"},{"c":"好","py":"hǎo"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"，","py":"，"},{"c":"否","py":"fǒu"},{"c":"则","py":"zé"},{"c":"会","py":"huì"},{"c":"失","py":"shī"},{"c":"败","py":"bài"},{"c":"。","py":"。"}],"vi":"Bạn phải học chăm chỉ, nếu không sẽ thất bại."}},{"hanzi":"夫妇","pinyin":"fūfù","hanViet":"PHU PHỤ","meaning":"cặp vợ chồng","pos":"Danh từ","example":{"zh":"他们夫妇去了公园。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"夫","py":"fū"},{"c":"妇","py":"fù"},{"c":"去","py":"qù"},{"c":"了","py":"le"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"。","py":"。"}],"vi":"Họ cặp vợ chồng đã đến công viên."}},{"hanzi":"夫妻","pinyin":"fūqī","hanViet":"PHU THÊ","meaning":"vợ chồng","pos":"Danh từ","example":{"zh":"夫妻一起吃饭。","pinyinPerChar":[{"c":"夫","py":"fū"},{"c":"妻","py":"qī"},{"c":"一","py":"yī"},{"c":"起","py":"qǐ"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Vợ chồng cùng ăn cơm."}},{"hanzi":"夫人","pinyin":"fūrén","hanViet":"PHU NHÂN","meaning":"vợ, người phụ nữ quý tộc","pos":"Danh từ","example":{"zh":"她是夫人。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"夫","py":"fū"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Cô ấy là vợ."}},{"hanzi":"感兴趣","pinyin":"gǎn xìngqù","hanViet":"CẢM HƯNG THÚ","meaning":"quan tâm, hứng thú","pos":"Động từ","example":{"zh":"他对音乐很感兴趣。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"音","py":"yīn"},{"c":"乐","py":"lè"},{"c":"很","py":"hěn"},{"c":"感","py":"gǎn"},{"c":"兴","py":"xīng"},{"c":"趣","py":"qù"},{"c":"。","py":"。"}],"vi":"Anh ấy rất quan tâm đến âm nhạc."}},{"hanzi":"工程","pinyin":"gōngchéng","hanViet":"CÔNG TRÌNH","meaning":"công trình, dự án","pos":"Danh từ","example":{"zh":"这个工程很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"工","py":"gōng"},{"c":"程","py":"chéng"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Dự án này rất quan trọng."}},{"hanzi":"公元","pinyin":"gōngyuán","hanViet":"CÔNG NGUYÊN","meaning":"năm Công nguyên","pos":"Danh từ","example":{"zh":"公元2024年是今年。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"元","py":"yuán"},{"c":"2","py":"2"},{"c":"0","py":"0"},{"c":"2","py":"2"},{"c":"4","py":"4"},{"c":"年","py":"nián"},{"c":"是","py":"shì"},{"c":"今","py":"jīn"},{"c":"年","py":"nián"},{"c":"。","py":"。"}],"vi":"Năm Công nguyên 2024 là năm nay."}},{"hanzi":"固定","pinyin":"gùdìng","hanViet":"CỐ ĐỊNH","meaning":"cố định, giữ nguyên","pos":"Tính từ","example":{"zh":"这个按钮是固定的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"按","py":"àn"},{"c":"钮","py":"niǔ"},{"c":"是","py":"shì"},{"c":"固","py":"gù"},{"c":"定","py":"dìng"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Nút bấm này được cố định."}},{"hanzi":"光临","pinyin":"guānglín","hanViet":"QUANG LÂM","meaning":"đón khách, đến","pos":"Động từ","example":{"zh":"欢迎光临。","pinyinPerChar":[{"c":"欢","py":"huān"},{"c":"迎","py":"yíng"},{"c":"光","py":"guāng"},{"c":"临","py":"lín"},{"c":"。","py":"。"}],"vi":"Chào mừng quý khách đến."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-3', 2, 'Gia đình & quan hệ (3)', '[{"hanzi":"逛","pinyin":"guàng","hanViet":"CUỐNG","meaning":"đi dạo, xem xem","pos":"Động từ","example":{"zh":"周末我去逛公园。","pinyinPerChar":[{"c":"周","py":"zhōu"},{"c":"末","py":"mò"},{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"逛","py":"guàng"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"。","py":"。"}],"vi":"Cuối tuần tôi đi dạo công viên."}},{"hanzi":"寒假","pinyin":"hánjià","hanViet":"HÀN GIẢ","meaning":"kỳ nghỉ đông","pos":"Danh từ","example":{"zh":"寒假很长。","pinyinPerChar":[{"c":"寒","py":"hán"},{"c":"假","py":"jiǎ"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Kỳ nghỉ đông rất dài."}},{"hanzi":"航空","pinyin":"hángkōng","hanViet":"HÀNG KHÔNG","meaning":"hàng không","pos":"Danh từ","example":{"zh":"航空公司很大。","pinyinPerChar":[{"c":"航","py":"háng"},{"c":"空","py":"kōng"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Công ty hàng không rất lớn."}},{"hanzi":"汇报","pinyin":"huìbào","hanViet":"HỐI BÁO","meaning":"báo cáo","pos":"Động từ","example":{"zh":"他汇报了工作情况。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"汇","py":"huì"},{"c":"报","py":"bào"},{"c":"了","py":"le"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"情","py":"qíng"},{"c":"况","py":"kuàng"},{"c":"。","py":"。"}],"vi":"Anh ta báo cáo tình hình công việc."}},{"hanzi":"婚礼","pinyin":"hūnlǐ","hanViet":"HÔN LỄ","meaning":"lễ cưới","pos":"Danh từ","example":{"zh":"他们举行婚礼。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"举","py":"jǔ"},{"c":"行","py":"xíng"},{"c":"婚","py":"hūn"},{"c":"礼","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Họ tổ chức lễ cưới."}},{"hanzi":"伙伴","pinyin":"huǒbàn","hanViet":"HOẢ BẠN","meaning":"đối tác, người bạn đồng hành","pos":"Danh từ","example":{"zh":"我有几个伙伴一起学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"几","py":"jǐ"},{"c":"个","py":"gè"},{"c":"伙","py":"huǒ"},{"c":"伴","py":"bàn"},{"c":"一","py":"yī"},{"c":"起","py":"qǐ"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Tôi có vài người bạn cùng học."}},{"hanzi":"记载","pinyin":"jìzǎi","hanViet":"KÝ TẢI","meaning":"ghi chép, lưu trữ thông tin","pos":"Động từ","example":{"zh":"这本书记载了历史事件。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"记","py":"jì"},{"c":"载","py":"zài"},{"c":"了","py":"le"},{"c":"历","py":"lì"},{"c":"史","py":"shǐ"},{"c":"事","py":"shì"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Cuốn sách này ghi chép các sự kiện lịch sử."}},{"hanzi":"家务","pinyin":"jiāwù","hanViet":"GIA VỤ","meaning":"công việc nhà, việc nhà","pos":"Danh từ","example":{"zh":"她做很多家务。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"做","py":"zuò"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"家","py":"jiā"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Cô ấy làm nhiều việc nhà."}},{"hanzi":"江","pinyin":"jiāng","hanViet":"GIANG","meaning":"sông","pos":"Danh từ","example":{"zh":"长江很长。","pinyinPerChar":[{"c":"长","py":"zhǎng"},{"c":"江","py":"jiāng"},{"c":"很","py":"hěn"},{"c":"长","py":"zhǎng"},{"c":"。","py":"。"}],"vi":"Sông Hằng rất dài."}},{"hanzi":"讲究","pinyin":"jiǎngjiu","hanViet":"GIẢNG CỨU","meaning":"quan tâm, chăm chút","pos":"Động từ","example":{"zh":"他很讲究饮食。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"讲","py":"jiǎng"},{"c":"究","py":"jiū"},{"c":"饮","py":"yǐn"},{"c":"食","py":"shí"},{"c":"。","py":"。"}],"vi":"Anh ấy rất quan tâm đến chế độ ăn uống."}},{"hanzi":"讲座","pinyin":"jiǎngzuò","hanViet":"GIẢNG TOẠ","meaning":"buổi trình bày, hội thảo","pos":"Danh từ","example":{"zh":"他们参加讲座。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"讲","py":"jiǎng"},{"c":"座","py":"zuò"},{"c":"。","py":"。"}],"vi":"Họ tham dự buổi trình bày."}},{"hanzi":"教训","pinyin":"jiàoxùn","hanViet":"GIÁO HUẤN","meaning":"dạy dỗ, bài học","pos":"Danh từ","example":{"zh":"这次事故是教训。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"事","py":"shì"},{"c":"故","py":"gù"},{"c":"是","py":"shì"},{"c":"教","py":"jiào"},{"c":"训","py":"xùn"},{"c":"。","py":"。"}],"vi":"Thứ này là bài học."}},{"hanzi":"姐妹","pinyin":"jiěmèi","hanViet":"TỶ MUỘI","meaning":"chị em, chị em gái","pos":"Danh từ","example":{"zh":"她有两个姐妹。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"有","py":"yǒu"},{"c":"两","py":"liǎng"},{"c":"个","py":"gè"},{"c":"姐","py":"jiě"},{"c":"妹","py":"mèi"},{"c":"。","py":"。"}],"vi":"Cô ấy có hai chị em gái."}},{"hanzi":"禁止","pinyin":"jìnzhǐ","hanViet":"CẤM CHỈ","meaning":"cấm, không cho phép","pos":"Động từ","example":{"zh":"禁止吸烟。","pinyinPerChar":[{"c":"禁","py":"jìn"},{"c":"止","py":"zhǐ"},{"c":"吸","py":"xī"},{"c":"烟","py":"yān"},{"c":"。","py":"。"}],"vi":"Cấm hút thuốc."}},{"hanzi":"看不起","pinyin":"kànbuqǐ","hanViet":"KHÁN BẤT KHỞI","meaning":"xem thường, coi thường","pos":"Động từ","example":{"zh":"不要看不起别人。","pinyinPerChar":[{"c":"不","py":"bù"},{"c":"要","py":"yào"},{"c":"看","py":"kàn"},{"c":"不","py":"bù"},{"c":"起","py":"qǐ"},{"c":"别","py":"bié"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Đừng coi thường người khác."}},{"hanzi":"空间","pinyin":"kōngjiān","hanViet":"KHÔNG GIAN","meaning":"không gian, không gian","pos":"Danh từ","example":{"zh":"这个房间空间很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"空","py":"kōng"},{"c":"间","py":"jiān"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Phòng này có không gian lớn."}},{"hanzi":"空","pinyin":"kòng","hanViet":"KHÔNG","meaning":"trống, không có gì","pos":"Tính từ","example":{"zh":"这个箱子空着。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"箱","py":"xiāng"},{"c":"子","py":"zi"},{"c":"空","py":"kōng"},{"c":"着","py":"zhe"},{"c":"。","py":"。"}],"vi":"Thùng này trống."}},{"hanzi":"快递","pinyin":"kuàidì","hanViet":"KHOÁI ĐỆ","meaning":"giao hàng nhanh","pos":"Danh từ","example":{"zh":"我等快递等了两个小时。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"等","py":"děng"},{"c":"快","py":"kuài"},{"c":"递","py":"dì"},{"c":"等","py":"děng"},{"c":"了","py":"le"},{"c":"两","py":"liǎng"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"时","py":"shí"},{"c":"。","py":"。"}],"vi":"Tôi đợi hàng nhanh hai giờ."}},{"hanzi":"老公","pinyin":"lǎogōng","hanViet":"LÃO CÔNG","meaning":"chồng","pos":"Danh từ","example":{"zh":"她的老公在公司。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"老","py":"lǎo"},{"c":"公","py":"gōng"},{"c":"在","py":"zài"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"。","py":"。"}],"vi":"Chồng của cô ấy đang ở công ty."}},{"hanzi":"老婆","pinyin":"lǎopo","hanViet":"LÃO BÀ","meaning":"vợ","pos":"Danh từ","example":{"zh":"他很爱他的老婆。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"爱","py":"ài"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"老","py":"lǎo"},{"c":"婆","py":"pó"},{"c":"。","py":"。"}],"vi":"Anh ấy rất yêu vợ mình."}},{"hanzi":"老实","pinyin":"lǎoshi","hanViet":"LÃO THỰC","meaning":"thông thạo, trung thực, ngoan ngoãn","pos":"Tính từ","example":{"zh":"他现在很老实。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"很","py":"hěn"},{"c":"老","py":"lǎo"},{"c":"实","py":"shí"},{"c":"。","py":"。"}],"vi":"Anh ấy bây giờ rất ngoan ngoãn."}},{"hanzi":"离不开","pinyin":"lí bu kāi","hanViet":"LY BẤT KHAI","meaning":"không thể tách rời, không thể thiếu","pos":"Động từ","example":{"zh":"我离不开你的帮助。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"离","py":"lí"},{"c":"不","py":"bù"},{"c":"开","py":"kāi"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"。","py":"。"}],"vi":"Tôi không thể thiếu sự giúp đỡ của bạn."}},{"hanzi":"粮食","pinyin":"liángshi","hanViet":"LƯƠNG THỰC","meaning":"lương thực, gạo, lương thực nông nghiệp","pos":"Danh từ","example":{"zh":"粮食很重要。","pinyinPerChar":[{"c":"粮","py":"liáng"},{"c":"食","py":"shí"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Lương thực rất quan trọng."}},{"hanzi":"临时",