","hanViet":"THẤT BẠI","meaning":"thất bại","pos":"Danh từ","example":{"zh":"这次比赛失败。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"失","py":"shī"},{"c":"败","py":"bài"},{"c":"。","py":"。"}],"vi":"Cuộc thi này thất bại."}},{"hanzi":"实施","pinyin":"shíshī","hanViet":"THỰC THI","meaning":"công khai thực hiện","pos":"Động từ","example":{"zh":"公司将实施新计划。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"将","py":"jiāng"},{"c":"实","py":"shí"},{"c":"施","py":"shī"},{"c":"新","py":"xīn"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"。","py":"。"}],"vi":"Công ty sẽ thực hiện kế hoạch mới."}},{"hanzi":"是否","pinyin":"shìfǒu","hanViet":"THỊ PHỦ","meaning":"có hay không","pos":"Liên từ","example":{"zh":"你是否知道？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"是","py":"shì"},{"c":"否","py":"fǒu"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"？","py":"？"}],"vi":"Bạn có biết không?"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-5', 4, 'Gia đình & quan hệ (5)', '[{"hanzi":"手工","pinyin":"shǒugōng","hanViet":"THỦ CÔNG","meaning":"làm thủ công","pos":"Danh từ","example":{"zh":"她喜欢手工。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"手","py":"shǒu"},{"c":"工","py":"gōng"},{"c":"。","py":"。"}],"vi":"Cô ấy thích làm thủ công."}},{"hanzi":"受不了","pinyin":"shòubuliǎo","hanViet":"THỌ BẤT LIỄU","meaning":"chịu không nổi, không chịu được","pos":"Động từ","example":{"zh":"这个夏天太热了，我受不了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"夏","py":"xià"},{"c":"天","py":"tiān"},{"c":"太","py":"tài"},{"c":"热","py":"rè"},{"c":"了","py":"le"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"受","py":"shòu"},{"c":"不","py":"bù"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Mùa hè này quá nóng, tôi không chịu nổi."}},{"hanzi":"叔叔","pinyin":"shūshu","hanViet":"THÚC THÚC","meaning":"cậu, chú, bác (người lớn nam)","pos":"Danh từ","example":{"zh":"我的叔叔是老师。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"叔","py":"shū"},{"c":"叔","py":"shū"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Cậu tôi là giáo viên."}},{"hanzi":"数码","pinyin":"shùmǎ","hanViet":"SỐ MÃ","meaning":"số hóa, thiết bị số, công nghệ số","pos":"Danh từ","example":{"zh":"他喜欢买数码产品。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"买","py":"mǎi"},{"c":"数","py":"shù"},{"c":"码","py":"mǎ"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Cậu ấy thích mua sản phẩm số."}},{"hanzi":"刷子","pinyin":"shuāzi","hanViet":"XOÁT TỬ","meaning":"bàn chải, bông, dụng cụ lau","pos":"Danh từ","example":{"zh":"我用刷子擦桌子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"刷","py":"shuā"},{"c":"子","py":"zi"},{"c":"擦","py":"cā"},{"c":"桌","py":"zhuō"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi dùng bàn chải để lau bàn."}},{"hanzi":"帅","pinyin":"shuài","hanViet":"SOÁI","meaning":"xinh, trông hay, hào nhoáng","pos":"Tính từ","example":{"zh":"他很帅。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"帅","py":"shuài"},{"c":"。","py":"。"}],"vi":"Cậu ấy rất xinh."}},{"hanzi":"说不定","pinyin":"shuōbudìng","hanViet":"THUYẾT BẤT ĐỊNH","meaning":"có thể, có lẽ, không rõ","pos":"Phó từ","example":{"zh":"说不定明天会下雨。","pinyinPerChar":[{"c":"说","py":"shuō"},{"c":"不","py":"bù"},{"c":"定","py":"dìng"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"会","py":"huì"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Có thể mưa vào ngày mai."}},{"hanzi":"松树","pinyin":"sōngshù","hanViet":"TÙNG THỤ","meaning":"cây thông","pos":"Danh từ","example":{"zh":"松树很高。","pinyinPerChar":[{"c":"松","py":"sōng"},{"c":"树","py":"shù"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Cây thông rất cao."}},{"hanzi":"孙女","pinyin":"sūnnǚ","hanViet":"TÔN","meaning":"chị ruột, cô ruột, cháu gái","pos":"Danh từ","example":{"zh":"她的孙女很可爱。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"孙","py":"sūn"},{"c":"女","py":"nǚ"},{"c":"很","py":"hěn"},{"c":"可","py":"kě"},{"c":"爱","py":"ài"},{"c":"。","py":"。"}],"vi":"Cháu gái của cô ấy rất đáng yêu."}},{"hanzi":"孙子","pinyin":"sūnzi","hanViet":"TÔN TỬ","meaning":"chị ruột, cô ruột, cháu trai","pos":"Danh từ","example":{"zh":"爷爷的孙子在读书。","pinyinPerChar":[{"c":"爷","py":"yé"},{"c":"爷","py":"yé"},{"c":"的","py":"de"},{"c":"孙","py":"sūn"},{"c":"子","py":"zi"},{"c":"在","py":"zài"},{"c":"读","py":"dú"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Cháu trai của ông bà đang học."}},{"hanzi":"通知书","pinyin":"tōngzhīshū","hanViet":"THÔNG TRI THƯ","meaning":"thông báo, văn bản thông báo","pos":"Danh từ","example":{"zh":"老师发了通知书。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"发","py":"fā"},{"c":"了","py":"le"},{"c":"通","py":"tōng"},{"c":"知","py":"zhī"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Giáo viên phát thông báo."}},{"hanzi":"同情","pinyin":"tóngqíng","hanViet":"ĐỒNG TÌNH","meaning":"xót xa, đồng cảm","pos":"Động từ","example":{"zh":"我很同情他的处境。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"同","py":"tóng"},{"c":"情","py":"qíng"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"处","py":"chù"},{"c":"境","py":"jìng"},{"c":"。","py":"。"}],"vi":"Tôi rất đồng cảm với hoàn cảnh của anh ấy."}},{"hanzi":"投入","pinyin":"tóurù","hanViet":"ĐẦU NHẬP","meaning":"đầu tư, bỏ công","pos":"Động từ","example":{"zh":"她投入很多时间学习。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"投","py":"tóu"},{"c":"入","py":"rù"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Cô ấy bỏ nhiều thời gian học tập."}},{"hanzi":"土地","pinyin":"tǔdì","hanViet":"THỔ ĐỊA","meaning":"đất đai, ruộng đất","pos":"Danh từ","example":{"zh":"农民在土地上劳动。","pinyinPerChar":[{"c":"农","py":"nóng"},{"c":"民","py":"mín"},{"c":"在","py":"zài"},{"c":"土","py":"tǔ"},{"c":"地","py":"dì"},{"c":"上","py":"shàng"},{"c":"劳","py":"láo"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Nông dân làm việc trên ruộng đất."}},{"hanzi":"微信","pinyin":"wēixìn","hanViet":"VI TÍN","meaning":"WeChat","pos":"Danh từ","example":{"zh":"我用微信联系朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"微","py":"wēi"},{"c":"信","py":"xìn"},{"c":"联","py":"lián"},{"c":"系","py":"xì"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi liên lạc bạn bằng WeChat."}},{"hanzi":"未必","pinyin":"wèibì","hanViet":"VỊ TẤT","meaning":"không hẳn, có thể không","pos":"Phó từ","example":{"zh":"他未必来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"未","py":"wèi"},{"c":"必","py":"bì"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy có thể không đến."}},{"hanzi":"稳","pinyin":"wěn","hanViet":"ỔN","meaning":"ổn định, không biến động","pos":"Tính từ","example":{"zh":"这个箱子很稳。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"箱","py":"xiāng"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"稳","py":"wěn"},{"c":"。","py":"。"}],"vi":"Cái hộp này rất ổn định."}},{"hanzi":"稳定","pinyin":"wěndìng","hanViet":"ỔN ĐỊNH","meaning":"ổn định, không thay đổi","pos":"Tính từ","example":{"zh":"这个国家很稳定。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"国","py":"guó"},{"c":"家","py":"jiā"},{"c":"很","py":"hěn"},{"c":"稳","py":"wěn"},{"c":"定","py":"dìng"},{"c":"。","py":"。"}],"vi":"Nước này rất ổn định."}},{"hanzi":"无","pinyin":"wú","hanViet":"VÔ","meaning":"không có, không","pos":"Tính từ","example":{"zh":"没有无。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"无","py":"wú"},{"c":"。","py":"。"}],"vi":"Không có gì không."}},{"hanzi":"无法","pinyin":"wúfǎ","hanViet":"VÔ PHÁP","meaning":"không thể, không có cách","pos":"Động từ","example":{"zh":"我无法去。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"无","py":"wú"},{"c":"法","py":"fǎ"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Tôi không thể đi."}},{"hanzi":"无数","pinyin":"wúshù","hanViet":"VÔ SỐ","meaning":"không đếm được, rất nhiều","pos":"Lượng từ","example":{"zh":"无数人来看。","pinyinPerChar":[{"c":"无","py":"wú"},{"c":"数","py":"shù"},{"c":"人","py":"rén"},{"c":"来","py":"lái"},{"c":"看","py":"kàn"},{"c":"。","py":"。"}],"vi":"Rất nhiều người đến xem."}},{"hanzi":"无所谓","pinyin":"wúsuǒwèi","hanViet":"VÔ SỞ VỊ","meaning":"không quan trọng, không cần quan tâm","pos":"Động từ","example":{"zh":"我无所谓。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"无","py":"wú"},{"c":"所","py":"suǒ"},{"c":"谓","py":"wèi"},{"c":"。","py":"。"}],"vi":"Tôi không quan tâm."}},{"hanzi":"无限","pinyin":"wúxiàn","hanViet":"VÔ HẠN","meaning":"không giới hạn, vô hạn","pos":"Tính từ","example":{"zh":"这个梦想无限大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"梦","py":"mèng"},{"c":"想","py":"xiǎng"},{"c":"无","py":"wú"},{"c":"限","py":"xiàn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Giấc mơ này vô hạn."}},{"hanzi":"显著","pinyin":"xiǎnzhù","hanViet":"HIỂN TRỨ","meaning":"rõ rệt, đáng chú ý","pos":"Tính từ","example":{"zh":"进步很显著。","pinyinPerChar":[{"c":"进","py":"jìn"},{"c":"步","py":"bù"},{"c":"很","py":"hěn"},{"c":"显","py":"xiǎn"},{"c":"著","py":"zhù"},{"c":"。","py":"。"}],"vi":"Cải thiện rất rõ rệt."}},{"hanzi":"新郎","pinyin":"xīnláng","hanViet":"TÂN LANG","meaning":"người cưới, chồng","pos":"Danh từ","example":{"zh":"新郎穿红色衣服。","pinyinPerChar":[{"c":"新","py":"xīn"},{"c":"郎","py":"láng"},{"c":"穿","py":"chuān"},{"c":"红","py":"hóng"},{"c":"色","py":"sè"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"。","py":"。"}],"vi":"Người cưới mặc quần áo màu đỏ."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-6', 5, 'Gia đình & quan hệ (6)', '[{"hanzi":"新娘","pinyin":"xīnniáng","hanViet":"TÂN NƯƠNG","meaning":"người cưới, vợ","pos":"Danh từ","example":{"zh":"新娘站在台上。","pinyinPerChar":[{"c":"新","py":"xīn"},{"c":"娘","py":"niáng"},{"c":"站","py":"zhàn"},{"c":"在","py":"zài"},{"c":"台","py":"tái"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Người cưới đứng trên sàn."}},{"hanzi":"形势","pinyin":"xíngshì","hanViet":"HÌNH THẾ","meaning":"tình hình, bối cảnh","pos":"Danh từ","example":{"zh":"现在的形势很严峻。","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"的","py":"de"},{"c":"形","py":"xíng"},{"c":"势","py":"shì"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"峻","py":"jùn"},{"c":"。","py":"。"}],"vi":"Tình hình hiện tại rất nghiêm trọng."}},{"hanzi":"兴趣","pinyin":"xìngqù","hanViet":"HƯNG THÚ","meaning":"sở thích, niềm quan tâm","pos":"Danh từ","example":{"zh":"他对音乐很有兴趣。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"音","py":"yīn"},{"c":"乐","py":"lè"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"兴","py":"xīng"},{"c":"趣","py":"qù"},{"c":"。","py":"。"}],"vi":"Anh ấy rất quan tâm đến âm nhạc."}},{"hanzi":"兄弟","pinyin":"xiōngdì","hanViet":"HUYNH ĐỆ","meaning":"anh em ruột, người bạn đồng tính","pos":"Danh từ","example":{"zh":"他们是好兄弟。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"是","py":"shì"},{"c":"好","py":"hǎo"},{"c":"兄","py":"xiōng"},{"c":"弟","py":"dì"},{"c":"。","py":"。"}],"vi":"Họ là những người bạn tốt."}},{"hanzi":"演讲","pinyin":"yǎnjiǎng","hanViet":"DIỄN GIẢNG","meaning":"bài phát biểu, nói chuyện","pos":"Danh từ","example":{"zh":"他做了一个很好的演讲。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"做","py":"zuò"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"的","py":"de"},{"c":"演","py":"yǎn"},{"c":"讲","py":"jiǎng"},{"c":"。","py":"。"}],"vi":"Anh ấy đã trình bày một bài nói rất tốt."}},{"hanzi":"阳台","pinyin":"yángtái","hanViet":"DƯƠNG ĐÀI","meaning":"ban công","pos":"Danh từ","example":{"zh":"我们在阳台上看风景。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"阳","py":"yáng"},{"c":"台","py":"tái"},{"c":"上","py":"shàng"},{"c":"看","py":"kàn"},{"c":"风","py":"fēng"},{"c":"景","py":"jǐng"},{"c":"。","py":"。"}],"vi":"Chúng tôi nhìn cảnh ở ban công."}},{"hanzi":"养成","pinyin":"yǎngchéng","hanViet":"DƯỠNG THÀNH","meaning":"thuộc thói quen, nuôi dưỡng","pos":"Động từ","example":{"zh":"要养成好习惯。","pinyinPerChar":[{"c":"要","py":"yào"},{"c":"养","py":"yǎng"},{"c":"成","py":"chéng"},{"c":"好","py":"hǎo"},{"c":"习","py":"xí"},{"c":"惯","py":"guàn"},{"c":"。","py":"。"}],"vi":"Cần phải hình thành thói quen tốt."}},{"hanzi":"以内","pinyin":"yǐnèi","hanViet":"DĨ NỘI","meaning":"trong phạm vi, không quá","pos":"Danh từ","example":{"zh":"五分钟以内可以到。","pinyinPerChar":[{"c":"五","py":"wǔ"},{"c":"分","py":"fēn"},{"c":"钟","py":"zhōng"},{"c":"以","py":"yǐ"},{"c":"内","py":"nèi"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"到","py":"dào"},{"c":"。","py":"。"}],"vi":"Có thể đến trong vòng năm phút."}},{"hanzi":"议论","pinyin":"yìlùn","hanViet":"NGHỊ LUẬN","meaning":"bàn luận, thảo luận","pos":"Danh từ","example":{"zh":"大家都在议论这件事。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"都","py":"dōu"},{"c":"在","py":"zài"},{"c":"议","py":"yì"},{"c":"论","py":"lùn"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Cả người đều bàn luận về việc này."}},{"hanzi":"预订","pinyin":"yùdìng","hanViet":"DỰ ĐÍNH","meaning":"đặt trước, đặt chỗ","pos":"Động từ","example":{"zh":"我预订了酒店。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"预","py":"yù"},{"c":"订","py":"dìng"},{"c":"了","py":"le"},{"c":"酒","py":"jiǔ"},{"c":"店","py":"diàn"},{"c":"。","py":"。"}],"vi":"Tôi đã đặt phòng khách sạn."}},{"hanzi":"圆满","pinyin":"yuánmǎn","hanViet":"VIÊN MÃN","meaning":"hoàn hảo, thành công","pos":"Tính từ","example":{"zh":"会议圆满成功。","pinyinPerChar":[{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"圆","py":"yuán"},{"c":"满","py":"mǎn"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Cuộc họp thành công một cách hoàn hảo."}},{"hanzi":"在乎","pinyin":"zàihu","hanViet":"TẠI HỒ","meaning":"quan tâm, coi trọng","pos":"Động từ","example":{"zh":"你在乎什么？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"在","py":"zài"},{"c":"乎","py":"hū"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"？","py":"？"}],"vi":"Bạn coi trọng điều gì?"}},{"hanzi":"丈夫","pinyin":"zhàngfu","hanViet":"TRƯỢNG PHU","meaning":"chồng","pos":"Danh từ","example":{"zh":"丈夫在家工作。","pinyinPerChar":[{"c":"丈","py":"zhàng"},{"c":"夫","py":"fū"},{"c":"在","py":"zài"},{"c":"家","py":"jiā"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Chồng ở nhà làm việc."}},{"hanzi":"争论","pinyin":"zhēnglùn","hanViet":"TRANH LUẬN","meaning":"thảo luận, bàn luận, khiếu nại","pos":"Động từ","example":{"zh":"他们在会议上争论这个问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"上","py":"shàng"},{"c":"争","py":"zhēng"},{"c":"论","py":"lùn"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Họ bàn luận vấn đề này trong cuộc họp."}},{"hanzi":"征服","pinyin":"zhēngfú","hanViet":"TRƯNG PHỤC","meaning":"thành công, chinh phục","pos":"Động từ","example":{"zh":"他征服了自己的恐惧。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"征","py":"zhēng"},{"c":"服","py":"fú"},{"c":"了","py":"le"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"恐","py":"kǒng"},{"c":"惧","py":"jù"},{"c":"。","py":"。"}],"vi":"Anh ấy đã chinh phục nỗi sợ hãi của mình."}},{"hanzi":"制订","pinyin":"zhìdìng","hanViet":"CHẾ ĐÍNH","meaning":"lập kế hoạch, soạn thảo","pos":"Động từ","example":{"zh":"他们制订了计划。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"制","py":"zhì"},{"c":"订","py":"dìng"},{"c":"了","py":"le"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"。","py":"。"}],"vi":"Họ đã lập kế hoạch."}},{"hanzi":"智能","pinyin":"zhìnéng","hanViet":"TRÍ NĂNG","meaning":"trí thông minh","pos":"Tính từ","example":{"zh":"机器人有智能。","pinyinPerChar":[{"c":"机","py":"jī"},{"c":"器","py":"qì"},{"c":"人","py":"rén"},{"c":"有","py":"yǒu"},{"c":"智","py":"zhì"},{"c":"能","py":"néng"},{"c":"。","py":"。"}],"vi":"Robot có trí thông minh."}},{"hanzi":"祝福","pinyin":"zhùfú","hanViet":"CHÚC PHÚC","meaning":"Lời chúc, nguyện phúc","pos":"Danh từ","example":{"zh":"我祝福你健康。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"祝","py":"zhù"},{"c":"福","py":"fú"},{"c":"你","py":"nǐ"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"。","py":"。"}],"vi":"Tôi chúc bạn khỏe mạnh."}},{"hanzi":"著作","pinyin":"zhùzuò","hanViet":"TRỨ TÁC","meaning":"Tác phẩm, bài viết","pos":"Danh từ","example":{"zh":"他有很多著作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"著","py":"zhù"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy có nhiều tác phẩm."}},{"hanzi":"单纯","pinyin":"dānchún","hanViet":"ĐƠN THUẦN","meaning":"đơn thuần, ngây thơ","pos":"Tính từ","example":{"zh":"她的想法很单纯，觉得每个人都是好人。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"想","py":"xiǎng"},{"c":"法","py":"fǎ"},{"c":"很","py":"hěn"},{"c":"单","py":"dān"},{"c":"纯","py":"chún"},{"c":"，","py":"，"},{"c":"觉","py":"jué"},{"c":"得","py":"dé"},{"c":"每","py":"měi"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"都","py":"dōu"},{"c":"是","py":"shì"},{"c":"好","py":"hǎo"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Suy nghĩ của cô ấy rất đơn thuần, cho rằng ai cũng là người tốt."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-7', 6, 'Cảm xúc & tâm trạng', '[{"hanzi":"吃惊","pinyin":"chījīng","hanViet":"KHIẾT KINH","meaning":"ngạc nhiên","pos":"Động từ","example":{"zh":"我吃惊了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"吃","py":"chī"},{"c":"惊","py":"jīng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tôi ngạc nhiên."}},{"hanzi":"担心","pinyin":"dānxīn","hanViet":"ĐẢM TÂM","meaning":"lo lắng, lo","pos":"Động từ","example":{"zh":"我担心他。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"担","py":"dān"},{"c":"心","py":"xīn"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Tôi lo lắng cho anh ấy."}},{"hanzi":"恶心","pinyin":"ěxin","hanViet":"ÁC TÂM","meaning":"độc, khó chịu, buồn nôn","pos":"Tính từ","example":{"zh":"这食物让我恶心。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"食","py":"shí"},{"c":"物","py":"wù"},{"c":"让","py":"ràng"},{"c":"我","py":"wǒ"},{"c":"恶","py":"è"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Món ăn này khiến tôi thấy khó chịu."}},{"hanzi":"放松","pinyin":"fàngsōng","hanViet":"PHÓNG TÙNG","meaning":"Giải tỏa căng thẳng, thư giãn","pos":"Động từ","example":{"zh":"我需要放松一下。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"放","py":"fàng"},{"c":"松","py":"sōng"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Tôi cần thư giãn một chút."}},{"hanzi":"风俗","pinyin":"fēngsú","hanViet":"PHONG TỤC","meaning":"tinh thần, phong tục","pos":"Danh từ","example":{"zh":"这个地方的风俗很有特点。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"地","py":"dì"},{"c":"方","py":"fāng"},{"c":"的","py":"de"},{"c":"风","py":"fēng"},{"c":"俗","py":"sú"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"特","py":"tè"},{"c":"点","py":"diǎn"},{"c":"。","py":"。"}],"vi":"Địa phương này có phong tục rất đặc biệt."}},{"hanzi":"好","pinyin":"hào","hanViet":"HẢO","meaning":"tốt, vui","pos":"Tính từ","example":{"zh":"今天天气好。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Thời tiết hôm nay tốt."}},{"hanzi":"乐趣","pinyin":"lèqù","hanViet":"LẠC THÚ","meaning":"sự thú vị, niềm vui","pos":"Danh từ","example":{"zh":"这本书很有乐趣。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"乐","py":"lè"},{"c":"趣","py":"qù"},{"c":"。","py":"。"}],"vi":"Cuốn sách này rất thú vị."}},{"hanzi":"泪","pinyin":"lèi","hanViet":"LỆ","meaning":"nước mắt, nước rơi từ mắt","pos":"Danh từ","example":{"zh":"她哭了，流下了眼泪。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"哭","py":"kū"},{"c":"了","py":"le"},{"c":"，","py":"，"},{"c":"流","py":"liú"},{"c":"下","py":"xià"},{"c":"了","py":"le"},{"c":"眼","py":"yǎn"},{"c":"泪","py":"lèi"},{"c":"。","py":"。"}],"vi":"Cô ấy khóc, rơi những giọt nước mắt."}},{"hanzi":"泪水","pinyin":"lèishuǐ","hanViet":"LỆ THUỶ","meaning":"nước mắt (thường dùng trong văn cảnh cảm xúc)","pos":"Danh từ","example":{"zh":"眼泪落在桌上。","pinyinPerChar":[{"c":"眼","py":"yǎn"},{"c":"泪","py":"lèi"},{"c":"落","py":"luò"},{"c":"在","py":"zài"},{"c":"桌","py":"zhuō"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Nước mắt rơi xuống bàn."}},{"hanzi":"商务","pinyin":"shāngwù","hanViet":"THƯƠNG VỤ","meaning":"kinh doanh, thương mại","pos":"Danh từ","example":{"zh":"他们谈生意。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"谈","py":"tán"},{"c":"生","py":"shēng"},{"c":"意","py":"yì"},{"c":"。","py":"。"}],"vi":"Họ trao đổi kinh doanh."}},{"hanzi":"失望","pinyin":"shīwàng","hanViet":"THẤT VỌNG","meaning":"thất vọng","pos":"Tính từ","example":{"zh":"我很失望。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"失","py":"shī"},{"c":"望","py":"wàng"},{"c":"。","py":"。"}],"vi":"Tôi rất thất vọng."}},{"hanzi":"舒适","pinyin":"shūshì","hanViet":"THƯ THÍCH","meaning":"thoải mái, thoải mái, dễ chịu","pos":"Tính từ","example":{"zh":"这个房间很舒适。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"很","py":"hěn"},{"c":"舒","py":"shū"},{"c":"适","py":"shì"},{"c":"。","py":"。"}],"vi":"Phòng này rất thoải mái."}},{"hanzi":"松","pinyin":"sōng","hanViet":"TÙNG","meaning":"nhẹ, thoải mái, thả lỏng","pos":"Tính từ","example":{"zh":"椅子很松。","pinyinPerChar":[{"c":"椅","py":"yǐ"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"松","py":"sōng"},{"c":"。","py":"。"}],"vi":"Ghế rất thoải mái."}},{"hanzi":"痛快","pinyin":"tòngkuài","hanViet":"THỐNG KHOÁI","meaning":"thoải mái, hài lòng","pos":"Tính từ","example":{"zh":"我很痛快地答应了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"痛","py":"tòng"},{"c":"快","py":"kuài"},{"c":"地","py":"dì"},{"c":"答","py":"dá"},{"c":"应","py":"yīng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tôi rất thoải mái khi đồng ý."}},{"hanzi":"微笑","pinyin":"wēixiào","hanViet":"VI TIẾU","meaning":"cười nhẹ, ánh mắt hiền hòa","pos":"Động từ","example":{"zh":"她对我微笑。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"对","py":"duì"},{"c":"我","py":"wǒ"},{"c":"微","py":"wēi"},{"c":"笑","py":"xiào"},{"c":"。","py":"。"}],"vi":"Cô ấy cười nhẹ với tôi."}},{"hanzi":"无聊","pinyin":"wúliáo","hanViet":"VÔ LIÊU","meaning":"vô nghĩa, chán chường","pos":"Tính từ","example":{"zh":"我很无聊。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"无","py":"wú"},{"c":"聊","py":"liáo"},{"c":"。","py":"。"}],"vi":"Tôi rất chán chường."}},{"hanzi":"喜爱","pinyin":"xǐ''ài","hanViet":"HỶ ÁI","meaning":"yêu thích, thích thú","pos":"Động từ","example":{"zh":"我喜爱音乐。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"爱","py":"ài"},{"c":"音","py":"yīn"},{"c":"乐","py":"lè"},{"c":"。","py":"。"}],"vi":"Tôi thích âm nhạc."}},{"hanzi":"心理","pinyin":"xīnlǐ","hanViet":"TÂM LÝ","meaning":"tâm lý, tâm trạng","pos":"Danh từ","example":{"zh":"他很关心心理健康。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"关","py":"guān"},{"c":"心","py":"xīn"},{"c":"心","py":"xīn"},{"c":"理","py":"lǐ"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"。","py":"。"}],"vi":"Anh ấy rất quan tâm