INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-8', 7, 'Công việc & văn phòng', '[{"hanzi":"抽奖","pinyin":"chōujiǎng","hanViet":"TRỪU THƯỞNG","meaning":"trúng số, rút thưởng","pos":"Danh từ","example":{"zh":"他们在抽奖。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"抽","py":"chōu"},{"c":"奖","py":"jiǎng"},{"c":"。","py":"。"}],"vi":"Họ đang rút thưởng."}},{"hanzi":"大会","pinyin":"dàhuì","hanViet":"ĐẠI HỘI","meaning":"cuộc họp lớn, đại hội","pos":"Danh từ","example":{"zh":"他们参加大会。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"大","py":"dà"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Họ tham gia cuộc họp lớn."}},{"hanzi":"方案","pinyin":"fāng''àn","hanViet":"PHƯƠNG ÁN","meaning":"Cách giải quyết, kế hoạch","pos":"Danh từ","example":{"zh":"我们需要一个方案。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"方","py":"fāng"},{"c":"案","py":"àn"},{"c":"。","py":"。"}],"vi":"Chúng tôi cần một giải pháp."}},{"hanzi":"负担","pinyin":"fùdān","hanViet":"PHỤ ĐẢM","meaning":"gánh nặng, trách nhiệm","pos":"Danh từ","example":{"zh":"这件事是我的负担。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"负","py":"fù"},{"c":"担","py":"dān"},{"c":"。","py":"。"}],"vi":"Việc này là gánh nặng của tôi."}},{"hanzi":"行业","pinyin":"hángyè","hanViet":"HÀNH NGHIỆP","meaning":"ngành nghề","pos":"Danh từ","example":{"zh":"他在这个行业工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"行","py":"xíng"},{"c":"业","py":"yè"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Cậu ấy làm việc trong ngành nghề này."}},{"hanzi":"合同","pinyin":"hétóng","hanViet":"HỢP ĐỒNG","meaning":"hợp đồng","pos":"Danh từ","example":{"zh":"他们签了合同。",