INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-10', 9, 'Ăn uống & ẩm thực (1)', '[{"hanzi":"矮","pinyin":"ǎi","hanViet":"ẢI","meaning":"thấp","pos":"Tính từ","example":{"zh":"他个子很矮。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"个","py":"gè"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"矮","py":"ǎi"},{"c":"。","py":"。"}],"vi":"Anh ta rất nhỏ."}},{"hanzi":"矮小","pinyin":"ǎixiǎo","hanViet":"ẢI TIỂU","meaning":"thấp, nhỏ","pos":"Tính từ","example":{"zh":"这座房子很矮小。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"矮","py":"ǎi"},{"c":"小","py":"xiǎo"},{"c":"。","py":"。"}],"vi":"Căn nhà này rất nhỏ."}},{"hanzi":"比分","pinyin":"bǐfēn","hanViet":"TỶ PHÂN","meaning":"kết quả trận đấu","pos":"Danh từ","example":{"zh":"比分是2比1。","pinyinPerChar":[{"c":"比","py":"bǐ"},{"c":"分","py":"fēn"},{"c":"是","py":"shì"},{"c":"2","py":"2"},{"c":"比","py":"bǐ"},{"c":"1","py":"1"},{"c":"。","py":"。"}],"vi":"Kết quả là 2-1."}},{"hanzi":"避免","pinyin":"bìmiǎn","hanViet":"TỊ MIỄN","meaning":"tránh, ngăn chặn","pos":"Động từ","example":{"zh":"我们要避免错误。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"避","py":"bì"},{"c":"免","py":"miǎn"},{"c":"错","py":"cuò"},{"c":"误","py":"wù"},{"c":"。","py":"。"}],"vi":"Chúng ta cần tránh sai lầm."}},{"hanzi":"冰","pinyin":"bīng","hanViet":"BĂNG","meaning":"đá băng, lạnh","pos":"Tính từ","example":{"zh":"天气很冷，像冰。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"冷","py":"lěng"},{"c":"，","py":"，"},{"c":"像","py":"xiàng"},{"c":"冰","py":"bīng"},{"c":"。","py":"。"}],"vi":"Thời tiết rất lạnh, lạnh như đá băng."}},{"hanzi":"冰雪","pinyin":"bīngxuě","hanViet":"BĂNG TUYẾT","meaning":"đá băng và tuyết","pos":"Danh từ","example":{"zh":"山上有很多冰雪。","pinyinPerChar":[{"c":"山","py":"shān"},{"c":"上","py":"shàng"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"冰","py":"bīng"},{"c":"雪","py":"xuě"},{"c":"。","py":"。"}],"vi":"Núi có nhiều đá băng và tuyết."}},{"hanzi":"才","pinyin":"cái","hanViet":"TÀI","meaning":"chỉ, mới","pos":"Đại từ","example":{"zh":"我才来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"才","py":"cái"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi mới đến."}},{"hanzi":"材料","pinyin":"cáiliào","hanViet":"TÀI LIỆU","meaning":"vật liệu, nguyên liệu","pos":"Danh từ","example":{"zh":"这个材料很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"材","py":"cái"},{"c":"料","py":"liào"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Vật liệu này rất tốt."}},{"hanzi":"财产","pinyin":"cáichǎn","hanViet":"TÀI SẢN","meaning":"tiền bạc và vật chất có ích","pos":"Danh từ","example":{"zh":"他拥有很多财产。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"拥","py":"yōng"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"财","py":"cái"},{"c":"产","py":"chǎn"},{"c":"。","py":"。"}],"vi":"Anh ấy sở hữu nhiều tài sản."}},{"hanzi":"财富","pinyin":"cáifù","hanViet":"TÀI PHÚ","meaning":"đời sống vật chất, tiền bạc","pos":"Danh từ","example":{"zh":"她希望过上富裕的生活。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"希","py":"xī"},{"c":"望","py":"wàng"},{"c":"过","py":"guò"},{"c":"上","py":"shàng"},{"c":"富","py":"fù"},{"c":"裕","py":"yù"},{"c":"的","py":"de"},{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"。","py":"。"}],"vi":"Cô ấy hy vọng sống ấm no."}},{"hanzi":"茶叶","pinyin":"cháyè","hanViet":"TRÀ DIỆP","meaning":"trà xanh, lá trà","pos":"Danh từ","example":{"zh":"他喜欢喝茶叶。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"喝","py":"hē"},{"c":"茶","py":"chá"},{"c":"叶","py":"yè"},{"c":"。","py":"。"}],"vi":"Anh ấy thích uống trà."}},{"hanzi":"长途","pinyin":"chángtú","hanViet":"TRƯỞNG ĐỒ","meaning":"hành trình xa, đường đi xa","pos":"Danh từ","example":{"zh":"这次旅行是长途。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"旅","py":"lǚ"},{"c":"行","py":"xíng"},{"c":"是","py":"shì"},{"c":"长","py":"zhǎng"},{"c":"途","py":"tú"},{"c":"。","py":"。"}],"vi":"Cuộc đi này là hành trình xa."}},{"hanzi":"抄写","pinyin":"chāoxiě","hanViet":"SAO TẢ","meaning":"chép, sao chép văn bản","pos":"Động từ","example":{"zh":"学生抄写课文。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"抄","py":"chāo"},{"c":"写","py":"xiě"},{"c":"课","py":"kè"},{"c":"文","py":"wén"},{"c":"。","py":"。"}],"vi":"Học sinh chép bài."}},{"hanzi":"潮流","pinyin":"cháoliú","hanViet":"TRÀO LƯU","meaning":"xu hướng, dòng chảy","pos":"Danh từ","example":{"zh":"这是一种潮流。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"种","py":"zhǒng"},{"c":"潮","py":"cháo"},{"c":"流","py":"liú"},{"c":"。","py":"。"}],"vi":"Đây là một xu hướng."}},{"hanzi":"诚信","pinyin":"chéngxìn","hanViet":"THÀNH TÍN","meaning":"tín nhiệm, trung thành","pos":"Tính từ","example":{"zh":"他很诚信。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"诚","py":"chéng"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Cậu ấy rất trung thành."}},{"hanzi":"程序","pinyin":"chéngxù","hanViet":"TRÌNH TỰ","meaning":"quy trình, chương trình","pos":"Danh từ","example":{"zh":"这个程序很复杂。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"程","py":"chéng"},{"c":"序","py":"xù"},{"c":"很","py":"hěn"},{"c":"复","py":"fù"},{"c":"杂","py":"zá"},{"c":"。","py":"。"}],"vi":"Chương trình này phức tạp."}},{"hanzi":"豆腐","pinyin":"dòufu","hanViet":"ĐẬU HỦ","meaning":"đậu phụ","pos":"Danh từ","example":{"zh":"我喜欢吃豆腐。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"豆","py":"dòu"},{"c":"腐","py":"fǔ"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn đậu phụ."}},{"hanzi":"独自","pinyin":"dúzì","hanViet":"ĐỘC TỰ","meaning":"duy nhất, một mình","pos":"Tính từ","example":{"zh":"他独自去旅行。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"独","py":"dú"},{"c":"自","py":"zì"},{"c":"去","py":"qù"},{"c":"旅","py":"lǚ"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Anh ấy đi du lịch một mình."}},{"hanzi":"堵","pinyin":"dǔ","hanViet":"ĐỔ","meaning":"lấp đầy, chặn đường","pos":"Động từ","example":{"zh":"交通堵车很严重。","pinyinPerChar":[{"c":"交","py":"jiāo"},{"c":"通","py":"tōng"},{"c":"堵","py":"dǔ"},{"c":"车","py":"chē"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"重","py":"zhòng"},{"c":"。","py":"。"}],"vi":"Giao thông bị tắc nghẽn rất nghiêm trọng."}},{"hanzi":"方针","pinyin":"fāngzhēn","hanViet":"PHƯƠNG CHÂM","meaning":"Chính sách, đường lối","pos":"Danh từ","example":{"zh":"国家有明确的方针。","pinyinPerChar":[{"c":"国","py":"guó"},{"c":"家","py":"jiā"},{"c":"有","py":"yǒu"},{"c":"明","py":"míng"},{"c":"确","py":"què"},{"c":"的","py":"de"},{"c":"方","py":"fāng"},{"c":"针","py":"zhēn"},{"c":"。","py":"。"}],"vi":"Nhà nước có chính sách rõ ràng."}},{"hanzi":"分为","pinyin":"fēnwéi","hanViet":"PHÂN VỊ","meaning":"chia ra, phân thành","pos":"Động từ","example":{"zh":"这本书分为三部分。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"分","py":"fēn"},{"c":"为","py":"wèi"},{"c":"三","py":"sān"},{"c":"部","py":"bù"},{"c":"分","py":"fēn"},{"c":"。","py":"。"}],"vi":"Sách này được chia thành ba phần."}},{"hanzi":"奋斗","pinyin":"fèndòu","hanViet":"PHẤN ĐẤU","meaning":"phong trào, đấu tranh","pos":"Động từ","example":{"zh":"他们奋斗了很多年。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"奋","py":"fèn"},{"c":"斗","py":"dòu"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"年","py":"nián"},{"c":"。","py":"。"}],"vi":"Họ đã đấu tranh nhiều năm."}},{"hanzi":"风格","pinyin":"fēnggé","hanViet":"PHONG CÁCH","meaning":"phong cách, phong cách","pos":"Danh từ","example":{"zh":"这件衣服的风格很好看。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"的","py":"de"},{"c":"风","py":"fēng"},{"c":"格","py":"gé"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"看","py":"kàn"},{"c":"。","py":"。"}],"vi":"Chiếc áo này có phong cách rất đẹp."}},{"hanzi":"概括","pinyin":"gàikuò","hanViet":"KHÁI QUÁT","meaning":"tóm tắt, khái quát","pos":"Động từ","example":{"zh":"请你概括一下这篇文章的主要内容。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"你","py":"nǐ"},{"c":"概","py":"gài"},{"c":"括","py":"kuò"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"这","py":"zhè"},{"c":"篇","py":"piān"},{"c":"文","py":"wén"},{"c":"章","py":"zhāng"},{"c":"的","py":"de"},{"c":"主","py":"zhǔ"},{"c":"要","py":"yào"},{"c":"内","py":"nèi"},{"c":"容","py":"róng"},{"c":"。","py":"。"}],"vi":"Hãy tóm tắt nội dung chính của bài viết này."}},{"hanzi":"高潮","pinyin":"gāocháo","hanViet":"CAO TRÀO","meaning":"đỉnh cao, sự kiện sôi động","pos":"Danh từ","example":{"zh":"这场比赛的高潮发生在最后一分钟。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"场","py":"chǎng"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"的","py":"de"},{"c":"高","py":"gāo"},{"c":"潮","py":"cháo"},{"c":"发","py":"fā"},{"c":"生","py":"shēng"},{"c":"在","py":"zài"},{"c":"最","py":"zuì"},{"c":"后","py":"hòu"},{"c":"一","py":"yī"},{"c":"分","py":"fēn"},{"c":"钟","py":"zhōng"},{"c":"。","py":"。"}],"vi":"Đỉnh cao của trận đấu xảy ra vào phút cuối."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-11', 10, 'Ăn uống & ẩm thực (2)', '[{"hanzi":"隔","pinyin":"gé","hanViet":"CÁCH","meaning":"khoảng cách, cách xa","pos":"Tính từ","example":{"zh":"两座山之间隔着一条河。","pinyinPerChar":[{"c":"两","py":"liǎng"},{"c":"座","py":"zuò"},{"c":"山","py":"shān"},{"c":"之","py":"zhī"},{"c":"间","py":"jiān"},{"c":"隔","py":"gé"},{"c":"着","py":"zhe"},{"c":"一","py":"yī"},{"c":"条","py":"tiáo"},{"c":"河","py":"hé"},{"c":"。","py":"。"}],"vi":"Giữa hai ngọn núi có một con sông."}},{"hanzi":"隔开","pinyin":"gékāi","hanViet":"CÁCH KHAI","meaning":"cách xa, tách biệt","pos":"Động từ","example":{"zh":"请把书隔开放好。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"书","py":"shū"},{"c":"隔","py":"gé"},{"c":"开","py":"kāi"},{"c":"放","py":"fàng"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Hãy để sách cách xa để sắp xếp."}},{"hanzi":"个别","pinyin":"gèbié","hanViet":"CÁ BIỆT","meaning":"cá nhân, từng cái","pos":"Tính từ","example":{"zh":"个别学生没有完成作业。","pinyinPerChar":[{"c":"个","py":"gè"},{"c":"别","py":"bié"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Một số học sinh chưa hoàn thành bài tập."}},{"hanzi":"个体","pinyin":"gètǐ","hanViet":"CÁ THỂ","meaning":"cá thể, đơn vị","pos":"Danh từ","example":{"zh":"个体经营的商店很多。","pinyinPerChar":[{"c":"个","py":"gè"},{"c":"体","py":"tǐ"},{"c":"经","py":"jīng"},{"c":"营","py":"yíng"},{"c":"的","py":"de"},{"c":"商","py":"shāng"},{"c":"店","py":"diàn"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"。","py":"。"}],"vi":"Nhiều cửa hàng kinh doanh cá nhân."}},{"hanzi":"各个","pinyin":"gègè","hanViet":"CÁC CÁ","meaning":"từng cái, từng phần","pos":"Tính từ","example":{"zh":"各个部门都要参加会议。","pinyinPerChar":[{"c":"各","py":"gè"},{"c":"个","py":"gè"},{"c":"部","py":"bù"},{"c":"门","py":"mén"},{"c":"都","py":"dōu"},{"c":"要","py":"yào"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Từng bộ phận đều phải tham gia họp."}},{"hanzi":"根据","pinyin":"gēnjù","hanViet":"CĂN CỨ","meaning":"dựa trên, theo","pos":"Liên từ","example":{"zh":"根据天气预报，今天会下雨。","pinyinPerChar":[{"c":"根","py":"gēn"},{"c":"据","py":"jù"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"预","py":"yù"},{"c":"报","py":"bào"},{"c":"，","py":"，"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"会","py":"huì"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Theo dự báo thời tiết, hôm nay sẽ mưa."}},{"hanzi":"构成","pinyin":"gòuchéng","hanViet":"CẤU THÀNH","meaning":"tạo thành, bao gồm","pos":"Động từ","example":{"zh":"这组词构成了一个句子。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"组","py":"zǔ"},{"c":"词","py":"cí"},{"c":"构","py":"gòu"},{"c":"成","py":"chéng"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"句","py":"jù"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tập hợp từ này tạo thành một câu."}},{"hanzi":"瓜","pinyin":"guā","hanViet":"QUA","meaning":"dưa, quả","pos":"Danh từ","example":{"zh":"他喜欢吃西瓜。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"西","py":"xī"},{"c":"瓜","py":"guā"},{"c":"。","py":"。"}],"vi":"Cậu ấy thích ăn dưa hấu."}},{"hanzi":"果实","pinyin":"guǒshí","hanViet":"QUẢ THỰC","meaning":"quả trái, kết quả","pos":"Danh từ","example":{"zh":"他努力工作获得果实。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"获","py":"huò"},{"c":"得","py":"dé"},{"c":"果","py":"guǒ"},{"c":"实","py":"shí"},{"c":"。","py":"。"}],"vi":"Cậu ấy làm việc chăm chỉ để đạt được kết quả."}},{"hanzi":"海鲜","pinyin":"hǎixiān","hanViet":"HẢI TIÊN","meaning":"thịt cá, tôm, cua...","pos":"Danh từ","example":{"zh":"我喜欢吃海鲜。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"海","py":"hǎi"},{"c":"鲜","py":"xiān"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn hải sản."}},{"hanzi":"呼吸","pinyin":"hūxī","hanViet":"HÔ HẤP","meaning":"sự hô hấp, thở","pos":"Danh từ","example":{"zh":"运动后我需要呼吸。","pinyinPerChar":[{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"后","py":"hòu"},{"c":"我","py":"wǒ"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"呼","py":"hū"},{"c":"吸","py":"xī"},{"c":"。","py":"。"}],"vi":"Sau khi vận động, tôi cần thở."}},{"hanzi":"技巧","pinyin":"jìqiǎo","hanViet":"KỸ XẢO","meaning":"kỹ năng, thủ thuật, cách thức","pos":"Danh từ","example":{"zh":"她有很多做饭的技巧。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"做","py":"zuò"},{"c":"饭","py":"fàn"},{"c":"的","py":"de"},{"c":"技","py":"jì"},{"c":"巧","py":"qiǎo"},{"c":"。","py":"。"}],"vi":"Cô ấy có nhiều kỹ năng nấu ăn."}},{"hanzi":"降落","pinyin":"jiàngluò","hanViet":"GIÁNG LẠC","meaning":"đông xuống, hạ cánh","pos":"Động từ","example":{"zh":"飞机降落。","pinyinPerChar":[{"c":"飞","py":"fēi"},{"c":"机","py":"jī"},{"c":"降","py":"jiàng"},{"c":"落","py":"luò"},{"c":"。","py":"。"}],"vi":"Máy bay hạ cánh."}},{"hanzi":"结构","pinyin":"jiégòu","hanViet":"KẾT CẤU","meaning":"cấu trúc, thành phần","pos":"Danh từ","example":{"zh":"这座建筑的结构很复杂。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"建","py":"jiàn"},{"c":"筑","py":"zhù"},{"c":"的","py":"de"},{"c":"结","py":"jié"},{"c":"构","py":"gòu"},{"c":"很","py":"hěn"},{"c":"复","py":"fù"},{"c":"杂","py":"zá"},{"c":"。","py":"。"}],"vi":"Cấu trúc của tòa nhà này rất phức tạp."}},{"hanzi":"结论","pinyin":"jiélùn","hanViet":"KẾT LUẬN","meaning":"kết luận, kết quả","pos":"Danh từ","example":{"zh":"根据数据得出结论。","pinyinPerChar":[{"c":"根","py":"gēn"},{"c":"据","py":"jù"},{"c":"数","py":"shù"},{"c":"据","py":"jù"},{"c":"得","py":"dé"},{"c":"出","py":"chū"},{"c":"结","py":"jié"},{"c":"论","py":"lùn"},{"c":"。","py":"。"}],"vi":"Dựa vào dữ liệu để rút ra kết luận."}},{"hanzi":"紧密","pinyin":"jǐnmì","hanViet":"KHẨN MẬT","meaning":"gắn bó, chặt chẽ","pos":"Tính từ","example":{"zh":"他们关系非常紧密。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"关","py":"guān"},{"c":"系","py":"xì"},{"c":"非","py":"fēi"},{"c":"常","py":"cháng"},{"c":"紧","py":"jǐn"},{"c":"密","py":"mì"},{"c":"。","py":"。"}],"vi":"Mối quan hệ của họ rất gắn bó."}},{"hanzi":"精力","pinyin":"jīnglì","hanViet":"TINH LỰC","meaning":"năng lượng, sức mạnh","pos":"Danh từ","example":{"zh":"他精力充沛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"精","py":"jīng"},{"c":"力","py":"lì"},{"c":"充","py":"chōng"},{"c":"沛","py":"pèi"},{"c":"。","py":"。"}],"vi":"Cô ấy có năng lượng dồi dào."}},{"hanzi":"酒吧","pinyin":"jiǔbā","hanViet":"TỬU BA","meaning":"quán rượu","pos":"Danh từ","example":{"zh":"我们去酒吧喝酒。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"酒","py":"jiǔ"},{"c":"吧","py":"ba"},{"c":"喝","py":"hē"},{"c":"酒","py":"jiǔ"},{"c":"。","py":"。"}],"vi":"Chúng ta đi quán rượu uống rượu."}},{"hanzi":"距离","pinyin":"jùlí","hanViet":"CỰ LY","meaning":"khoảng cách","pos":"Danh từ","example":{"zh":"学校离我家很近。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"离","py":"lí"},{"c":"我","py":"wǒ"},{"c":"家","py":"jiā"},{"c":"很","py":"hěn"},{"c":"近","py":"jìn"},{"c":"。","py":"。"}],"vi":"Trường học gần nhà tôi rất nhiều."}},{"hanzi":"看来","pinyin":"kànlái","hanViet":"KHÁN LAI","meaning":"theo như, có lẽ","pos":"Phó từ","example":{"zh":"看来他会来。","pinyinPerChar":[{"c":"看","py":"kàn"},{"c":"来","py":"lái"},{"c":"他","py":"tā"},{"c":"会","py":"huì"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Theo như anh ấy sẽ đến."}},{"hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","hanViet":"KHOÁNG TUYỀN THUỶ","meaning":"nước khoáng","pos":"Danh từ","example":{"zh":"他喝矿泉水。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喝","py":"hē"},{"c":"矿","py":"kuàng"},{"c":"泉","py":"quán"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy uống nước khoáng."}},{"hanzi":"扩大","pinyin":"kuòdà","hanViet":"KHUẾCH ĐẠI","meaning":"mở rộng, tăng kích thước","pos":"Động từ","example":{"zh":"公司扩大了规模。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"扩","py":"kuò"},{"c":"大","py":"dà"},{"c":"了","py":"le"},{"c":"规","py":"guī"},{"c":"模","py":"mó"},{"c":"。","py":"。"}],"vi":"Công ty đã mở rộng quy mô."}},{"hanzi":"辣","pinyin":"là","hanViet":"LẠT","meaning":"cay, cay đắng","pos":"Tính từ","example":{"zh":"这个饭很辣。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"饭","py":"fàn"},{"c":"很","py":"hěn"},{"c":"辣","py":"là"},{"c":"。","py":"。"}],"vi":"Món này rất cay."}},{"hanzi":"老家","pinyin":"lǎojiā","hanViet":"LÃO GIA","meaning":"quê hương, nơi ở cũ","pos":"Danh từ","example":{"zh":"他老家在广东。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"老","py":"lǎo"},{"c":"家","py":"jiā"},{"c":"在","py":"zài"},{"c":"广","py":"guǎng"},{"c":"东","py":"dōng"},{"c":"。","py":"。"}],"vi":"Quê hương cũ của anh ấy ở Quảng Đông."}},{"hanzi":"厘米","pinyin":"límǐ","hanViet":"LY MỄ","meaning":"xăng-ti-mét","pos":"Lượng từ","example":{"zh":"这本书厚一厘米。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"厚","py":"hòu"},{"c":"一","py":"yī"},{"c":"厘","py":"lí"},{"c":"米","py":"mǐ"},{"c":"。","py":"。"}],"vi":"Cuốn sách này dày một xăng-ti-mét."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-12', 11, 'Ăn uống & ẩm thực (3)', '[{"hanzi":"了不起","pinyin":"liǎobuqǐ","hanViet":"LIỄU BẤT KHỞI","meaning":"Quyền lực, năng lực cao","pos":"Tính từ","example":{"zh":"他是个了不起的人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"个","py":"gè"},{"c":"了","py":"le"},{"c":"不","py":"bù"},{"c":"起","py":"qǐ"},{"c":"的","py":"de"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy là một người rất xuất sắc."}},{"hanzi":"列","pinyin":"liè","hanViet":"LIỆT","meaning":"Liệt kê, xếp theo thứ tự","pos":"Động từ","example":{"zh":"请列出名字。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"列","py":"liè"},{"c":"出","py":"chū"},{"c":"名","py":"míng"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Xin hãy liệt kê tên."}},{"hanzi":"列车","pinyin":"lièchē","hanViet":"LIỆT XA","meaning":"Tàu, phương tiện đường sắt","pos":"Danh từ","example":{"zh":"这列车很快。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"列","py":"liè"},{"c":"车","py":"chē"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Tàu này rất nhanh."}},{"hanzi":"零食","pinyin":"língshí","hanViet":"LINH THỰC","meaning":"Đồ ăn vặt, món ăn nhẹ","pos":"Danh từ","example":{"zh":"他喜欢吃零食。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"零","py":"líng"},{"c":"食","py":"shí"},{"c":"。","py":"。"}],"vi":"Anh ấy thích ăn đồ ăn vặt."}},{"hanzi":"轮椅","pinyin":"lúnyǐ","hanViet":"LUÂN Ỷ","meaning":"Xe lăn","pos":"Danh từ","example":{"zh":"他坐轮椅。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"坐","py":"zuò"},{"c":"轮","py":"lún"},{"c":"椅","py":"yǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy ngồi trong xe lăn."}},{"hanzi":"轮子","pinyin":"lúnzi","hanViet":"LUÂN TỬ","meaning":"Bánh xe","pos":"Danh từ","example":{"zh":"汽车有四个轮子。","pinyinPerChar":[{"c":"汽","py":"qì"},{"c":"车","py":"chē"},{"c":"有","py":"yǒu"},{"c":"四","py":"sì"},{"c":"个","py":"gè"},{"c":"轮","py":"lún"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Ô tô có bốn bánh xe."}},{"hanzi":"梦想","pinyin":"mèngxiǎng","hanViet":"MỘNG TƯỞNG","meaning":"ước mơ, khát khao","pos":"Danh từ","example":{"zh":"她的梦想是当医生。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"梦","py":"mèng"},{"c":"想","py":"xiǎng"},{"c":"是","py":"shì"},{"c":"当","py":"dāng"},{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Ước mơ của cô ấy là trở thành bác sĩ."}},{"hanzi":"秘密","pinyin":"mìmì","hanViet":"BÍ MẬT","meaning":"bí mật","pos":"Danh từ","example":{"zh":"这个消息很秘密。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"很","py":"hěn"},{"c":"秘","py":"mì"},{"c":"密","py":"mì"},{"c":"。","py":"。"}],"vi":"Thông tin này rất bí mật."}},{"hanzi":"密码","pinyin":"mìmǎ","hanViet":"MẬT MÃ","meaning":"mã, mật khẩu","pos":"Danh từ","example":{"zh":"请输入密码。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"输","py":"shū"},{"c":"入","py":"rù"},{"c":"密","py":"mì"},{"c":"码","py":"mǎ"},{"c":"。","py":"。"}],"vi":"Hãy nhập mật khẩu."}},{"hanzi":"密切","pinyin":"mìqiè","hanViet":"MẬT THIẾT","meaning":"gần gũi, liên quan chặt chẽ","pos":"Tính từ","example":{"zh":"我们关系密切。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"关","py":"guān"},{"c":"系","py":"xì"},{"c":"密","py":"mì"},{"c":"切","py":"qiè"},{"c":"。","py":"。"}],"vi":"Mối quan hệ giữa chúng ta rất gần gũi."}},{"hanzi":"盘","pinyin":"pán","hanViet":"BÀN","meaning":"đĩa, bánh, vòng","pos":"Danh từ","example":{"zh":"这个盘子很圆。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"盘","py":"pán"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"圆","py":"yuán"},{"c":"。","py":"。"}],"vi":"Đĩa này tròn."}},{"hanzi":"平方","pinyin":"píngfāng","hanViet":"BÌNH PHƯƠNG","meaning":"phân số, phương, diện tích","pos":"Danh từ","example":{"zh":"这块地一平方米。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"块","py":"kuài"},{"c":"地","py":"dì"},{"c":"一","py":"yī"},{"c":"平","py":"píng"},{"c":"方","py":"fāng"},{"c":"米","py":"mǐ"},{"c":"。","py":"。"}],"vi":"Mảnh đất này một mét vuông."}},{"hanzi":"期待","pinyin":"qīdài","hanViet":"KỲ ĐÃI","meaning":"mong đợi, khao khát","pos":"Động từ","example":{"zh":"我期待你的来信。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"期","py":"qī"},{"c":"待","py":"dài"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"来","py":"lái"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Tôi mong đợi thư của bạn đến."}},{"hanzi":"汽水","pinyin":"qìshuǐ","hanViet":"KHÍ THUỶ","meaning":"nước giải khát có ga","pos":"Danh từ","example":{"zh":"我想喝一杯汽水。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"喝","py":"hē"},{"c":"一","py":"yī"},{"c":"杯","py":"bēi"},{"c":"汽","py":"qì"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Tôi muốn uống một cốc nước giải khát."}},{"hanzi":"汽油","pinyin":"qìyóu","hanViet":"KHÍ DẦU","meaning":"xăng dầu, nhiên liệu xe","pos":"Danh từ","example":{"zh":"这辆车需要汽油。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"辆","py":"liàng"},{"c":"车","py":"chē"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"汽","py":"qì"},{"c":"油","py":"yóu"},{"c":"。","py":"。"}],"vi":"Xe này cần xăng dầu."}},{"hanzi":"烧","pinyin":"shāo","hanViet":"THIÊU","meaning":"nóng, đốt, nấu","pos":"Động từ","example":{"zh":"我喜欢吃热的食物。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"热","py":"rè"},{"c":"的","py":"de"},{"c":"食","py":"shí"},{"c":"物","py":"wù"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn đồ ăn nóng."}},{"hanzi":"身材","pinyin":"shēncái","hanViet":"THÂN TÀI","meaning":"hình dáng, vóc lọt","pos":"Danh từ","example":{"zh":"她的身材很好。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"身","py":"shēn"},{"c":"材","py":"cái"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Vóc dáng của cô ấy rất tốt."}},{"hanzi":"神秘","pinyin":"shénmì","hanViet":"THẦN BÍ","meaning":"bí ẩn, ma thuật","pos":"Tính từ","example":{"zh":"这件事很神秘。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"神","py":"sh