INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-13', 12, 'Ăn uống & ẩm thực (4)', '[{"hanzi":"途中","pinyin":"túzhōng","hanViet":"ĐỒ TRUNG","meaning":"trong hành trình, trên đường","pos":"Danh từ","example":{"zh":"我们在途中遇到了朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"途","py":"tú"},{"c":"中","py":"zhōng"},{"c":"遇","py":"yù"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Chúng tôi gặp bạn trong hành trình."}},{"hanzi":"推销","pinyin":"tuīxiāo","hanViet":"SUY TIÊU","meaning":"quảng bá, bán hàng","pos":"Động từ","example":{"zh":"她推销产品给顾客。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"推","py":"tuī"},{"c":"销","py":"xiāo"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"给","py":"gěi"},{"c":"顾","py":"gù"},{"c":"客","py":"kè"},{"c":"。","py":"。"}],"vi":"Cô ấy quảng bá sản phẩm cho khách hàng."}},{"hanzi":"味儿","pinyin":"wèir","hanViet":"VỊ NHI","meaning":"mùi, hương vị","pos":"Danh từ","example":{"zh":"这道菜有点味儿。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"道","py":"dào"},{"c":"菜","py":"cài"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"味","py":"wèi"},{"c":"儿","py":"ér"},{"c":"。","py":"。"}],"vi":"Món này hơi có mùi."}},{"hanzi":"吸收","pinyin":"xīshōu","hanViet":"HẤP THU","meaning":"hấp thụ, hút vào","pos":"Động từ","example":{"zh":"植物吸收水。","pinyinPerChar":[{"c":"植","py":"zhí"},{"c":"物","py":"wù"},{"c":"吸","py":"xī"},{"c":"收","py":"shōu"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Thực vật hấp thụ nước."}},{"hanzi":"下载","pinyin":"xiàzài","hanViet":"HẠ TẢI","meaning":"tải xuống","pos":"Động từ","example":{"zh":"请下载这个文件。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"下","py":"xià"},{"c":"载","py":"zài"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"文","py":"wén"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Vui lòng tải xuống tệp này."}},{"hanzi":"鲜","pinyin":"xiān","hanViet":"TIÊN","meaning":"tươi, ngon, hiếm","pos":"Tính từ","example":{"zh":"这道菜很鲜。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"道","py":"dào"},{"c":"菜","py":"cài"},{"c":"很","py":"hěn"},{"c":"鲜","py":"xiān"},{"c":"。","py":"。"}],"vi":"Món ăn này rất ngon."}},{"hanzi":"鲜花","pinyin":"xiānhuā","hanViet":"TIÊN HOA","meaning":"hoa, hoa tươi","pos":"Danh từ","example":{"zh":"她送我鲜花。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"送","py":"sòng"},{"c":"我","py":"wǒ"},{"c":"鲜","py":"xiān"},{"c":"花","py":"huā"},{"c":"。","py":"。"}],"vi":"Cô ấy gửi cho tôi hoa tươi."}},{"hanzi":"咸","pinyin":"xián","hanViet":"HÀM","meaning":"mặn, có vị mặn","pos":"Tính từ","example":{"zh":"这碗汤有点咸。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"碗","py":"wǎn"},{"c":"汤","py":"tāng"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"咸","py":"xián"},{"c":"。","py":"。"}],"vi":"Tô này có chút mặn."}},{"hanzi":"小吃","pinyin":"xiǎochī","hanViet":"TIỂU KHIẾT","meaning":"món ăn nhỏ, đồ ăn vặt","pos":"Danh từ","example":{"zh":"这里有很多好小吃。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"好","py":"hǎo"},{"c":"小","py":"xiǎo"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Ở đây có nhiều món ăn ngon."}},{"hanzi":"效率","pinyin":"xiàolǜ","hanViet":"HIỆU","meaning":"hiệu suất, năng suất","pos":"Danh từ","example":{"zh":"我们要提高工作效率。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"提","py":"tí"},{"c":"高","py":"gāo"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"效","py":"xiào"},{"c":"率","py":"lǜ"},{"c":"。","py":"。"}],"vi":"Chúng ta cần tăng hiệu suất làm việc."}},{"hanzi":"新鲜","pinyin":"xīnxiān","hanViet":"TÂN TIÊN","meaning":"mới, tươi, ngon","pos":"Tính từ","example":{"zh":"这个水果很新鲜。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"很","py":"hěn"},{"c":"新","py":"xīn"},{"c":"鲜","py":"xiān"},{"c":"。","py":"。"}],"vi":"Quả này rất tươi ngon."}},{"hanzi":"牙","pinyin":"yá","hanViet":"NHA","meaning":"răng","pos":"Danh từ","example":{"zh":"他牙齿很白。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"牙","py":"yá"},{"c":"齿","py":"chǐ"},{"c":"很","py":"hěn"},{"c":"白","py":"bái"},{"c":"。","py":"。"}],"vi":"Răng anh ấy rất trắng."}},{"hanzi":"盐","pinyin":"yán","hanViet":"DIÊM","meaning":"muối","pos":"Danh từ","example":{"zh":"菜里放了盐。","pinyinPerChar":[{"c":"菜","py":"cài"},{"c":"里","py":"lǐ"},{"c":"放","py":"fàng"},{"c":"了","py":"le"},{"c":"盐","py":"yán"},{"c":"。","py":"。"}],"vi":"Món ăn đã có muối."}},{"hanzi":"一律","pinyin":"yīlǜ","hanViet":"NHẤT LUẬT","meaning":"tất cả đều, một cách nhất quán","pos":"Tính từ","example":{"zh":"这次考试一律不允许带手机。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"一","py":"yī"},{"c":"律","py":"lǜ"},{"c":"不","py":"bù"},{"c":"允","py":"yǔn"},{"c":"许","py":"xǔ"},{"c":"带","py":"dài"},{"c":"手","py":"shǒu"},{"c":"机","py":"jī"},{"c":"。","py":"。"}],"vi":"Thí sinh này không được phép mang điện thoại trong kỳ thi."}},{"hanzi":"种植","pinyin":"zhòngzhí","hanViet":"CHỦNG THỰC","meaning":"Trồng trọt, canh tác","pos":"Động từ","example":{"zh":"他们种植水果。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"种","py":"zhǒng"},{"c":"植","py":"zhí"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Họ trồng trọt trái cây."}},{"hanzi":"转告","pinyin":"zhuǎngào","hanViet":"CHUYỂN CÁO","meaning":"Đưa tin, truyền đạt","pos":"Động từ","example":{"zh":"请转告他。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"转","py":"zhuǎn"},{"c":"告","py":"gào"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Xin hãy chuyển tin cho anh ấy."}},{"hanzi":"追求","pinyin":"zhuīqiú","hanViet":"TRUY CẦU","meaning":"nghĩa vụ, theo đuổi mục tiêu","pos":"Động từ","example":{"zh":"她追求幸福。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"追","py":"zhuī"},{"c":"求","py":"qiú"},{"c":"幸","py":"xìng"},{"c":"福","py":"fú"},{"c":"。","py":"。"}],"vi":"Cô ấy theo đuổi hạnh phúc."}},{"hanzi":"字母","pinyin":"zìmǔ","hanViet":"TỰ MẪU","meaning":"ký tự, chữ cái","pos":"Danh từ","exam