INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-18', 17, 'Thời tiết & tự nhiên', '[{"hanzi":"爱国","pinyin":"àiguó","hanViet":"ÁI QUỐC","meaning":"yêu nước","pos":"Động từ","example":{"zh":"我们要爱国。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"爱","py":"ài"},{"c":"国","py":"guó"},{"c":"。","py":"。"}],"vi":"Chúng ta phải yêu nước."}},{"hanzi":"潮","pinyin":"cháo","hanViet":"TRÀO","meaning":"sóng, dòng nước mạnh","pos":"Danh từ","example":{"zh":"海边有很多潮。","pinyinPerChar":[{"c":"海","py":"hǎi"},{"c":"边","py":"biān"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"潮","py":"cháo"},{"c":"。","py":"。"}],"vi":"Bờ biển có nhiều sóng."}},{"hanzi":"潮湿","pinyin":"cháoshī","hanViet":"TRÀO THẤP","meaning":"nóng ẩm, ướt bậy","pos":"Tính từ","example":{"zh":"天气今天很潮湿。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"很","py":"hěn"},{"c":"潮","py":"cháo"},{"c":"湿","py":"shī"},{"c":"。","py":"。"}],"vi":"Thời tiết hôm nay rất ẩm."}},{"hanzi":"打雷","pinyin":"dǎléi","hanViet":"ĐẢ LÔI","meaning":"sấm sét","pos":"Động từ","example":{"zh":"今晚打雷。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"晚","py":"wǎn"},{"c":"打","py":"dǎ"},{"c":"雷","py":"léi"},{"c":"。","py":"。"}],"vi":"Tối nay sấm sét."}},{"hanzi":"顶","pinyin":"dǐng","hanViet":"ĐỈNH","meaning":"đầu, đỉnh","pos":"Danh từ","example":{"zh":"他把帽子戴在顶上。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"把","py":"bǎ"},{"c":"帽","py":"mào"},{"c":"子","py":"zi"},{"c":"戴","py":"dài"},{"c":"在","py":"zài"},{"c":"顶","py":"dǐng"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Anh ấy đeo mũ trên đầu."}},{"hanzi":"分散","pinyin":"fēnsàn","hanViet":"PHÂN TÁN","meaning":"Lá, phân tán, không tập trung","pos":"Động từ","example":{"zh":"人群分散开来。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"群","py":"qún"},{"c":"分","py":"fēn"},{"c":"散","py":"sàn"},{"c":"开","py":"kāi"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Những người trong đám tán ra."}},{"hanzi":"风景","pinyin":"fēngjǐng","hanViet":"PHONG CẢNH","meaning":"cảnh đẹp, cảnh quan","pos":"Danh từ","example":{"zh":"这里的风景很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"的","py":"de"},{"c":"风","py":"fēng"},{"c":"景","py":"jǐng"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Cảnh ở đây rất đẹp."}},{"hanzi":"官方","pinyin":"guānfāng","hanViet":"QUAN PHƯƠNG","meaning":"chính thức, nhà nước","pos":"Tính từ","example":{"zh":"官方发布了新消息。","pinyinPerChar":[{"c":"官","py":"guān"},{"c":"方","py":"fāng"},{"c":"发","py":"fā"},{"c":"布","py":"bù"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Cơ quan chính thức đã công bố thông báo mới."}},{"hanzi":"寒冷","pinyin":"hánlěng","hanViet":"HÀN LẠNH","meaning":"lạnh","pos":"Tính từ","example":{"zh":"今天很寒冷。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"很","py":"hěn"},{"c":"寒","py":"hán"},{"c":"冷","py":"lěng"},{"c":"。","py":"。"}],"vi":"Hôm nay rất lạnh."}},{"hanzi":"回复","pinyin":"huífù","hanViet":"HỒI PHỤC","meaning":"trả lời, phục hồi","pos":"Động từ","example":{"zh":"请回复我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"回","py":"huí"},{"c":"复","py":"fù"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Xin trả lời cho tôi."}},{"hanzi":"火","pinyin":"huǒ","hanViet":"HOẢ","meaning":"lửa, đám lửa","pos":"Danh từ","example":{"zh":"火很热。","pinyinPerChar":[{"c":"火","py":"huǒ"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"。","py":"。"}],"vi":"Lửa rất nóng."}},{"hanzi":"激动","pinyin":"jīdòng","hanViet":"KÍCH ĐỘNG","meaning":"giật gân, phấn khích","pos":"Động từ","example":{"zh":"她很激动。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"很","py":"hěn"},{"c":"激","py":"jī"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Cô ấy rất phấn khích."}},{"hanzi":"降温","pinyin":"jiàngwēn","hanViet":"GIÁNG ÔN","meaning":"giảm nhiệt độ","pos":"Động từ","example":{"zh":"天气降温。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"降","py":"jiàng"},{"c":"温","py":"wēn"},{"c":"。","py":"。"}],"vi":"Thời tiết giảm nhiệt độ."}},{"hanzi":"镜头","pinyin":"jìngtóu","hanViet":"KÍNH ĐẦU","meaning":"phim ảnh, khung cảnh","pos":"Danh từ","example":{"zh":"镜头转向左边。","pinyinPerChar":[{"c":"镜","py":"jìng"},{"c":"头","py":"tóu"},{"c":"转","py":"zhuǎn"},{"c":"向","py":"xiàng"},{"c":"左","py":"zuǒ"},{"c":"边","py":"biān"},{"c":"。","py":"。"}],"vi":"Phim quay sang bên trái."}},{"hanzi":"开花","pinyin":"kāihuā","hanViet":"KHAI HOA","meaning":"hoa, nở hoa","pos":"Động từ","example":{"zh":"樱花开了。","pinyinPerChar":[{"c":"樱","py":"yīng"},{"c":"花","py":"huā"},{"c":"开","py":"kāi"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Hoa anh đào đã nở."}},{"hanzi":"开水","pinyin":"kāishuǐ","hanViet":"KHAI THUỶ","meaning":"nước sôi","pos":"Danh từ","example":{"zh":"请喝热开水。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"喝","py":"hē"},{"c":"热","py":"rè"},{"c":"开","py":"kāi"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Vui lòng uống nước sôi."}},{"hanzi":"垃圾","pinyin":"lājī","hanViet":"LẠP SẮC","meaning":"rác, đồ thừa","pos":"Danh từ","example":{"zh":"请把垃圾扔进桶。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"垃","py":"lā"},{"c":"圾","py":"jī"},{"c":"扔","py":"rēng"},{"c":"进","py":"jìn"},{"c":"桶","py":"tǒng"},{"c":"。","py":"。"}],"vi":"Hãy bỏ rác vào thùng."}},{"hanzi":"来不及","pinyin":"láibují","hanViet":"LAI BẤT CẬP","meaning":"quá sớm, không kịp","pos":"Phó từ","example":{"zh":"我来不及赶车。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"来","py":"lái"},{"c":"不","py":"bù"},{"c":"及","py":"jí"},{"c":"赶","py":"gǎn"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Tôi không kịp đón xe."}},{"hanzi":"来源","pinyin":"láiyuán","hanViet":"LAI NGUYÊN","meaning":"nguồn gốc, nguồn","pos":"Danh từ","example":{"zh":"这个消息的来源是谁？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"的","py":"de"},{"c":"来","py":"lái"},{"c":"源","py":"yuán"},{"c":"是","py":"shì"},{"c":"谁","py":"shuí"},{"c":"？","py":"？"}],"vi":"Ai là nguồn của tin này?"}},{"hanzi":"冷静","pinyin":"lěngjìng","hanViet":"LẠNH TĨNH","meaning":"lạnh lùng, bình tĩnh, không hoảng loạn","pos":"Tính từ","example":{"zh":"他在危险中很冷静。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"危","py":"wēi"},{"c":"险","py":"xiǎn"},{"c":"中","py":"zhōng"},{"c":"很","py":"hěn"},{"c":"冷","py":"lěng"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Anh ấy rất bình tĩnh trong tình huống nguy hiểm."}},{"hanzi":"浓","pinyin":"nóng","hanViet":"NỒNG","meaning":"mạnh, đậm, dày","pos":"Tính từ","example":{"zh":"这杯茶很浓。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"杯","py":"bēi"},{"c":"茶","py":"chá"},{"c":"很","py":"hěn"},{"c":"浓","py":"nóng"},{"c":"。","py":"。"}],"vi":"Cốc trà này rất đậm."}},{"hanzi":"热闹","pinyin":"rènao","hanViet":"NHIỆT NÁO","meaning":"nóng, sôi động","pos":"Tính từ","example":{"zh":"市场很热闹。","pinyinPerChar":[{"c":"市","py":"shì"},{"c":"场","py":"chǎng"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"闹","py":"nào"},{"c":"。","py":"。"}],"vi":"Chợ rất đông."}},{"hanzi":"森林","pinyin":"sēnlín","hanViet":"SÂM LÂM","meaning":"rừng nguyên sinh","pos":"Danh từ","example":{"zh":"森林里住着很多动物。","pinyinPerChar":[{"c":"森","py":"sēn"},{"c":"林","py":"lín"},{"c":"里","py":"lǐ"},{"c":"住","py":"zhù"},{"c":"着","py":"zhe"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"动","py":"dòng"},{"c":"物","py":"wù"},{"c":"。","py":"。"}],"vi":"Trong rừng nguyên sinh sống nhiều động vật."}},{"hanzi":"晒","pinyin":"shài","hanViet":"SÁI","meaning":"mở nắng, phơi","pos":"Động từ","example":{"zh":"我晒被子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"晒","py":"shài"},{"c":"被","py":"bèi"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi phơi chăn."}},{"hanzi":"闪电","pinyin":"shǎndiàn","hanViet":"THIỂM ĐIỆN","meaning":"sét","pos":"Danh từ","example":{"zh":"天空中有闪电。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"空","py":"kōng"},{"c":"中","py":"zhōng"},{"c":"有","py":"yǒu"},{"c":"闪","py":"shǎn"},{"c":"电","py":"diàn"},{"c":"。","py":"。"}