INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-19', 18, 'Sức khỏe & cơ thể (1)', '[{"hanzi":"啊","pinyin":"ā","hanViet":"A","meaning":"vần, biểu cảm","pos":"Thán từ","example":{"zh":"啊，今天天气真好！","pinyinPerChar":[{"c":"啊","py":"a"},{"c":"，","py":"，"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"真","py":"zhēn"},{"c":"好","py":"hǎo"},{"c":"！","py":"！"}],"vi":"À, hôm nay thời tiết thật đẹp!"}},{"hanzi":"摆动","pinyin":"bǎidòng","hanViet":"BÀI ĐỘNG","meaning":"lắc, dao động","pos":"Động từ","example":{"zh":"他摆动手臂。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"摆","py":"bǎi"},{"c":"动","py":"dòng"},{"c":"手","py":"shǒu"},{"c":"臂","py":"bì"},{"c":"。","py":"。"}],"vi":"Anh ta lắc cánh tay."}},{"hanzi":"摆脱","pinyin":"bǎituō","hanViet":"BÀI THOÁT","meaning":"bỏ trốn, giải thoát","pos":"Động từ","example":{"zh":"我们要摆脱困难。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"摆","py":"bǎi"},{"c":"脱","py":"tuō"},{"c":"困","py":"kùn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Chúng ta phải vượt qua khó khăn."}},{"hanzi":"参与","pinyin":"cānyù","hanViet":"THAM DỮ","meaning":"tham gia vào hoạt động","pos":"Động từ","example":{"zh":"他参与了比赛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"参","py":"cān"},{"c":"与","py":"yǔ"},{"c":"了","py":"le"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"。","py":"。"}],"vi":"Anh ấy tham gia cuộc thi."}},{"hanzi":"彻底","pinyin":"chèdǐ","hanViet":"TRIỆT ĐỂ","meaning":"hoàn toàn, tuyệt đối","pos":"Tính từ","example":{"zh":"他彻底解决了问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"彻","py":"chè"},{"c":"底","py":"dǐ"},{"c":"解","py":"jiě"},{"c":"决","py":"jué"},{"c":"了","py":"le"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Cậu ấy đã giải quyết vấn đề một cách hoàn toàn."}},{"hanzi":"充电器","pinyin":"chōngdiànqì","hanViet":"SUNG ĐIỆN KHÍ","meaning":"điện thoại, laptop sạc pin","pos":"Danh từ","example":{"zh":"我用充电器给手机充电。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"充","py":"chōng"},{"c":"电","py":"diàn"},{"c":"器","py":"qì"},{"c":"给","py":"gěi"},{"c":"手","py":"shǒu"},{"c":"机","py":"jī"},{"c":"充","py":"chōng"},{"c":"电","py":"diàn"},{"c":"。","py":"。"}],"vi":"Tôi dùng ổ cắm sạc để sạc điện thoại."}},{"hanzi":"抽烟","pinyin":"chōuyān","hanViet":"TRỪU YÊN","meaning":"hút thuốc","pos":"Động từ","example":{"zh":"她不抽烟。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"不","py":"bù"},{"c":"抽","py":"chōu"},{"c":"烟","py":"yān"},{"c":"。","py":"。"}],"vi":"Cô ấy không hút thuốc."}},{"hanzi":"促使","pinyin":"cùshǐ","hanViet":"XÚC SỬ","meaning":"làm cho, dẫn đến","pos":"Động từ","example":{"zh":"天气促使我们外出。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"促","py":"cù"},{"c":"使","py":"shǐ"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"外","py":"wài"},{"c":"出","py":"chū"},{"c":"。","py":"。"}],"vi":"Thời tiết làm cho chúng ta đi ngoài."}},{"hanzi":"打针","pinyin":"dǎzhēn","hanViet":"ĐẢ CHÂM","meaning":"chích mũi, tiêm","pos":"Động từ","example":{"zh":"他打针。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"打","py":"dǎ"},{"c":"针","py":"zhēn"},{"c":"。","py":"。"}],"vi":"Anh ấy chích mũi."}},{"hanzi":"点名","pinyin":"diǎnmíng","hanViet":"ĐIỂM DANH","meaning":"điểm danh","pos":"Danh từ","example":{"zh":"老师今天点名检查出勤。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"点","py":"diǎn"},{"c":"名","py":"míng"},{"c":"检","py":"jiǎn"},{"c":"查","py":"chá"},{"c":"出","py":"chū"},{"c":"勤","py":"qín"},{"c":"。","py":"。"}],"vi":"Giáo viên hôm nay điểm danh kiểm tra sự hiện diện."}},{"hanzi":"动画片","pinyin":"dònghuàpiàn","hanViet":"ĐỘNG HOẠ PHIẾN","meaning":"phim hoạt hình","pos":"Danh từ","example":{"zh":"孩子们喜欢看动画片。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"看","py":"kàn"},{"c":"动","py":"dòng"},{"c":"画","py":"huà"},{"c":"片","py":"piàn"},{"c":"。","py":"。"}],"vi":"Các em nhỏ thích xem