ǎizhèng","hanViet":"CẢI CHÍNH","meaning":"sửa chữa, sửa lỗi","pos":"Động từ","example":{"zh":"请改正你的错误。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"改","py":"gǎi"},{"c":"正","py":"zhèng"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"错","py":"cuò"},{"c":"误","py":"wù"},{"c":"。","py":"。"}],"vi":"Xin sửa lỗi của bạn."}},{"hanzi":"骨头","pinyin":"gǔtou","hanViet":"CỐT ĐẦU","meaning":"xương","pos":"Danh từ","example":{"zh":"这块骨头很硬。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"块","py":"kuài"},{"c":"骨","py":"gǔ"},{"c":"头","py":"tóu"},{"c":"很","py":"hěn"},{"c":"硬","py":"yìng"},{"c":"。","py":"。"}],"vi":"Khối xương này rất cứng."}},{"hanzi":"号码","pinyin":"hàomǎ","hanViet":"HIỆU MÃ","meaning":"số điện thoại, mã số","pos":"Danh từ","example":{"zh":"请问你的号码是多少？","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"问","py":"wèn"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"号","py":"hào"},{"c":"码","py":"mǎ"},{"c":"是","py":"shì"},{"c":"多","py":"duō"},{"c":"少","py":"shǎo"},{"c":"？","py":"？"}],"vi":"Bạn vui lòng cho biết số của mình là bao nhiêu?"}},{"hanzi":"护士","pinyin":"hùshi","hanViet":"HỘ SĨ","meaning":"y tá","pos":"Danh từ","example":{"zh":"护士在病房里工作。","pinyinPerChar":[{"c":"护","py":"hù"},{"c":"士","py":"shì"},{"c":"在","py":"zài"},{"c":"病","py":"bìng"},{"c":"房","py":"fáng"},{"c":"里","py":"lǐ"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Y tá làm việc trong phòng bệnh."}},{"hanzi":"机遇","pinyin":"jīyù","hanViet":"CƠ NGỘ","meaning":"dịp, cơ hội","pos":"Danh từ","example":{"zh":"这是一个好机遇。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"好","py":"hǎo"},{"c":"机","py":"jī"},{"c":"遇","py":"yù"},{"c":"。","py":"。"}],"vi":"Đây là một cơ hội tốt."}},{"hanzi":"减肥","pinyin":"jiǎnféi","hanViet":"GIẢM PHÌ","meaning":"giảm cân","pos":"Động từ","example":{"zh":"她每天运动减肥。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"减","py":"jiǎn"},{"c":"肥","py":"féi"},{"c":"。","py":"。"}],"vi":"Cô ấy tập thể dục mỗi ngày để giảm cân."}},{"hanzi":"健身","pinyin":"jiànshēn","hanViet":"KIỆN THÂN","meaning":"tập thể dục để cơ thể khỏe mạnh","pos":"Danh từ","example":{"zh":"她每天健身。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"健","py":"jiàn"},{"c":"身","py":"shēn"},{"c":"。","py":"。"}],"vi":"Cô ấy tập thể dục mỗi ngày."}},{"hanzi":"近代","pinyin":"jìndài","hanViet":"CẬN ĐẠI","meaning":"đại cổ, gần đây","pos":"Danh từ","example":{"zh":"近代历史很有意思。","pinyinPerChar":[{"c":"近","py":"jìn"},{"c":"代","py":"dài"},{"c":"历","py":"lì"},{"c":"史","py":"shǐ"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Lịch sử đại cổ rất thú vị."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-20', 19, 'Sức khỏe & cơ thể (2)', '[{"hanzi":"角色","pinyin":"juésè","hanViet":"GIÁC SẮC","meaning":"vai trò, nhân vật","pos":"Danh từ","example":{"zh":"他在工作中扮演重要角色。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"中","py":"zhōng"},{"c":"扮","py":"bàn"},{"c":"演","py":"yǎn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"角","py":"jiǎo"},{"c":"色","py":"sè"},{"c":"。","py":"。"}],"vi":"Anh ấy đóng vai quan trọng trong công việc."}},{"hanzi":"口袋","pinyin":"kǒudai","hanViet":"KHẨU ĐẠI","meaning":"quần đùi, túi","pos":"Danh từ","example":{"zh":"他把钥匙放进口袋。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"把","py":"bǎ"},{"c":"钥","py":"yào"},{"c":"匙","py":"shi"},{"c":"放","py":"fàng"},{"c":"进","py":"jìn"},{"c":"口","py":"kǒu"},{"c":"袋","py":"dài"},{"c":"。","py":"。"}],"vi":"Anh ấy bỏ chìa khóa vào túi."}},{"hanzi":"苦","pinyin":"kǔ","hanViet":"KHỔ","meaning":"khó chịu, cay, mệt mỏi","pos":"Tính từ","example":{"zh":"这道菜很苦。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"道","py":"dào"},{"c":"菜","py":"cài"},{"c":"很","py":"hěn"},{"c":"苦","py":"kǔ"},{"c":"。","py":"。"}],"vi":"Món này rất cay."}},{"hanzi":"疗养","pinyin":"liáoyǎng","hanViet":"LIỆU DƯỠNG","meaning":"chữa bệnh, chăm sóc sức khỏe, phục hồi","pos":"Danh từ","example":{"zh":"他去疗养。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"去","py":"qù"},{"c":"疗","py":"liáo"},{"c":"养","py":"yǎng"},{"c":"。","py":"。"}],"vi":"Anh ấy đi chữa bệnh."}},{"hanzi":"列入","pinyin":"lièrù","hanViet":"LIỆT NHẬP","meaning":"Đưa vào danh sách, xếp vào","pos":"Động từ","example":{"zh":"他被列入名单。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"被","py":"bèi"},{"c":"列","py":"liè"},{"c":"入","py":"rù"},{"c":"名","py":"míng"},{"c":"单","py":"dān"},{"c":"。","py":"。"}],"vi":"Anh ấy được đưa vào danh sách."}},{"hanzi":"哪怕","pinyin":"nǎpà","hanViet":"NẢ PHẠ","meaning":"dù, cho dù","pos":"Liên từ","example":{"zh":"哪怕下雨，我也去。","pinyinPerChar":[{"c":"哪","py":"nǎ"},{"c":"怕","py":"pà"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"也","py":"yě"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Dù mưa, tôi vẫn đi."}},{"hanzi":"脑袋","pinyin":"nǎodai","hanViet":"NÃO ĐẠI","meaning":"đầu","pos":"Danh từ","example":{"zh":"他撞到了脑袋。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"撞","py":"zhuàng"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"脑","py":"nǎo"},{"c":"袋","py":"dài"},{"c":"。","py":"。"}],"vi":"Anh ấy chạm vào đầu."}},{"hanzi":"胖子","pinyin":"pàngzi","hanViet":"BÀN TỬ","meaning":"người mập","pos":"Danh từ","example":{"zh":"他是个胖子。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"个","py":"gè"},{"c":"胖","py":"pàng"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Cậu ấy là một người mập."}},{"hanzi":"器官","pinyin":"qìguān","hanViet":"KHÍ QUAN","meaning":"tổ chức, cơ quan trong cơ thể","pos":"Danh từ","example":{"zh":"心脏是人体的重要器官。","pinyinPerChar":[{"c":"心","py":"xīn"},{"c":"脏","py":"zàng"},{"c":"是","py":"shì"},{"c":"人","py":"rén"},{"c":"体","py":"tǐ"},{"c":"的","py":"de"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"器","py":"qì"},{"c":"官","py":"guān"},{"c":"。","py":"。"}],"vi":"Tim là một cơ quan quan trọng trong cơ thể người."}},{"hanzi":"伤害","pinyin":"shānghài","hanViet":"THƯƠNG HẠI","meaning":"làm tổn hại, làm đau","pos":"Động từ","example":{"zh":"他不应该伤害别人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"伤","py":"shāng"},{"c":"害","py":"hài"},{"c":"别","py":"bié"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy không nên làm tổn hại người khác."}},{"hanzi":"神话","pinyin":"shénhuà","hanViet":"THẦN THOẠI","meaning":"thần thoại","pos":"Danh từ","example":{"zh":"这个故事是神话。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"故","py":"gù"},{"c":"事","py":"shì"},{"c":"是","py":"shì"},{"c":"神","py":"shén"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Câu chuyện này là thần thoại."}},{"hanzi":"手里","pinyin":"shǒu li","hanViet":"THỦ LÝ","meaning":"trong tay","pos":"Danh từ","example":{"zh":"他手里拿着书。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"手","py":"shǒu"},{"c":"里","py":"lǐ"},{"c":"拿","py":"ná"},{"c":"着","py":"zhe"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Anh ta trong tay đang cầm sách."}},{"hanzi":"手术","pinyin":"shǒushù","hanViet":"THỦ THUẬT","meaning":"phẫu thuật","pos":"Danh từ","example":{"zh":"医生做手术。","pinyinPerChar":[{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"做","py":"zuò"},{"c":"手","py":"shǒu"},{"c":"术","py":"shù"},{"c":"。","py":"。"}],"vi":"Bác sĩ thực hiện phẫu thuật."}},{"hanzi":"率先","pinyin":"shuàixiān","hanViet":"TIÊN","meaning":"đi đầu, tiên phong","pos":"Động từ","example":{"zh":"他们率先完成任务。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"率","py":"lǜ"},{"c":"先","py":"xiān"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"任","py":"rèn"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Họ đi đầu hoàn thành nhiệm vụ."}},{"hanzi":"体检","pinyin":"tǐjiǎn","hanViet":"THỂ KIỂM","meaning":"khám sức khỏe","pos":"Danh từ","example":{"zh":"他要去体检。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"要","py":"yào"},{"c":"去","py":"qù"},{"c":"体","py":"tǐ"},{"c":"检","py":"jiǎn"},{"c":"。","py":"。"}],"vi":"Anh ấy đi khám sức khỏe."}},{"hanzi":"体重","pinyin":"tǐzhòng","hanViet":"THỂ TRỌNG","meaning":"cân nặng","pos":"Danh từ","example":{"zh":"她的体重很轻。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"体","py":"tǐ"},{"c":"重","py":"zhòng"},{"c":"很","py":"hěn"},{"c":"轻","py":"qīng"},{"c":"。","py":"。"}],"vi":"Cân nặng của cô ấy rất nhẹ."}},{"hanzi":"童话","pinyin":"tónghuà","hanViet":"ĐỒNG THOẠI","meaning":"câu chuyện cổ tích","pos":"Danh từ","example":{"zh":"这个童话很有趣。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"童","py":"tóng"},{"c":"话","py":"huà"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"趣","py":"qù"},{"c":"。","py":"。"}],"vi":"Câu chuyện cổ tích này rất thú vị."}},{"hanzi":"围巾","pinyin":"wéijīn","hanViet":"VI CÂN","meaning":"keo cổ","pos":"Danh từ","example":{"zh":"她戴了一条红色围巾。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"戴","py":"dài"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"条","py":"tiáo"},{"c":"红","py":"hóng"},{"c":"色","py":"sè"},{"c":"围","py":"wéi"},{"c":"巾","py":"jīn"},{"c":"。","py":"。"}],"vi":"Cô ấy đeo một chiếc keo cổ đỏ."}},{"hanzi":"维修","pinyin":"wéixiū","hanViet":"DUY TU","meaning":"sửa chữa","pos":"Động từ","example":{"zh":"我去维修电脑。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"维","py":"wéi"},{"c":"修","py":"xiū"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"。","py":"。"}],"vi":"Tôi đi sửa máy tính."}},{"hanzi":"吸烟","pinyin":"xīyān","hanViet":"HẤP YÊN","meaning":"hút thuốc","pos":"Động từ","example":{"zh":"他不吸烟。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"吸","py":"xī"},{"c":"烟","py":"yān"},{"c":"。","py":"。"}],"vi":"Cậu ấy không hút thuốc."}},{"hanzi":"系列","pinyin":"xìliè","hanViet":"HỆ LIỆT","meaning":"danh mục, loạt, chuỗi","pos":"Danh từ","example":{"zh":"这是一系列书。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"系","py":"xì"},{"c":"列","py":"liè"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Đây là một loạt sách."}},{"hanzi":"项","pinyin":"xiàng","hanViet":"HẠNG","meaning":"mục, hàng, vai","pos":"Danh từ","example":{"zh":"这项工作很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"项","py":"xiàng"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Việc này rất quan trọng."}},{"hanzi":"胸部","pinyin":"xiōngbù","hanViet":"HUNG BỘ","meaning":"ngực, phần ngực","pos":"Danh từ","example":{"zh":"他胸部很健康。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"胸","py":"xiōng"},{"c":"部","py":"bù"},{"c":"很","py":"hěn"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"。","py":"。"}],"vi":"Ngực anh ấy rất khỏe."}},{"hanzi":"修理","pinyin":"xiūlǐ","hanViet":"TU LÝ","meaning":"sửa chữa, bảo trì","pos":"Động từ","example":{"zh":"我要修理这台电脑。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"修","py":"xiū"},{"c":"理","py":"lǐ"},{"c":"这","py":"zhè"},{"c":"台","py":"tái"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"。","py":"。"}],"vi":"Tôi sẽ sửa chữa máy tính này."}},{"hanzi":"眼里","pinyin":"yǎnli","hanViet":"NHÃN LÝ","meaning":"trong mắt","pos":"Danh từ","example":{"zh":"他的眼里有希望。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"眼","py":"yǎn"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"希","py":"xī"},{"c":"望","py":"wàng"},{"c":"。","py":"。"}],"vi":"Trong mắt anh ấy có hy vọng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-21', 20, 'Nhà cửa & đồ vật (1)', '[{"hanzi":"安","pinyin":"ān","hanViet":"AN","meaning":"yên bình","pos":"Tính từ","example":{"zh":"这里很安静。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"安","py":"ān"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Đây rất yên bình."}},{"hanzi":"冰箱","pinyin":"bīngxiāng","hanViet":"BĂNG RƯƠNG","meaning":"tủ lạnh","pos":"Danh từ","example":{"zh":"我把水果放进冰箱。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"把","py":"bǎ"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"放","py":"fàng"},{"c":"进","py":"jìn"},{"c":"冰","py":"bīng"},{"c":"箱","py":"xiāng"},{"c":"。","py":"。"}],"vi":"Tôi để trái cây vào tủ lạnh."}},{"hanzi":"操场","pinyin":"cāochǎng","hanViet":"THAO TRƯỜNG","meaning":"sân vận động","pos":"Danh từ","example":{"zh":"学生们在操场上跑步。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"操","py":"cāo"},{"c":"场","py":"chǎng"},{"c":"上","py":"shàng"},{"c":"跑","py":"pǎo"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Học sinh đang chạy bộ trên sân vận động."}},{"hanzi":"唱片","pinyin":"chàngpiàn","hanViet":"XƯỚNG PHIẾN","meaning":"đĩa nhạc, bản ghi âm","pos":"Danh từ","example":{"zh":"她买了一张唱片。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"买","py":"mǎi"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"唱","py":"chàng"},{"c":"片","py":"piàn"},{"c":"。","py":"。"}],"vi":"Cô ấy mua một đĩa nhạc."}},{"hanzi":"沉","pinyin":"chén","hanViet":"TRẦM","meaning":"nặng, chìm, chậm","pos":"Tính từ","example":{"zh":"石头很沉。","pinyinPerChar":[{"c":"石","py":"shí"},{"c":"头","py":"tóu"},{"c":"很","py":"hěn"},{"c":"沉","py":"chén"},{"c":"。","py":"。"}],"vi":"Đá nặng lắm."}},{"hanzi":"沉重","pinyin":"chénzhòng","hanViet":"TRẦM TRỌNG","meaning":"nặng nề, nặng","pos":"Tính từ","example":{"zh":"这件衣服很沉重。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"很","py":"hěn"},{"c":"沉","py":"chén"},{"c":"重","py":"zhòng"},{"c":"。","py":"。"}],"vi":"Quần áo này rất nặng."}},{"hanzi":"出口","pinyin":"chūkǒu","hanViet":"XUẤT KHẨU","meaning":"lối ra, cửa ra","pos":"Danh từ","example":{"zh":"请从这个出口走。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"从","py":"cóng"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"出","py":"chū"},{"c":"口","py":"kǒu"},{"c":"走","py":"zǒu"},{"c":"。","py":"。"}],"vi":"Xin đi qua lối ra này."}},{"hanzi":"窗户","pinyin":"chuānghu","hanViet":"SONG HỘ","meaning":"cửa sổ","pos":"Danh từ","example":{"zh":"窗户开着。","pinyinPerChar":[{"c":"窗","py":"chuāng"},{"c":"户","py":"hù"},{"c":"开","py":"kāi"},{"c":"着","py":"zhe"},{"c":"。","py":"。"}],"vi":"Cửa sổ đang mở."}},{"hanzi":"窗台","pinyin":"chuāngtái","hanViet":"SONG ĐÀI","meaning":"sàn cửa sổ","pos":"Danh từ","example":{"zh":"书放在窗台上。","pinyinPerChar":[{"c":"书","py":"shū"},{"c":"放","py":"fàng"},{"c":"在","py":"zài"},{"c":"窗","py":"chuāng"},{"c":"台","py":"tái"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Sách đặt trên sàn cửa sổ."}},{"hanzi":"窗子","pinyin":"chuāngzi","hanViet":"SONG TỬ","meaning":"cửa sổ","pos":"Danh từ","example":{"zh":"窗子很大。","pinyinPerChar":[{"c":"窗","py":"chuāng"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Cửa sổ rất lớn."}},{"hanzi":"大规模","pinyin":"dà guīmó","hanViet":"ĐẠI QUY MÔ","meaning":"mức lớn, quy mô lớn","pos":"Danh từ","example":{"zh":"这次活动规模很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"规","py":"guī"},{"c":"模","py":"mó"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Hoạt động này có quy mô rất lớn."}},{"hanzi":"大楼","pinyin":"dà lóu","hanViet":"ĐẠI LÂU","meaning":"tòa nhà cao, tòa nhà","pos":"Danh từ","example":{"zh":"这栋大楼很高。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"栋","py":"dòng"},{"c":"大","py":"dà"},{"c":"楼","py":"lóu"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Tòa nhà cao này rất cao."}},{"hanzi":"大型","pinyin":"dàxíng","hanViet":"ĐẠI HÌNH","meaning":"có quy mô lớn, lớn","pos":"Tính từ","example":{"zh":"这是一场大型演出。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"场","py":"chǎng"},{"c":"大","py":"dà"},{"c":"型","py":"xíng"},{"c":"演","py":"yǎn"},{"c":"出","py":"chū"},{"c":"。","py":"。"}],"vi":"Đây là một buổi biểu diễn quy mô lớn."}},{"hanzi":"袋","pinyin":"dài","hanViet":"ĐẠI","meaning":"túi","pos":"Danh từ","example":{"zh":"我买了一个袋子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"买","py":"mǎi"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"袋","py":"dài"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi mua một cái túi."}},{"hanzi":"电灯","pinyin":"diàndēng","hanViet":"ĐIỆN ĐĂNG","meaning":"đèn điện","pos":"Danh từ","example":{"zh":"房间里有很多电灯。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"电","py":"diàn"},{"c":"灯","py":"dēng"},{"c":"。","py":"。"}],"vi":"Phòng có nhiều đèn điện."}},{"hanzi":"电梯","pinyin":"diàntī","hanViet":"ĐIỆN THÊ","meaning":"thang máy","pos":"Danh từ","example":{"zh":"请上电梯。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"上","py":"shàng"},{"c":"电","py":"diàn"},{"c":"梯","py":"tī"},{"c":"。","py":"。"}],"vi":"Hãy lên thang máy."}},{"hanzi":"盖","pinyin":"gài","hanViet":"CÁI","meaning":"mái nhà, che phủ","pos":"Danh từ","example":{"zh":"这座房子的盖子很新。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"的","py":"de"},{"c":"盖","py":"gài"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"新","py":"xīn"},{"c":"。","py":"。"}],"vi":"Mái nhà nhà này rất mới."}},{"hanzi":"户","pinyin":"hù","hanViet":"HỘ","meaning":"cửa, nhà, đơn vị","pos":"Danh từ","example":{"zh":"这间屋子有两扇门。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"间","py":"jiān"},{"c":"屋","py":"wū"},{"c":"子","py":"zi"},{"c":"有","py":"yǒu"},{"c":"两","py":"liǎng"},{"c":"扇","py":