INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-22', 21, 'Nhà cửa & đồ vật (2)', '[{"hanzi":"宁静","pinyin":"níngjìng","hanViet":"NINH TĨNH","meaning":"yên bình, tĩnh lặng","pos":"Tính từ","example":{"zh":"房间里很宁静。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"宁","py":"níng"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Phòng này rất yên bình."}},{"hanzi":"暖气","pinyin":"nuǎnqì","hanViet":"NOÃN KHÍ","meaning":"lò sưởi, hệ thống sưởi ấm","pos":"Danh từ","example":{"zh":"冬天要开暖气。","pinyinPerChar":[{"c":"冬","py":"dōng"},{"c":"天","py":"tiān"},{"c":"要","py":"yào"},{"c":"开","py":"kāi"},{"c":"暖","py":"nuǎn"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Vào mùa đông cần bật lò sưởi."}},{"hanzi":"盘子","pinyin":"pánzi","hanViet":"BÀN TỬ","meaning":"đĩa","pos":"Danh từ","example":{"zh":"我用盘子盛饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"盘","py":"pán"},{"c":"子","py":"zi"},{"c":"盛","py":"shèng"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi dùng đĩa để đựng cơm."}},{"hanzi":"批","pinyin":"pī","hanViet":"PHÊ","meaning":"lô, lô hàng, phê bình","pos":"Danh từ","example":{"zh":"老师批评学生。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"批","py":"pī"},{"c":"评","py":"píng"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Giáo viên phê bình học sinh."}},{"hanzi":"平静","pinyin":"píngjìng","hanViet":"BÌNH TĨNH","meaning":"yên bình, tĩnh lặng","pos":"Tính từ","example":{"zh":"湖面很平静。","pinyinPerChar":[{"c":"湖","py":"hú"},{"c":"面","py":"miàn"},{"c":"很","py":"hěn"},{"c":"平","py":"píng"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Sông hồ rất yên bình."}},{"hanzi":"巧克力","pinyin":"qiǎokèlì","hanViet":"XẢO KHẮC LỰC","meaning":"sô cô la","pos":"Danh từ","example":{"zh":"我喜欢吃巧克力。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"巧","py":"qiǎo"},{"c":"克","py":"kè"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn sô cô la."}},{"hanzi":"轻松","pinyin":"qīngsōng","hanViet":"KHINH TÙNG","meaning":"nhẹ nhàng, thoải mái","pos":"Tính từ","example":{"zh":"今天天气很轻松。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"轻","py":"qīng"},{"c":"松","py":"sōng"},{"c":"。","py":"。"}],"vi":"Hôm nay thời tiết rất thoải mái."}},{"hanzi":"人家","pinyin":"rénjia","hanViet":"NHÂN GIA","meaning":"người đó, nhà đó, ai đó","pos":"Đại từ","example":{"zh":"人家的房子很干净。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"家","py":"jiā"},{"c":"的","py":"de"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"干","py":"gàn"},{"c":"净","py":"jìng"},{"c":"。","py":"。"}],"vi":"Nhà người đó rất sạch sẽ."}},{"hanzi":"伞","pinyin":"sǎn","hanViet":"TẢN","meaning":"giấy, ô","pos":"Danh từ","example":{"zh":"下雨了，我拿伞。","pinyinPerChar":[{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"了","py":"le"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"拿","py":"ná"},{"c":"伞","py":"sǎn"},{"c":"。","py":"。"}],"vi":"Đang mưa, tôi lấy ô."}},{"hanzi":"上门","pinyin":"shàngmén","hanViet":"THƯỢNG MÔN","meaning":"đến nhà, đến ủi nhà","pos":"Động từ","example":{"zh":"他上门来找我。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"上","py":"shàng"},{"c":"门","py":"mén"},{"c":"来","py":"lái"},{"c":"找","py":"zhǎo"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Anh ta đến nhà để gặp tôi."}},{"hanzi":"诗人","pinyin":"shīrén","hanViet":"THI NHÂN","meaning":"nhà thơ","pos":"Danh từ","example":{"zh":"她是著名的诗人。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"著","py":"zhù"},{"c":"名","py":"míng"},{"c":"的","py":"de"},{"c":"诗","py":"shī"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Cô ấy là nhà thơ nổi tiếng."}},{"hanzi":"塑料袋","pinyin":"sùliàodài","hanViet":"TỐ LIỆU ĐẠI","meaning":"giấy nilon, túi nhựa","pos":"Danh từ","example":{"zh":"我用塑料袋装东西。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"塑","py":"sù"},{"c":"料","py":"liào"},{"c":"袋","py":"dài"},{"c":"装","py":"zhuāng"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"。","py":"。"}],"vi":"Tôi dùng túi nhựa để đựng đồ."}},{"hanzi":"台阶","pinyin":"táijiē","hanViet":"ĐÀI GIAI","meaning":"bậc thang","pos":"Danh từ","example":{"zh":"楼前有台阶。","pinyinPerChar":[{"c":"楼","py":"lóu"},{"c":"前","py":"qián"},{"c":"有","py":"yǒu"},{"c":"台","py":"tái"},{"c":"阶","py":"jiē"},{"c":"。","py":"。"}],"vi":"Trước nhà có bậc thang."}},{"hanzi":"台上","pinyin":"táishàng","hanViet":"ĐÀI THƯỢNG","meaning":"trên sàn ghế, trên đài","pos":"Danh từ","example":{"zh":"老师在台上讲话。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"在","py":"zài"},{"c":"台","py":"tái"},{"c":"上","py":"shàng"},{"c":"讲","py":"jiǎng"},{"c":"话","py":"huà"},{"c":"。","py":"。"}],"vi":"Giáo viên đang giảng bài trên sàn."}},{"hanzi":"王","pinyin":"wáng","hanViet":"VƯƠNG","meaning":"vua, nhà vua, tên người","pos":"Danh từ","example":{"zh":"他叫王明。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"叫","py":"jiào"},{"c":"王","py":"wáng"},{"c":"明","py":"míng"},{"c":"。","py":"。"}],"vi":"Anh ấy tên là Vương Minh."}},{"hanzi":"系统","pinyin":"xìtǒng","hanViet":"HỆ THỐNG","meaning":"hệ thống, hệ thống máy tính","pos":"Danh từ","example":{"zh":"这个系统很好用。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"系","py":"xì"},{"c":"统","py":"tǒng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Hệ thống này rất dễ sử dụng."}},{"hanzi":"形容","pinyin":"xíngróng","hanViet":"HÌNH DUNG","meaning":"mô tả, miêu tả","pos":"Động từ","example":{"zh":"请形容一下你的房子。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"形","py":"xíng"},{"c":"容","py":"róng"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Hãy mô tả nhà của bạn."}},{"hanzi":"牙刷","pinyin":"yáshuā","hanViet":"NHA XOÁT","meaning":"bàn chải, bàn chải răng","pos":"Danh từ","example":{"zh":"我每天早上用牙刷刷牙。","pinyinPerCh