INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-23', 22, 'Quần áo & màu sắc', '[{"hanzi":"薄","pinyin":"báo","hanViet":"BẠC","meaning":"mỏng, kém, hèn nhát","pos":"Tính từ","example":{"zh":"这件衣服很薄。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"很","py":"hěn"},{"c":"薄","py":"báo"},{"c":"。","py":"。"}],"vi":"Quần áo này rất mỏng."}},{"hanzi":"穿上","pinyin":"chuānshang","hanViet":"XUYÊN THƯỢNG","meaning":"mặc lên","pos":"Động từ","example":{"zh":"她穿上外套。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"穿","py":"chuān"},{"c":"上","py":"shàng"},{"c":"外","py":"wài"},{"c":"套","py":"tào"},{"c":"。","py":"。"}],"vi":"Cô ấy mặc áo khoác lên."}},{"hanzi":"独特","pinyin":"dútè","hanViet":"ĐỘC ĐẶC","meaning":"đặc biệt, độc đáo","pos":"Tính từ","example":{"zh":"这本书有独特的风格。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"有","py":"yǒu"},{"c":"独","py":"dú"},{"c":"特","py":"tè"},{"c":"的","py":"de"},{"c":"风","py":"fēng"},{"c":"格","py":"gé"},{"c":"。","py":"。"}],"vi":"Cuốn sách này có phong cách độc đáo."}},{"hanzi":"毫米","pinyin":"háomǐ","hanViet":"HÀO MỄ","meaning":"milimét","pos":"Lượng từ","example":{"zh":"这支笔长一毫米。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"支","py":"zhī"},{"c":"笔","py":"bǐ"},{"c":"长","py":"zhǎng"},{"c":"一","py":"yī"},{"c":"毫","py":"háo"},{"c":"米","py":"mǐ"},{"c":"。","py":"。"}],"vi":"Cây bút này dài một milimét."}},{"hanzi":"毫升","pinyin":"háoshēng","hanViet":"HÀO THĂNG","meaning":"mililit","pos":"Lượng từ","example":{"zh":"这杯水有一毫升。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"杯","py":"bēi"},{"c":"水","py":"shuǐ"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"毫","py":"háo"},{"c":"升","py":"shēng"},{"c":"。","py":"。"}],"vi":"Cốc nước này có một mililit."}},{"hanzi":"黄金","pinyin":"huángjīn","hanViet":"HOÀNG KIM","meaning":"vàng, vàng bạc","pos":"Danh từ","example":{"zh":"黄金很贵。","pinyinPerChar":[{"c":"黄","py":"huáng"},{"c":"金","py":"jīn"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Vàng rất đắt."}},{"hanzi":"轮","pinyin":"lún","hanViet":"LUÂN","meaning":"Vòng, vòng tròn, quay","pos":"Danh từ","example":{"zh":"这是一个轮子。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"轮","py":"lún"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Đây là một bánh xe."}},{"hanzi":"毛巾","pinyin":"máojīn","hanViet":"MAO CÂN","meaning":"miếng vải lau mặt","pos":"Danh từ","example":{"zh":"他用毛巾擦了擦手。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"用","py":"yòng"},{"c":"毛","py":"máo"},{"c":"巾","py":"jīn"},{"c":"擦","py":"cā"},{"c":"了","py":"le"},{"c":"擦","py":"cā"},{"c":"手","py":"shǒu"},{"c":"。","py":"。"}],"vi":"Anh ấy dùng khăn giấy lau tay."}},{"hanzi":"帽子","pinyin":"màozi","hanViet":"MẠO TỬ","meaning":"mũ","pos":"Danh từ","example":{"zh":"她戴了一顶帽子。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"戴","py":"dài"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"顶","py":"dǐng"},{"c":"帽","py":"mào"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Cô ấy mặc một chiếc mũ."}},{"hanzi":"闹","pinyin":"nào","hanViet":"NÁO","meaning":"náo, ồn ào, gây rối","pos":"Động từ","example":{"zh":"别在这里闹。","pinyinPerChar":[{"c":"别","py":"bié"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"闹","py":"nào"},{"c":"。","py":"。"}],"vi":"Đừng ồn ào ở đây."}},{"hanzi":"闹钟","pinyin":"nàozhōng","hanViet":"NÁO CHUNG","meaning":"đồng hồ báo thức","pos":"Danh từ","example":{"zh":"闹钟响了。","pinyinPerChar":[{"c":"闹","py":"nào"},{"c":"钟","py":"zhōng"},{"c":"响","py":"xiǎng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Đồng hồ báo thức reo."}},{"hanzi":"圈","pinyin":"quān","hanViet":"KHUYÊN","meaning":"vòng, khu vực, nhóm","pos":"Danh từ","example":{"zh":"他在圈里。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"圈","py":"quān"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy ở trong vòng."}},{"hanzi":"色","pinyin":"sè","hanViet":"SẮC","meaning":"màu sắc","pos":"Tính từ","example":{"zh":"这件衣服颜色很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"颜","py":"yán"},{"c":"色","py":"sè"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Cái áo này màu rất đẹp."}},{"hanzi":"色彩","pinyin":"sècǎi","hanViet":"SẮC THÁI","meaning":"màu, sắc","pos":"Danh từ","example":{"zh":"春天的色彩很美。","pinyinPerChar":[{"c":"春","py":"chūn"},{"c":"天","py":"tiān"},{"c":"的","py":"de"},{"c":"色","py":"sè"},{"c":"彩","py":"cǎi"},{"c":"很","py":"hěn"},{"c":"美","py":"měi"},{"c":"。","py":"。"}],"vi":"Màu sắc mùa xuân rất đẹp."}},{"hanzi":"脱","pinyin":"tuō","hanViet":"THOÁT","meaning":"tháo, bỏ, ra khỏi","pos":"Động từ","example":{"zh":"他脱下了外套。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"脱","py":"tuō"},{"c":"下","py":"xià"},{"c":"了","py":"le"},{"c":"外","py":"wài"},{"c":"套","py":"tào"},{"c":"。","py":"。"}],"vi":"Anh ấy tháo ra chiếc áo khoác."}},{"hanzi":"袜子","pinyin":"wàzi","hanViet":"VẠT TỬ","meaning":"quần áo dép, vớ","pos":"Danh từ","example":{"zh":"我穿了两双袜子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"穿","py":"chuān"},{"c":"了","py":"le"},{"c":"两","py":"liǎng"},{"c":"双","py":"shuāng"},{"c":"袜","py":"wà"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi mặc hai đôi vớ."}},{"hanzi":"外套","pinyin":"wàitào","hanViet":"NGOẠI SÁO","meaning":"áo khoác bên ngoài","pos":"Danh từ","example":{"zh":"他穿了一件黑色外套。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"穿","py":"chuān"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"件","py":"jiàn"},{"c":"黑","py":"hēi"},{"c":"色","py":"sè"},{"c":"外","py":"wài"},{"c":"套","py":"tào"},{"c":"。","py":"。"}],"vi":"Anh ấy mặc một chiếc áo khoác đen."}},{"hanzi":"五颜六色","pinyin":"wǔyán-liùsè","hanViet":"NGŨ NHAN LỤC SẮC","meaning":"có nhiều màu sắc","pos":"Cụm từ","example":{"zh":"花园里五颜六色。","pinyinPerChar":[{"c":"花","py":"huā"},{"c":"园","py":"yuán"},{"c":"里","py":"lǐ"},{"c":"五","py":"wǔ"},{"c":"颜","py":"yán"},{"c":"六","py":"liù"},{"c":"色","py":"sè"},{"c":"。","py":"。"}],"vi":"Vườn hoa có nhiều màu sắc."}},{"hanzi":"摇","pinyin":"yáo","hanViet":"DAO","meaning":"lắc, rung","pos":"Động từ","example":{"zh":"他摇着头。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"摇","py":"yáo"},{"c":"着","py":"zhe"},{"c":"头","py":"tóu"},{"c":"。","py":"。"}],"vi":"Anh ấy lắc đầu."}},{"hanzi":"圆","pinyin":"yuán","hanViet":"VIÊN","meaning":"tròn, vòng","pos":"Tính từ","example":{"zh":"这个月亮很圆。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"月","py":"yuè"},{"c":"亮","py":"liàng"},{"c":"很","py":"hěn"},{"c":"圆","py":"yuán"},{"c":"。","py":"。"}],"vi":"Mặt trăng rất tròn."}},{"hanzi":"着","pinyin":"zháo","hanViet":"TRỨ","meaning":"trạng thái, đang","pos":"Động từ","example":{"zh":"他着火了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"着","py":"zhe"},{"c":"火","py":"huǒ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cô ấy bị đỏ lửa."}},{"hanzi":"总共","pinyin":"zǒnggòng","hanViet":"TỔNG CỘNG","meaning":"tổng cộng, tất cả","pos":"Tính từ","example":{"zh":"总共三个人。","pinyinPerChar":[{"c":"总","py":"zǒng"},{"c":"共","py":"gòng"},{"c":"三","py":"sān"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Tổng cộng ba người."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-24', 23, 'Giao tiếp & lời nói', '[{"hanzi":"暗示","pinyin":"ànshì","hanViet":"ÁM THỊ","meaning":"gợi ý, ám chỉ","pos":"Danh từ","example":{"zh":"他用眼神暗示我。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"用","py":"yòng"},{"c":"眼","py":"yǎn"},{"c":"神","py":"shén"},{"c":"暗","py":"àn"},{"c":"示","py":"shì"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Anh ta dùng ánh mắt gợi ý cho tôi."}},{"hanzi":"包括","pinyin":"bāokuò","hanViet":"BAO QUÁT","meaning":"có chứa, bao gồm","pos":"Động từ","example":{"zh":"这本书包括很多故事。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"包","py":"bāo"},{"c":"括","py":"kuò"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"故","py":"gù"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Sách này có chứa nhiều câu chuyện."}},{"hanzi":"避","pinyin":"bì","hanViet":"TỊ","meaning":"tránh, tránh khỏi","pos":"Động từ","example":{"zh":"他避开了麻烦。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"避","py":"bì"},{"c":"开","py":"kāi"},{"c":"了","py":"le"},{"c":"麻","py":"má"},{"c":"烦","py":"fán"},{"c":"。","py":"。"}],"vi":"Anh ấy tránh khỏi sự cố."}},{"hanzi":"辩论","pinyin":"biànlùn","hanViet":"BIỆN LUẬN","meaning":"thảo luận, tranh luận","pos":"Danh từ","example":{"zh":"他们在辩论问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"辩","py":"biàn"},{"c":"论","py":"lùn"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Họ đang tranh luận về vấn đề."}},{"hanzi":"表扬","pinyin":"biǎoyáng","hanViet":"BIỂU DƯƠNG","meaning":"khen ngợi","pos":"Động từ","example":{"zh":"老师表扬了学生。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"表","py":"biǎo"},{"c":"扬","py":"yáng"},{"c":"了","py":"le"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Giáo viên đã khen học sinh."}},{"hanzi":"不管","pinyin":"bùguǎn","hanViet":"BẤT QUẢN","meaning":"dù, bất kể","pos":"Liên từ","example":{"zh":"不管天气怎么样，我们去。","pinyinPerChar":[{"c":"不","py":"bù"},{"c":"管","py":"guǎn"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"样","py":"yàng"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Dù thời tiết thế nào, chúng ta đi."}},{"hanzi":"称赞","pinyin":"chēngzàn","hanViet":"XƯNG TÁN","meaning":"khen ngợi","pos":"Động từ","example":{"zh":"老师称赞了我。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"称","py":"chēng"},{"c":"赞","py":"zàn"},{"c":"了","py":"le"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Thầy cô khen tôi."}},{"hanzi":"尺寸","pinyin":"chǐcùn","hanViet":"THƯỚC THỐN","meaning":"kích thước","pos":"Danh từ","example":{"zh":"请告诉我尺寸。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"告","py":"gào"},{"c":"诉","py":"sù"},{"c":"我","py":"wǒ"},{"c":"尺","py":"chǐ"},{"c":"寸","py":"cùn"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi biết kích thước."}},{"hanzi":"尺子","pinyin":"chǐzi","hanViet":"THƯỚC TỬ","meaning":"thước kính","pos":"Danh từ","example":{"zh":"我的尺子在哪里？","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"尺","py":"chǐ"},{"c":"子","py":"zi"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Thước kính của tôi ở đâu?"}},{"hanzi":"答案","pinyin":"dá''àn","hanViet":"ĐÁP ÁN","meaning":"đáp án, câu trả lời","pos":"Danh từ","example":{"zh":"请给我答案。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"答","py":"dá"},{"c":"案","py":"àn"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi câu trả lời."}},{"hanzi":"翻","pinyin":"fān","hanViet":"PHIÊN","meaning":"Lật, lặp lại, dịch","pos":"Động từ","example":{"zh":"翻开书看看。","pinyinPerChar":[{"c":"翻","py":"fān"},{"c":"开","py":"kāi"},{"c":"书","py":"shū"},{"c":"看","py":"kàn"},{"c":"看","py":"kàn"},{"c":"。","py":"。"}],"vi":"Lật mở sách xem xem."}},{"hanzi":"翻译","pinyin":"fānyì","hanViet":"PHIÊN DỊCH","meaning":"Chuyển đổi ngôn ngữ từ một ngôn ngữ sang ngôn ngữ khác","pos":"Danh từ","example":{"zh":"他会翻译中文。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"会","py":"huì"},{"c":"翻","py":"fān"},{"c":"译","py":"yì"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"。","py":"。"}],"vi":"Cô ấy biết dịch tiếng Trung."}},{"hanzi":"符合","pinyin":"fúhé","hanViet":"PHÙ HỢP","meaning":"đồng ý, khớp","pos":"Động từ","example":{"zh":"这符合事实。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"符","py":"fú"},{"c":"合","py":"hé"},{"c":"事","py":"shì"},{"c":"实","py":"shí"},{"c":"。","py":"。"}],"vi":"Điều này khớp với sự thật."}},{"hanzi":"高尚","pinyin":"gāoshàng","hanViet":"CAO THƯỢNG","meaning":"cao thượng, cao đẹp","pos":"Tính từ","example":{"zh":"她的行为非常高尚。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"行","py":"xíng"},{"c":"为","py":"wèi"},{"c":"非","py":"fēi"},{"c":"常","py":"cháng"},{"c":"高","py":"gāo"},{"c":"尚","py":"shàng"},{"c":"。","py":"。"}],"vi":"Hành vi của cô ấy rất cao thượng."}},{"hanzi":"怪","pinyin":"guài","hanViet":"QUÁI","meaning":"bất thường, lạ","pos":"Tính từ","example":{"zh":"这个问题有点怪。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"怪","py":"guài"},{"c":"。","py":"。"}],"vi":"Câu hỏi này hơi lạ."}},{"hanzi":"规模","pinyin":"guīmó","hanViet":"QUY MÔ","meaning":"quy mô, kích thước","pos":"Danh từ","example":{"zh":"公司规模很大。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"规","py":"guī"},{"c":"模","py":"mó"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Công ty quy mô rất lớn."}},{"hanzi":"含","pinyin":"hán","hanViet":"HÀM","meaning":"có, chứa","pos":"Động từ","example":{"zh":"这杯水含糖。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"杯","py":"bēi"},{"c":"水","py":"shuǐ"},{"c":"含","py":"hán"},{"c":"糖","py":"táng"},{"c":"。","py":"。"}],"vi":"Cốc nước này có đường."}},{"hanzi":"含量","pinyin":"hánliàng","hanViet":"HÀM LƯỢNG","meaning":"tỷ lệ chứa","pos":"Danh từ","example":{"zh":"这杯咖啡含量咖啡很高。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"杯","py":"bēi"},{"c":"咖","py":"kā"},{"c":"啡","py":"fēi"},{"c":"含","py":"hán"},{"c":"量","py":"liàng"},{"c":"咖","py":"kā"},{"c":"啡","py":"fēi"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Cốc cà phê này có hàm lượng cà phê cao."}},{"hanzi":"解释","pinyin":"jiěshì","hanViet":"GIẢI THÍCH","meaning":"giải thích","pos":"Động từ","example":{"zh":"请解释这个词的意思。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"解","py":"jiě"},{"c":"释","py":"shì"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"词","py":"cí"},{"c":"的","py":"de"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Xin giải thích nghĩa của từ này."}},{"hanzi":"口语","pinyin":"kǒuyǔ","hanViet":"KHẨU NGỮ","meaning":"ngôn ngữ nói, nói chuyện","pos":"Danh từ","example":{"zh":"他说的口语很自然。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"的","py":"de"},{"c":"口","py":"kǒu"},{"c":"语","py":"yǔ"},{"c":"很","py":"hěn"},{"c":"自","py":"zì"},{"c":"然","py":"rán"},{"c":"。","py":"。"}],"vi":"Ngôn ngữ nói của anh ấy rất tự nhiên."}},{"hanzi":"俩","pinyin":"liǎ","hanViet":"LƯỠNG","meaning":"hai người (thường dùng với từ chỉ người)","pos":"Đại từ","example":{"zh":"我们俩是朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"俩","py":"liǎ"},{"c":"是","py":"shì"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Hai người chúng tôi là bạn."}},{"hanzi":"名牌儿","pinyin":"míngpáir","hanViet":"DANH BÀI NHI","meaning":"hàng nổi tiếng, đồ thời thượng","pos":"Danh từ","example":{"zh":"这件衣服是名牌儿。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"是","py":"shì"},{"c":"名","py":"míng"},{"c":"牌","py":"pái"},{"c":"儿","py":"ér"},{"c":"。","py":"。"}],"vi":"Cái áo này là đồ thời thượng."}},{"hanzi":"赏","pinyin":"shǎng","hanViet":"THƯỞNG","meaning":"khen, thưởng, ngắm","pos":"Động từ","example":{"zh":"大家赏花。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"赏","py":"shǎng"},{"c":"花","py":"huā"},{"c":"。","py":"。"}],"vi":"Cả người đều ngắm hoa."}},{"hanzi":"申请","pinyin":"shēnqǐng","hanViet":"THÂN THỈNH","meaning":"nộp đơn xin, đề nghị","pos":"Động từ","example":{"zh":"他申请了这份工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"申","py":"shēn"},{"c":"请","py":"qǐng"},{"c":"了","py":"le"},{"c":"这","py":"zhè"},{"c":"份","py":"fèn"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ta đã nộp đơn xin công việc này."}},{"hanzi":"说服","pinyin":"shuōfú","hanViet":"THUYẾT PHỤC","meaning":"thuyết phục, thuyết phục","pos":"Động từ","example":{"zh":"他说服我去参加活动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"服","py":"fú"},{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Cậu ấy thuyết phục tôi tham gia sự kiện."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-25', 24, 'Suy nghĩ & ý kiến', '[{"hanzi":"表情","pinyin":"biǎoqíng","hanViet":"BIỂU TÌNH","meaning":"nghĩa mặt, biểu hiện","pos":"Danh từ","example":{"zh":"她的表情很开心。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"表","py":"biǎo"},{"c":"情","py":"qíng"},{"c":"很","py":"hěn"},{"c":"开","py":"kāi"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Mặt nạ của cô ấy rất vui vẻ."}},{"hanzi":"措施","pinyin":"cuòshī","hanViet":"THỐ THI","meaning":"biện pháp, giải pháp","pos":"Danh từ","example":{"zh":"政府采取了新措施。","pinyinPerChar":[{"c":"政","py":"zhèng"},{"c":"府","py":"fǔ"},{"c":"采","py":"cǎi"},{"c":"取","py":"qǔ"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"措","py":"cuò"},{"c":"施","py":"shī"},{"c":"。","py":"。"}],"vi":"Chính phủ đã áp dụng biện pháp mới."}},{"hanzi":"对比","pinyin":"duìbǐ","hanViet":"ĐỐI TỶ","meaning":"so sánh, đối chiếu","pos":"Danh từ","example":{"zh":"我们用对比来看两件事。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"用","py":"yòng"},{"c":"对","py":"duì"},{"c":"比","py":"bǐ"},{"c":"来","py":"lái"},{"c":"看","py":"kàn"},{"c":"两","py":"liǎng"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Chúng tôi dùng phương pháp so sánh để xem xét hai việc."}},{"hanzi":"格外","pinyin":"géwài","hanViet":"CÁCH NGOẠI","meaning":"đặc biệt, hơn cả","pos":"Phó từ","example":{"zh":"今天天气格外冷。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"格","py":"gé"},{"c":"外","py":"wài"},{"c":"冷","py":"lěng"},{"c":"。","py":"。"}],"vi":"Thời tiết hôm nay đặc biệt lạnh."}},{"hanzi":"含义","pinyin":"hányì","hanViet":"HÀM NGHĨA","meaning":"ý nghĩa","pos":"Danh từ","example":{"zh":"这个词含义很深。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"词","py":"cí"},{"c":"含","py":"hán"},{"c":"义","py":"yì"},{"c":"很","py":"hěn"},{"c":"深","py":"shēn"},{"c":"。","py":"。"}],"vi":"Từ này có nghĩa rất sâu."}},{"hanzi":"怀念","pinyin":"huáiniàn","hanViet":"HOÀI NIỆM","meaning":"niệm nhớ, nhớ lại","pos":"Động từ","example":{"zh":"我怀念过去的日子。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"怀","py":"huái"},{"c":"念","py":"niàn"},{"c":"过","py":"guò"},{"c":"去","py":"qù"},{"c":"的","py":"de"},{"c":"日","py":"rì"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Tôi nhớ lại những ngày xưa."}},{"hanzi":"怀疑","pinyin":"huáiyí","hanViet":"HOÀI NGHI","meaning":"bất tin, nghi ngờ","pos":"Động từ","example":{"zh":"我怀疑他说的是真的。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"怀","py":"huái"},{"c":"疑","py":"yí"},{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"的","py":"de"},{"c":"是","py":"shì"},{"c":"真","py":"zhēn"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Tôi nghi ngờ anh ta nói điều thật."}},{"hanzi":"获得","pinyin":"huòdé","hanViet":"HOẠCH ĐẮC","meaning":"đạt được, thu được","pos":"Động từ","example":{"zh":"她获得了成功。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"获","py":"huò"},{"c":"得","py":"dé"},{"c":"了","py":"le"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Cô ấy đạt được thành công."}},{"hanzi":"坚固","pinyin":"jiāngù","hanViet":"KIÊN CỐ","meaning":"chắc chắn, bền vững","pos":"Tính từ","example":{"zh":"这座桥很坚固。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"桥","py":"qiáo"},{"c":"很","py":"hěn"},{"c":"坚","py":"jiān"},{"c":"固","py":"gù"},{"c":"。","py":"。"}],"vi":"Cầu này rất chắc chắn."}},{"hanzi":"可见","pinyin":"kějiàn","hanViet":"KHẢ KIẾN","meaning":"có thể thấy, rõ ràng","pos":"Tính từ","example":{"zh":"可见的证据。","pinyinPerChar":[{"c":"可","py":"kě"},{"c":"见","py":"jiàn"},{"c":"的","py":"de"},{"c":"证","py":"zhèng"},{"c":"据","py":"jù"},{"c":"。","py":"。"}],"vi":"Bằng chứng rõ ràng."}},{"hanzi":"梦","pinyin":"mèng","hanViet":"MỘNG","meaning":"giấc mơ, ước mơ","pos":"Danh từ","example":{"zh":"他有一个美梦。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"美","py":"měi"},{"c":"梦","py":"mèng"},{"c":"。","py":"。"}],"vi":"Anh ấy có một giấc mơ đẹp."}},{"hanzi":"思考","pinyin":"sīkǎo","hanViet":"TƯ KHẢO","meaning":"suy nghĩ, phân tích","pos":"Động từ","example":{"zh":"他每天思考问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"思","py":"sī"},{"c":"考","py":"kǎo"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Anh ấy suy nghĩ về vấn đề mỗi ngày."}},{"hanzi":"特殊","pinyin":"tèshū","hanViet":"ĐẶC THÙ","meaning":"đặc biệt, riêng","pos":"Tính từ","example":{"zh":"这个节日很特殊。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"节","py":"jié"},{"c":"日","py":"rì"},{"c":"很","py":"hěn"},{"c":"特","py":"tè"},{"c":"殊","py":"shū"},{"c":"。","py":"。"}],"vi":"Ngày lễ này rất đặc biệt."}},{"hanzi":"透","pinyin":"tòu","hanViet":"THẤU","meaning":"xuyên qua, rõ ràng","pos":"Tính từ","example":{"zh":"窗户很透，光线很好。","pinyinPerChar":[{"c":"窗","py":"chuāng"},{"c":"户","py":"hù"},{"c":"很","py":"hěn"},{"c":"透","py":"tòu"},{"c":"，","py":"，"},{"c":"光","py":"guāng"},{"c":"线","py":"xiàn"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cửa sổ rất trong suốt, ánh sáng rất tốt."}},{"hanzi":"想念","pinyin":"xiǎngniàn","hanViet":"TƯỞNG NIỆM","meaning":"muốn nhớ, nhớ nhớ","pos":"Động từ","example":{"zh":"我想念我的家人。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"念","py":"niàn"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"家","py":"jiā"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Tôi nhớ nhớ gia đình của mình."}},{"hanzi":"想象","pinyin":"xiǎngxiàng","hanViet":"TƯỞNG TƯỢNG","meaning":"hình dung, tưởng tượng","pos":"Động từ","example":{"zh":"他喜欢想象未来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"想","py":"xiǎng"},{"c":"象","py":"xiàng"},{"c":"未","py":"wèi"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy thích hình dung tương lai."}},{"hanzi":"疑问","pinyin":"yíwèn","hanViet":"NGHI VẤN","meaning":"bất ngờ, nghi ngờ, thắc mắc","pos":"Danh từ","example":{"zh":"他对这件事有疑问。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"有","py":"yǒu"},{"c":"疑","py":"yí"},{"c":"问","py":"wèn"},{"c":"。","py":"。"}],"vi":"Anh ấy có thắc mắc về việc này."}},{"hanzi":"预测","pinyin":"yùcè","hanViet":"DỰ TRẮC","meaning":"dự đoán","pos":"Động từ","example":{"zh":"科学家预测未来天气。","pinyinPerChar":[{"c":"科","py":"kē"},{"c":"学","py":"xué"},{"c":"家","py":"jiā"},{"c":"预","py":"yù"},{"c":"测","py":"cè"},{"c":"未","py":"wèi"},{"c":"来","py":"lái"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Các nhà khoa học dự đoán thời tiết trong tương lai."}},{"hanzi":"征求","pinyin":"zhēngqiú","hanViet":"TRƯNG CẦU","meaning":"tìm hiểu, mời ý kiến","pos":"Động từ","example":{"zh":"领导征求大家的意见。","pinyinPerChar":[{"c":"领","py":"lǐng"},{"c":"导","py":"dǎo"},{"c":"征","py":"zhēng"},{"c":"求","py":"qiú"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"的","py":"de"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Lãnh đạo đã tìm hiểu ý kiến của mọi người."}},{"hanzi":"自信","pinyin":"zìxìn","hanViet":"TỰ TÍN","meaning":"tin tưởng vào bản thân","pos":"Tính từ","example":{"zh":"她很自信。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"很","py":"hěn"},{"c":"自","py":"zì"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Cô ấy rất tự tin."}},{"hanzi":"综合","pinyin":"zōnghé","hanViet":"TỔNG HỢP","meaning":"tổng hợp, kết hợp","pos":"Tính từ","example":{"zh":"这是一个综合问题。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"综","py":"zōng"},{"c":"合","py":"hé"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Đây là một vấn đề tổng hợp."}},{"hanzi":"做梦","pinyin":"zuòmèng","hanViet":"TỐ MỘNG","meaning":"mơ, ước mơ","pos":"Động từ","example":{"zh":"他做梦了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"做","py":"zuò"},{"c":"梦","py":"mèng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đang mơ."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-26', 25, 'Hành động & vận động (1)', '[{"hanzi":"摆","pinyin":"bǎi","hanViet":"BÀI","meaning":"xếp, đặt","pos":"Động từ","example":{"zh":"请把书摆好。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"书","py":"shū"},{"c":"摆","py":"bǎi"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Hãy xếp sách cho đẹp."}},{"hanzi":"抱","pinyin":"bào","hanViet":"BÃO","meaning":"vỗ, ôm, nắm","pos":"Động từ","example":{"zh":"她抱着孩子。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"抱","py":"bào"},{"c":"着","py":"zhe"},{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Cô ấy ôm em bé."}},{"hanzi":"倍","pinyin":"bèi","hanViet":"BỘI","meaning":"gấp, số lần","pos":"Số từ","example":{"zh":"这本书的价格是原来的两倍。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"的","py":"de"},{"c":"价","py":"jià"},{"c":"格","py":"gé"},{"c":"是","py":"shì"},{"c":"原","py":"yuán"},{"c":"来","py":"lái"},{"c":"的","py":"de"},{"c":"两","py":"liǎng"},{"c":"倍","py":"bèi"},{"c":"。","py":"。"}],"vi":"Giá sách này gấp đôi giá ban đầu."}},{"hanzi":"布置","pinyin":"bùzhì","hanViet":"BỐ TRÍ","meaning":"sắp xếp, trang trí","pos":"Động từ","example":{"zh":"她布置了房间。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"布","py":"bù"},{"c":"置","py":"zhì"},{"c":"了","py":"le"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Cô ấy đã sắp xếp phòng."}},{"hanzi":"操作","pinyin":"cāozuò","hanViet":"THAO TÁC","meaning":"thao tác, điều khiển","pos":"Động từ","example":{"zh":"请小心操作电脑。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"小","py":"xiǎo"},{"c":"心","py":"xīn"},{"c":"操","py":"cāo"},{"c":"作","py":"zuò"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"。","py":"。"}],"vi":"Xin hãy thao tác máy tính cẩn thận."}},{"hanzi":"测","pinyin":"cè","hanViet":"TRẮC","meaning":"đo, kiểm tra","pos":"Động từ","example":{"zh":"测量温度。","pinyinPerChar":[{"c":"测","py":"cè"},{"c":"量","py":"liàng"},{"c":"温","py":"wēn"},{"c":"度","py":"dù"},{"c":"。","py":"。"}],"vi":"Đo nhiệt độ."}},{"hanzi":"测试","pinyin":"cèshì","hanViet":"TRẮC THÍ","meaning":"kiểm tra, thử nghiệm","pos":"Động từ","example":{"zh":"老师测试学生的知识。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"测","py":"cè"},{"c":"试","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"的","py":"de"},{"c":"知","py":"zhī"},{"c":"识","py":"shí"},{"c":"。","py":"。"}],"vi":"Giáo viên kiểm tra kiến thức của học sinh."}},{"hanzi":"迟到","pinyin":"chídào","hanViet":"TRÌ ĐÁO","meaning":"đến muộn","pos":"Động từ","example":{"zh":"他迟到了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"迟","py":"chí"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cậu ấy đến muộn."}},{"hanzi":"充电","pinyin":"chōngdiàn","hanViet":"SUNG ĐIỆN","meaning":"sạc điện","pos":"Động từ","example":{"zh":"手机需要充电。","pinyinPerChar":[{"c":"手","py":"shǒu"},{"c":"机","py":"jī"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"充","py":"chōng"},{"c":"电","py":"diàn"},{"c":"。","py":"。"}],"vi":"Điện thoại cần sạc."}},{"hanzi":"充分","pinyin":"chōngfèn","hanViet":"SUNG PHÂN","meaning":"đầy đủ, đủ điều","pos":"Tính từ","example":{"zh":"我们要充分准备。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"充","py":"chōng"},{"c":"分","py":"fēn"},{"c":"准","py":"zhǔn"},{"c":"备","py":"bèi"},{"c":"。","py":"。"}],"vi":"Chúng ta cần chuẩn bị đầy đủ."}},{"hanzi":"抽","pinyin":"chōu","hanViet":"TRỪU","meaning":"rút, hút","pos":"Động từ","example":{"zh":"他抽烟。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"抽","py":"chōu"},{"c":"烟","py":"yān"},{"c":"。","py":"。"}],"vi":"Anh ấy hút thuốc."}},{"hanzi":"出席","pinyin":"chūxí","hanViet":"XUẤT TỊCH","meaning":"đi dự, tham dự","pos":"Động từ","example":{"zh":"他出席会议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"出","py":"chū"},{"c":"席","py":"xí"},{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Anh ấy dự họp."}},{"hanzi":"此外","pinyin":"cǐwài","hanViet":"THỬ NGOẠI","meaning":"ngoài ra, thêm nữa","pos":"Liên từ","example":{"zh":"我会学习中文，此外还会学日语。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"会","py":"huì"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"，","py":"，"},{"c":"此","py":"cǐ"},{"c":"外","py":"wài"},{"c":"还","py":"hái"},{"c":"会","py":"huì"},{"c":"学","py":"xué"},{"c":"日","py":"rì"},{"c":"语","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Tôi sẽ học tiếng Trung, ngoài ra còn học tiếng Nhật."}},{"hanzi":"刺激","pinyin":"cìjī","hanViet":"THÍCH KÍCH","meaning":"thúc đẩy, kích thích","pos":"Tính từ","example":{"zh":"这种食物很刺激。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"种","py":"zhǒng"},{"c":"食","py":"shí"},{"c":"物","py":"wù"},{"c":"很","py":"hěn"},{"c":"刺","py":"cì"},{"c":"激","py":"jī"},{"c":"。","py":"。"}],"vi":"Món ăn này rất kích thích."}},{"hanzi":"促进","pinyin":"cùjìn","hanViet":"XÚC TIẾN","meaning":"thúc đẩy, góp phần","pos":"Động từ","example":{"zh":"运动促进健康。","pinyinPerChar":[{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"促","py":"cù"},{"c":"进","py":"jìn"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"。","py":"。"}],"vi":"Vận động thúc đẩy sức khỏe."}},{"hanzi":"打","pinyin":"dá","hanViet":"ĐẢ","meaning":"đánh, chạm, làm","pos":"Động từ","example":{"zh":"我打篮球。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"打","py":"dǎ"},{"c":"篮","py":"lán"},{"c":"球","py":"qiú"},{"c":"。","py":"。"}],"vi":"Tôi chơi bóng rổ."}},{"hanzi":"打败","pinyin":"dǎbài","hanViet":"ĐẢ BẠI","meaning":"đánh bại, chiến thắng","pos":"Động từ","example":{"zh":"我们打败敌人。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"打","py":"dǎ"},{"c":"败","py":"bài"},{"c":"敌","py":"dí"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Chúng tôi đánh bại kẻ thù."}},{"hanzi":"待遇","pinyin":"dàiyù","hanViet":"ĐÃI NGỘ","meaning":"quy chế, điều kiện, đối xử","pos":"Danh từ","example":{"zh":"他的待遇很好。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"待","py":"dài"},{"c":"遇","py":"yù"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Điều kiện của anh ấy rất tốt."}},{"hanzi":"戴","pinyin":"dài","hanViet":"ĐỘI","meaning":"đeo, mang","pos":"Động từ","example":{"zh":"她戴一顶帽子。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"戴","py":"dài"},{"c":"一","py":"yī"},{"c":"顶","py":"dǐng"},{"c":"帽","py":"mào"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Cô ấy đeo một chiếc mũ."}},{"hanzi":"电源","pinyin":"diànyuán","hanViet":"ĐIỆN NGUYÊN","meaning":"nguồn điện","pos":"Danh từ","example":{"zh":"电源断了。","pinyinPerChar":[{"c":"电","py":"diàn"},{"c":"源","py":"yuán"},{"c":"断","py":"duàn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Nguồn điện đã bị ngắt."}},{"hanzi":"度过","pinyin":"dùguò","hanViet":"ĐỘ QUÁ","meaning":"trải qua, chấm dứt","pos":"Động từ","example":{"zh":"我们度过了一个愉快的假期。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"度","py":"dù"},{"c":"过","py":"guò"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"愉","py":"yú"},{"c":"快","py":"kuài"},{"c":"的","py":"de"},{"c":"假","py":"jiǎ"},{"c":"期","py":"qī"},{"c":"。","py":"。"}],"vi":"Chúng tôi đã trải qua một kỳ nghỉ vui vẻ."}},{"hanzi":"对于","pinyin":"duìyú","hanViet":"ĐỐI Ư","meaning":"về đối với, liên quan đến","pos":"Liên từ","example":{"zh":"对于这个问题，我有意见。","pinyinPerChar":[{"c":"对","py":"duì"},{"c":"于","py":"yú"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Về vấn đề này, tôi có ý kiến."}},{"hanzi":"封闭","pinyin":"fēngbì","hanViet":"PHONG BẾ","meaning":"đóng, khép lại","pos":"Tính từ","example":{"zh":"这条路被封闭了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"被","py":"bèi"},{"c":"封","py":"fēng"},{"c":"闭","py":"bì"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Con đường này bị đóng."}},{"hanzi":"付出","pinyin":"fùchū","hanViet":"PHÓ XUẤT","meaning":"đóng góp, hy sinh","pos":"Động từ","example":{"zh":"他为梦想付出努力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"为","py":"wèi"},{"c":"梦","py":"mèng"},{"c":"想","py":"xiǎng"},{"c":"付","py":"fù"},{"c":"出","py":"chū"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Anh ấy hy sinh nỗ lực cho giấc mơ."}},{"hanzi":"附近","pinyin":"fùjìn","hanViet":"PHỤ CẬN","meaning":"xung quanh, gần đó","pos":"Danh từ","example":{"zh":"学校附近有很多商店。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"附","py":"fù"},{"c":"近","py":"jìn"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"商","py":"shāng"},{"c":"店","py":"diàn"},{"c":"。","py":"。"}],"vi":"Xung quanh trường học có nhiều cửa hàng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-27', 26, 'Hành động & vận động (2)', '[{"hanzi":"关","pinyin":"guān","hanViet":"QUAN","meaning":"tắt, đóng","pos":"Động từ","example":{"zh":"请把门关上。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"门","py":"mén"},{"c":"关","py":"guān"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Hãy đóng cửa."}},{"hanzi":"关闭","pinyin":"guānbì","hanViet":"QUAN BẾ","meaning":"tắt, đóng (hệ thống, cửa)","pos":"Động từ","example":{"zh":"请关闭电脑。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"关","py":"guān"},{"c":"闭","py":"bì"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"。","py":"。"}],"vi":"Hãy tắt máy tính."}},{"hanzi":"关于","pinyin":"guānyú","hanViet":"QUAN Ư","meaning":"về, liên quan đến","pos":"Liên từ","example":{"zh":"他谈论关于工作的事情。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"谈","py":"tán"},{"c":"论","py":"lùn"},{"c":"关","py":"guān"},{"c":"于","py":"yú"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"的","py":"de"},{"c":"事","py":"shì"},{"c":"情","py":"qíng"},{"c":"。","py":"。"}],"vi":"Cậu ấy nói về chuyện công việc."}},{"hanzi":"官","pinyin":"guān","hanViet":"QUAN","meaning":"quan chức","pos":"Danh từ","example":{"zh":"他是官员。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"官","py":"guān"},{"c":"员","py":"yuán"},{"c":"。","py":"。"}],"vi":"Cậu ấy là quan chức."}},{"hanzi":"光盘","pinyin":"guāngpán","hanViet":"QUANG BÀN","meaning":"ăn hết bát, không để lại","pos":"Danh từ","example":{"zh":"我们应该光盘。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"光","py":"guāng"},{"c":"盘","py":"pán"},{"c":"。","py":"。"}],"vi":"Chúng ta nên ăn hết bát."}},{"hanzi":"归","pinyin":"guī","hanViet":"QUY","meaning":"quy về, trở về","pos":"Động từ","example":{"zh":"他归家了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"归","py":"guī"},{"c":"家","py":"jiā"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cậu ấy đã về nhà."}},{"hanzi":"忽视","pinyin":"hūshì","hanViet":"HỐT THỊ","meaning":"không coi trọng, bỏ qua","pos":"Động từ","example":{"zh":"他忽视了我的意见。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"忽","py":"hū"},{"c":"视","py":"shì"},{"c":"了","py":"le"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Anh ta bỏ qua ý kiến của tôi."}},{"hanzi":"及格","pinyin":"jígé","hanViet":"CẬP CÁCH","meaning":"đạt chuẩn, qua môn","pos":"Động từ","example":{"zh":"他及格了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"及","py":"jí"},{"c":"格","py":"gé"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đạt chuẩn."}},{"hanzi":"检测","pinyin":"jiǎncè","hanViet":"KIỂM TRẮC","meaning":"kiểm tra, xét nghiệm","pos":"Động từ","example":{"zh":"医生检测了他的血压。","pinyinPerChar":[{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"检","py":"jiǎn"},{"c":"测","py":"cè"},{"c":"了","py":"le"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"血","py":"xuè"},{"c":"压","py":"yā"},{"c":"。","py":"。"}],"vi":"Bác sĩ kiểm tra huyết áp của anh ấy."}},{"hanzi":"交换","pinyin":"jiāohuàn","hanViet":"GIAO HOÁN","meaning":"đổi, trao đổi","pos":"Động từ","example":{"zh":"他们交换意见。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"交","py":"jiāo"},{"c":"换","py":"huàn"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Họ trao đổi ý kiến."}},{"hanzi":"经典","pinyin":"jīngdiǎn","hanViet":"KINH ĐIỂN","meaning":"kinh điển, nổi tiếng","pos":"Tính từ","example":{"zh":"这本书是经典。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"是","py":"shì"},{"c":"经","py":"jīng"},{"c":"典","py":"diǎn"},{"c":"。","py":"。"}],"vi":"Cuốn sách này là kinh điển."}},{"hanzi":"竟然","pinyin":"jìngrán","hanViet":"CÁNH NHIÊN","meaning":"thật ra, bất ngờ","pos":"Phó từ","example":{"zh":"他竟然来了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"竟","py":"jìng"},{"c":"然","py":"rán"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cô ấy bất ngờ đã đến."}},{"hanzi":"究竟","pinyin":"jiūjìng","hanViet":"CỨU CÁNH","meaning":"thực ra, cuối cùng","pos":"Đại từ","example":{"zh":"究竟是谁？","pinyinPerChar":[{"c":"究","py":"jiū"},{"c":"竟","py":"jìng"},{"c":"是","py":"shì"},{"c":"谁","py":"shuí"},{"c":"？","py":"？"}],"vi":"Cuối cùng là ai?"}},{"hanzi":"具备","pinyin":"jùbèi","hanViet":"CỤ BỊ","meaning":"có đủ điều kiện, có sẵn","pos":"Động từ","example":{"zh":"他具备良好的沟通能力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"具","py":"jù"},{"c":"备","py":"bèi"},{"c":"良","py":"liáng"},{"c":"好","py":"hǎo"},{"c":"的","py":"de"},{"c":"沟","py":"gōu"},{"c":"通","py":"tōng"},{"c":"能","py":"néng"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Anh ấy có khả năng giao tiếp tốt."}},{"hanzi":"卷","pinyin":"juàn","hanViet":"CUỘN","meaning":"lật, cuộn, gập","pos":"Động từ","example":{"zh":"他把纸卷起来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"把","py":"bǎ"},{"c":"纸","py":"zhǐ"},{"c":"卷","py":"juǎn"},{"c":"起","py":"qǐ"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy cuộn giấy lại."}},{"hanzi":"看望","pinyin":"kànwàng","hanViet":"KHÁN VỌNG","meaning":"đến thăm, gặp","pos":"Động từ","example":{"zh":"我想看望我的祖母。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"看","py":"kàn"},{"c":"望","py":"wàng"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"祖","py":"zǔ"},{"c":"母","py":"mǔ"},{"c":"。","py":"。"}],"vi":"Tôi muốn thăm bà nội."}},{"hanzi":"考察","pinyin":"kǎochá","hanViet":"KHẢO SÁT","meaning":"thăm dò, điều tra","pos":"Động từ","example":{"zh":"他们来考察学校。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"来","py":"lái"},{"c":"考","py":"kǎo"},{"c":"察","py":"chá"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Họ đến thăm dò trường học."}},{"hanzi":"扩展","pinyin":"kuòzhǎn","hanViet":"KHUẾCH TRIỂN","meaning":"mở rộng, mở rộng phạm vi","pos":"Động từ","example":{"zh":"我们要扩展知识。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"扩","py":"kuò"},{"c":"展","py":"zhǎn"},{"c":"知","py":"zhī"},{"c":"识","py":"shí"},{"c":"。","py":"。"}],"vi":"Chúng tôi cần mở rộng kiến thức."}},{"hanzi":"拉开","pinyin":"lākāi","hanViet":"LẠP KHAI","meaning":"kéo ra, mở rộng khoảng cách","pos":"Động từ","example":{"zh":"他拉开窗户。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"拉","py":"lā"},{"c":"开","py":"kāi"},{"c":"窗","py":"chuāng"},{"c":"户","py":"hù"},{"c":"。","py":"。"}],"vi":"Anh ấy kéo cửa sổ ra."}},{"hanzi":"了解","pinyin":"liǎojiě","hanViet":"LIỄU GIẢI","meaning":"Biết rõ, nắm bắt được","pos":"Động từ","example":{"zh":"我了解这件事。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"了","py":"le"},{"c":"解","py":"jiě"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Tôi biết rõ việc này."}},{"hanzi":"流传","pinyin":"liúchuán","hanViet":"LƯU TRUYỀN","meaning":"Lây lan, truyền đi","pos":"Động từ","example":{"zh":"这个故事流传很广。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"故","py":"gù"},{"c":"事","py":"shì"},{"c":"流","py":"liú"},{"c":"传","py":"chuán"},{"c":"很","py":"hěn"},{"c":"广","py":"guǎng"},{"c":"。","py":"。"}],"vi":"Câu chuyện này lan rộng."}},{"hanzi":"录取","pinyin":"lùqǔ","hanViet":"LỤC THỦ","meaning":"Được tuyển chọn, nhận vào","pos":"Động từ","example":{"zh":"他被录取了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"被","py":"bèi"},{"c":"录","py":"lù"},{"c":"取","py":"qǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy được tuyển chọn."}},{"hanzi":"落","pinyin":"luò","hanViet":"LẠC","meaning":"Rơi, chạm, kết thúc","pos":"Động từ","example":{"zh":"叶子落了。","pinyinPerChar":[{"c":"叶","py":"yè"},{"c":"子","py":"zi"},{"c":"落","py":"luò"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Lá rơi."}},{"hanzi":"没想到","pinyin":"méi xiǎngdào","hanViet":"MỘT TƯỞNG ĐÁO","meaning":"đáng lẽ không, không ngờ","pos":"Phó từ","example":{"zh":"没想到你会来。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"想","py":"xiǎng"},{"c":"到","py":"dào"},{"c":"你","py":"nǐ"},{"c":"会","py":"huì"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Đáng lẽ không, bạn lại đến."}},{"hanzi":"摸","pinyin":"mō","hanViet":"MÒ","meaning":"chạm, sờ, khám","pos":"Động từ","example":{"zh":"她摸了摸头。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"摸","py":"mō"},{"c":"了","py":"le"},{"c":"摸","py":"mō"},{"c":"头","py":"tóu"},{"c":"。","py":"。"}],"vi":"Cô ấy sờ vào đầu."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-28', 27, 'Hành động & vận động (3)', '[{"hanzi":"切","pinyin":"qiē","hanViet":"THIẾT","meaning":"cắt, chẻ","pos":"Động từ","example":{"zh":"他切了苹果。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"切","py":"qiè"},{"c":"了","py":"le"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Anh ấy đã cắt quả táo."}},{"hanzi":"趋势","pinyin":"qūshì","hanViet":"XU THẾ","meaning":"xu hướng, hướng đi","pos":"Danh từ","example":{"zh":"这个趋势很明显。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"趋","py":"qū"},{"c":"势","py":"shì"},{"c":"很","py":"hěn"},{"c":"明","py":"míng"},{"c":"显","py":"xiǎn"},{"c":"。","py":"。"}],"vi":"Xu hướng này rất rõ ràng."}},{"hanzi":"散","pinyin":"sàn","hanViet":"TÁN","meaning":"phân tán, trải ra","pos":"Động từ","example":{"zh":"风把纸张吹散了。","pinyinPerChar":[{"c":"风","py":"fēng"},{"c":"把","py":"bǎ"},{"c":"纸","py":"zhǐ"},{"c":"张","py":"zhāng"},{"c":"吹","py":"chuī"},{"c":"散","py":"sàn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Gió thổi bay tờ giấy ra nhiều phía."}},{"hanzi":"闪","pinyin":"shǎn","hanViet":"THIỂM","meaning":"chớp, bật ra","pos":"Động từ","example":{"zh":"闪电很亮。","pinyinPerChar":[{"c":"闪","py":"shǎn"},{"c":"电","py":"diàn"},{"c":"很","py":"hěn"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Sét rất sáng."}},{"hanzi":"上楼","pinyin":"shàng lóu","hanViet":"THƯỢNG LÂU","meaning":"lên tầng","pos":"Động từ","example":{"zh":"请把书上楼。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"书","py":"shū"},{"c":"上","py":"shàng"},{"c":"楼","py":"lóu"},{"c":"。","py":"。"}],"vi":"Xin hãy đưa sách lên tầng."}},{"hanzi":"甚至","pinyin":"shènzhì","hanViet":"THẬM CHÍ","meaning":"đến nỗi, thậm chí","pos":"Phó từ","example":{"zh":"他甚至不吃饭。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"甚","py":"shèn"},{"c":"至","py":"zhì"},{"c":"不","py":"bù"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Anh ta thậm chí không ăn cơm."}},{"hanzi":"试卷","pinyin":"shìjuàn","hanViet":"THÍ CUỘN","meaning":"đề kiểm tra","pos":"Danh từ","example":{"zh":"老师发试卷。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"发","py":"fā"},{"c":"试","py":"shì"},{"c":"卷","py":"juǎn"},{"c":"。","py":"。"}],"vi":"Thầy giáo phát đề thi."}},{"hanzi":"刷牙","pinyin":"shuā yá","hanViet":"XOÁT NHA","meaning":"đánh răng","pos":"Động từ","example":{"zh":"他刷牙的时候听音乐。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"刷","py":"shuā"},{"c":"牙","py":"yá"},{"c":"的","py":"de"},{"c":"时","py":"shí"},{"c":"候","py":"hòu"},{"c":"听","py":"tīng"},{"c":"音","py":"yīn"},{"c":"乐","py":"lè"},{"c":"。","py":"。"}],"vi":"Cậu ấy nghe nhạc khi đánh răng."}},{"hanzi":"帅哥","pinyin":"shuàigē","hanViet":"SOÁI CA","meaning":"chàng trai xinh, người đẹp trai","pos":"Danh từ","example":{"zh":"那个帅哥很漂亮。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"个","py":"gè"},{"c":"帅","py":"shuài"},{"c":"哥","py":"gē"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Chàng trai đó rất xinh đẹp."}},{"hanzi":"缩短","pinyin":"suōduǎn","hanViet":"SÚC ĐOẢN","meaning":"rút ngắn, thu hẹp","pos":"Động từ","example":{"zh":"我们要缩短时间。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"缩","py":"suō"},{"c":"短","py":"duǎn"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Chúng ta cần rút ngắn thời gian."}},{"hanzi":"躺","pinyin":"tǎng","hanViet":"THẢNG","meaning":"nằm, nằm ngửa","pos":"Động từ","example":{"zh":"他躺在床上。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"躺","py":"tǎng"},{"c":"在","py":"zài"},{"c":"床","py":"chuáng"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Anh ấy nằm trên giường."}},{"hanzi":"特征","pinyin":"tèzhēng","hanViet":"ĐẶC TRƯNG","meaning":"đặc điểm, dấu ấn","pos":"Danh từ","example":{"zh":"他有很多特征。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"特","py":"tè"},{"c":"征","py":"zhēng"},{"c":"。","py":"。"}],"vi":"Cô ấy có nhiều đặc điểm."}},{"hanzi":"填","pinyin":"tián","hanViet":"ĐIỀN","meaning":"điền, lấp","pos":"Động từ","example":{"zh":"请填写表格。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"填","py":"tián"},{"c":"写","py":"xiě"},{"c":"表","py":"biǎo"},{"c":"格","py":"gé"},{"c":"。","py":"。"}],"vi":"Vui lòng điền biểu mẫu."}},{"hanzi":"挑","pinyin":"tiǎo","hanViet":"KHIÊU","meaning":"chỉ, chỉ ra","pos":"Động từ","example":{"zh":"请你指出问题。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"你","py":"nǐ"},{"c":"指","py":"zhǐ"},{"c":"出","py":"chū"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Hãy chỉ ra vấn đề."}},{"hanzi":"调皮","pinyin":"tiáopí","hanViet":"ĐIỆU BÌ","meaning":"đáng mưu mọt, khôn khéo","pos":"Tính từ","example":{"zh":"他有点调皮。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"调","py":"diào"},{"c":"皮","py":"pí"},{"c":"。","py":"。"}],"vi":"Anh ấy hơi đáng mưu mọt."}},{"hanzi":"贴","pinyin":"tiē","hanViet":"THIẾP","meaning":"dán, dán lên","pos":"Động từ","example":{"zh":"她把照片贴在墙上。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"把","py":"bǎ"},{"c":"照","py":"zhào"},{"c":"片","py":"piàn"},{"c":"贴","py":"tiē"},{"c":"在","py":"zài"},{"c":"墙","py":"qiáng"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Cô ấy dán ảnh lên tường."}},{"hanzi":"投","pinyin":"tóu","hanViet":"ĐẦU","meaning":"ném, nộp, ủng hộ","pos":"Động từ","example":{"zh":"他投了很多票。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"投","py":"tóu"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"票","py":"piào"},{"c":"。","py":"。"}],"vi":"Anh ấy đã bỏ nhiều phiếu bầu."}},{"hanzi":"位于","pinyin":"wèiyú","hanViet":"VỊ Ư","meaning":"nằm ở, đặt tại","pos":"Động từ","example":{"zh":"公司位于市中心。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"位","py":"wèi"},{"c":"于","py":"yú"},{"c":"市","py":"shì"},{"c":"中","py":"zhōng"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Công ty nằm ở trung tâm thành phố."}},{"hanzi":"吸","pinyin":"xī","hanViet":"HẤP","meaning":"hít, hút","pos":"Động từ","example":{"zh":"他吸气。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"吸","py":"xī"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Cậu ấy hít khí."}},{"hanzi":"下楼","pinyin":"xià lóu","hanViet":"HẠ LÂU","meaning":"lên xuống tầng, đi xuống","pos":"Động từ","example":{"zh":"我要下楼吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"下","py":"xià"},{"c":"楼","py":"lóu"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi muốn xuống tầng để ăn cơm."}},{"hanzi":"小伙子","pinyin":"xiǎohuǒzi","hanViet":"TIỂU HOẢ TỬ","meaning":"cậu trai, chàng trai","pos":"Danh từ","example":{"zh":"那个小伙子很聪明。","pinyinPerChar":[{"c":"那","py":"nà"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"伙","py":"huǒ"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"聪","py":"cōng"},{"c":"明","py":"míng"},{"c":"。","py":"。"}],"vi":"Cậu trai đó rất thông minh."}},{"hanzi":"醒","pinyin":"xǐng","hanViet":"TỈNH","meaning":"thức dậy, tỉnh táo","pos":"Động từ","example":{"zh":"我醒来时天已经亮了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"醒","py":"xǐng"},{"c":"来","py":"lái"},{"c":"时","py":"shí"},{"c":"天","py":"tiān"},{"c":"已","py":"yǐ"},{"c":"经","py":"jīng"},{"c":"亮","py":"liàng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Khi tôi thức dậy, trời đã sáng rồi."}},{"hanzi":"性质","pinyin":"xìngzhì","hanViet":"TÍNH CHẤT","meaning":"đặc điểm, bản chất","pos":"Danh từ","example":{"zh":"这种材料的性质很坚固。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"种","py":"zhǒng"},{"c":"材","py":"cái"},{"c":"料","py":"liào"},{"c":"的","py":"de"},{"c":"性","py":"xìng"},{"c":"质","py":"zhì"},{"c":"很","py":"hěn"},{"c":"坚","py":"jiān"},{"c":"固","py":"gù"},{"c":"。","py":"。"}],"vi":"Đặc điểm của vật liệu này rất bền."}},{"hanzi":"寻找","pinyin":"xúnzhǎo","hanViet":"TẦM TRẢO","meaning":"tìm kiếm","pos":"Động từ","example":{"zh":"我在找我的钥匙。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"找","py":"zhǎo"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"钥","py":"yào"},{"c":"匙","py":"shi"},{"c":"。","py":"。"}],"vi":"Tôi đang tìm chiếc chìa khóa của mình."}},{"hanzi":"依靠","pinyin":"yīkào","hanViet":"Y KHÁO","meaning":"tùy thuộc, dựa vào","pos":"Động từ","example":{"zh":"我靠努力学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"靠","py":"kào"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Tôi học giỏi nhờ sự cố gắng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-29', 28, 'Hành động & vận động (4)', '[{"hanzi":"移","pinyin":"yí","hanViet":"DI","meaning":"dời, chuyển, di chuyển","pos":"Động từ","example":{"zh":"他把书移到桌子上。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"把","py":"bǎ"},{"c":"书","py":"shū"},{"c":"移","py":"yí"},{"c":"到","py":"dào"},{"c":"桌","py":"zhuō"},{"c":"子","py":"zi"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Anh ấy dời sách lên bàn."}},{"hanzi":"移动","pinyin":"yídòng","hanViet":"DI ĐỘNG","meaning":"di chuyển, chuyển động","pos":"Động từ","example":{"zh":"车辆正在移动。","pinyinPerChar":[{"c":"车","py":"chē"},{"c":"辆","py":"liàng"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"移","py":"yí"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Tàu đang di chuyển."}},{"hanzi":"引进","pinyin":"yǐnjìn","hanViet":"DẪN TIẾN","meaning":"đưa vào, thu hút, nhập khẩu","pos":"Động từ","example":{"zh":"公司引进 nhiều sản phẩm mới. ","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"引","py":"yǐn"},{"c":"进","py":"jìn"},{"c":" ","py":" "},{"c":"n","py":"n"},{"c":"h","py":"h"},{"c":"i","py":"i"},{"c":"ề","py":"ề"},{"c":"u","py":"u"},{"c":" ","py":" "},{"c":"s","py":"s"},{"c":"ả","py":"ả"},{"c":"n","py":"n"},{"c":" ","py":" "},{"c":"p","py":"p"},{"c":"h","py":"h"},{"c":"ẩ","py":"ẩ"},{"c":"m","py":"m"},{"c":" ","py":" "},{"c":"m","py":"m"},{"c":"ớ","py":"ớ"},{"c":"i","py":"i"},{"c":".","py":"."},{"c":" ","py":" "}],"vi":"Công ty đưa vào nhiều sản phẩm mới."}},{"hanzi":"引起","pinyin":"yǐnqǐ","hanViet":"DẪN KHỞI","meaning":"gây ra, dẫn đến","pos":"Động từ","example":{"zh":"Mưa gây ra lũ lụt. ","pinyinPerChar":[{"c":"M","py":"M"},{"c":"ư","py":"ư"},{"c":"a","py":"a"},{"c":" ","py":" "},{"c":"g","py":"g"},{"c":"â","py":"â"},{"c":"y","py":"y"},{"c":" ","py":" "},{"c":"r","py":"r"},{"c":"a","py":"a"},{"c":" ","py":" "},{"c":"l","py":"l"},{"c":"ũ","py":"ũ"},{"c":" ","py":" "},{"c":"l","py":"l"},{"c":"ụ","py":"ụ"},{"c":"t","py":"t"},{"c":".","py":"."},{"c":" ","py":" "}],"vi":"Mưa gây ra lụt lụt."}},{"hanzi":"邮局","pinyin":"yóujú","hanViet":"BƯU CỤC","meaning":"bưu điện","pos":"Danh từ","example":{"zh":"我去邮局寄信。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"邮","py":"yóu"},{"c":"局","py":"jú"},{"c":"寄","py":"jì"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Tôi đi bưu điện gửi thư."}},{"hanzi":"遇","pinyin":"yù","hanViet":"NGỘ","meaning":"gặp, chạm vào","pos":"Động từ","example":{"zh":"我遇到一个朋友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"遇","py":"yù"},{"c":"到","py":"dào"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi gặp một người bạn."}},{"hanzi":"遇到","pinyin":"yùdào","hanViet":"NGỘ ĐÁO","meaning":"gặp phải, chạm vào","pos":"Động từ","example":{"zh":"他遇到麻烦。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"遇","py":"yù"},{"c":"到","py":"dào"},{"c":"麻","py":"má"},{"c":"烦","py":"fán"},{"c":"。","py":"。"}],"vi":"Cậu ấy gặp sự cố."}},{"hanzi":"在于","pinyin":"zàiyú","hanViet":"TẠI Ư","meaning":"tại sao, nằm ở điều gì","pos":"Liên từ","example":{"zh":"问题在于方法是否正确。","pinyinPerChar":[{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"在","py":"zài"},{"c":"于","py":"yú"},{"c":"方","py":"fāng"},{"c":"法","py":"fǎ"},{"c":"是","py":"shì"},{"c":"否","py":"fǒu"},{"c":"正","py":"zhèng"},{"c":"确","py":"què"},{"c":"。","py":"。"}],"vi":"Vấn đề nằm ở việc phương pháp có đúng không."}},{"hanzi":"战胜","pinyin":"zhànshèng","hanViet":"CHIẾN THẮNG","meaning":"vượt qua, chiến thắng","pos":"Động từ","example":{"zh":"他战胜了困难。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"战","py":"zhàn"},{"c":"胜","py":"shèng"},{"c":"了","py":"le"},{"c":"困","py":"kùn"},{"c":"难","py":"nán"},{"c":"。","py":"。"}],"vi":"Anh ấy đã vượt qua khó khăn."}},{"hanzi":"折","pinyin":"zhé","hanViet":"CHIẾT","meaning":"gãy, giảm, gấp","pos":"Động từ","example":{"zh":"树枝折断了。","pinyinPerChar":[{"c":"树","py":"shù"},{"c":"枝","py":"zhī"},{"c":"折","py":"zhé"},{"c":"断","py":"duàn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cành cây gãy đứt."}},{"hanzi":"针对","pinyin":"zhēnduì","hanViet":"CHÂM ĐỐI","meaning":"đối diện với, nhắm vào","pos":"Động từ","example":{"zh":"这项政策针对的是失业人员。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"项","py":"xiàng"},{"c":"政","py":"zhèng"},{"c":"策","py":"cè"},{"c":"针","py":"zhēn"},{"c":"对","py":"duì"},{"c":"的","py":"de"},{"c":"是","py":"shì"},{"c":"失","py":"shī"},{"c":"业","py":"yè"},{"c":"人","py":"rén"},{"c":"员","py":"yuán"},{"c":"。","py":"。"}],"vi":"Chính sách này nhắm vào người thất nghiệp."}},{"hanzi":"著名","pinyin":"zhùmíng","hanViet":"TRỨ DANH","meaning":"Nổi tiếng, nổi bật","pos":"Tính từ","example":{"zh":"这部电影很著名。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"很","py":"hěn"},{"c":"著","py":"zhù"},{"c":"名","py":"míng"},{"c":"。","py":"。"}],"vi":"Phim này rất nổi tiếng."}},{"hanzi":"抓紧","pinyin":"zhuājǐn","hanViet":"TRẢO KHẨN","meaning":"Nhanh chóng, gấp, sắp xếp","pos":"Động từ","example":{"zh":"我们抓紧时间。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"抓","py":"zhuā"},{"c":"紧","py":"jǐn"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Chúng ta gấp thời gian."}},{"hanzi":"转动","pinyin":"zhuǎndòng","hanViet":"CHUYỂN ĐỘNG","meaning":"Xoay, chuyển động","pos":"Động từ","example":{"zh":"我转动手柄。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"转","py":"zhuǎn"},{"c":"动","py":"dòng"},{"c":"手","py":"shǒu"},{"c":"柄","py":"bǐng"},{"c":"。","py":"。"}],"vi":"Tôi quay tay điều khiển."}},{"hanzi":"转身","pinyin":"zhuǎnshēn","hanViet":"CHUYỂN THÂN","meaning":"Quay người, chuyển hướng","pos":"Động từ","example":{"zh":"他转身走开。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"转","py":"zhuǎn"},{"c":"身","py":"shēn"},{"c":"走","py":"zǒu"},{"c":"开","py":"kāi"},{"c":"。","py":"。"}],"vi":"Anh ấy quay người đi."}},{"hanzi":"转弯","pinyin":"zhuǎnwān","hanViet":"CHUYỂN LOAN","meaning":"Xoay góc, bẻ đường","pos":"Động từ","example":{"zh":"车转弯了。","pinyinPerChar":[{"c":"车","py":"chē"},{"c":"转","py":"zhu