INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-30', 29, 'Bổ sung (1)', '[{"hanzi":"…分之…","pinyin":"…fēn zhī…","hanViet":"PHÂN CHI","meaning":"…phần…","pos":"Cụm từ","example":{"zh":"他吃了三分之一。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"吃","py":"chī"},{"c":"了","py":"le"},{"c":"三","py":"sān"},{"c":"分","py":"fēn"},{"c":"之","py":"zhī"},{"c":"一","py":"yī"},{"c":"。","py":"。"}],"vi":"Anh ấy đã ăn một phần ba."}},{"hanzi":"一再","pinyin":"yīzài","hanViet":"NHẤT TÁI","meaning":"một lần nữa, nhiều lần","pos":"Phó từ","example":{"zh":"他一再提醒我注意安全。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"一","py":"yī"},{"c":"再","py":"zài"},{"c":"提","py":"tí"},{"c":"醒","py":"xǐng"},{"c":"我","py":"wǒ"},{"c":"注","py":"zhù"},{"c":"意","py":"yì"},{"c":"安","py":"ān"},{"c":"全","py":"quán"},{"c":"。","py":"。"}],"vi":"Anh ấy nhắc tôi nhiều lần về an toàn."}},{"hanzi":"一致","pinyin":"yīzhì","hanViet":"NHẤT TRÍ","meaning":"đồng ý, thống nhất","pos":"Tính từ","example":{"zh":"大家意见一致。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"意","py":"yì"},{"c":"见","py":"jiàn"},{"c":"一","py":"yī"},{"c":"致","py":"zhì"},{"c":"。","py":"。"}],"vi":"Cả nhóm đồng ý."}},{"hanzi":"一般来说","pinyin":"yībānláishuō","hanViet":"NHẤT BAN LAI THUYẾT","meaning":"về chung thể, nói chung","pos":"Phó từ","example":{"zh":"一般来说，他每天都工作。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"般","py":"bān"},{"c":"来","py":"lái"},{"c":"说","py":"shuō"},{"c":"，","py":"，"},{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"都","py":"dōu"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Về chung thể, anh ấy mỗi ngày đều làm việc."}},{"hanzi":"下降","pinyin":"xiàjiàng","hanViet":"HẠ GIÁNG","meaning":"giảm, sụt giảm","pos":"Động từ","example":{"zh":"价格下降了。","pinyinPerChar":[{"c":"价","py":"jià"},{"c":"格","py":"gé"},{"c":"下","py":"xià"},{"c":"降","py":"jiàng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Giá đã giảm."}},{"hanzi":"专心","pinyin":"zhuānxīn","hanViet":"CHUYÊN TÂM","meaning":"Tập trung, cống hiến","pos":"Tính từ","example":{"zh":"他专心学习。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"专","py":"zhuān"},{"c":"心","py":"xīn"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Anh ấy tập trung học tập."}},{"hanzi":"严","pinyin":"yán","hanViet":"NGHIÊM","meaning":"khắt khe, nghiêm","pos":"Tính từ","example":{"zh":"他很严格。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"格","py":"gé"},{"c":"。","py":"。"}],"vi":"Anh ấy rất khắt khe."}},{"hanzi":"严格","pinyin":"yángé","hanViet":"NGHIÊM CÁCH","meaning":"khắt khe, nghiêm túc","pos":"Tính từ","example":{"zh":"老师要求我们严格遵守规则。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"要","py":"yào"},{"c":"求","py":"qiú"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"严","py":"yán"},{"c":"格","py":"gé"},{"c":"遵","py":"zūn"},{"c":"守","py":"shǒu"},{"c":"规","py":"guī"},{"c":"则","py":"zé"},{"c":"。","py":"。"}],"vi":"Giáo viên yêu cầu chúng ta tuân thủ quy tắc nghiêm ngặt."}},{"hanzi":"中奖","pinyin":"zhòngjiǎng","hanViet":"TRUNG THƯỞNG","meaning":"Trúng giải","pos":"Động từ","example":{"zh":"她中奖了。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"中","py":"zhōng"},{"c":"奖","py":"jiǎng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cô ấy trúng giải."}},{"hanzi":"主题","pinyin":"zhǔtí","hanViet":"CHỦ ĐỀ","meaning":"Chủ đề, đề tài","pos":"Danh từ","example":{"zh":"这节课主题是环保。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"节","py":"jié"},{"c":"课","py":"kè"},{"c":"主","py":"zhǔ"},{"c":"题","py":"tí"},{"c":"是","py":"shì"},{"c":"环","py":"huán"},{"c":"保","py":"bǎo"},{"c":"。","py":"。"}],"vi":"Môn học này chủ đề là bảo vệ môi trường."}},{"hanzi":"之一","pinyin":"zhīyī","hanViet":"CHI NHẤT","meaning":"một trong","pos":"Danh từ","example":{"zh":"这是解决问题的重要方法之一。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"解","py":"jiě"},{"c":"决","py":"jué"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"的","py":"de"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"方"