INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-31', 30, 'Bổ sung (2)', '[{"hanzi":"似的","pinyin":"shìde","hanViet":"TỰ ĐÍCH","meaning":"như vậy, như thế","pos":"Phó từ","example":{"zh":"他走路像个小孩似的。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"路","py":"lù"},{"c":"像","py":"xiàng"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"孩","py":"hái"},{"c":"似","py":"shì"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Anh ta đi lại như một đứa trẻ vậy."}},{"hanzi":"位置","pinyin":"wèizhì","hanViet":"VỊ TRÍ","meaning":"vị trí, chỗ","pos":"Danh từ","example":{"zh":"请告诉我位置。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"告","py":"gào"},{"c":"诉","py":"sù"},{"c":"我","py":"wǒ"},{"c":"位","py":"wèi"},{"c":"置","py":"zhì"},{"c":"。","py":"。"}],"vi":"Hãy cho tôi biết vị trí."}},{"hanzi":"体操","pinyin":"tǐcāo","hanViet":"THỂ THAO","meaning":"vật lý, thể dục","pos":"Danh từ","example":{"zh":"他每天做体操。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"做","py":"zuò"},{"c":"体","py":"tǐ"},{"c":"操","py":"cāo"},{"c":"。","py":"。"}],"vi":"Anh ấy làm thể dục mỗi ngày."}},{"hanzi":"作为","pinyin":"zuòwéi","hanViet":"TÁC VỊ","meaning":"vai trò, làm gì","pos":"Danh từ","example":{"zh":"作为学生。","pinyinPerChar":[{"c":"作","py":"zuò"},{"c":"为","py":"wèi"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Là một học sinh."}},{"hanzi":"使劲","pinyin":"shǐjìn","hanViet":"SỬ KÌNH","meaning":"mạnh mẽ, dùng sức","pos":"Động từ","example":{"zh":"他使劲打开门。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"使","py":"shǐ"},{"c":"劲","py":"jìn"},{"c":"打","py":"dǎ"},{"c":"开","py":"kāi"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Anh ta dùng sức để mở cửa."}},{"hanzi":"供应","pinyin":"gōngyìng","hanViet":"CUNG ƯNG","meaning":"cung cấp, cung ứng","pos":"Động từ","example":{"zh":"商店供应很多商品。","pinyinPerChar":[{"c":"商","py":"shāng"},{"c":"店","py":"diàn"},{"c":"供","py":"gōng"},{"c":"应","py":"yīng"},{"c":"很","py":"hěn"},{"c