INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-33', 32, 'Bổ sung (4)', '[{"hanzi":"哪","pinyin":"na","hanViet":"NẢ","meaning":"nào, đâu","pos":"Đại từ","example":{"zh":"你去哪里？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"去","py":"qù"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Bạn đi đâu?"}},{"hanzi":"售货员","pinyin":"shòuhuòyuán","hanViet":"THỤ HOÁ VIÊN","meaning":"người bán hàng, nhân viên bán hàng","pos":"Danh từ","example":{"zh":"售货员在柜台前帮顾客找东西。","pinyinPerChar":[{"c":"售","py":"shòu"},{"c":"货","py":"huò"},{"c":"员","py":"yuán"},{"c":"在","py":"zài"},{"c":"柜","py":"guì"},{"c":"台","py":"tái"},{"c":"前","py":"qián"},{"c":"帮","py":"bāng"},{"c":"顾","py":"gù"},{"c":"客","py":"kè"},{"c":"找","py":"zhǎo"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"。","py":"。"}],"vi":"Nhân viên bán hàng ở quầy giúp khách tìm đồ."}},{"hanzi":"喂","pinyin":"wèi","hanViet":"UỶ","meaning":"vâng, ừ (gọi ai)","pos":"Thán từ","example":{"zh":"喂，你在哪里？","pinyinPerChar":[{"c":"喂","py":"wèi"},{"c":"，","py":"，"},{"c":"你","py":"nǐ"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Vâng, anh/chị ở đâu vậy?"}},{"hanzi":"善于","pinyin":"shànyú","hanViet":"THIỆN Ư","meaning":"thành thạo, giỏi","pos":"Động từ","example":{"zh":"他善于画画。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"善","py":"shàn"},{"c":"于","py":"yú"},{"c":"画","py":"huà"},{"c":"画","py":"huà"},{"c":"。","py":"。"}],"vi":"Anh ấy giỏi vẽ hình."}},{"hanzi":"善良","pinyin":"shànliáng","hanViet":"THIỆN LƯƠNG","meaning":"tình thiện, tốt bụng","pos":"Tính từ","example":{"zh":"她很善良。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"很","py":"hěn"},{"c":"善","py":"shàn"},{"c":"良","py":"liáng"},{"c":"。","py":"。"}],"vi":"Cô ấy rất tốt bụng."}},{"hanzi":"嘴巴","pinyin":"zuǐba","hanViet":"CHUỶ BA","meaning":"miệng, miệng nói","pos":"Danh từ","example":{"zh":"他嘴巴很大。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"嘴","py":"zuǐ"},{"c":"巴","py":"bā"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Anh ấy miệng to."}},{"hanzi":"图案","pinyin":"tú''àn","hanViet":"ĐỒ ÁN","meaning":"mẫu hình, hình vẽ","pos":"Danh từ","example":{"zh":"墙上有漂亮的图案。","pinyinPerChar":[{"c":"墙","py":"qiáng"},{"c":"上","py":"shàng"},{"c":"有","py":"yǒu"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"的","py":"de"},{"c":"图","py":"tú"},{"c":"案","py":"àn"},{"c":"。","py":"。"}],"vi":"Trên tường có mẫu hình đẹp."}},{"hanzi":"型","pinyin":"xíng","hanViet":"HÌNH","meaning":"mẫu, kiểu, hình dạng","pos":"Danh từ","example":{"zh":"这款车型很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"款","py":"kuǎn"},{"c":"车","py":"chē"},{"c":"型","py":"xíng"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Mẫu xe này rất đẹp."}},{"hanzi":"型号","pinyin":"xínghào","hanViet":"HÌNH HIỆU","meaning":"mẫu mã, loại","pos":"Danh từ","example":{"zh":"这台电脑的型号是什么？","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"台","py":"tái"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"的","py":"de"},{"c":"型","py":"xíng"},{"c":"号","py":"hào"},{"c":"是","py":"shì"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"？","py":"？"}],"vi":"Mẫu mã máy tính này là gì?"}},{"hanzi":"塑料","pinyin":"sùliào","hanViet":"TỐ LIỆU","meaning":"nhựa","pos":"Danh từ","example":{"zh":"这个杯子是塑料。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"杯","py":"bēi"},{"c":"子","py":"zi"},{"c":"是","py":"shì"},{"c":"塑","py":"sù"},{"c":"料","py":"liào"},{"c":"。","py":"。"}],"vi":"Cái ly này làm bằng nhựa."}},{"hanzi":"填空","pinyin":"tiánkòng","hanViet":"ĐIỀN KHÔNG","meaning":"điền chỗ trống","pos":"Danh từ","example":{"zh":"老师布置了填空作业。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"布","py":"bù"},{"c":"置","py":"zhì"},{"c":"了","py":"le"},{"c":"填","py":"tián"},{"c":"空","py":"kōng"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"。","py":"。"}],"vi":"Giáo viên giao bài tập điền chỗ trống."}},{"hanzi":"士兵","pinyin":"shìbīng","hanViet":"SĨ BINH","meaning":"người lính","pos":"Danh từ","example":{"zh":"士兵穿军装。","pinyinPerChar":[{"c":"士","py":"shì"},{"c":"兵","py":"bīng"},{"c":"穿","py":"chuān"},{"c":"军","py":"jūn"},{"c":"装","py":"zhuāng"},{"c":"。","py":"。"}],"vi":"Nhân viên mặc trang phục quân đội."}},{"hanzi":"处","pinyin":"chù","hanViet":"XỨ","meaning":"nơi ở, xử lý, vị trí","pos":"Danh từ","example":{"zh":"他住在这个处。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"处","py":"chù"},{"c":"。","py":"。"}],"vi":"Anh ấy ở tại nơi này."}},{"hanzi":"处于","pinyin":"chǔyú","hanViet":"XỨ Ư","meaning":"trong tình trạng, ở vị trí","pos":"Động từ","example":{"zh":"公司处于困难时期。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"处","py":"chù"},{"c":"于","py":"yú"},{"c":"困","py":"kùn"},{"c":"难","py":"nán"},{"c":"时","py":"shí"},{"c":"期","py":"qī"},{"c":"。","py":"。"}],"vi":"Công ty đang trong giai đoạn khó khăn."}},{"hanzi":"复制","pinyin":"fùzhì","hanViet":"PHỤC CHẾ","meaning":"sao chép, nhân bản","pos":"Động từ","example":{"zh":"请复制这个文件。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"复","py":"fù"},{"c":"制","py":"zhì"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"文","py":"wén"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Xin sao chép tập tin này."}},{"hanzi":"外交官","pinyin":"wàijiāoguān","hanViet":"NGOẠI GIAO QUAN","meaning":"diễn viên ngoại giao","pos":"Danh từ","example":{"zh":"他是外交官。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"外","py":"wài"},{"c":"交","py":"jiāo"},{"c":"官","py":"guān"},{"c":"。","py":"。"}],"vi":"Anh ấy là nhà ngoại giao."}},{"hanzi":"外汇","pinyin":"wàihuì","hanViet":"NGOẠI HỐI","meaning":"tiền tệ ngoại hối","pos":"Danh từ","example":{"zh":"银行交易外汇。","pinyinPerChar":[{"c":"银","py":"yín"},{"c":"行","py":"xíng"},{"c":"交","py":"jiāo"},{"c":"易","py":"yì"},{"c":"外","py":"wài"},{"c":"汇","py":"huì"},{"c":"。","py":"。"}],"vi":"Ngân hàng giao dịch tiền tệ ngoại hối."}},{"hanzi":"多样","pinyin":"duōyàng","hanViet":"ĐA DẠNG","meaning":"đa dạng","pos":"Tính từ","example":{"zh":"这里有很多多样东西。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"多","py":"duō"},{"c":"样","py":"yàng"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"。","py":"。"}],"vi":"Đây có nhiều thứ đa dạng."}},{"hanzi":"多次","pinyin":"duō cì","hanViet":"ĐA THỨ","meaning":"nhiều lần","pos":"Phó từ","example":{"zh":"他多次来过这里。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"多","py":"duō"},{"c":"次","py":"cì"},{"c":"来","py":"lái"},{"c":"过","py":"guò"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy đã đến đây nhiều lần."}},{"hanzi":"多种","pinyin":"duō zhǒng","hanViet":"ĐA CHỦNG","meaning":"nhiều loại","pos":"Tính từ","example":{"zh":"这里有多种水果。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"多","py":"duō"},{"c":"种","py":"zhǒng"},{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Đây có nhiều loại trái cây."}},{"hanzi":"大多","pinyin":"dàduō","hanViet":"ĐẠI ĐA","meaning":"hầu như, phần lớn","pos":"Tính từ","example":{"zh":"大多人都喜欢这个电影。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"多","py":"duō"},{"c":"人","py":"rén"},{"c":"都","py":"dōu"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"。","py":"。"}],"vi":"Hầu như tất cả mọi người đều thích bộ phim này."}},{"hanzi":"大陆","pinyin":"dàlù","hanViet":"ĐẠI LỤC","meaning":"lục địa, lục địa châu Á","pos":"Danh từ","example":{"zh":"他来自大陆。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"来","py":"lái"},{"c":"自","py":"zì"},{"c":"大","py":"dà"},{"c":"陆","py":"lù"},{"c":"。","py":"。"}],"vi":"Anh ấy đến từ lục địa."}},{"hanzi":"天真","pinyin":"tiānzhēn","hanViet":"THIÊN CHÂN","meaning":"ngây thơ, trong trẻo","pos":"Tính từ","example":{"zh":"孩子很天真。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"天","py":"tiān"},{"c":"真","py":"zhēn"},{"c":"。","py":"。"}],"vi":"Cậu bé rất ngây thơ."}},{"hanzi":"失业","pinyin":"shīyè","hanViet":"THẤT NGHIỆP","meaning":"bị mất việc","pos":"Động từ","example":{"zh":"他失业了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"失","py":"shī"},{"c":"业","py":"yè"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ta đã mất việc."}},{"hanzi":"套餐","pinyin":"tàocān","hanViet":"SÁO XAN","meaning":"gói quà, gói dịch vụ","pos":"Danh từ","example":{"zh":"这个套餐很贵。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"套","py":"tào"},{"c":"餐","py":"cān"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Gói này rất đắt."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-34', 33, 'Bổ sung (5)', '[{"hanzi":"好友","pinyin":"hǎoyǒu","hanViet":"HẢO HỮU","meaning":"bạn tốt","pos":"Danh từ","example":{"zh":"我有很多好友。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"好","py":"hǎo"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi có nhiều bạn tốt."}},{"hanzi":"学问","pinyin":"xuéwen","hanViet":"HỌC VẤN","meaning":"kiến thức, tài năng","pos":"Danh từ","example":{"zh":"他很有学问。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"学","py":"xué"},{"c":"问","py":"wèn"},{"c":"。","py":"。"}],"vi":"Anh ấy rất có kiến thức."}},{"hanzi":"守","pinyin":"shǒu","hanViet":"THỦ","meaning":"bảo vệ, giữ","pos":"Động từ","example":{"zh":"他守着门。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"守","py":"shǒu"},{"c":"着","py":"zhe"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Anh ta giữ cửa."}},{"hanzi":"实用","pinyin":"shíyòng","hanViet":"THỰC DỤNG","meaning":"có ích, khả dụng","pos":"Tính từ","example":{"zh":"这本书很实用。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"实","py":"shí"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Sách này rất thực dụng."}},{"hanzi":"宽","pinyin":"kuān","hanViet":"KHOAN","meaning":"rộng, rộng rãi","pos":"Tính từ","example":{"zh":"这条路很宽。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"宽","py":"kuān"},{"c":"。","py":"。"}],"vi":"Tuyến đường này rất rộng."}},{"hanzi":"宽广","pinyin":"kuānguǎng","hanViet":"KHOAN QUẢNG","meaning":"rộng lớn, rộng lớn","pos":"Tính từ","example":{"zh":"这片草地很宽广。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"片","py":"piàn"},{"c":"草","py":"cǎo"},{"c":"地","py":"dì"},{"c":"很","py":"hěn"},{"c":"宽","py":"kuān"},{"c":"广","py":"guǎng"},{"c":"。","py":"。"}],"vi":"Vụ cỏ này rất rộng lớn."}},{"hanzi":"寄","pinyin":"jì","hanViet":"KÝ","meaning":"gửi, bưu kiện","pos":"Động từ","example":{"zh":"我寄了一封信给他。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"寄","py":"jì"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"封","py":"fēng"},{"c":"信","py":"xìn"},{"c":"给","py":"gěi"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Tôi đã gửi một bức thư cho anh ấy."}},{"hanzi":"对付","pinyin":"duìfu","hanViet":"ĐỐI PHÓ","meaning":"đối phó, xử lý","pos":"Động từ","example":{"zh":"我不知道怎么对付这个问题。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"知","py":"zhī"},{"c":"道","py":"dào"},{"c":"怎","py":"zěn"},{"c":"么","py":"me"},{"c":"对","py":"duì"},{"c":"付","py":"fù"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Tôi không biết cách xử lý vấn đề này."}},{"hanzi":"小型","pinyin":"xiǎoxíng","hanViet":"TIỂU HÌNH","meaning":"nhỏ, kích thước nhỏ","pos":"Tính từ","example":{"zh":"这是一辆小型汽车。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"辆","py":"liàng"},{"c":"小","py":"xiǎo"},{"c":"型","py":"xíng"},{"c":"汽","py":"qì"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Đây là một chiếc xe nhỏ."}},{"hanzi":"尺","pinyin":"chǐ","hanViet":"THƯỚC","meaning":"đơn vị đo dài","pos":"Danh từ","example":{"zh":"一尺有多长？","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"尺","py":"chǐ"},{"c":"有","py":"yǒu"},{"c":"多","py":"duō"},{"c":"长","py":"zhǎng"},{"c":"？","py":"？"}],"vi":"Một thước dài bao nhiêu?"}},{"hanzi":"尽力","pinyin":"jìnlì","hanViet":"TẬN LỰC","meaning":"làm hết sức, nỗ lực","pos":"Động từ","example":{"zh":"我会尽力帮助你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"会","py":"huì"},{"c":"尽","py":"jǐn"},{"c":"力","py":"lì"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi sẽ nỗ lực giúp bạn."}},{"hanzi":"尽快","pinyin":"jǐnkuài","hanViet":"TẬN KHOÁI","meaning":"nhanh nhất có thể","pos":"Phó từ","example":{"zh":"请尽快回复我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"尽","py":"jǐn"},{"c":"快","py":"kuài"},{"c":"回","py":"huí"},{"c":"复","py":"fù"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Xin trả lời cho tôi càng nhanh càng tốt."}},{"hanzi":"尾巴","pinyin":"wěiba","hanViet":"VĨ BA","meaning":"đuôi","pos":"Danh từ","example":{"zh":"猫有一条尾巴。","pinyinPerChar":[{"c":"猫","py":"māo"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"条","py":"tiáo"},{"c":"尾","py":"wěi"},{"c":"巴","py":"bā"},{"c":"。","py":"。"}],"vi":"Con mèo có một chiếc đuôi."}},{"hanzi":"居住","pinyin":"jūzhù","hanViet":"CƯ TRÚ","meaning":"ở nơi sinh sống","pos":"Động từ","example":{"zh":"他们居住在北京。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"居","py":"jū"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"北","py":"běi"},{"c":"京","py":"jīng"},{"c":"。","py":"。"}],"vi":"Họ ở tại Bắc Kinh."}},{"hanzi":"居民","pinyin":"jūmín","hanViet":"CƯ DÂN","meaning":"người dân, cư dân","pos":"Danh từ","example":{"zh":"居民们很安静。","pinyinPerChar":[{"c":"居","py":"jū"},{"c":"民","py":"mín"},{"c":"们","py":"men"},{"c":"很","py":"hěn"},{"c":"安","py":"ān"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Người dân rất yên tĩnh."}},{"hanzi":"巨大","pinyin":"jùdà","hanViet":"CỰ ĐẠI","meaning":"rất lớn","pos":"Tính từ","example":{"zh":"这座山非常巨大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"座","py":"zuò"},{"c":"山","py":"shān"},{"c":"非","py":"fēi"},{"c":"常","py":"cháng"},{"c":"巨","py":"jù"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Ngọn núi này rất lớn."}},{"hanzi":"并","pinyin":"bìng","hanViet":"TỊNH","meaning":"và, cùng","pos":"Liên từ","example":{"zh":"他并没有来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"并","py":"bìng"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy không đến."}},{"hanzi":"幼儿园","pinyin":"yòu''éryuán","hanViet":"ẤU NHI VIÊN","meaning":"trường mẫu giáo","pos":"Danh từ","example":{"zh":"孩子们去幼儿园学习。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"幼","py":"yòu"},{"c":"儿","py":"ér"},{"c":"园","py":"yuán"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Trẻ em đi học trường mẫu giáo."}},{"hanzi":"应","pinyin":"yīng","hanViet":"ƯNG","meaning":"phải, nên, đáp ứng","pos":"Động từ","example":{"zh":"你应该努力学习。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Bạn nên cố gắng học tập."}},{"hanzi":"引导","pinyin":"yǐndǎo","hanViet":"DẪN ĐẠO","meaning":"dẫn dắt, hướng dẫn","pos":"Động từ","example":{"zh":"老师引导学生学习新单词。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"引","py":"yǐn"},{"c":"导","py":"dǎo"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"新","py":"xīn"},{"c":"单","py":"dān"},{"c":"词","py":"cí"},{"c":"。","py":"。"}],"vi":"Giáo viên hướng dẫn học sinh học từ mới."}},{"hanzi":"弯","pinyin":"wān","hanViet":"LOAN","meaning":"hình cong, cong lại","pos":"Tính từ","example":{"zh":"这条路弯弯的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"弯","py":"wān"},{"c":"弯","py":"wān"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Con đường này cong cong."}},{"hanzi":"弱","pinyin":"ruò","hanViet":"NHƯỢC","meaning":"yếu, yếu đuối","pos":"Tính từ","example":{"zh":"他身体很弱。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"身","py":"shēn"},{"c":"体","py":"tǐ"},{"c":"很","py":"hěn"},{"c":"弱","py":"ruò"},{"c":"。","py":"。"}],"vi":"Anh ấy cơ thể rất yếu."}},{"hanzi":"影子","pinyin":"yǐngzi","hanViet":"ẢNH TỬ","meaning":"đối tượng, bóng","pos":"Danh từ","example":{"zh":"太阳下去，影子消失了。","pinyinPerChar":[{"c":"太","py":"tài"},{"c":"阳","py":"yáng"},{"c":"下","py":"xià"},{"c":"去","py":"qù"},{"c":"，","py":"，"},{"c":"影","py":"yǐng"},{"c":"子","py":"zi"},{"c":"消","py":"xiāo"},{"c":"失","py":"shī"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Khi mặt trời lặn, bóng đổ biến mất."}},{"hanzi":"律师","pinyin":"lǜshī","hanViet":"LUẬT SƯ","meaning":"Luật sư","pos":"Danh từ","example":{"zh":"他是律师。","pinyinPerChar":[{"c":"