INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-35', 34, 'Bổ sung (6)', '[{"hanzi":"总之","pinyin":"zǒngzhī","hanViet":"TỔNG CHI","meaning":"tóm lại, nói chung","pos":"Liên từ","example":{"zh":"总之，我们要努力。","pinyinPerChar":[{"c":"总","py":"zǒng"},{"c":"之","py":"zhī"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Tóm lại, chúng ta phải cố gắng."}},{"hanzi":"总理","pinyin":"zǒnglǐ","hanViet":"TỔNG LÝ","meaning":"thủ tướng, chủ nhiệm","pos":"Danh từ","example":{"zh":"他是总理。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"总","py":"zǒng"},{"c":"理","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy là Thủ tướng."}},{"hanzi":"总统","pinyin":"zǒngtǒng","hanViet":"TỔNG THỐNG","meaning":"tổng thống, tổng bộ","pos":"Danh từ","example":{"zh":"他是总统。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"总","py":"zǒng"},{"c":"统","py":"tǒng"},{"c":"。","py":"。"}],"vi":"Anh ấy là Tổng thống."}},{"hanzi":"成人","pinyin":"chéngrén","hanViet":"THÀNH NHÂN","meaning":"người lớn, trưởng thành","pos":"Danh từ","example":{"zh":"他已经是成人了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"已","py":"yǐ"},{"c":"经","py":"jīng"},{"c":"是","py":"shì"},{"c":"成","py":"chéng"},{"c":"人","py":"rén"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cậu ấy đã trưởng thành."}},{"hanzi":"或许","pinyin":"huòxǔ","hanViet":"HOẶC HỨA","meaning":"có thể, có lẽ","pos":"Phó từ","example":{"zh":"他或许会来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"或","py":"huò"},{"c":"许","py":"xǔ"},{"c":"会","py":"huì"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy có lẽ sẽ đến."}},{"hanzi":"战争","pinyin":"zhànzhēng","hanViet":"CHIẾN TRANH","meaning":"war","pos":"Danh từ","example":{"zh":"国家避免战争。","pinyinPerChar":[{"c":"国","py":"guó"},{"c":"家","py":"jiā"},{"c":"避","py":"bì"},{"c":"免","py":"miǎn"},{"c":"战","py":"zhàn"},{"c":"争","py":"zhēng"},{"c":"。","py":"。"}],"vi":"Quốc gia tránh chiến tranh."}},{"hanzi":"战士","pinyin":"zhànshì","hanViet":"CHIẾN SĨ","meaning":"chiến sĩ","pos":"Danh từ","example":{"zh":"战士英勇作战。","pinyinPerChar":[{"c":"战","py":"zhàn"},{"c":"士","py":"shì"},{"c":"英","py":"yīng"},{"c":"勇","py":"yǒng"},{"c":"作","py":"zuò"},{"c":"战","py":"zhàn"},{"c":"。","py":"。"}],"vi":"Chiến sĩ kiệt sức chiến đấu."}},{"hanzi":"打扫","pinyin":"dǎsǎo","hanViet":"ĐẢ TẢO","meaning":"dọn dẹp","pos":"Động từ","example":{"zh":"我打扫房间。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"打","py":"dǎ"},{"c":"扫","py":"sǎo"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Tôi dọn phòng."}},{"hanzi":"扫","pinyin":"sǎo","hanViet":"TẢO","meaning":"dọn dẹp, lau","pos":"Động từ","example":{"zh":"我扫地。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"扫","py":"sǎo"},{"c":"地","py":"dì"},{"c":"。","py":"。"}],"vi":"Tôi dọn nhà vệ sinh."}},{"hanzi":"抄","pinyin":"chāo","hanViet":"SAO","meaning":"chép, sao chép","pos":"Động từ","example":{"zh":"请抄写这个字。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"抄","py":"chāo"},{"c":"写","py":"xiě"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Xin hãy chép chữ này."}},{"hanzi":"投诉","pinyin":"tóusù","hanViet":"ĐẦU TỐ","meaning":"nghị vụ, khiếu nại","pos":"Động từ","example":{"zh":"顾客向公司投诉了服务。","pinyinPerChar":[{"c":"顾","py":"gù"},{"c":"客","py":"kè"},{"c":"向","py":"xiàng"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"投","py":"tóu"},{"c":"诉","py":"sù"},{"c":"了","py":"le"},{"c":"服","py":"fú"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Khách hàng đã khiếu nại dịch vụ của công ty."}},{"hanzi":"投资","pinyin":"tóuzī","hanViet":"ĐẦU TƯ","meaning":"đầu tư","pos":"Động từ","example":{"zh":"他们投资了新项目。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"投","py":"tóu"},{"c":"资","py":"zī"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"项","py":"xiàng"},{"c":"目","py":"mù"},{"c":"。","py":"。"}],"vi":"Họ đã đầu tư vào dự án mới."}},{"hanzi":"担任","pinyin":"dānrèn","hanViet":"ĐẢM NHIỆM","meaning":"gán