INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-37', 36, 'Bổ sung (8)', '[{"hanzi":"标志","pinyin":"biāozhì","hanViet":"TIÊU CHÍ","meaning":"dấu hiệu, biểu tượng","pos":"Danh từ","example":{"zh":"这是一个安全标志。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"安","py":"ān"},{"c":"全","py":"quán"},{"c":"标","py":"biāo"},{"c":"志","py":"zhì"},{"c":"。","py":"。"}],"vi":"Đây là một biểu tượng an toàn."}},{"hanzi":"树叶","pinyin":"shùyè","hanViet":"THỤ DIỆP","meaning":"lá cây","pos":"Danh từ","example":{"zh":"树叶很绿。","pinyinPerChar":[{"c":"树","py":"shù"},{"c":"叶","py":"yè"},{"c":"很","py":"hěn"},{"c":"绿","py":"lǜ"},{"c":"。","py":"。"}],"vi":"Lá cây rất xanh."}},{"hanzi":"树林","pinyin":"shùlín","hanViet":"THỤ LÂM","meaning":"rừng, thung lũng cây cối","pos":"Danh từ","example":{"zh":"我们去树林里散步。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"树","py":"shù"},{"c":"林","py":"lín"},{"c":"里","py":"lǐ"},{"c":"散","py":"sàn"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi dạo trong rừng."}},{"hanzi":"根","pinyin":"gēn","hanViet":"CĂN","meaning":"cây, gốc","pos":"Danh từ","example":{"zh":"这棵树的根很深。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"棵","py":"kē"},{"c":"树","py":"shù"},{"c":"的","py":"de"},{"c":"根","py":"gēn"},{"c":"很","py":"hěn"},{"c":"深","py":"shēn"},{"c":"。","py":"。"}],"vi":"Cây này có gốc rất sâu."}},{"hanzi":"梦见","pinyin":"mèngjiàn","hanViet":"MỘNG KIẾN","meaning":"thấy trong giấc mơ","pos":"Động từ","example":{"zh":"昨晚我梦见你。","pinyinPerChar":[{"c":"昨","py":"zuó"},{"c":"晚","py":"wǎn"},{"c":"我","py":"wǒ"},{"c":"梦","py":"mèng"},{"c":"见","py":"jiàn"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Vừa qua tối tôi thấy bạn trong giấc mơ."}},{"hanzi":"棵","pinyin":"kē","hanViet":"KHOẢ","meaning":"cây, cột","pos":"Danh từ","example":{"zh":"一棵树。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"棵","py":"kē"},{"c":"树","py":"shù"},{"c":"。","py":"。"}],"vi":"M