INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-38', 37, 'Bổ sung (9)', '[{"hanzi":"登录","pinyin":"dēnglù","hanViet":"ĐĂNG LỤC","meaning":"đăng nhập","pos":"Động từ","example":{"zh":"登录这个网站需要输入密码。","pinyinPerChar":[{"c":"登","py":"dēng"},{"c":"录","py":"lù"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"网","py":"wǎng"},{"c":"站","py":"zhàn"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"输","py":"shū"},{"c":"入","py":"rù"},{"c":"密","py":"mì"},{"c":"码","py":"mǎ"},{"c":"。","py":"。"}],"vi":"Để đăng nhập vào trang web này cần nhập mật khẩu."}},{"hanzi":"的确","pinyin":"díquè","hanViet":"ĐÍCH XÁC","meaning":"quả thật, đúng là","pos":"Phó từ","example":{"zh":"他说的的确有道理，我们应该认真考虑。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"的","py":"de"},{"c":"的","py":"de"},{"c":"确","py":"què"},{"c":"有","py":"yǒu"},{"c":"道","py":"dào"},{"c":"理","py":"lǐ"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"认","py":"rèn"},{"c":"真","py":"zhēn"},{"c":"考","py":"kǎo"},{"c":"虑","py":"lǜ"},{"c":"。","py":"。"}],"vi":"Những gì anh ấy nói quả thật có lý, chúng ta nên cân nhắc kỹ."}},{"hanzi":"相反","pinyin":"xiāngfǎn","hanViet":"TƯƠNG PHẢN","meaning":"ngược lại","pos":"Liên từ","example":{"zh":"他不来，我就去。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"来","py":"lái"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"就","py":"jiù"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Anh ấy không đến, tôi sẽ đi."}},{"hanzi":"相处","pinyin":"xiāngchǔ","hanViet":"TƯƠNG XỨ","meaning":"giao tiếp, sống chung, đối xử với nhau","pos":"Động từ","example":{"zh":"他们相处很好。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"相","py":"xiāng"},{"c":"处","py":"chù"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Họ đối xử với nhau rất tốt."}},{"hanzi":"相片","pinyin":"xiàngpiàn","hanViet":"TƯƠNG PHIẾN","meaning":"bức ảnh, hình ảnh","pos":"Danh từ","example":{"zh":"她照了很多相片。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"照","py":"zhào"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"相","py":"xiāng"},{"c":"片","py":"piàn"},{"c":"。","py":"。"}],"vi":"Cô ấy chụp nhiều bức ảnh."}},{"hanzi":"眼镜","pinyin":"yǎnjìng","hanViet":"NHÃN KÍNH","meaning":"kính","pos":"Danh từ","example":{"zh":"他戴眼镜。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"戴","py":"dài"},{"c":"眼","py":"yǎn"},{"c":"镜","py":"jìng"},{"c":"。","py":"。"}],"vi":"Anh ấy đeo kính."}},{"hanzi":"着火","pinyin":"zháohuǒ","hanViet":"TRỨ HOẢ","meaning":"bắt lửa, cháy","pos":"Động từ","example":{"zh":"房间着火了。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"着","py":"zhe"},{"c":"火","py":"huǒ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Phòng đang cháy."}},{"hanzi":"研制","pinyin":"yánzhì","hanViet":"NGHIÊN CHẾ","meaning":"phát triển, chế tạo","pos":"Động từ","example":{"zh":"他们正在研制新药。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"研","py":"yán"},{"c":"制","py":"zhì"},{"c":"新","py":"xīn"},{"c":"药","py":"yào"},{"c":"。","py":"。"}],"vi":"Họ đang phát triển thuốc mới."}},{"hanzi":"研究生","pinyin":"yánjiūshēng","hanViet":"NGHIÊN CỨU SINH","meaning":"sinh viên sau đại học","pos":"Danh từ","example":{"zh":"他是研究生。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"研","py":"yán"},{"c":"究","py":"jiū"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Anh ấy là sinh viên sau đại học."}},{"hanzi":"确认","pinyin":"quèrèn","hanViet":"XÁC NHẬN","meaning":"xác nhận","pos":"Động từ","example":{"zh":"请确认你的名字。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"确","py":"què"},{"c":"认","py":"rèn"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"名","py":"míng"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Vui lòng xác nhận tên của bạn."}},{"hanzi":"种","pinyin":"zhòng","hanViet":"CHỦNG","meaning":"Loại, giống","pos":"Danh từ","example":{"zh":"这种花很漂亮。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"种","py":"zhǒng"},{"c":"花","py":"huā"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Loại hoa này rất đẹp."}},{"hanzi":"种类","pinyin":"zhǒnglèi","hanViet":"CHỦNG LOẠI","meaning":"Loại, loại hình","pos":"Danh từ","example":{"zh":"这有很多种类。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"种","py":"zhǒng"},{"c":"类","py":"lèi"},{"c":"。","py":"。"}],"vi":"Đây có nhiều loại."}},{"hanzi":"移民","pinyin":"yímín","hanViet":"DI DÂN","meaning":"di cư, nhập cư","pos":"Danh từ","example":{"zh":"他决定移民到Canada。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"决","py":"jué"},{"c":"定","py":"dìng"},{"c":"移","py":"yí"},{"c":"民","py":"mín"},{"c":"到","py":"dào"},{"c":"C","py":"C"},{"c":"a","py":"a"},{"c":"n","py":"n"},{"c":"a","py":"a"},{"c":"d","py":"d"},{"c":"a","py":"a"},{"c":"。","py":"。"}],"vi":"Anh ấy quyết định di cư đến Canada."}},{"hanzi":"童年","pinyin":"tóngnián","hanViet":"ĐỒNG NIÊN","meaning":"thời thơ ấu","pos":"Danh từ","example":{"zh":"他一直怀念自己的童年。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"一","py":"yī"},{"c":"直","py":"zhí"},{"c":"怀","py":"huái"},{"c":"念","py":"niàn"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"童","py":"tóng"},{"c":"年","py":"nián"},{"c":"。","py":"。"}],"vi":"Anh ấy vẫn nhớ lại thời thơ ấu của mình."}},{"hanzi":"符号","pinyin":"fúhào","hanViet":"PHÙ HIỆU","meaning":"ký hiệu, biểu tượng","pos":"Danh từ","example":{"zh":"这是一个符号。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"符","py":"fú"},{"c":"号","py":"hào"},{"c":"。","py":"。"}],"vi":"Đây là một ký hiệu."}},{"hanzi":"箱","pinyin":"xiāng","hanViet":"RƯƠNG","meaning":"hộp, thùng","pos":"Danh từ","example":{"zh":"箱子很大。","pinyinPerChar":[{"c":"箱","py":"xiāng"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Hộp này rất lớn."}},{"hanzi":"箱子","pinyin":"xiāngzi","hanViet":"RƯƠNG TỬ","meaning":"hộp, thùng","pos":"Danh từ","example":{"zh":"把箱子放好。","pinyinPerChar":[{"c":"把","py":"bǎ"},{"c":"箱","py":"xiāng"},{"c":"子","py":"zi"},{"c":"放","py":"fàng"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Hãy đặt hộp này lên chỗ."}},{"hanzi":"类型","pinyin":"lèixíng","hanViet":"LOẠI HÌNH","meaning":"loại, hình thức, kiểu","pos":"Danh từ","example":{"zh":"这个问题有很多类型。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"类","py":"lèi"},{"c":"型","py":"xíng"},{"c":"。","py":"。"}],"vi":"Câu hỏi này có nhiều loại."}},{"hanzi":"粗","pinyin":"cū","hanViet":"THÔ","meaning":"thô, xấu","pos":"Tính từ","example":{"zh":"这条裤子很粗。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"裤","py":"kù"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"粗","py":"cū"},{"c":"。","py":"。"}],"vi":"Quần này rất thô."}},{"hanzi":"粗心","pinyin":"cūxīn","hanViet":"THÔ TÂM","meaning":"vô tình, thiếu cẩn thận","pos":"Tính từ","example":{"zh":"他做事很粗心。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"做","py":"zuò"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"粗","py":"cū"},{"c":"心","py":"xīn"},{"c":"。","py":"。"}],"vi":"Anh ấy làm việc rất thiếu cẩn thận."}},{"hanzi":"纷纷","pinyin":"fēnfēn","hanViet":"PHÂN PHÂN","meaning":"nhiều, rối bời","pos":"Tính từ","example":{"zh":"人们纷纷走进图书馆。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"们","py":"men"},{"c":"纷","py":"fēn"},{"c":"纷","py":"fēn"},{"c":"走","py":"zǒu"},{"c":"进","py":"jìn"},{"c":"图","py":"tú"},{"c":"书","py":"shū"},{"c":"馆","py":"guǎn"},{"c":"。","py":"。"}],"vi":"Người ta nhiều người chạy vào thư viện."}},{"hanzi":"细","pinyin":"xì","hanViet":"TẾ","meaning":"lành, nhỏ xíu, chi tiết","pos":"Tính từ","example":{"zh":"这条路很细。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"路","py":"lù"},{"c":"很","py":"hěn"},{"c":"细","py":"xì"},{"c":"。","py":"。"}],"vi":"Con đường này rất nhỏ."}},{"hanzi":"细致","pinyin":"xìzhì","hanViet":"TẾ TRÍ","meaning":"lành, tỉ mỉ, chi tiết","pos":"Tính từ","example":{"zh":"她做事很细致。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"做","py":"zuò"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"细","py":"xì"},{"c":"致","py":"zhì"},{"c":"。","py":"。"}],"vi":"Cô ấy làm việc rất tỉ mỉ."}},{"hanzi":"细节","pinyin":"xìjié","hanViet":"TẾ TIẾT","meaning":"chi tiết","pos":"Danh từ","example":{"zh":"他很注意细节。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"注","py":"zhù"},{"c":"意","py":"yì"},{"c":"细","py":"xì"},{"c":"节","py":"jié"},{"c":"。","py":"。"}],"vi":"Anh ấy rất chú ý đến những chi tiết."}},{"hanzi":"结","pinyin":"jié","hanViet":"KẾT","meaning":"nối, gắn, kết thúc","pos":"Động từ","example":{"zh":"他们结婚了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"结","py":"jié"},{"c":"婚","py":"hūn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Họ đã kết hôn."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-39', 38, 'Bổ sung (10)', '[{"hanzi":"统一","pinyin":"tǒngyī","hanViet":"THỐNG NHẤT","meaning":"đồng nhất, thống nhất","pos":"Tính từ","example":{"zh":"请把这些字写统一。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"这","py":"zhè"},{"c":"些","py":"xiē"},{"c":"字","py":"zì"},{"c":"写","py":"xiě"},{"c":"统","py":"tǒng"},{"c":"一","py":"yī"},{"c":"。","py":"。"}],"vi":"Xin hãy viết các chữ này đồng nhất."}},{"hanzi":"统计","pinyin":"tǒngjì","hanViet":"THỐNG KẾ","meaning":"thống kê, tính toán","pos":"Động từ","example":{"zh":"老师让我们统计作业数量。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"让","py":"ràng"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"统","py":"tǒng"},{"c":"计","py":"jì"},{"c":"作","py":"zuò"},{"c":"业","py":"yè"},{"c":"数","py":"shù"},{"c":"量","py":"liàng"},{"c":"。","py":"。"}],"vi":"Giáo viên yêu cầu chúng ta thống kê số lượng bài tập."}},{"hanzi":"维护","pinyin":"wéihù","hanViet":"DUY HỘ","meaning":"bảo vệ, bảo trì","pos":"Động từ","example":{"zh":"他维护法律。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"维","py":"wéi"},{"c":"护","py":"hù"},{"c":"法","py":"fǎ"},{"c":"律","py":"lǜ"},{"c":"。","py":"。"}],"vi":"Anh ấy bảo vệ pháp luật."}},{"hanzi":"维持","pinyin":"wéichí","hanViet":"DUY TRÌ","meaning":"duy trì, giữ vững","pos":"Động từ","example":{"zh":"我们要维持和平。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"维","py":"wéi"},{"c":"持","py":"chí"},{"c":"和","py":"hé"},{"c":"平","py":"píng"},{"c":"。","py":"。"}],"vi":"Chúng tôi cần duy trì hòa bình."}},{"hanzi":"缓解","pinyin":"huǎnjiě","hanViet":"HOÃN GIẢI","meaning":"làm giảm, làm dịu","pos":"Động từ","example":{"zh":"药可以缓解疼痛。","pinyinPerChar":[{"c":"药","py":"yào"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"缓","py":"huǎn"},{"c":"解","py":"jiě"},{"c":"疼","py":"téng"},{"c":"痛","py":"tòng"},{"c":"。","py":"。"}],"vi":"Thuốc có thể làm giảm đau."}},{"hanzi":"编","pinyin":"biān","hanViet":"BIÊN","meaning":"sắp xếp, gộp, viết","pos":"Động từ","example":{"zh":"他正在编故事。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"编","py":"biān"},{"c":"故","py":"gù"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Anh ấy đang viết truyện."}},{"hanzi":"缩小","pinyin":"suōxiǎo","hanViet":"SÚC TIỂU","meaning":"giảm, thu nhỏ","pos":"Động từ","example":{"zh":"地图缩小了。","pinyinPerChar":[{"c":"地","py":"dì"},{"c":"图","py":"tú"},{"c":"缩","py":"suō"},{"c":"小","py":"xiǎo"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Bản đồ đã thu nhỏ."}},{"hanzi":"网址","pinyin":"wǎngzhǐ","hanViet":"VÕNG CHỈ","meaning":"địa chỉ web","pos":"Danh từ","example":{"zh":"请输入网址。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"输","py":"shū"},{"c":"入","py":"rù"},{"c":"网","py":"wǎng"},{"c":"址","py":"zhǐ"},{"c":"。","py":"。"}],"vi":"Hãy nhập địa chỉ web."}},{"hanzi":"网络","pinyin":"wǎngluò","hanViet":"VÕNG LẠC","meaning":"mạng","pos":"Danh từ","example":{"zh":"我每天上网。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"上","py":"shàng"},{"c":"网","py":"wǎng"},{"c":"。","py":"。"}],"vi":"Tôi truy cập mạng mỗi ngày."}},{"hanzi":"美女","pinyin":"měinǚ","hanViet":"MỸ","meaning":"người phụ nữ đẹp","pos":"Danh từ","example":{"zh":"她是个美女。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"是","py":"shì"},{"c":"个","py":"gè"},{"c":"美","py":"měi"},{"c":"女","py":"nǚ"},{"c":"。","py":"。"}],"vi":"Cô ấy là một người phụ nữ đẹp."}},{"hanzi":"而","pinyin":"ér","hanViet":"NHI","meaning":"và, nhưng, song","pos":"Liên từ","example":{"zh":"他想学习，而我想工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"想","py":"xiǎng"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"，","py":"，"},{"c":"而","py":"ér"},{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Anh ấy muốn học, còn tôi muốn làm việc."}},{"hanzi":"聚","pinyin":"jù","hanViet":"TỤ","meaning":"tụ tập, gặp gỡ","pos":"Động từ","example":{"zh":"朋友们聚在一起。","pinyinPerChar":[{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"们","py":"men"},{"c":"聚","py":"jù"},{"c":"在","py":"zài"},{"c":"一","py":"yī"},{"c":"起","py":"qǐ"},{"c":"。","py":"。"}],"vi":"Các bạn gặp nhau ở một nơi."}},{"hanzi":"聚会","pinyin":"jùhuì","hanViet":"TỤ HỘI","meaning":"tiệc tùng, buổi gặp gỡ","pos":"Danh từ","example":{"zh":"我们周末去聚会。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"周","py":"zhōu"},{"c":"末","py":"mò"},{"c":"去","py":"qù"},{"c":"聚","py":"jù"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi chơi buổi tối cuối tuần."}},{"hanzi":"肥","pinyin":"féi","hanViet":"PHÌ","meaning":"Dày, béo, mỡ","pos":"Tính từ","example":{"zh":"这只猫很肥。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"只","py":"zhǐ"},{"c":"猫","py":"māo"},{"c":"很","py":"hěn"},{"c":"肥","py":"féi"},{"c":"。","py":"。"}],"vi":"Con mèo này rất béo."}},{"hanzi":"能干","pinyin":"nénggàn","hanViet":"NĂNG CÁN","meaning":"kiên nhẫn, giỏi việc","pos":"Tính từ","example":{"zh":"她很能干。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"很","py":"hěn"},{"c":"能","py":"néng"},{"c":"干","py":"gàn"},{"c":"。","py":"。"}],"vi":"Cô ấy rất giỏi việc."}},{"hanzi":"腰","pinyin":"yāo","hanViet":"YÊU","meaning":"cổ, lưng, eo","pos":"Danh từ","example":{"zh":"他腰疼。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"腰","py":"yāo"},{"c":"疼","py":"téng"},{"c":"。","py":"。"}],"vi":"Anh ấy đau lưng."}},{"hanzi":"自","pinyin":"zì","hanViet":"TỰ","meaning":"tự, bản thân","pos":"Đại từ","example":{"zh":"他自己做了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"做","py":"zuò"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy làm việc đó bản thân."}},{"hanzi":"良好","pinyin":"liánghǎo","hanViet":"LƯƠNG HẢO","meaning":"tốt, thuận lợi, tốt đẹp","pos":"Tính từ","example":{"zh":"天气很好。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Thời tiết rất tốt."}},{"hanzi":"节省","pinyin":"jiéshěng","hanViet":"TIẾT TỈNH","meaning":"tiết kiệm, dùng ít hơn","pos":"Động từ","example":{"zh":"我们应该节省水和电。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"节","py":"jié"},{"c":"省","py":"shěng"},{"c":"水","py":"shuǐ"},{"c":"和","py":"hé"},{"c":"电","py":"diàn"},{"c":"。","py":"。"}],"vi":"Chúng ta nên tiết kiệm nước và điện."}},{"hanzi":"英勇","pinyin":"yīngyǒng","hanViet":"ANH DŨNG","meaning":"dũng cảm, xứng đáng ca ngợi","pos":"Tính từ","example":{"zh":"Anh ấy là người quân nhân rất英勇。","pinyinPerChar":[{"c":"A","py":"A"},{"c":"n","py":"n"},{"c":"h","py":"h"},{"c":" ","py":" "},{"c":"ấ","py":"ấ"},{"c":"y","py":"y"},{"c":" ","py":" "},{"c":"l","py":"l"},{"c":"à","py":"à"},{"c":" ","py":" "},{"c":"n","py":"n"},{"c":"g","py":"g"},{"c":"ư","py":"ư"},{"c":"ờ","py":"ờ"},{"c":"i","py":"i"},{"c":" ","py":" "},{"c":"q","py":"q"},{"c":"u","py":"u"},{"c":"â","py":"â"},{"c":"n","py":"n"},{"c":" ","py":" "},{"c":"n","py":"n"},{"c":"h","py":"h"},{"c":"â","py":"â"},{"c":"n","py":"n"},{"c":" ","py":" "},{"c":"r","py":"r"},{"c":"ấ","py":"ấ"},{"c":"t","py":"t"},{"c":"英","py":"yīng"},{"c":"勇","py":"yǒng"},{"c":"。","py":"。"}],"vi":"Anh ấy là người lính rất dũng cảm."}},{"hanzi":"药物","pinyin":"yàowù","hanViet":"DƯỢC VẬT","meaning":"thuốc, chất dược","pos":"Danh từ","example":{"zh":"医生开了药物。","pinyinPerChar":[{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"开","py":"kāi"},{"c":"了","py":"le"},{"c":"药","py":"yào"},{"c":"物","py":"wù"},{"c":"。","py":"。"}],"vi":"Bác sĩ kê toa thuốc."}},{"hanzi":"获","pinyin":"huò","hanViet":"HOẠCH","meaning":"thu được, giành được","pos":"Động từ","example":{"zh":"他获奖了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"获","py":"huò"},{"c":"奖","py":"jiǎng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đã giành giải."}},{"hanzi":"获取","pinyin":"huòqǔ","hanViet":"HOẠCH THỦ","meaning":"nhận được, thu thập được","pos":"Động từ","example":{"zh":"他获取了新知识。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"获","py":"huò"},{"c":"取","py":"qǔ"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"知","py":"zhī"},{"c":"识","py":"shí"},{"c":"。","py":"。"}],"vi":"Anh ấy nhận được kiến thức mới."}},{"hanzi":"虫子","pinyin":"chóngzi","hanViet":"TRÙNG TỬ","meaning":"con sâu, côn trùng","pos":"Danh từ","example":{"zh":"房间里有很多虫子。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"虫","py":"chóng"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Phòng có nhiều côn trùng."}},{"hanzi":"被迫","pinyin":"bèipò","hanViet":"BỊ BÁCH","meaning":"bị ép buộc","pos":"Tính từ","example":{"zh":"他被迫离开了公司。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"被","py":"bèi"},{"c":"迫","py":"pò"},{"c":"离","py":"lí"},{"c":"开","py":"kāi"},{"c":"了","py":"le"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"。","py":"。"}],"vi":"Anh ấy bị ép phải rời công ty."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-40', 39, 'Bổ sung (11)', '[{"hanzi":"装置","pinyin":"zhuāngzhì","hanViet":"TRANG TRÍ","meaning":"thiết bị, cỗ máy, cài đặt","pos":"Danh từ","example":{"zh":"这个装置很复杂。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"装","py":"zhuāng"},{"c":"置","py":"zhì"},{"c":"很","py":"hěn"},{"c":"复","py":"fù"},{"c":"杂","py":"zá"},{"c":"。","py":"。"}],"vi":"Cỗ máy này rất phức tạp."}},{"hanzi":"西瓜","pinyin":"xīguā","hanViet":"TÂY QUA","meaning":"dưa hấu","pos":"Danh từ","example":{"zh":"我喜欢西瓜。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"西","py":"xī"},{"c":"瓜","py":"guā"},{"c":"。","py":"。"}],"vi":"Tôi thích dưa hấu."}},{"hanzi":"要","pinyin":"yào","hanViet":"YẾU","meaning":"phải, cần","pos":"Động từ","example":{"zh":"你要努力。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"要","py":"yào"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"。","py":"。"}],"vi":"Bạn phải cố gắng."}},{"hanzi":"规则","pinyin":"guīzé","hanViet":"QUY TẮC","meaning":"quy tắc","pos":"Danh từ","example":{"zh":"请遵守规则。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"遵","py":"zūn"},{"c":"守","py":"shǒu"},{"c":"规","py":"guī"},{"c":"则","py":"zé"},{"c":"。","py":"。"}],"vi":"Hãy tuân thủ quy tắc."}},{"hanzi":"规律","pinyin":"guīlǜ","hanViet":"QUY LUẬT","meaning":"quy luật, quy trình","pos":"Danh từ","example":{"zh":"生活有规律。","pinyinPerChar":[{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"有","py":"yǒu"},{"c":"规","py":"guī"},{"c":"律","py":"lǜ"},{"c":"。","py":"。"}],"vi":"Cuộc sống có quy luật."}},{"hanzi":"诗","pinyin":"shī","hanViet":"THI","meaning":"thơ","pos":"Danh từ","example":{"zh":"他写了一首诗。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"写","py":"xiě"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"首","py":"shǒu"},{"c":"诗","py":"shī"},{"c":"。","py":"。"}],"vi":"Anh ta viết một bài thơ."}},{"hanzi":"诚实","pinyin":"chéngshí","hanViet":"THÀNH THỰC","meaning":"thành thật, trung thực","pos":"Tính từ","example":{"zh":"他很诚实。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"诚","py":"chéng"},{"c":"实","py":"shí"},{"c":"。","py":"。"}],"vi":"Cậu ấy rất trung thực."}},{"hanzi":"语法","pinyin":"yǔfǎ","hanViet":"NGỮ PHÁP","meaning":"ngữ pháp","pos":"Danh từ","example":{"zh":"他学中文语法很认真。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"学","py":"xué"},{"c":"中","py":"zhōng"},{"c":"文","py":"wén"},{"c":"语","py":"yǔ"},{"c":"法","py":"fǎ"},{"c":"很","py":"hěn"},{"c":"认","py":"rèn"},{"c":"真","py":"zhēn"},{"c":"。","py":"。"}],"vi":"Anh ấy học ngữ pháp tiếng Trung rất cẩn thận."}},{"hanzi":"语音","pinyin":"yǔyīn","hanViet":"NGỮ ÂM","meaning":"âm thanh, phát âm","pos":"Danh từ","example":{"zh":"这本书讲语音。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"讲","py":"jiǎng"},{"c":"语","py":"yǔ"},{"c":"音","py":"yīn"},{"c":"。","py":"。"}],"vi":"Cuốn sách này nói về âm thanh."}},{"hanzi":"误会","pinyin":"wùhuì","hanViet":"NGỘ HỘI","meaning":"sự hiểu lầm, sự nhầm lẫn","pos":"Danh từ","example":{"zh":"我们误会了。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"误","py":"wù"},{"c":"会","py":"huì"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Chúng tôi đã hiểu lầm nhau."}},{"hanzi":"货","pinyin":"huò","hanViet":"HOÁ","meaning":"hàng hóa, hàng hóa","pos":"Danh từ","example":{"zh":"这件货很贵。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"货","py":"huò"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Món hàng này đắt tiền."}},{"hanzi":"质量","pinyin":"zhìliàng","hanViet":"CHẤT LƯỢNG","meaning":"chất lượng","pos":"Danh từ","example":{"zh":"产品质量很好。","pinyinPerChar":[{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"质","py":"zhì"},{"c":"量","py":"liàng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chất lượng sản phẩm rất tốt."}},{"hanzi":"资料","pinyin":"zīliào","hanViet":"TƯ LIỆU","meaning":"tài liệu, dữ liệu","pos":"Danh từ","example":{"zh":"请把资料发给我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"资","py":"zī"},{"c":"料","py":"liào"},{"c":"发","py":"fā"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Hãy gửi tài liệu cho tôi."}},{"hanzi":"资源","pinyin":"zīyuán","hanViet":"TƯ NGUYÊN","meaning":"nguồn lực, tài nguyên","pos":"Danh từ","example":{"zh":"我们要保护自然资源。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"保","py":"bǎo"},{"c":"护","py":"hù"},{"c":"自","py":"zì"},{"c":"然","py":"rán"},{"c":"资","py":"zī"},{"c":"源","py":"yuán"},{"c":"。","py":"。"}],"vi":"Chúng ta phải bảo vệ tài nguyên thiên nhiên."}},{"hanzi":"赞助","pinyin":"zànzhù","hanViet":"TÁN TRỢ","meaning":"hỗ trợ tài chính","pos":"Động từ","example":{"zh":"他们赞助了学校的活动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"赞","py":"zàn"},{"c":"助","py":"zhù"},{"c":"了","py":"le"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"的","py":"de"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Họ hỗ trợ hoạt động của trường học."}},{"hanzi":"赢得","pinyin":"yíngdé","hanViet":"DOANH ĐẮC","meaning":"thắng, giành được","pos":"Động từ","example":{"zh":"他赢得比赛。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"赢","py":"yíng"},{"c":"得","py":"dé"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"。","py":"。"}],"vi":"Anh ấy giành chiến thắng trong cuộc thi."}},{"hanzi":"身份","pinyin":"shēnfèn","hanViet":"THÂN PHẦN","meaning":"chức vụ, danh tính, phẩm vị","pos":"Danh từ","example":{"zh":"他是老师这个身份。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"身","py":"shēn"},{"c":"份","py":"fèn"},{"c":"。","py":"。"}],"vi":"Anh ta là người giáo viên."}},{"hanzi":"轻易","pinyin":"qīngyì","hanViet":"KHINH DỊCH","meaning":"lạc lối, dễ dàng","pos":"Phó từ","example":{"zh":"他轻易没有成功。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"轻","py":"qīng"},{"c":"易","py":"yì"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Anh ấy không dễ dàng thành công."}},{"hanzi":"迅速","pinyin":"xùnsù","hanViet":"TẤN TỐC","meaning":"nhanh chóng","pos":"Tính từ","example":{"zh":"请迅速完成任务。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"迅","py":"xùn"},{"c":"速","py":"sù"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"任","py":"rèn"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Vui lòng hoàn thành nhiệm vụ nhanh chóng."}},{"hanzi":"过分","pinyin":"guòfèn","hanViet":"QUÁ PHÂN","meaning":"quá nhiều, vượt mức","pos":"Tính từ","example":{"zh":"他说话过分。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"话","py":"huà"},{"c":"过","py":"guò"},{"c":"分","py":"fēn"},{"c":"。","py":"。"}],"vi":"Cậu ta nói chuyện quá nhiều."}},{"hanzi":"运动会","pinyin":"yùndònghuì","hanViet":"VẬN ĐỘNG HỘI","meaning":"giải thể dục, hội thể dục","pos":"Danh từ","example":{"zh":"学校举行运动会。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"举","py":"jǔ"},{"c":"行","py":"xíng"},{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Trường học tổ chức giải thể dục."}},{"hanzi":"运动员","pinyin":"yùndòngyuán","hanViet":"VẬN ĐỘNG VIÊN","meaning":"thể thao viên","pos":"Danh từ","example":{"zh":"他是运动员。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"员","py":"yuán"},{"c":"。","py":"。"}],"vi":"Cậu ấy là vận động viên."}},{"hanzi":"运用","pinyin":"yùnyòng","hanViet":"VẬN DỤNG","meaning":"sử dụng, áp dụng","pos":"Động từ","example":{"zh":"老师运用游戏教学生。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"运","py":"yùn"},{"c":"用","py":"yòng"},{"c":"游","py":"yóu"},{"c":"戏","py":"xì"},{"c":"教","py":"jiào"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Giáo viên dùng trò chơi để dạy học sinh."}},{"hanzi":"进口","pinyin":"jìnkǒu","hanViet":"TIẾN KHẨU","meaning":"nhập khẩu, nhập","pos":"Danh từ","example":{"zh":"这个产品是进口的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"产","py":"chǎn"},{"c"