INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-1', 0, 'Gia đình & quan hệ (1)', '[{"hanzi":"岸","pinyin":"àn","hanViet":"NGẠN","meaning":"đáy sông, bờ","pos":"Danh từ","example":{"zh":"船停在岸边。","pinyinPerChar":[{"c":"船","py":"chuán"},{"c":"停","py":"tíng"},{"c":"在","py":"zài"},{"c":"岸","py":"àn"},{"c":"边","py":"biān"},{"c":"。","py":"。"}],"vi":"Tàu đậu ở bờ sông."}},{"hanzi":"拜访","pinyin":"bàifǎng","hanViet":"BÁI PHỎNG","meaning":"đến thăm, gặp","pos":"Động từ","example":{"zh":"我明天拜访老师。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"拜","py":"bài"},{"c":"访","py":"fǎng"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"。","py":"。"}],"vi":"Tôi mai tối đến thăm thầy cô."}},{"hanzi":"扮演","pinyin":"bànyǎn","hanViet":"BAN DIỄN","meaning":"đóng vai, biểu diễn","pos":"Động từ","example":{"zh":"他扮演主角。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"扮","py":"bàn"},{"c":"演","py":"yǎn"},{"c":"主","py":"zhǔ"},{"c":"角","py":"jiǎo"},{"c":"。","py":"。"}],"vi":"Anh ấy đóng vai chính."}},{"hanzi":"棒","pinyin":"bàng","hanViet":"BỔNG","meaning":"tuyệt vời, xuất sắc","pos":"Tính từ","example":{"zh":"这个主意很棒。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"主","py":"zhǔ"},{"c":"意","py":"yì"},{"c":"很","py":"hěn"},{"c":"棒","py":"bàng"},{"c":"。","py":"。"}],"vi":"Ý tưởng này rất tuyệt vời."}},{"hanzi":"保养","pinyin":"bǎoyǎng","hanViet":"BẢO DƯỠNG","meaning":"chăm sóc, bảo dưỡng","pos":"Động từ","example":{"zh":"他每天保养皮肤。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"保","py":"bǎo"},{"c":"养","py":"yǎng"},{"c":"皮","py":"pí"},{"c":"肤","py":"fū"},{"c":"。","py":"。"}],"vi":"Anh ấy mỗi ngày chăm sóc da."}},{"hanzi":"报答","pinyin":"bàodá","hanViet":"BÁO ĐÁP","meaning":"trả công, trả ơn","pos":"Động từ","example":{"zh":"我要报答他的帮助。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"报","py":"bào"},{"c":"答","py":"dá"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"。","py":"。"}],"vi":"Tôi sẽ trả công sự giúp đỡ của anh ấy."}},{"hanzi":"报警","pinyin":"bàojǐng","hanViet":"BÁO CẢNH","meaning":"thông báo cảnh báo","pos":"Động từ","example":{"zh":"他报警了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"报","py":"bào"},{"c":"警","py":"jǐng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đã báo cảnh báo."}},{"hanzi":"抱怨","pinyin":"bàoyuàn","hanViet":"BÃO OÁN","meaning":"than vãn, phàn nàn","pos":"Động từ","example":{"zh":"她抱怨工作太累。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"抱","py":"bào"},{"c":"怨","py":"yuàn"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"太","py":"tài"},{"c":"累","py":"lèi"},{"c":"。","py":"。"}],"vi":"Cô ấy than vãn công việc quá mệt."}},{"hanzi":"辈","pinyin":"bèi","hanViet":"BỐI","meaning":"thế hệ, thế hệ cùng cha mẹ","pos":"Danh từ","example":{"zh":"我们是同一辈。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"是","py":"shì"},{"c":"同","py":"tóng"},{"c":"一","py":"yī"},{"c":"辈","py":"bèi"},{"c":"。","py":"。"}],"vi":"Chúng tôi cùng thế hệ."}},{"hanzi":"宾馆","pinyin":"bīnguǎn","hanViet":"TÂN QUÁN","meaning":"nhà lưu trú, khách sạn","pos":"Danh từ","example":{"zh":"我住在市中心的宾馆里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"市","py":"shì"},{"c":"中","py":"zhōng"},{"c":"心","py":"xīn"},{"c":"的","py":"de"},{"c":"宾","py":"bīn"},{"c":"馆","py":"guǎn"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi ở trong khách sạn ở trung tâm thành phố."}},{"hanzi":"不顾","pinyin":"bùgù","hanViet":"BẤT CỐ","meaning":"không ngờ, không lưu ý","pos":"Động từ","example":{"zh":"他不顾危险继续前进。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"顾","py":"gù"},{"c":"危","py":"wēi"},{"c":"险","py":"xiǎn"},{"c":"继","py":"jì"},{"c":"续","py":"xù"},{"c":"前","py":"qián"},{"c":"进","py":"jìn"},{"c":"。","py":"。"}],"vi":"Anh ấy không ngờ nguy hiểm mà tiếp tục đi."}},{"hanzi":"不利","pinyin":"bùlì","hanViet":"BẤT LỢI","meaning":"không thuận lợi, bất lợi","pos":"Tính từ","example":{"zh":"这对我们不利。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"对","py":"duì"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"不","py":"bù"},{"c":"利","py":"lì"},{"c":"。","py":"。"}],"vi":"Điều này không thuận lợi cho chúng ta."}},{"hanzi":"不耐烦","pinyin":"bù nàifán","hanViet":"BẤT NẠI PHIỀN","meaning":"bực bội, khó chịu","pos":"Tính từ","example":{"zh":"他不耐烦等人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"耐","py":"nài"},{"c":"烦","py":"fán"},{"c":"等","py":"děng"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Anh ấy bực bội chờ người khác."}},{"hanzi":"不幸","pinyin":"bùxìng","hanViet":"BẤT HẠNH","meaning":"xui xẻo, không may","pos":"Tính từ","example":{"zh":"他不幸失业了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"幸","py":"xìng"},{"c":"失","py":"shī"},{"c":"业","py":"yè"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy không may bị thất nghiệp."}},{"hanzi":"不易","pinyin":"bùyì","hanViet":"BẤT DỊCH","meaning":"khó, không dễ dàng","pos":"Tính từ","example":{"zh":"这件事不易完成。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"不","py":"bù"},{"c":"易","py":"yì"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"。","py":"。"}],"vi":"Việc này không dễ dàng hoàn thành."}},{"hanzi":"不良","pinyin":"bùliáng","hanViet":"BẤT LƯƠNG","meaning":"xấu, không tốt","pos":"Tính từ","example":{"zh":"他有不良习惯。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"不","py":"bù"},{"c":"良","py":"liáng"},{"c":"习","py":"xí"},{"c":"惯","py":"guàn"},{"c":"。","py":"。"}],"vi":"Cậu ấy có thói quen xấu."}},{"hanzi":"不免","pinyin":"bùmiǎn","hanViet":"BẤT MIỄN","meaning":"không tránh khỏi, không thể không","pos":"Phó từ","example":{"zh":"这件事不免让人难过。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"不","py":"bù"},{"c":"免","py":"miǎn"},{"c":"让","py":"ràng"},{"c":"人","py":"rén"},{"c":"难","py":"nán"},{"c":"过","py":"guò"},{"c":"。","py":"。"}],"vi":"Việc này không tránh khỏi khiến người ta buồn."}},{"hanzi":"不能不","pinyin":"bù néng bù","hanViet":"BẤT NĂNG BẤT","meaning":"không thể không, bắt buộc phải","pos":"Động từ","example":{"zh":"我不能不关心这件事。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"能","py":"néng"},{"c":"不","py":"bù"},{"c":"关","py":"guān"},{"c":"心","py":"xīn"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Tôi không thể không quan tâm việc này."}},{"hanzi":"不停","pinyin":"bù tíng","hanViet":"BẤT ĐÌNH","meaning":"liên tục, không dừng lại","pos":"Động từ","example":{"zh":"风不停地吹。","pinyinPerChar":[{"c":"风","py":"fēng"},{"c":"不","py":"bù"},{"c":"停","py":"tíng"},{"c":"地","py":"dì"},{"c":"吹","py":"chuī"},{"c":"。","py":"。"}],"vi":"Gió không ngừng thổi."}},{"hanzi":"不许","pinyin":"bùxǔ","hanViet":"BẤT HỨA","meaning":"không được phép","pos":"Động từ","example":{"zh":"妈妈不许我晚回家。","pinyinPerChar":[{"c":"妈","py":"mā"},{"c":"妈","py":"mā"},{"c":"不","py":"bù"},{"c":"许","py":"xǔ"},{"c":"我","py":"wǒ"},{"c":"晚","py":"wǎn"},{"c":"回","py":"huí"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Mẹ không cho tôi về muộn nhà."}},{"hanzi":"不止","pinyin":"bùzhǐ","hanViet":"BẤT CHỈ","meaning":"nhiều hơn, không chỉ","pos":"Tính từ","example":{"zh":"这件事不止简单。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"不","py":"bù"},{"c":"止","py":"zhǐ"},{"c":"简","py":"jiǎn"},{"c":"单","py":"dān"},{"c":"。","py":"。"}],"vi":"Việc này không chỉ đơn giản."}},{"hanzi":"不足","pinyin":"bùzú","hanViet":"BẤT TÚC","meaning":"thiếu, không đủ","pos":"Tính từ","example":{"zh":"他的经验不足。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"经","py":"jīng"},{"c":"验","py":"yàn"},{"c":"不","py":"bù"},{"c":"足","py":"zú"},{"c":"。","py":"。"}],"vi":"Kinh nghiệm của cậu ấy không đủ."}},{"hanzi":"拆除","pinyin":"chāichú","hanViet":"SÁCH TRỪ","meaning":"tháo dỡ, phá hủy","pos":"Động từ","example":{"zh":"他们拆除了旧建筑。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"拆","py":"chāi"},{"c":"除","py":"chú"},{"c":"了","py":"le"},{"c":"旧","py":"jiù"},{"c":"建","py":"jiàn"},{"c":"筑","py":"zhù"},{"c":"。","py":"。"}],"vi":"Họ đã tháo dỡ công trình cũ."}},{"hanzi":"产业","pinyin":"chǎnyè","hanViet":"SẢN NGHIỆP","meaning":"ngành nghề, công nghiệp","pos":"Danh từ","example":{"zh":"这个地区的产业很发达。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"地","py":"dì"},{"c":"区","py":"qū"},{"c":"的","py":"de"},{"c":"产","py":"chǎn"},{"c":"业","py":"yè"},{"c":"很","py":"hěn"},{"c":"发","py":"fā"},{"c":"达","py":"dá"},{"c":"。","py":"。"}],"vi":"Ngành nghề ở vùng này rất phát triển."}},{"hanzi":"场面","pinyin":"chǎngmiàn","hanViet":"TRƯỜNG DIỆN","meaning":"sự việc, bối cảnh, cảnh vật","pos":"Danh từ","example":{"zh":"现场的场面很热闹。","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"场","py":"chǎng"},{"c":"的","py":"de"},{"c":"场","py":"chǎng"},{"c":"面","py":"miàn"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"闹","py":"nào"},{"c":"。","py":"。"}],"vi":"Sự kiện tại chỗ rất vui tươi."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-2', 1, 'Gia đình & quan hệ (2)', '[{"hanzi":"成交","pinyin":"chéngjiāo","hanViet":"THÀNH GIAO","meaning":"thành công, giao dịch thành công","pos":"Động từ","example":{"zh":"他们成交了交易。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"成","py":"chéng"},{"c":"交","py":"jiāo"},{"c":"了","py":"le"},{"c":"交","py":"jiāo"},{"c":"易","py":"yì"},{"c":"。","py":"。"}],"vi":"Họ đã thành công giao dịch."}},{"hanzi":"乘客","pinyin":"chéngkè","hanViet":"THỪA KHÁCH","meaning":"người đi xe, hành khách","pos":"Danh từ","example":{"zh":"乘客们在车上。","pinyinPerChar":[{"c":"乘","py":"chéng"},{"c":"客","py":"kè"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"车","py":"chē"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Hành khách đang trên xe."}},{"hanzi":"冲动","pinyin":"chōngdòng","hanViet":"XUNG ĐỘNG","meaning":"cảm giác bốc đồng, ham muốn","pos":"Danh từ","example":{"zh":"他有冲动买新车。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"冲","py":"chōng"},{"c":"动","py":"dòng"},{"c":"买","py":"mǎi"},{"c":"新","py":"xīn"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Anh ấy có cảm giác ham muốn mua xe mới."}},{"hanzi":"出差","pinyin":"chūchāi","hanViet":"XUẤT SAI","meaning":"đi công tác","pos":"Động từ","example":{"zh":"他今天出差去北京。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"出","py":"chū"},{"c":"差","py":"chà"},{"c":"去","py":"qù"},{"c":"北","py":"běi"},{"c":"京","py":"jīng"},{"c":"。","py":"。"}],"vi":"Anh ấy đi công tác hôm nay đến Bắc Kinh."}},{"hanzi":"除非","pinyin":"chúfēi","hanViet":"TRỪ PHI","meaning":"nếu không…thì không","pos":"Liên từ","example":{"zh":"除非你道歉，他才会原谅你。","pinyinPerChar":[{"c":"除","py":"chú"},{"c":"非","py":"fēi"},{"c":"你","py":"nǐ"},{"c":"道","py":"dào"},{"c":"歉","py":"qiàn"},{"c":"，","py":"，"},{"c":"他","py":"tā"},{"c":"才","py":"cái"},{"c":"会","py":"huì"},{"c":"原","py":"yuán"},{"c":"谅","py":"liàng"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Nếu không bạn xin lỗi, anh ấy sẽ không tha thứ bạn."}},{"hanzi":"厨房","pinyin":"chúfáng","hanViet":"TRÙ PHÒNG","meaning":"bếp","pos":"Danh từ","example":{"zh":"我在厨房做饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"厨","py":"chú"},{"c":"房","py":"fáng"},{"c":"做","py":"zuò"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi nấu ăn trong bếp."}},{"hanzi":"传递","pinyin":"chuándì","hanViet":"TRUYỀN ĐỆ","meaning":"truyền, gửi","pos":"Động từ","example":{"zh":"他传递了信息给大家。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"传","py":"chuán"},{"c":"递","py":"dì"},{"c":"了","py":"le"},{"c":"信","py":"xìn"},{"c":"息","py":"xī"},{"c":"给","py":"gěi"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Anh ấy đã truyền thông tin cho mọi người."}},{"hanzi":"辞职","pinyin":"cízhí","hanViet":"TỪ CHỨC","meaning":"nhượng chức, từ bỏ công việc","pos":"Động từ","example":{"zh":"他辞职了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"辞","py":"cí"},{"c":"职","py":"zhí"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đã nghỉ việc."}},{"hanzi":"打扰","pinyin":"dǎrǎo","hanViet":"ĐẢ NHIỄU","meaning":"làm phiền, gây khó chịu","pos":"Động từ","example":{"zh":"对不起，打扰你了。","pinyinPerChar":[{"c":"对","py":"duì"},{"c":"不","py":"bù"},{"c":"起","py":"qǐ"},{"c":"，","py":"，"},{"c":"打","py":"dǎ"},{"c":"扰","py":"rǎo"},{"c":"你","py":"nǐ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Xin lỗi, làm phiền bạn rồi."}},{"hanzi":"地带","pinyin":"dìdài","hanViet":"ĐỊA ĐỚI","meaning":"vùng, miền","pos":"Danh từ","example":{"zh":"这是一个美丽的地带。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"美","py":"měi"},{"c":"丽","py":"lì"},{"c":"的","py":"de"},{"c":"地","py":"dì"},{"c":"带","py":"dài"},{"c":"。","py":"。"}],"vi":"Đây là một vùng đẹp."}},{"hanzi":"地形","pinyin":"dìxíng","hanViet":"ĐỊA HÌNH","meaning":"địa hình","pos":"Danh từ","example":{"zh":"这里的地形很复杂。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"的","py":"de"},{"c":"地","py":"dì"},{"c":"形","py":"xíng"},{"c":"很","py":"hěn"},{"c":"复","py":"fù"},{"c":"杂","py":"zá"},{"c":"。","py":"。"}],"vi":"Địa hình ở đây rất phức tạp."}},{"hanzi":"递","pinyin":"dì","hanViet":"ĐỆ","meaning":"tặng, giao, đưa","pos":"Động từ","example":{"zh":"递给我一张纸。","pinyinPerChar":[{"c":"递","py":"dì"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"纸","py":"zhǐ"},{"c":"。","py":"。"}],"vi":"Giao cho tôi một tờ giấy."}},{"hanzi":"递给","pinyin":"dì gěi","hanViet":"ĐỆ CẤP","meaning":"tặng, giao cho","pos":"Động từ","example":{"zh":"他递给我一杯水。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"递","py":"dì"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"一","py":"yī"},{"c":"杯","py":"bēi"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy tặng tôi một cốc nước."}},{"hanzi":"典礼","pinyin":"diǎnlǐ","hanViet":"ĐIỂN LỄ","meaning":"lễ, nghi lễ, công bố","pos":"Danh từ","example":{"zh":"举行婚礼典礼。","pinyinPerChar":[{"c":"举","py":"jǔ"},{"c":"行","py":"xíng"},{"c":"婚","py":"hūn"},{"c":"礼","py":"lǐ"},{"c":"典","py":"diǎn"},{"c":"礼","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tổ chức lễ cưới."}},{"hanzi":"冻","pinyin":"dòng","hanViet":"ĐÔNG","meaning":"đóng băng, đông lạnh","pos":"Tính từ","example":{"zh":"天气冻了。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"冻","py":"dòng"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Thời tiết lạnh giá."}},{"hanzi":"儿女","pinyin":"érnǚ","hanViet":"NHI","meaning":"con cháu, con trai và con gái","pos":"Danh từ","example":{"zh":"他们有两个儿女。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"有","py":"yǒu"},{"c":"两","py":"liǎng"},{"c":"个","py":"gè"},{"c":"儿","py":"ér"},{"c":"女","py":"nǚ"},{"c":"。","py":"。"}],"vi":"Họ có hai con."}},{"hanzi":"发布","pinyin":"fābù","hanViet":"PHÁT BỐ","meaning":"thông báo, công bố","pos":"Động từ","example":{"zh":"公司发布了新产品。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"发","py":"fā"},{"c":"布","py":"bù"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Công ty công bố sản phẩm mới."}},{"hanzi":"负责人","pinyin":"fùzérén","hanViet":"PHỤ TRÁCH NHÂN","meaning":"người chịu trách nhiệm","pos":"Danh từ","example":{"zh":"请问负责人在哪里？","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"问","py":"wèn"},{"c":"负","py":"fù"},{"c":"责","py":"zé"},{"c":"人","py":"rén"},{"c":"在","py":"zài"},{"c":"哪","py":"nǎ"},{"c":"里","py":"lǐ"},{"c":"？","py":"？"}],"vi":"Xin hỏi người chịu trách nhiệm ở đâu?"}},{"hanzi":"工艺","pinyin":"gōngyì","hanViet":"CÔNG NGHỆ","meaning":"công nghệ, kỹ thuật, thủ công","pos":"Danh từ","example":{"zh":"这件工艺品很精美。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"工","py":"gōng"},{"c":"艺","py":"yì"},{"c":"品","py":"pǐn"},{"c":"很","py":"hěn"},{"c":"精","py":"jīng"},{"c":"美","py":"měi"},{"c":"。","py":"。"}],"vi":"Món trang sức này rất tinh xảo."}},{"hanzi":"公式","pinyin":"gōngshì","hanViet":"CÔNG THỨC","meaning":"công thức toán học hoặc quy tắc","pos":"Danh từ","example":{"zh":"这个公式很简单。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"公","py":"gōng"},{"c":"式","py":"shì"},{"c":"很","py":"hěn"},{"c":"简","py":"jiǎn"},{"c":"单","py":"dān"},{"c":"。","py":"。"}],"vi":"Công thức này rất đơn giản."}},{"hanzi":"公正","pinyin":"gōngzhèng","hanViet":"CÔNG CHÍNH","meaning":"công bằng, chính đáng","pos":"Tính từ","example":{"zh":"法官必须公正。","pinyinPerChar":[{"c":"法","py":"fǎ"},{"c":"官","py":"guān"},{"c":"必","py":"bì"},{"c":"须","py":"xū"},{"c":"公","py":"gōng"},{"c":"正","py":"zhèng"},{"c":"。","py":"。"}],"vi":"Công tụ phải công bằng."}},{"hanzi":"关怀","pinyin":"guānhuái","hanViet":"QUAN HOÀI","meaning":"quan tâm, chăm sóc","pos":"Danh từ","example":{"zh":"她对孩子很关怀。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"对","py":"duì"},{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"关","py":"guān"},{"c":"怀","py":"huái"},{"c":"。","py":"。"}],"vi":"Cô ấy rất quan tâm đến con."}},{"hanzi":"规划","pinyin":"guīhuà","hanViet":"QUY HOẠCH","meaning":"lên kế hoạch, bố trí","pos":"Động từ","example":{"zh":"我们需要规划未来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"规","py":"guī"},{"c":"划","py":"huà"},{"c":"未","py":"wèi"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Chúng tôi cần lên kế hoạch cho tương lai."}},{"hanzi":"国民","pinyin":"guómín","hanViet":"QUỐC DÂN","meaning":"người dân, công dân","pos":"Danh từ","example":{"zh":"国民应该遵守法律。","pinyinPerChar":[{"c":"国","py":"guó"},{"c":"民","py":"mín"},{"c":"应","py":"yīng"},{"c":"该","py":"gāi"},{"c":"遵","py":"zūn"},{"c":"守","py":"shǒu"},{"c":"法","py":"fǎ"},{"c":"律","py":"lǜ"},{"c":"。","py":"。"}],"vi":"Công dân nên tuân thủ pháp luật."}},{"hanzi":"贺卡","pinyin":"hèkǎ","hanViet":"HẠ CA","meaning":"thẻ chúc mừng","pos":"Danh từ","example":{"zh":"我送她一张贺卡。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"送","py":"sòng"},{"c":"她","py":"tā"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"贺","py":"hè"},{"c":"卡","py":"kǎ"},{"c":"。","py":"。"}],"vi":"Tôi gửi cho cô ấy một lá thư chúc mừng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-3', 2, 'Gia đình & quan hệ (3)', '[{"hanzi":"回报","pinyin":"huíbào","hanViet":"HỒI BÁO","meaning":"trả lại, báo đáp","pos":"Động từ","example":{"zh":"我要回报你的帮助。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"回","py":"huí"},{"c":"报","py":"bào"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"。","py":"。"}],"vi":"Tôi sẽ trả lại sự giúp đỡ của bạn."}},{"hanzi":"基地","pinyin":"jīdì","hanViet":"CƠ ĐỊA","meaning":"trung tâm, căn cứ","pos":"Danh từ","example":{"zh":"基地在山上。","pinyinPerChar":[{"c":"基","py":"jī"},{"c":"地","py":"dì"},{"c":"在","py":"zài"},{"c":"山","py":"shān"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Trung tâm ở trên núi."}},{"hanzi":"坚定","pinyin":"jiāndìng","hanViet":"KIÊN ĐỊNH","meaning":"kiên định, quyết đoán","pos":"Tính từ","example":{"zh":"他心里很坚定。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"心","py":"xīn"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"坚","py":"jiān"},{"c":"定","py":"dìng"},{"c":"。","py":"。"}],"vi":"Anh ấy rất kiên định trong tâm trí."}},{"hanzi":"键盘","pinyin":"jiànpán","hanViet":"KIỆN BÀN","meaning":"bàn phím","pos":"Danh từ","example":{"zh":"我每天用键盘打字。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"用","py":"yòng"},{"c":"键","py":"jiàn"},{"c":"盘","py":"pán"},{"c":"打","py":"dǎ"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Tôi dùng bàn phím gõ chữ mỗi ngày."}},{"hanzi":"解除","pinyin":"jiěchú","hanViet":"GIẢI TRỪ","meaning":"xóa bỏ, giải quyết","pos":"Động từ","example":{"zh":"我们解除紧张局势。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"解","py":"jiě"},{"c":"除","py":"chú"},{"c":"紧","py":"jǐn"},{"c":"张","py":"zhāng"},{"c":"局","py":"jú"},{"c":"势","py":"shì"},{"c":"。","py":"。"}],"vi":"Chúng ta giải quyết tình thế căng thẳng."}},{"hanzi":"局面","pinyin":"júmiàn","hanViet":"CỤC DIỆN","meaning":"bối cảnh, tình hình","pos":"Danh từ","example":