INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-8', 7, 'Ăn uống & ẩm thực (1)', '[{"hanzi":"白酒","pinyin":"báijiǔ","hanViet":"BẠCH TỬU","meaning":"rượu men tinh khiết","pos":"Danh từ","example":{"zh":"他喜欢喝白酒。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"喝","py":"hē"},{"c":"白","py":"bái"},{"c":"酒","py":"jiǔ"},{"c":"。","py":"。"}],"vi":"Anh ấy thích uống rượu trắng."}},{"hanzi":"饼","pinyin":"bǐng","hanViet":"BÁNH","meaning":"bánh, bánh mì, bánh xèo","pos":"Danh từ","example":{"zh":"他做的饼很好吃。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"做","py":"zuò"},{"c":"的","py":"de"},{"c":"饼","py":"bǐng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Bánh mà anh ấy làm rất ngon."}},{"hanzi":"饼干","pinyin":"bǐnggān","hanViet":"BÁNH CÁN","meaning":"bánh quy","pos":"Danh từ","example":{"zh":"我喜欢吃饼干。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"饼","py":"bǐng"},{"c":"干","py":"gàn"},{"c":"。","py":"。"}],"vi":"Tôi thích ăn bánh quy."}},{"hanzi":"裁判","pinyin":"cáipàn","hanViet":"TÀI PHÁN","meaning":"người điều hành, người phán xử","pos":"Danh từ","example":{"zh":"裁判宣布比赛结束。","pinyinPerChar":[{"c":"裁","py":"cái"},{"c":"判","py":"pàn"},{"c":"宣","py":"xuān"},{"c":"布","py":"bù"},{"c":"比","py":"bǐ"},{"c":"赛","py":"sài"},{"c":"结","py":"jié"},{"c":"束","py":"shù"},{"c":"。","py":"。"}],"vi":"Người điều hành tuyên bố trận đấu kết thúc."}},{"hanzi":"餐馆","pinyin":"cānguǎn","hanViet":"XAN QUÁN","meaning":"nhà hàng","pos":"Danh từ","example":{"zh":"我们去餐馆吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"去","py":"qù"},{"c":"餐","py":"cān"},{"c":"馆","py":"guǎn"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi nhà hàng ăn."}},{"hanzi":"餐厅","pinyin":"cāntīng","hanViet":"XAN SẢNH","meaning":"nhà hàng, quán ăn","pos":"Danh từ","example":{"zh":"他在餐厅工作。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"在","py":"zài"},{"c":"餐","py":"cān"},{"c":"厅","py":"tīng"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Cậu ấy làm việc ở nhà hàng."}},{"hanzi":"餐饮","pinyin":"cānyǐn","hanViet":"XAN ẨM","meaning":"đồ ăn, đồ uống","pos":"Danh từ","example":{"zh":"餐饮服务很重要。","pinyinPerChar":[{"c":"餐","py":"cān"},{"c":"饮","py":"yǐn"},{"c":"服","py":"fú"},{"c":"务","py":"wù"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Dịch vụ ăn uống rất quan trọng."}},{"hanzi":"差距","pinyin":"chājù","hanViet":"SAI CỰ","meaning":"khoảng cách, mức độ chênh lệch","pos":"Danh từ","example":{"zh":"他们在年龄上有很大差距。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"在","py":"zài"},{"c":"年","py":"nián"},{"c":"龄","py":"líng"},{"c":"上","py":"shàng"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"差","py":"chà"},{"c":"距","py":"jù"},{"c":"。","py":"。"}],"vi":"Họ có độ tuổi chênh lệch rất lớn."}},{"hanzi":"成效","pinyin":"chéngxiào","hanViet":"THÀNH HIỆU","meaning":"kết quả, hiệu quả","pos":"Danh từ","example":{"zh":"这个计划取得了成效。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"取","py":"qǔ"},{"c":"得","py":"dé"},{"c":"了","py":"le"},{"c":"成","py":"chéng"},{"c":"效","py":"xiào"},{"c":"。","py":"。"}],"vi":"Kế hoạch này đạt được kết quả."}},{"hanzi":"成语","pinyin":"chéngyǔ","hanViet":"THÀNH NGỮ","meaning":"câu thành ngữ","pos":"Danh từ","example":{"zh":"他说了一个成语。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"说","py":"shuō"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"成","py":"chéng"},{"c":"语","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Anh ấy nói một câu thành ngữ."}},{"hanzi":"城里","pinyin":"chénglǐ","hanViet":"THÀNH LÝ","meaning":"trong thành phố","pos":"Danh từ","example":{"zh":"我们住在城里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"城","py":"chéng"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Chúng tôi sống ở trong thành phố."}},{"hanzi":"吃力","pinyin":"chīlì","hanViet":"KHIẾT LỰC","meaning":"mắc khó khăn, mệt sức","pos":"Động từ","example":{"zh":"这件事吃力不讨好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"吃","py":"chī"},{"c":"力","py":"lì"},{"c":"不","py":"bù"},{"c":"讨","py":"tǎo"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Việc này khó khăn và không được tốt."}},{"hanzi":"臭","pinyin":"chòu","hanViet":"XÚ","meaning":"mùi hôi, xấu","pos":"Tính từ","example":{"zh":"这件衣服有点臭。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"有","py":"yǒu"},{"c":"点","py":"diǎn"},{"c":"臭","py":"chòu"},{"c":"。","py":"。"}],"vi":"Cái áo này hơi mùi hôi."}},{"hanzi":"处罚","pinyin":"chǔfá","hanViet":"XỨ PHẠT","meaning":"phạt, xử phạt","pos":"Động từ","example":{"zh":"老师处罚了他。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"处","py":"chù"},{"c":"罚","py":"fá"},{"c":"了","py":"le"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Giáo viên đã phạt anh ấy."}},{"hanzi":"创立","pinyin":"chuànglì","hanViet":"SÁNG LẬP","meaning":"thành lập, sáng lập","pos":"Động từ","example":{"zh":"他们创立了一家公司。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"创","py":"chuàng"},{"c":"立","py":"lì"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"家","py":"jiā"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"。","py":"。"}],"vi":"Họ đã thành lập một công ty."}},{"hanzi":"从而","pinyin":"cóng''ér","hanViet":"TÒNG NHI","meaning":"từ đó, do đó, để đạt kết quả","pos":"Liên từ","example":{"zh":"他努力学习，从而取得好成绩。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"努","py":"nǔ"},{"c":"力","py":"lì"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"，","py":"，"},{"c":"从","py":"cóng"},{"c":"而","py":"ér"},{"c":"取","py":"qǔ"},{"c":"得","py":"dé"},{"c":"好","py":"hǎo"},{"c":"成","py":"chéng"},{"c":"绩","py":"jì"},{"c":"。","py":"。"}],"vi":"Anh ấy học chăm chỉ, từ đó đạt được kết quả tốt."}},{"hanzi":"大纲","pinyin":"dàgāng","hanViet":"ĐẠI CƯƠNG","meaning":"sơ đồ, khung chương trình","pos":"Danh từ","example":{"zh":"老师把考试大纲发给我们。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"把","py":"bǎ"},{"c":"考","py":"kǎo"},{"c":"试","py":"shì"},{"c":"大","py":"dà"},{"c":"纲","py":"gāng"},{"c":"发","py":"fā"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"。","py":"。"}],"vi":"Giáo viên phát cho chúng tôi sơ đồ thi."}},{"hanzi":"蛋糕","pinyin":"dàngāo","hanViet":"ĐẢN CAO","meaning":"bánh ngọt","pos":"Danh từ","example":{"zh":"蛋糕很好吃。","pinyinPerChar":[{"c":"蛋","py":"dàn"},{"c":"糕","py":"gāo"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Bánh ngọt rất ngon."}},{"hanzi":"低于","pinyin":"dīyú","hanViet":"ĐÊ Ư","meaning":"thấp hơn, dưới mức","pos":"Tính từ","example":{"zh":"成绩低于预期。","pinyinPerChar":[{"c":"成","py":"chéng"},{"c":"绩","py":"jì"},{"c":"低","py":"dī"},{"c":"于","py":"yú"},{"c":"预","py":"yù"},{"c":"期","py":"qī"},{"c":"。","py":"。"}],"vi":"Kết quả thấp hơn mong đợi."}},{"hanzi":"电饭锅","pinyin":"diànfànguō","hanViet":"ĐIỆN PHẠN OA","meaning":"máy nấu cơm điện","pos":"Danh từ","example":{"zh":"她用电饭锅做饭。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"用","py":"yòng"},{"c":"电","py":"diàn"},{"c":"饭","py":"fàn"},{"c":"锅","py":"guō"},{"c":"做","py":"zuò"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Cô ấy dùng máy nấu cơm điện để nấu cơm."}},{"hanzi":"豆制品","pinyin":"dòuzhìpǐn","hanViet":"ĐẬU CHẾ PHẨM","meaning":"sản phẩm từ đậu","pos":"Danh từ","example":{"zh":"他喜欢吃豆制品。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"吃","py":"chī"},{"c":"豆","py":"dòu"},{"c":"制","py":"zhì"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Anh ấy thích ăn sản phẩm từ đậu."}},{"hanzi":"发行","pinyin":"fāxíng","hanViet":"PHÁT HÀNH","meaning":"phát hành, xuất bản","pos":"Động từ","example":{"zh":"这本书已经发行。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"已","py":"yǐ"},{"c":"经","py":"jīng