INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-9', 8, 'Ăn uống & ẩm thực (2)', '[{"hanzi":"分成","pinyin":"fēnchéng","hanViet":"PHÂN THÀNH","meaning":"chia thành","pos":"Động từ","example":{"zh":"这块蛋糕分成四份。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"块","py":"kuài"},{"c":"蛋","py":"dàn"},{"c":"糕","py":"gāo"},{"c":"分","py":"fēn"},{"c":"成","py":"chéng"},{"c":"四","py":"sì"},{"c":"份","py":"fèn"},{"c":"。","py":"。"}],"vi":"Cái bánh này chia thành bốn miếng."}},{"hanzi":"风度","pinyin":"fēngdù","hanViet":"PHONG ĐỘ","meaning":"vẻ đẹp lễ phép, cách ứng xử","pos":"Danh từ","example":{"zh":"他有一种很好的风度。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"种","py":"zhǒng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"的","py":"de"},{"c":"风","py":"fēng"},{"c":"度","py":"dù"},{"c":"。","py":"。"}],"vi":"Anh ấy có một vẻ đẹp lễ phép rất tốt."}},{"hanzi":"服从","pinyin":"fúcóng","hanViet":"PHỤC TÒNG","meaning":"tuân theo, chấp nhận lệnh","pos":"Động từ","example":{"zh":"他服从命令。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"服","py":"fú"},{"c":"从","py":"cóng"},{"c":"命","py":"mìng"},{"c":"令","py":"lìng"},{"c":"。","py":"。"}],"vi":"Anh ấy tuân theo lệnh."}},{"hanzi":"幅度","pinyin":"fúdù","hanViet":"BỨC ĐỘ","meaning":"mức độ, khoảng cách, số lượng","pos":"Danh từ","example":{"zh":"温度的幅度很大。","pinyinPerChar":[{"c":"温","py":"wēn"},{"c":"度","py":"dù"},{"c":"的","py":"de"},{"c":"幅","py":"fú"},{"c":"度","py":"dù"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Mức độ nhiệt độ rất lớn."}},{"hanzi":"附件","pinyin":"fùjiàn","hanViet":"PHỤ KIỆN","meaning":"đính kèm, tài liệu kèm theo","pos":"Danh từ","example":{"zh":"请把附件发给我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"附","py":"fù"},{"c":"件","py":"jiàn"},{"c":"发","py":"fā"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Xin gửi tài liệu kèm theo cho tôi."}},{"hanzi":"改革","pinyin":"gǎigé","hanViet":"CẢI CÁCH","meaning":"thay đổi, cải cách","pos":"Động từ","example":{"zh":"他们正在改革制度。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"改","py":"gǎi"},{"c":"革","py":"gé"},{"c":"制","py":"zhì"},{"c":"度","py":"dù"},{"c":"。","py":"。"}],"vi":"Họ đang cải cách chế độ."}},{"hanzi":"钢笔","pinyin":"gāngbǐ","hanViet":"CƯƠNG BÚT","meaning":"món viết bằng nhựa, mực, bút","pos":"Danh từ","example":{"zh":"他用钢笔写了一封信。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"用","py":"yòng"},{"c":"钢","py":"gāng"},{"c":"笔","py":"bǐ"},{"c":"写","py":"xiě"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"封","py":"fēng"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Anh ấy dùng bút chì viết một lá thư."}},{"hanzi":"搞好","pinyin":"gǎohǎo","hanViet":"CẢO HẢO","meaning":"làm cho tốt, hoàn thành","pos":"Động từ","example":{"zh":"我们要搞好工作。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"搞","py":"gǎo"},{"c":"好","py":"hǎo"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Chúng ta phải làm tốt công việc."}},{"hanzi":"跟随","pinyin":"gēnsuí","hanViet":"CÂN TUỲ","meaning":"theo sau, đi cùng","pos":"Động từ","example":{"zh":"我跟随他去学校。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"跟","py":"gēn"},{"c":"随","py":"suí"},{"c":"他","py":"tā"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Tôi đi cùng anh ấy đến trường."}},{"hanzi":"工作日","pinyin":"gōngzuòrì","hanViet":"CÔNG TÁC NHẬT","meaning":"ngày làm việc, ngày thường","pos":"Danh từ","example":{"zh":"我周末不上班。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"周","py":"zhōu"},{"c":"末","py":"mò"},{"c":"不","py":"bù"},{"c":"上","py":"shàng"},{"c":"班","py":"bān"},{"c":"。","py":"。"}],"vi":"Tôi không đi làm vào cuối tuần."}},{"hanzi":"鼓","pinyin":"gǔ","hanViet":"CỔ","meaning":"dầu, nổ, vỗ","pos":"Động từ","example":{"zh":"他鼓起勇气。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"鼓","py":"gǔ"},{"c":"起","py":"qǐ"},{"c":"勇","py":"yǒng"},{"c":"气","py":"qì"},{"c":"。","py":