INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-10', 9, 'Ăn uống & ẩm thực (3)', '[{"hanzi":"戒","pinyin":"jiè","hanViet":"GIỚI","meaning":"cấm, ngừng hôn mê","pos":"Động từ","example":{"zh":"他戒烟后身体变好。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"戒","py":"jiè"},{"c":"烟","py":"yān"},{"c":"后","py":"hòu"},{"c":"身","py":"shēn"},{"c":"体","py":"tǐ"},{"c":"变","py":"biàn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Anh ta bỏ thuốc lá thì sức khỏe tốt hơn."}},{"hanzi":"警告","pinyin":"jǐnggào","hanViet":"CẢNH CÁO","meaning":"cảnh báo, cảnh báo","pos":"Danh từ","example":{"zh":"他收到警告。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"收","py":"shōu"},{"c":"到","py":"dào"},{"c":"警","py":"jǐng"},{"c":"告","py":"gào"},{"c":"。","py":"。"}],"vi":"Anh ta nhận được cảnh báo."}},{"hanzi":"酒鬼","pinyin":"jiǔguǐ","hanViet":"TỬU QUỶ","meaning":"người say rượu","pos":"Danh từ","example":{"zh":"他是酒鬼。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"酒","py":"jiǔ"},{"c":"鬼","py":"guǐ"},{"c":"。","py":"。"}],"vi":"Anh ta là người say rượu."}},{"hanzi":"举动","pinyin":"jǔdòng","hanViet":"CỬ ĐỘNG","meaning":"hành động, lệnh","pos":"Danh từ","example":{"zh":"他的举动很奇怪。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"举","py":"jǔ"},{"c":"动","py":"dòng"},{"c":"很","py":"hěn"},{"c":"奇","py":"qí"},{"c":"怪","py":"guài"},{"c":"。","py":"。"}],"vi":"Hành động của anh ta rất lạ."}},{"hanzi":"剧本","pinyin":"jùběn","hanViet":"KỊCH BẢN","meaning":"kịch bản, văn bản diễn ra","pos":"Danh từ","example":{"zh":"这部电影的剧本很精彩。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"的","py":"de"},{"c":"剧","py":"jù"},{"c":"本","py":"běn"},{"c":"很","py":"hěn"},{"c":"精","py":"jīng"},{"c":"彩","py":"cǎi"},{"c":"。","py":"。"}],"vi":"Kịch bản phim này rất hay."}},{"hanzi":"烤肉","pinyin":"kǎoròu","hanViet":"KHẢO NHỤC","meaning":"thịt nướng","pos":"Danh từ","example":{"zh":"我们吃了很多烤肉。","pinyinPerChar":[{"c":"我","py":"