INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-11', 10, 'Ăn uống & ẩm thực (4)', '[{"hanzi":"蔬菜","pinyin":"shūcài","hanViet":"SƠ THÁI","meaning":"rau","pos":"Danh từ","example":{"zh":"我每天吃蔬菜。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"吃","py":"chī"},{"c":"蔬","py":"shū"},{"c":"菜","py":"cài"},{"c":"。","py":"。"}],"vi":"Tôi mỗi ngày ăn rau."}},{"hanzi":"摔","pinyin":"shuāi","hanViet":"SUẤT","meaning":"xùn, ngã, văng","pos":"Động từ","example":{"zh":"他摔倒了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"摔","py":"shuāi"},{"c":"倒","py":"dào"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy ngã xuống."}},{"hanzi":"摔倒","pinyin":"shuāidǎo","hanViet":"SUẤT ĐÁO","meaning":"ngã, văng","pos":"Động từ","example":{"zh":"女孩摔倒在地上。","pinyinPerChar":[{"c":"女","py":"nǚ"},{"c":"孩","py":"hái"},{"c":"摔","py":"shuāi"},{"c":"倒","py":"dào"},{"c":"在","py":"zài"},{"c":"地","py":"dì"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Cô gái ngã xuống đất."}},{"hanzi":"私人","pinyin":"sīrén","hanViet":"TƯ NHÂN","meaning":"riêng tư, cá nhân","pos":"Tính từ","example":{"zh":"这是私人事务。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"私","py":"sī"},{"c":"人","py":"rén"},{"c":"事","py":"shì"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Đây là chuyện riêng tư."}},{"hanzi":"酸甜苦辣","pinyin":"suān-tián-kǔ-là","hanViet":"TOAN ĐIỀM KHỔ LẠT","meaning":"chua, ngọt, cay, đắng","pos":"Danh từ","example":{"zh":"这道菜有酸甜苦辣。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"道","py":"dào"},{"c":"菜","py":"cài"},{"c":"有","py":"yǒu"},{"c":"酸","py":"suān"},{"c":"甜","py":"tián"},{"c":"苦","py":"kǔ"},{"c":"辣","py":"là"},{"c":"。","py":"。"}],"vi":"Món ăn này có chua, ngọt, cay, đắng."}},{"hanzi":"随着","pinyin":"suízhe","hanViet":"TUỲ TRỨ","meaning":"kèm theo, cùng với","pos":"Liên từ","example":{"zh":"随着时间过去，事情变了。","pinyinPerChar":[{"c":"随","py":"suí"},{"c":"着","py":"zhe"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"过","py":