INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-12', 11, 'Ăn uống & ẩm thực (5)', '[{"hanzi":"运行","pinyin":"yùnxíng","hanViet":"VẬN HÀNH","meaning":"chạy, vận hành","pos":"Động từ","example":{"zh":"系统正在运行。","pinyinPerChar":[{"c":"系","py":"xì"},{"c":"统","py":"tǒng"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"运","py":"yùn"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Hệ thống đang chạy."}},{"hanzi":"增","pinyin":"zēng","hanViet":"TĂNG","meaning":"tăng thêm","pos":"Động từ","example":{"zh":"数量增多了。","pinyinPerChar":[{"c":"数","py":"shù"},{"c":"量","py":"liàng"},{"c":"增","py":"zēng"},{"c":"多","py":"duō"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Số lượng tăng thêm."}},{"hanzi":"增产","pinyin":"zēngchǎn","hanViet":"TĂNG SẢN","meaning":"tăng sản xuất","pos":"Động từ","example":{"zh":"工厂增产了。","pinyinPerChar":[{"c":"工","py":"gōng"},{"c":"厂","py":"chǎng"},{"c":"增","py":"zēng"},{"c":"产","py":"chǎn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Công ty tăng sản xuất."}},{"hanzi":"增大","pinyin":"zēngdà","hanViet":"TĂNG ĐẠI","meaning":"làm tăng, tăng kích thước","pos":"Động từ","example":{"zh":"声音增大了。","pinyinPerChar":[{"c":"声","py":"shēng"},{"c":"音","py":"yīn"},{"c":"增","py":"zēng"},{"c":"大","py":"dà"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Tiếng nói tăng lên."}},{"hanzi":"增多","pinyin":"zēngduō","hanViet":"TĂNG ĐA","meaning":"tăng số lượng","pos":"Động từ","example":{"zh":"人越来越多。","pinyinPerChar":[{"c":"人","py":"rén"},{"c":"越","py":"yuè"},{"c":"来","py":"lái"},{"c":"越","py":"yuè"},{"c":"多","py":"duō"},{"c":"。","py":"。"}],"vi":"Người càng nhiều."}},{"hanzi":"增强","pinyin":"zēngqiáng","hanViet":"TĂNG CƯỜNG","meaning":"tăng cường, tăng mạnh","pos":"Động từ","example":{"zh":"我们要增强体质。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"增","py":"zēng"},{"c":"强","py":"qiáng"},{"c":"体","py":"tǐ"},{"c":"质","py":"zhì"},{"c":"。","py":"。"}],"vi":"Chúng ta cần tăng cường sức khỏe."}},{"hanzi":"涨