INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-13', 12, 'Mua sắm & tiền bạc', '[{"hanzi":"博览会","pinyin":"bólǎnhuì","hanViet":"BÁC LÃM HỘI","meaning":"triển lãm, hội chợ","pos":"Danh từ","example":{"zh":"我们参加了博览会。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"了","py":"le"},{"c":"博","py":"bó"},{"c":"览","py":"lǎn"},{"c":"会","py":"huì"},{"c":"。","py":"。"}],"vi":"Chúng tôi đã tham gia triển lãm."}},{"hanzi":"采购","pinyin":"cǎigòu","hanViet":"THÁI CẤU","meaning":"mua sắm, mua hàng","pos":"Động từ","example":{"zh":"公司正在采购新设备。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"采","py":"cǎi"},{"c":"购","py":"gòu"},{"c":"新","py":"xīn"},{"c":"设","py":"shè"},{"c":"备","py":"bèi"},{"c":"。","py":"。"}],"vi":"Công ty đang mua sắm thiết bị mới."}},{"hanzi":"成本","pinyin":"chéngběn","hanViet":"THÀNH BẢN","meaning":"chi phí, vốn đầu tư","pos":"Danh từ","example":{"zh":"这件衣服的成本很高。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"的","py":"de"},{"c":"成","py":"chéng"},{"c":"本","py":"běn"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Chi phí của bộ quần áo này rất cao."}},{"hanzi":"存款","pinyin":"cúnkuǎn","hanViet":"TỒN KHOẢN","meaning":"tiền gửi, tiền tiết kiệm, số dư tài khoản","pos":"Danh từ","example":{"zh":"他每个月存一笔款。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"个","py":"gè"},{"c":"月","py":"yuè"},{"c":"存","py":"cún"},{"c":"一","py":"yī"},{"c":"笔","py":"bǐ"},{"c":"款","py":"kuǎn"},{"c":"。","py":"。"}],"vi":"Anh ấy mỗi tháng gửi một khoản tiền."}},{"hanzi":"打包","pinyin":"dǎbāo","hanViet":"ĐẢ BAO","meaning":"gói, đóng gói, đóng gói hàng hóa","pos":"Động từ","example":{"zh":"请把这些东西打包好。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"这","py":"zhè"},{"c":"些","py":"xiē"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c"