INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-14', 13, 'Du lịch & giao thông', '[{"hanzi":"比重","pinyin":"bǐzhòng","hanViet":"TỶ TRỌNG","meaning":"tỷ trọng","pos":"Danh từ","example":{"zh":"这个部分的比重很高。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"部","py":"bù"},{"c":"分","py":"fēn"},{"c":"的","py":"de"},{"c":"比","py":"bǐ"},{"c":"重","py":"zhòng"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Tỷ trọng của phần này rất cao."}},{"hanzi":"不得了","pinyin":"bùdéliǎo","hanViet":"BẤT ĐẮC LIỄU","meaning":"đáng sợ, nghiêm trọng","pos":"Liên từ","example":{"zh":"问题不得了了。","pinyinPerChar":[{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"不","py":"bù"},{"c":"得","py":"dé"},{"c":"了","py":"le"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Vấn đề đang trở nên nghiêm trọng."}},{"hanzi":"彩票","pinyin":"cǎipiào","hanViet":"THÁI PHIẾU","meaning":"xổ số, vé số","pos":"Danh từ","example":{"zh":"他买了一张彩票。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"买","py":"mǎi"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"彩","py":"cǎi"},{"c":"票","py":"piào"},{"c":"。","py":"。"}],"vi":"Cậu ấy mua một vé số."}},{"hanzi":"车主","pinyin":"chēzhǔ","hanViet":"XA CHỦ","meaning":"chủ xe","pos":"Danh từ","example":{"zh":"车主把车停在这里。","pinyinPerChar":[{"c":"车","py":"chē"},{"c":"主","py":"zhǔ"},{"c":"把","py":"bǎ"},{"c":"车","py":"chē"},{"c":"停","py":"tíng"},{"c":"在","py":"zài"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Chủ xe đậu xe ở đây."}},{"hanzi":"乘","pinyin":"chéng","hanViet":"THỪA","meaning":"tận dụng, đi xe","pos":"Động từ","example":{"zh":"他乘车去上班。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"乘","py":"chéng"},{"c":"车","py":"chē"},{"c":"去","py":"qù"},{"c":"上","py":"shàng"},{"c":"班","py":"bān"},{"c":"。","py":"。"}],"vi":"Anh ấy đi xe để đi làm."}},{"hanzi":"乘车","pinyin":"chéng chē","hanViet":"THỪA XA","meaning":"đi xe","pos":"Động từ","example":{"zh":"她乘车去学校。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"乘","py":"chéng"},{"c":"车","py":"chē"},{"c":"去","py":"qù"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"。","py":"。"}],"vi":"Cô ấy đi xe đến trường."}},{"hanzi":"大事","pinyin":"dàshì","hanViet":"ĐẠI SỰ","meaning":"vấn đề lớn, sự việc quan trọng","pos":"Danh từ","example":{"zh":"这件大事要好好处理。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"大","py":"dà"},{"c":"事","py":"shì"},{"c":"要","py":"yào"},{"c":"好","py":"hǎo"},{"c":"好","py":"hǎo"},{"c":"处","py":"chù"},{"c":"理","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Vấn đề lớn này cần xử lý kỹ."}},{"hanzi":"关键","pinyin":"guānjiàn","hanViet":"QUAN KIỆN","meaning":"yếu tố quan trọng","pos":"Danh từ","example":{"zh":"这个关键点很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"关","py":"guān"},{"c":"键","py":"jiàn"},{"c":"点","py":"diǎn"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Điểm quan trọng này rất quan trọng."}},{"hanzi":"驾驶","pinyin":"jiàshǐ","hanViet":"GIÁ SỬ","meaning":"lái xe","pos":"Động từ","example":{"zh":"他会驾驶汽车。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"会","py":"huì"},{"c":"驾","py":"jià"},{"c":"驶","py":"shǐ"},{"c":"汽","py":"qì"},{"c":"车","py":"chē"},{"c":"。","py":"。"}],"vi":"Anh ấy biết lái xe."}},{"hanzi":"驾照","pinyin":"jiàzhào","hanViet":"GIÁ CHIẾU","meaning":"giấy phép lái xe","pos":"Danh từ","example":{"zh":"他有驾照。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"驾","py":"jià"},{"c":"照","py":"zhào"},{"c":"。","py":"。"}],"vi":"Anh ấy có bằng lái."}},{"hanzi":"码头","pinyin":"mǎtóu","hanViet":"MÃ ĐẦU","meaning":"bến, cảng","pos":"Danh từ","example":{"zh":"船停在码头。","pinyinPerChar":[{"c":"船","py":"chuán"},{"c":"停","py":"tíng"},{"c":"在","py":"zài"},{"c":"码","py":"mǎ"},{"c":"头","py":"tóu"},{"c":"。","py":"。"}],"vi":"Tàu đậu ở bến."}},{"hanzi":"煤气","pinyin":"méiqì","hanViet":"MÔI KHÍ","meaning":"khí gas, khí đốt","pos":"Danh từ","example":{"zh":"煤气很危险。","pinyinPerChar":[{"c":"煤","py":"méi"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"危","py":"wēi"},{"c":"险","py":"xiǎn"},{"c":"。","py":"。"}],"vi":"Khí đốt rất nguy hiểm."}},{"hanzi":"摩托","pinyin":"mótuō","hanViet":"MA THÁC","meaning":"Xe máy","pos":"Danh từ","example":{"zh":"他骑摩托去上班。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"骑","py":"qí"},{"c":"摩","py":"mó"},{"c":"托","py":"tuō"},{"c":"去","py":"qù"},{"c":"上","py":"shàng"},{"c":"班","py":"bān"},{"c":"。","py":"。"}],"vi":"Anh ấy đi xe máy đi làm."}},{"hanzi":"山区","pinyin":"shānqū","hanViet":"SƠN KHU","meaning":"vùng núi, vùng đất núi cao","pos":"Danh từ","example":{"zh":"他们住在山区。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"山","py":"shān"},{"c":"区","py":"qū"},{"c":"。","py":"。"}],"vi":"Họ sống ở vùng núi."}},{"hanzi":"十足","pinyin":"shízú","hanViet":"THẬP TÚC","meaning":"toàn vẹn, trọn vẹn","pos":"Tính từ","example":{"zh":"这件衣服十足合适。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"十","py":"shí"},{"c":"足","py":"zú"},{"c":"合","py":"hé"},{"c":"适","py":"shì"},{"c":"。","py":"。"}],"vi":"Cái áo này vừa vặn lắm."}},{"hanzi":"随后","pinyin":"suíhòu","hanViet":"TUỲ HẬU","meaning":"sau đó, ngay sau","pos":"Phó từ","example":{"zh":"他走了，随后我们也走了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"了","py":"le"},{"c":"，","py":"，"},{"c":"随","py":"suí"},{"c":"后","py":"hòu"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"也","py":"yě"},{"c":"走","py":"zǒu"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đi, sau đó chúng tôi cũng đi."}},{"hanzi":"欣赏","pinyin":"xīnshǎng","hanViet":"HÂN THƯỞNG","meaning":"Ngưỡng mộ, trân trọng","pos":"Động từ","example":{"zh":"我欣赏他的勇气。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"欣","py":"xīn"},{"c":"赏","py":"shǎng"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"勇","py":"yǒng"},{"c":"气","py":"qì"},{"c":"。","py":"。"}],"vi":"Tôi ngưỡng mộ sự dũng cảm của anh ấy."}},{"hanzi":"严肃","pinyin":"yánsù","hanViet":"NGHIÊM TÚC","meaning":"trọng sự; nghiêm túc","pos":"Tính từ","example":{"zh":"他脸色很严肃。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"脸","py":"liǎn"},{"c":"色","py":"sè"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"肃","py":"sù"},{"c":"。","py":"。"}],"vi":"Mặt cậu ấy trông rất nghiêm túc."}},{"hanzi":"一下子","pinyin":"yīxiàzi","hanViet":"NHẤT HẠ TỬ","meaning":"ngay lập tức, một lúc","pos":"Phó từ","example":{"zh":"一下子就明白了。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"子","py":"zi"},{"c":"就","py":"jiù"},{"c":"明","py":"míng"},{"c":"白","py":"bái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Ngay lập tức đã hiểu."}},{"hanzi":"怨","pinyin":"yuàn","hanViet":"OÁN","meaning":"phàn nàn, ghen","pos":"Động từ","example":{"zh":"他对这件事很怨。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"很","py":"hěn"},{"c":"怨","py":"yuàn"},{"c":"。","py":"。"}],"vi":"Cậu ta rất phàn nàn về việc này."}},{"hanzi":"珍惜","pinyin":"zhēnxī","hanViet":"TRÂN TÍCH","meaning":"trân trọng, giữ gìn","pos":"Động từ","example":{"zh":"我们要珍惜时间。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"珍","py":"zhēn"},{"c":"惜","py":"xī"},{"c":"时","py":"shí"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Chúng ta phải trân trọng thời gian."}},{"hanzi":"终身","pinyin":"zhōngshēn","hanViet":"CHUNG THÂN","meaning":"trọn đời, suốt đời","pos":"Danh từ","example":{"zh":"他选择终身服务。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"选","py":"xuǎn"},{"c":"择","py":"zé"},{"c":"终","py":"zhōng"},{"c":"身","py":"shēn"},{"c":"服","py":"fú"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Anh ấy chọn phục vụ suốt đời."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-15', 14, 'Thời gian & lịch (1)', '[{"hanzi":"闭幕式","pinyin":"bìmùshì","hanViet":"BẾ MÀN THỨC","meaning":"lễ kết thúc","pos":"Danh từ","example":{"zh":"他们举行了闭幕式。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"举","py":"jǔ"},{"c":"行","py":"xíng"},{"c":"了","py":"le"},{"c":"闭","py":"bì"},{"c":"幕","py":"mù"},{"c":"式","py":"shì"},{"c":"。","py":"。"}],"vi":"Họ tổ chức lễ kết thúc."}},{"hanzi":"不曾","pinyin":"bùcéng","hanViet":"BẤT TỪNG","meaning":"chưa bao giờ, chưa từng","pos":"Phó từ","example":{"zh":"我不曾见过他。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"曾","py":"céng"},{"c":"见","py":"jiàn"},{"c":"过","py":"guò"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Tôi chưa từng gặp anh ấy."}},{"hanzi":"不时","pinyin":"bùshí","hanViet":"BẤT THỜI","meaning":"thỉnh thoảng, có lúc","pos":"Phó từ","example":{"zh":"他不时给我发消息。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"不","py":"bù"},{"c":"时","py":"shí"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"发","py":"fā"},{"c":"消","py":"xiāo"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Cậu ấy thỉnh thoảng gửi tin nhắn cho tôi."}},{"hanzi":"迟","pinyin":"chí","hanViet":"TRÌ","meaning":"trễ, chậm","pos":"Tính từ","example":{"zh":"他迟到了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"迟","py":"chí"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy đến trễ."}},{"hanzi":"除夕","pinyin":"chúxī","hanViet":"TRỪ TỊCH","meaning":"đêm cuối năm, Tết trước","pos":"Danh từ","example":{"zh":"除夕夜家家都贴年画。","pinyinPerChar":[{"c":"除","py":"chú"},{"c":"夕","py":"xī"},{"c":"夜","py":"yè"},{"c":"家","py":"jiā"},{"c":"家","py":"jiā"},{"c":"都","py":"dōu"},{"c":"贴","py":"tiē"},{"c":"年","py":"nián"},{"c":"画","py":"huà"},{"c":"。","py":"。"}],"vi":"Đêm Giỗ Tổ, mỗi nhà đều dán tranh năm mới."}},{"hanzi":"此刻","pinyin":"cǐkè","hanViet":"THỬ KHẮC","meaning":"lúc này, hiện tại","pos":"Danh từ","example":{"zh":"此刻，天空非常安静。","pinyinPerChar":[{"c":"此","py":"cǐ"},{"c":"刻","py":"kè"},{"c":"，","py":"，"},{"c":"天","py":"tiān"},{"c":"空","py":"kōng"},{"c":"非","py":"fēi"},{"c":"常","py":"cháng"},{"c":"安","py":"ān"},{"c":"静","py":"jìng"},{"c":"。","py":"。"}],"vi":"Lúc này, bầu trời rất yên tĩnh."}},{"hanzi":"此时","pinyin":"cǐshí","hanViet":"THỬ THỜI","meaning":"khi này, lúc này","pos":"Danh từ","example":{"zh":"此时，他正在看书。","pinyinPerChar":[{"c":"此","py":"cǐ"},{"c":"时","py":"shí"},{"c":"，","py":"，"},{"c":"他","py":"tā"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"看","py":"kàn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Lúc này, anh ấy đang đọc sách."}},{"hanzi":"寸","pinyin":"cùn","hanViet":"THỐN","meaning":"một đơn vị chiều dài (1/30 mét), xương xà","pos":"Lượng từ","example":{"zh":"这张纸只有一寸宽。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"张","py":"zhāng"},{"c":"纸","py":"zhǐ"},{"c":"只","py":"zhǐ"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"寸","py":"cùn"},{"c":"宽","py":"kuān"},{"c":"。","py":"。"}],"vi":"Cuốn giấy này chỉ rộng một cùn."}},{"hanzi":"当场","pinyin":"dāngchǎng","hanViet":"ĐƯƠNG TRƯỜNG","meaning":"trong lúc xảy ra sự việc","pos":"Danh từ","example":{"zh":"他当场被发现偷东西。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"当","py":"dāng"},{"c":"场","py":"chǎng"},{"c":"被","py":"bèi"},{"c":"发","py":"fā"},{"c":"现","py":"xiàn"},{"c":"偷","py":"tōu"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"。","py":"。"}],"vi":"Anh ấy bị phát hiện đang cầm trộm ngay tại chỗ."}},{"hanzi":"当代","pinyin":"dāngdài","hanViet":"ĐƯƠNG ĐẠI","meaning":"thời hiện đại, hiện tại","pos":"Tính từ","example":{"zh":"当代社会变化很快。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"代","py":"dài"},{"c":"社","py":"shè"},{"c":"会","py":"huì"},{"c":"变","py":"biàn"},{"c":"化","py":"huà"},{"c":"很","py":"hěn"},{"c":"快","py":"kuài"},{"c":"。","py":"。"}],"vi":"Xã hội hiện đại thay đổi rất nhanh."}},{"hanzi":"当年","pinyin":"dāngnián","hanViet":"ĐƯƠNG NIÊN","meaning":"năm đó, thời đó","pos":"Danh từ","example":{"zh":"当年天气很热。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"年","py":"nián"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"。","py":"。"}],"vi":"Năm đó thời tiết rất nóng."}},{"hanzi":"当前","pinyin":"dāngqián","hanViet":"ĐƯƠNG TIỀN","meaning":"hiện tại, bây giờ","pos":"Tính từ","example":{"zh":"当前形势很严峻。","pinyinPerChar":[{"c":"当","py":"dāng"},{"c":"前","py":"qián"},{"c":"形","py":"xíng"},{"c":"势","py":"shì"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"峻","py":"jùn"},{"c":"。","py":"。"}],"vi":"Bối cảnh hiện tại rất nghiêm trọng."}},{"hanzi":"二维码","pinyin":"èrwéimǎ","hanViet":"NHỊ DUY MÃ","meaning":"mã hai chiều","pos":"Danh từ","example":{"zh":"这个二维码可以扫描。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"二","py":"èr"},{"c":"维","py":"wéi"},{"c":"码","py":"mǎ"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"扫","py":"sǎo"},{"c":"描","py":"miáo"},{"c":"。","py":"。"}],"vi":"Mã hai chiều này có thể quét."}},{"hanzi":"丰收","pinyin":"fēngshōu","hanViet":"PHONG THU","meaning":"cây trồng cho nhiều trái, mùa vụ tốt","pos":"Danh từ","example":{"zh":"今年庄稼丰收。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"年","py":"nián"},{"c":"庄","py":"zhuāng"},{"c":"稼","py":"jià"},{"c":"丰","py":"fēng"},{"c":"收","py":"shōu"},{"c":"。","py":"。"}],"vi":"Năm nay mùa màng tốt."}},{"hanzi":"感想","pinyin":"gǎnxiǎng","hanViet":"CẢM TƯỞNG","meaning":"ý nghĩ, cảm nhận sau khi trải qua","pos":"Danh từ","example":{"zh":"这次旅行给我留下了很多感想。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"次","py":"cì"},{"c":"旅","py":"lǚ"},{"c":"行","py":"xíng"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"留","py":"liú"},{"c":"下","py":"xià"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"感","py":"gǎn"},{"c":"想","py":"xiǎng"},{"c":"。","py":"。"}],"vi":"Cuộc du lịch này để lại cho tôi nhiều cảm nghĩ."}},{"hanzi":"个儿","pinyin":"gèr","hanViet":"CÁ NHI","meaning":"chiều cao, độ cao của người","pos":"Danh từ","example":{"zh":"他个儿很高。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"个","py":"gè"},{"c":"儿","py":"ér"},{"c":"很","py":"hěn"},{"c":