INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-16', 15, 'Thời gian & lịch (2)', '[{"hanzi":"礼貌","pinyin":"lǐmào","hanViet":"LỄ MẠO","meaning":"lịch sự","pos":"Tính từ","example":{"zh":"她很有礼貌。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"礼","py":"lǐ"},{"c":"貌","py":"mào"},{"c":"。","py":"。"}],"vi":"Cô ấy rất lịch sự."}},{"hanzi":"秒","pinyin":"miǎo","hanViet":"MIỂU","meaning":"Phút, một đơn vị thời gian","pos":"Danh từ","example":{"zh":"这个视频一秒钟就播放完了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"视","py":"shì"},{"c":"频","py":"pín"},{"c":"一","py":"yī"},{"c":"秒","py":"miǎo"},{"c":"钟","py":"zhōng"},{"c":"就","py":"jiù"},{"c":"播","py":"bō"},{"c":"放","py":"fàng"},{"c":"完","py":"wán"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Video này chỉ cần một phút là xong."}},{"hanzi":"明亮","pinyin":"míngliàng","hanViet":"MINH LƯỢNG","meaning":"Sáng, rạng rỡ","pos":"Tính từ","example":{"zh":"房间里很明亮。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"明","py":"míng"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Phòng này rất sáng."}},{"hanzi":"年度","pinyin":"niándù","hanViet":"NIÊN ĐỘ","meaning":"hàng năm, của năm","pos":"Tính từ","example":{"zh":"年度报告已经完成。","pinyinPerChar":[{"c":"年","py":"nián"},{"c":"度","py":"dù"},{"c":"报","py":"bào"},{"c":"告","py":"gào"},{"c":"已","py":"yǐ"},{"c":"经","py":"jīng"},{"c":"完","py":"wán"},{"c":"成","py":"chéng"},{"c":"。","py":"。"}],"vi":"Báo cáo hàng năm đã hoàn thành."}},{"hanzi":"年龄","pinyin":"niánlíng","hanViet":"NIÊN LINH","meaning":"tuổi, độ tuổi","pos":"Danh từ","example":{"zh":"她的年龄比我大两岁。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"年","py":"nián"},{"c":"龄","py":"líng"},{"c":"比","py":"bǐ"},{"c":"我","py":"wǒ"},{"c":"大","py":"dà"},{"c":"两","py":"liǎng"},{"c":"岁","py":"suì"},{"c":"。","py":"。"}],"vi":"Tuổi cô ấy lớn hơn tôi hai tuổi."}},{"hanzi":"年前","pinyin":"niánqián","hanViet":"NIÊN TIỀN","meaning":"trước đây trong năm này","pos":"Phó từ","example":{"zh":"他年前来过这里。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"年","py":"nián"},{"c":"前","py":"qián"},{"c":"来","py":"lái"},{"c":"过","py":"guò"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Anh ấy đã đến đây trước đây trong năm này."}},{"hanzi":"偶尔","pinyin":"ǒu''ěr","hanViet":"NGẪU NHĨ","meaning":"thỉnh thoảng","pos":"Phó từ","example":{"zh":"我偶尔会去公园散步。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"偶","py":"ǒu"},{"c":"尔","py":"ěr"},{"c":"会","py":"huì"},{"c":"去","py":"qù"},{"c":"公","py":"gōng"},{"c":"园","py":"yuán"},{"c":"散","py":"sàn"},{"c":"步","py":"bù"},{"c":"。","py":"。"}],"vi":"Tôi thỉnh thoảng đi dạo công viên."}},{"hanzi":"前景","pinyin":"qiánjǐng","hanViet":"TIỀN CẢNH","meaning":"tương lai, triển vọng","pos":"Danh từ","example":{"zh":"这家公司的前景很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"家","py":"jiā"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"的","py":"de"},{"c":"前","py":"qián"},{"c":"景","py":"jǐng"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Tương lai của công ty này rất tốt."}},{"hanzi":"清晨","pinyin":"qīngchén","hanViet":"THANH THẦN","meaning":"Buổi sáng sạch sẽ, sáng sớm","pos":"Danh từ","example":{"zh":"清晨的空气很清新。","pinyinPerChar":[{"c":"清","py":"qīng"},{"c":"晨","py":"chén"},{"c":"的","py":"de"},{"c":"空","py":"kōng"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"清","py":"qīng"},{"c":"新","py":"xīn"},{"c":"。","py":"。"}],"vi":"Không khí buổi sáng rất trong lành."}},{"hanzi":"时光","pinyin":"shíguāng","hanViet":"THỜI QUANG","meaning":"thời gian, thời gian trôi qua","pos":"Danh từ","example":{"zh":"时光飞逝。","pinyinPerChar":[{"c":"时","py":"shí"},{"c":"光","py":"guāng"},{"c":"飞","py":"fēi"},{"c":"逝","py":"shì"},{"c":"。","py":"。"}],"vi":"Thời gian trôi nhanh."}},{"hanzi":"时事","pinyin":"shíshì","hanViet":"THỜI SỰ","meaning":"vấn đề thời sự, sự kiện hiện tại","pos":"Danh từ","example":{"zh":"他关注时事。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"