INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-19', 18, 'Sức khỏe & cơ thể (1)', '[{"hanzi":"按摩","pinyin":"ànmó","hanViet":"ÁN MA","meaning":"xoa bóp cơ thể để thư giản","pos":"Động từ","example":{"zh":"他每天晚上按摩肩膀。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"晚","py":"wǎn"},{"c":"上","py":"shàng"},{"c":"按","py":"àn"},{"c":"摩","py":"mó"},{"c":"肩","py":"jiān"},{"c":"膀","py":"bǎng"},{"c":"。","py":"。"}],"vi":"Anh ấy mỗi tối xoa bóp vai."}},{"hanzi":"悲剧","pinyin":"bēijù","hanViet":"BI KỊCH","meaning":"vụ tai nạn, bi kịch","pos":"Danh từ","example":{"zh":"这场悲剧让大家震惊。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"场","py":"chǎng"},{"c":"悲","py":"bēi"},{"c":"剧","py":"jù"},{"c":"让","py":"ràng"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"震","py":"zhèn"},{"c":"惊","py":"jīng"},{"c":"。","py":"。"}],"vi":"Vụ tai nạn này khiến mọi người sốc."}},{"hanzi":"鼻子","pinyin":"bízi","hanViet":"TỴ TỬ","meaning":"mũi","pos":"Danh từ","example":{"zh":"她的鼻子很高。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"鼻","py":"bí"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"。","py":"。"}],"vi":"Mũi của cô ấy rất cao."}},{"hanzi":"补贴","pinyin":"bǔtiē","hanViet":"BỔ THIẾP","meaning":"hoàn trả, trợ cấp","pos":"Danh từ","example":{"zh":"政府给农民补贴。","pinyinPerChar":[{"c":"政","py":"zhèng"},{"c":"府","py":"fǔ"},{"c":"给","py":"gěi"},{"c":"农","py":"nóng"},{"c":"民","py":"mín"},{"c":"补","py":"bǔ"},{"c":"贴","py":"tiē"},{"c":"。","py":"。"}],"vi":"Chính phủ hỗ trợ tiền cho nông dân."}},{"hanzi":"叉","pinyin":"chā","hanViet":"XOA","meaning":"dùng để gọt, xé, hoặc chỉ cây cầu","pos":"Danh từ","example":{"zh":"他用一根筷子叉着饭。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"用","py":"yòng"},{"c":"一","py":"yī"},{"c":"根","py":"gēn"},{"c":"筷","py":"kuài"},{"c":"子","py":"zi"},{"c":"叉","py":"chā"},{"c":"着","py":"zhe"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Anh ta dùng một đôi đũa gọt cơm."}},{"hanzi":"叉子",