việc này là trò cười."}},{"hanzi":"客厅","pinyin":"kètīng","hanViet":"KHÁCH SẢNH","meaning":"phòng khách","pos":"Danh từ","example":{"zh":"客厅里很干净。","pinyinPerChar":[{"c":"客","py":"kè"},{"c":"厅","py":"tīng"},{"c":"里","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"干","py":"gàn"},{"c":"净","py":"jìng"},{"c":"。","py":"。"}],"vi":"Phòng khách rất sạch sẽ."}},{"hanzi":"领带","pinyin":"lǐngdài","hanViet":"LÃNH ĐỚI","meaning":"dây xâu, cà vạt","pos":"Danh từ","example":{"zh":"他戴着一根黑色领带。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"戴","py":"dài"},{"c":"着","py":"zhe"},{"c":"一","py":"yī"},{"c":"根","py":"gēn"},{"c":"黑","py":"hēi"},{"c":"色","py":"sè"},{"c":"领","py":"lǐng"},{"c":"带","py":"dài"},{"c":"。","py":"。"}],"vi":"Anh ấy mặc một chiếc cà vạt đen."}},{"hanzi":"毛笔","pinyin":"máobǐ","hanViet":"MAO BÚT","meaning":"bút chổi","pos":"Danh từ","example":{"zh":"他用毛笔写字。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"用","py":"yòng"},{"c":"毛","py":"máo"},{"c":"笔","py":"bǐ"},{"c":"写","py":"xiě"},{"c":"字","py":"zì"},{"c":"。","py":"。"}],"vi":"Anh ấy viết bằng bút chổi."}},{"hanzi":"模范","pinyin":"mófàn","hanViet":"MÔ PHẠM","meaning":"Mẫu mực, tấm gương","pos":"Danh từ","example":{"zh":"他是我们学习的榜样。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"的","py":"de"},{"c":"榜","py":"bǎng"},{"c":"样","py":"yàng"},{"c":"。","py":"。"}],"vi":"Anh ấy là tấm gương mà chúng ta học tập."}},{"hanzi":"模式","pinyin":"móshì","hanViet":"MÔ THỨC","meaning":"Kiểu, hình thức, mô hình","pos":"Danh từ","example":{"zh":"他使用这种模式。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"使","py":"shǐ"},{"c":"用","py":"yòng"},{"c":"这","py":"zhè"},{"c":"种","py":"zhǒng"},{"c":"模","py":"mó"},{"c":"式","py":"shì"},{"c":"。","py":"。"}],"vi":"Anh ấy dùng kiểu này."}},{"hanzi":"墙壁","pinyin":"qiángbì","hanViet":"TƯỜNG BÍCH","meaning":"tường, bức tường","pos":"Danh từ","example":{"zh":"墙壁上有一幅画。","pinyinPerChar":[{"c":"墙","py":"qiáng"},{"c":"壁","py":"bì"},{"c":"上","py":"shàng"},{"c":"有","py":"yǒu"},{"c":"一","py":"yī"},{"c":"幅","py":"fú"},{"c":"画","py":"huà"},{"c":"。","py":"。"}],"vi":"Trên tường có một bức tranh."}},{"hanzi":"敲门","pinyin":"qiāo mén","hanViet":"XAO MÔN","meaning":"vụn cửa","pos":"Danh từ","example":{"zh":"敲门声很大。","pinyinPerChar":[{"c":"敲","py":"qiāo"},{"c":"门","py":"mén"},{"c":"声","py":"shēng"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Tiếng vúm cửa rất to."}},{"hanzi":"热门","pinyin":"rèmén","hanViet":"NHIỆT MÔN","meaning":"Phổ biến, được ưa chuộng, nổi bật","pos":"Tính từ","example":{"zh":"这本书很热门。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"很","py":"hěn"},{"c":"热","py":"rè"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Cuốn sách này rất được ưa chuộng."}},{"hanzi":"扇子","pinyin":"shànzi","hanViet":"PHIẾN TỬ","meaning":"quạt","pos":"Danh từ","example":{"zh":"我用扇子扇风。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"用","py":"yòng"},{"c":"扇","py":"shàn"},{"c":"子","py":"zi"},{"c":"扇","py":"shàn"},{"c":"风","py":"fēng"},{"c":"。","py":"。"}],"vi":"Tôi dùng quạt để thổi gió."}},{"hanzi":"舍得","pinyin":"shěde","hanViet":"XẢ ĐẮC","meaning":"sẵn sàng, dám, sẵn sàng mất","pos":"Động từ","example":{"zh":"他舍得帮大家。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"舍","py":"shě"},{"c":"得","py":"dé"},{"c":"帮","py":"bāng"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"。","py":"。"}],"vi":"Anh ta sẵn sàng giúp mọi người."}},{"hanzi":"社区","pinyin":"shèqū","hanViet":"XÃ KHU","meaning":"khu dân cư, cộng đồng","pos":"Danh từ","example":{"zh":"他们住在社区。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"社","py":"shè"},{"c":"区","py":"qū"},{"c":"。","py":"。"}],"vi":"Họ sống ở khu dân cư."}},{"hanzi":"神经","pinyin":"shénjīng","hanViet":"THẦN KINH","meaning":"tủy sống, thần kinh","pos":"Danh từ","example":{"zh":"他受伤了神经。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"受","py":"shòu"},{"c":"伤","py":"shāng"},{"c":"了","py":"le"},{"c":"神","py":"shén"},{"c":"经","py":"jīng"},{"c":"。","py":"。"}],"vi":"Anh ấy bị thương thần kinh."}},{"hanzi":"示范","pinyin":"shìfàn","hanViet":"THỊ PHẠM","meaning":"thí điểm, ví dụ minh họa","pos":"Danh từ","example":{"zh":"这是一个示范。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"示","py":"shì"},{"c":"范","py":"fàn"},{"c":"。","py":"。"}],"vi":"Đây là một ví dụ."}},{"hanzi":"书柜","pinyin":"shūguì","hanViet":"THƯ QUỸ","meaning":"tủ để sách","pos":"Danh từ","example":{"zh":"书柜上放着很多书。","pinyinPerChar":[{"c":"书","py":"shū"},{"c":"柜","py":"guì"},{"c":"上","py":"shàng"},{"c":"放","py":"fàng"},{"c":"着","py":"zhe"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tủ sách trên có nhiều sách."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-22', 21, 'Quần áo & màu sắc', '[{"hanzi":"便条","pinyin":"biàntiáo","hanViet":"TIỆN ĐIỀU","meaning":"đơn vị, tờ giấy nháp","pos":"Danh từ","example":{"zh":"他写了一张便条。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"写","py":"xiě"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"张","py":"zhāng"},{"c":"便","py":"biàn"},{"c":"条","py":"tiáo"},{"c":"。","py":"。"}],"vi":"Anh ấy viết một tờ nháp."}},{"hanzi":"传达","pinyin":"chuándá","hanViet":"TRUYỀN ĐẠT","meaning":"truyền tải, báo hiệu","pos":"Động từ","example":{"zh":"秘书传达了领导的指示。","pinyinPerChar":[{"c":"秘","py":"mì"},{"c":"书","py":"shū"},{"c":"传","py":"chuán"},{"c":"达","py":"dá"},{"c":"了","py":"le"},{"c":"领","py":"lǐng"},{"c":"导","py":"dǎo"},{"c":"的","py":"de"},{"c":"指","py":"zhǐ"},{"c":"示","py":"shì"},{"c":"。","py":"。"}],"vi":"Phụ tá đã truyền tải chỉ dẫn của lãnh đạo."}},{"hanzi":"打扮","pinyin":"dǎban","hanViet":"ĐẢ BAN","meaning":"trang trí, trang phục, làm đẹp","pos":"Động từ","example":{"zh":"她打扮得很漂亮。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"打","py":"dǎ"},{"c":"扮","py":"bàn"},{"c":"得","py":"dé"},{"c":"很","py":"hěn"},{"c":"漂","py":"piāo"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Cô ấy trang bị rất đẹp."}},{"hanzi":"高跟鞋","pinyin":"gāogēnxié","hanViet":"CAO CÂN HÀI","meaning":"giày có gót cao","pos":"Danh từ","example":{"zh":"她喜欢穿高跟鞋。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"穿","py":"chuān"},{"c":"高","py":"gāo"},{"c":"跟","py":"gēn"},{"c":"鞋","py":"xié"},{"c":"。","py":"。"}],"vi":"Cô ấy thích mặc giày cao gót."}},{"hanzi":"灰色","pinyin":"huīsè","hanViet":"HÔI SẮC","meaning":"màu xám","pos":"Tính từ","example":{"zh":"这件衣服是灰色。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"是","py":"shì"},{"c":"灰","py":"huī"},{"c":"色","py":"sè"},{"c":"。","py":"。"}],"vi":"Chiếc áo này màu xám."}},{"hanzi":"尽管","pinyin":"jǐnguǎn","hanViet":"TẬN QUẢN","meaning":"dù, mặc dù","pos":"Phó từ","example":{"zh":"尽管很累，他还是继续工作。","pinyinPerChar":[{"c":"尽","py":"jǐn"},{"c":"管","py":"guǎn"},{"c":"很","py":"hěn"},{"c":"累","py":"lèi"},{"c":"，","py":"，"},{"c":"他","py":"tā"},{"c":"还","py":"hái"},{"c":"是","py":"shì"},{"c":"继","py":"jì"},{"c":"续","py":"xù"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"。","py":"。"}],"vi":"Dù rất mệt, anh ta vẫn tiếp tục làm việc."}},{"hanzi":"矛盾","pinyin":"máodùn","hanViet":"MÂU THUẪN","meaning":"mâu thuẫn, xung đột","pos":"Danh từ","example":{"zh":"他们之间有矛盾。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"之","py":"zhī"},{"c":"间","py":"jiān"},{"c":"有","py":"yǒu"},{"c":"矛","py":"máo"},{"c":"盾","py":"dùn"},{"c":"。","py":"。"}],"vi":"Giữa họ có mâu thuẫn."}},{"hanzi":"牛仔裤","pinyin":"niúzǎikù","hanViet":"NGƯU TỂ KHỐ","meaning":"quần jean","pos":"Danh từ","example":{"zh":"他穿了一条牛仔裤。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"穿","py":"chuān"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"条","py":"tiáo"},{"c":"牛","py":"niú"},{"c":"仔","py":"zǎi"},{"c":"裤","py":"kù"},{"c":"。","py":"。"}],"vi":"Anh ấy mặc một chiếc quần jean."}},{"hanzi":"披","pinyin":"pī","hanViet":"PHI","meaning":"mặc, bọc, xếp","pos":"Động từ","example":{"zh":"她披着外套出门。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"披","py":"pī"},{"c":"着","py":"zhe"},{"c":"外","py":"wài"},{"c":"套","py":"tào"},{"c":"出","py":"chū"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Cô ấy mặc áo khoác bên ngoài ra đường."}},{"hanzi":"青","pinyin":"qīng","hanViet":"THANH","meaning":"xanh, thanh","pos":"Tính từ","example":{"zh":"天空很青。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"空","py":"kōng"},{"c":"很","py":"hěn"},{"c":"青","py":"qīng"},{"c":"。","py":"。"}],"vi":"Bầu trời rất xanh."}},{"hanzi":"染","pinyin":"rǎn","hanViet":"NHIỄM","meaning":"Tẩy, nhuộm, bám màu","pos":"Động từ","example":{"zh":"她染了头发。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"染","py":"rǎn"},{"c":"了","py":"le"},{"c":"头","py":"tóu"},{"c":"发","py":"fā"},{"c":"。","py":"。"}],"vi":"Cô ấy nhuộm tóc."}},{"hanzi":"绕","pinyin":"rào","hanViet":"NHIỄU","meaning":"Vòng quanh, tránh, lặp lại","pos":"Động từ","example":{"zh":"路绕着山。","pinyinPerChar":[{"c":"路","py":"lù"},{"c":"绕","py":"rào"},{"c":"着","py":"zhe"},{"c":"山","py":"shān"},{"c":"。","py":"。"}],"vi":"Đường vòng quanh núi."}},{"hanzi":"散","pinyin":"sǎn","hanViet":"TÁN","meaning":"phân tán, tháo gỡ","pos":"Động từ","example":{"zh":"风把纸张吹散了。","pinyinPerChar":[{"c":"风","py":"fēng"},{"c":"把","py":"bǎ"},{"c":"纸","py":"zhǐ"},{"c":"张","py":"zhāng"},{"c":"吹","py":"chuī"},{"c":"散","py":"sàn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Gió thổi bay tờ giấy."}},{"hanzi":"逃","pinyin":"táo","hanViet":"ĐÀO","meaning":"trốn, bỏ trốn","pos":"Động từ","example":{"zh":"他逃跑了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"逃","py":"táo"},{"c":"跑","py":"pǎo"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ta trốn đi."}},{"hanzi":"逃跑","pinyin":"táopǎo","hanViet":"ĐÀO BÀO","meaning":"trốn chạy, bỏ trốn","pos":"Động từ","example":{"zh":"他们决定逃跑。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"决","py":"jué"},{"c":"定","py":"dìng"},{"c":"逃","py":"táo"},{"c":"跑","py":"pǎo"},{"c":"。","py":"。"}],"vi":"Họ quyết định trốn chạy."}},{"hanzi":"桃","pinyin":"táo","hanViet":"ĐÀO","meaning":"đào (cây, trái)","pos":"Danh từ","example":{"zh":"桃子很甜。","pinyinPerChar":[{"c":"桃","py":"táo"},{"c":"子","py":"zi"},{"c":"很","py":"hěn"},{"c":"甜","py":"tián"},{"c":"。","py":"。"}],"vi":"Quả đào rất ngọt."}},{"hanzi":"桃树","pinyin":"táoshù","hanViet":"ĐÀO THỤ","meaning":"cây đào","pos":"Danh từ","example":{"zh":"桃树开花了。","pinyinPerChar":[{"c":"桃","py":"táo"},{"c":"树","py":"shù"},{"c":"开","py":"kāi"},{"c":"花","py":"huā"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Cây đào đã nở hoa."}},{"hanzi":"调节","pinyin":"tiáojié","hanViet":"ĐIỆU TIẾT","meaning":"sắp xếp, điều chỉnh, điều tiết","pos":"Động từ","example":{"zh":"请调节音量。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"调","py":"diào"},{"c":"节","py":"jié"},{"c":"音","py":"yīn"},{"c":"量","py":"liàng"},{"c":"。","py":"。"}],"vi":"Xin điều chỉnh âm lượng."}},{"hanzi":"西装","pinyin":"xīzhuāng","hanViet":"TÂY TRANG","meaning":"quần áo lịch sự, bộ vest và quần","pos":"Danh từ","example":{"zh":"他穿西装去会议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"穿","py":"chuān"},{"c":"西","py":"xī"},{"c":"装","py":"zhuāng"},{"c":"去","py":"qù"},{"c":"会","py":"huì"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Anh ta mặc vest đi họp."}},{"hanzi":"鲜艳","pinyin":"xiānyàn","hanViet":"TIÊN DIỄM","meaning":"sặc sỡ, rực rỡ","pos":"Tính từ","example":{"zh":"花儿很鲜艳。","pinyinPerChar":[{"c":"花","py":"huā"},{"c":"儿","py":"ér"},{"c":"很","py":"hěn"},{"c":"鲜","py":"xiān"},{"c":"艳","py":"yàn"},{"c":"。","py":"。"}],"vi":"Hoa rất sặc sỡ."}},{"hanzi":"摇头","pinyin":"yáotóu","hanViet":"DAO ĐẦU","meaning":"lắc đầu; từ chối","pos":"Động từ","example":{"zh":"他摇头表示不同意。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"摇","py":"yáo"},{"c":"头","py":"tóu"},{"c":"表","py":"biǎo"},{"c":"示","py":"shì"},{"c":"不","py":"bù"},{"c":"同","py":"tóng"},{"c":"意","py":"yì"},{"c":"。","py":"。"}],"vi":"Cậu ấy lắc đầu thể hiện sự không đồng ý."}},{"hanzi":"紫","pinyin":"zǐ","hanViet":"TỬ","meaning":"tử, màu tím","pos":"Tính từ","example":{"zh":"这朵花是紫色的。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"朵","py":"duǒ"},{"c":"花","py":"huā"},{"c":"是","py":"shì"},{"c":"紫","py":"zǐ"},{"c":"色","py":"sè"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Cành hoa này màu tím."}},{"hanzi":"总数","pinyin":"zǒngshù","hanViet":"TỔNG SỐ","meaning":"tổng cộng, số lượng tất cả","pos":"Danh từ","example":{"zh":"总数是多少？","pinyinPerChar":[{"c":"总","py":"zǒng"},{"c":"数","py":"shù"},{"c":"是","py":"shì"},{"c":"多","py":"duō"},{"c":"少","py":"shǎo"},{"c":"？","py":"？"}],"vi":"Tổng số là bao nhiêu?"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-23', 22, 'Giao tiếp & lời nói', '[{"hanzi":"本人","pinyin":"běnrén","hanViet":"BẢN NHÂN","meaning":"người nói/người đề cập","pos":"Danh từ","example":{"zh":"本人已签署文件。","pinyinPerChar":[{"c":"本","py":"běn"},{"c":"人","py":"rén"},{"c":"已","py":"yǐ"},{"c":"签","py":"qiān"},{"c":"署","py":"shǔ"},{"c":"文","py":"wén"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Người nói đã ký văn bản."}},{"hanzi":"称2","pinyin":"chēng","hanViet":"XƯNG","meaning":"nói tên, gọi","pos":"Động từ","example":{"zh":"他称他为朋友。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"称","py":"chēng"},{"c":"他","py":"tā"},{"c":"为","py":"wèi"},{"c":"朋","py":"péng"},{"c":"友","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Anh ta gọi anh ấy là bạn."}},{"hanzi":"传真","pinyin":"chuánzhēn","hanViet":"TRUYỀN CHÂN","meaning":"gửi thư điện tử, fax","pos":"Danh từ","example":{"zh":"请用传真把文件发给我。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"用","py":"yòng"},{"c":"传","py":"chuán"},{"c":"真","py":"zhēn"},{"c":"把","py":"bǎ"},{"c":"文","py":"wén"},{"c":"件","py":"jiàn"},{"c":"发","py":"fā"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Vui lòng gửi tài liệu qua fax cho tôi."}},{"hanzi":"答","pinyin":"dá","hanViet":"ĐÁP","meaning":"trả lời, đáp lại","pos":"Động từ","example":{"zh":"请你回答问题。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"你","py":"nǐ"},{"c":"回","py":"huí"},{"c":"答","py":"dá"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Hãy trả lời câu hỏi."}},{"hanzi":"答复","pinyin":"dáfù","hanViet":"ĐÁP PHỤC","meaning":"trả lời, phản hồi, thông báo lại","pos":"Động từ","example":{"zh":"他没有答复我的邮件。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"答","py":"dá"},{"c":"复","py":"fù"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"邮","py":"yóu"},{"c":"件","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Anh ấy không trả lời email của tôi."}},{"hanzi":"分解","pinyin":"fēnjiě","hanViet":"PHÂN GIẢI","meaning":"phân rã, giải thích","pos":"Động từ","example":{"zh":"这个问题分解成几个小问题。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"分","py":"fēn"},{"c":"解","py":"jiě"},{"c":"成","py":"chéng"},{"c":"几","py":"jǐ"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Vấn đề này được phân rã thành một số vấn đề nhỏ."}},{"hanzi":"公告","pinyin":"gōnggào","hanViet":"CÔNG CÁO","meaning":"thông báo chính thức","pos":"Danh từ","example":{"zh":"学校发布了新的公告。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"发","py":"fā"},{"c":"布","py":"bù"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"的","py":"de"},{"c":"公","py":"gōng"},{"c":"告","py":"gào"},{"c":"。","py":"。"}],"vi":"Trường học đã phát ra thông báo mới."}},{"hanzi":"共享","pinyin":"gòngxiǎng","hanViet":"CỘNG HƯỞNG","meaning":"cùng dùng, chia sẻ","pos":"Động từ","example":{"zh":"我们共享这个资源。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"共","py":"gòng"},{"c":"享","py":"xiǎng"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"资","py":"zī"},{"c":"源","py":"yuán"},{"c":"。","py":"。"}],"vi":"Chúng tôi cùng dùng tài nguyên này."}},{"hanzi":"回信","pinyin":"huíxìn","hanViet":"HỒI TÍN","meaning":"trả lời thư","pos":"Danh từ","example":{"zh":"我等你的回信。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"等","py":"děng"},{"c":"你","py":"nǐ"},{"c":"的","py":"de"},{"c":"回","py":"huí"},{"c":"信","py":"xìn"},{"c":"。","py":"。"}],"vi":"Tôi đang chờ tin nhắn của bạn."}},{"hanzi":"奖励","pinyin":"jiǎnglì","hanViet":"THƯỞNG LỆ","meaning":"khen thưởng","pos":"Động từ","example":{"zh":"老师奖励了优秀学生。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"奖","py":"jiǎng"},{"c":"励","py":"lì"},{"c":"了","py":"le"},{"c":"优","py":"yōu"},{"c":"秀","py":"xiù"},{"c":"学","py":"xué"},{"c":"生","py":"shēng"},{"c":"。","py":"。"}],"vi":"Giáo viên khen thưởng học sinh giỏi."}},{"hanzi":"交代","pinyin":"jiāodài","hanViet":"GIAO ĐẠI","meaning":"giải thích, chỉ rõ","pos":"Động từ","example":{"zh":"请你交代一下原因。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"你","py":"nǐ"},{"c":"交","py":"jiāo"},{"c":"代","py":"dài"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"原","py":"yuán"},{"c":"因","py":"yīn"},{"c":"。","py":"。"}],"vi":"Xin bạn giải thích nguyên nhân."}},{"hanzi":"拒绝","pinyin":"jùjué","hanViet":"CỰ TUYỆT","meaning":"từ chối","pos":"Động từ","example":{"zh":"他拒绝接受。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"拒","py":"jù"},{"c":"绝","py":"jué"},{"c":"接","py":"jiē"},{"c":"受","py":"shòu"},{"c":"。","py":"。"}],"vi":"Anh ta từ chối chấp nhận."}},{"hanzi":"连接","pinyin":"liánjiē","hanViet":"LIÊN TIẾP","meaning":"kết nối","pos":"Động từ","example":{"zh":"他连接两台电脑。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"连","py":"lián"},{"c":"接","py":"jiē"},{"c":"两","py":"liǎng"},{"c":"台","py":"tái"},{"c":"电","py":"diàn"},{"c":"脑","py":"nǎo"},{"c":"。","py":"。"}],"vi":"Anh ấy kết nối hai máy tính."}},{"hanzi":"联络","pinyin":"liánluò","hanViet":"LIÊN LẠC","meaning":"liên lạc","pos":"Động từ","example":{"zh":"我联络了他。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"联","py":"lián"},{"c":"络","py":"luò"},{"c":"了","py":"le"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Tôi liên lạc với anh ấy."}},{"hanzi":"赔","pinyin":"péi","hanViet":"BỒI","meaning":"bồi thường, đền bù","pos":"Động từ","example":{"zh":"公司赔了顾客钱。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"赔","py":"péi"},{"c":"了","py":"le"},{"c":"顾","py":"gù"},{"c":"客","py":"kè"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Công ty bồi thường cho khách hàng tiền."}},{"hanzi":"频繁","pinyin":"pínfán","hanViet":"TẦN PHỒN","meaning":"nhiều lần, thường xuyên","pos":"Tính từ","example":{"zh":"他经常来，很频繁。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"经","py":"jīng"},{"c":"常","py":"cháng"},{"c":"来","py":"lái"},{"c":"，","py":"，"},{"c":"很","py":"hěn"},{"c":"频","py":"pín"},{"c":"繁","py":"fán"},{"c":"。","py":"。"}],"vi":"Anh ấy đến thường xuyên, rất nhiều lần."}},{"hanzi":"情节","pinyin":"qíngjié","hanViet":"TÌNH TIẾT","meaning":"Chuyện kể, mạch truyện, cốt truyện","pos":"Danh từ","example":{"zh":"这部电影的情节很有意思。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"的","py":"de"},{"c":"情","py":"qíng"},{"c":"节","py":"jié"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"sī"},{"c":"。","py":"。"}],"vi":"Cốt truyện phim này rất hay."}},{"hanzi":"劝","pinyin":"quàn","hanViet":"KHUYẾN","meaning":"Khuyên, thuyết phục","pos":"Động từ","example":{"zh":"她劝我不要迟到。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"劝","py":"quàn"},{"c":"我","py":"wǒ"},{"c":"不","py":"bù"},{"c":"要","py":"yào"},{"c":"迟","py":"chí"},{"c":"到","py":"dào"},{"c":"。","py":"。"}],"vi":"Cô ấy khuyên tôi không nên đến muộn."}},{"hanzi":"说法","pinyin":"shuōfǎ","hanViet":"THUYẾT PHÁP","meaning":"cách diễn đạt, cách nói","pos":"Danh từ","example":{"zh":"他有自己的说法。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"说","py":"shuō"},{"c":"法","py":"fǎ"},{"c":"。","py":"。"}],"vi":"Anh ấy có cách nhìn nhận của riêng mình."}},{"hanzi":"提示","pinyin":"tíshì","hanViet":"ĐỀ THỊ","meaning":"gợi ý, chỉ dẫn","pos":"Danh từ","example":{"zh":"屏幕上有提示。","pinyinPerChar":[{"c":"屏","py":"píng"},{"c":"幕","py":"mù"},{"c":"上","py":"shàng"},{"c":"有","py":"yǒu"},{"c":"提","py":"tí"},{"c":"示","py":"shì"},{"c":"。","py":"。"}],"vi":"Màn hình có gợi ý."}},{"hanzi":"体积","pinyin":"tǐjī","hanViet":"THỂ TÍCH","meaning":"thể tích, kích thước","pos":"Danh từ","example":{"zh":"这个箱子的体积很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"箱","py":"xiāng"},{"c":"子","py":"zi"},{"c":"的","py":"de"},{"c":"体","py":"tǐ"},{"c":"积","py":"jī"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Hộp này có kích thước rất lớn."}},{"hanzi":"调解","pinyin":"tiáojiě","hanViet":"ĐIỆU GIẢI","meaning":"thông thương, hòa giải, can thiệp để giải quyết mâu thuẫn","pos":"Động từ","example":{"zh":"法官帮助调解纠纷。","pinyinPerChar":[{"c":"法","py":"fǎ"},{"c":"官","py":"guān"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"调","py":"diào"},{"c":"解","py":"jiě"},{"c":"纠","py":"jiū"},{"c":"纷","py":"fēn"},{"c":"。","py":"。"}],"vi":"Công tước giúp hòa giải tranh chấp."}},{"hanzi":"脱离","pinyin":"tuōlí","hanViet":"THOÁT LY","meaning":"tách rời, rời khỏi","pos":"Động từ","example":{"zh":"他脱离了团队。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"脱","py":"tuō"},{"c":"离","py":"lí"},{"c":"了","py":"le"},{"c":"团","py":"tuán"},{"c":"队","py":"duì"},{"c":"。","py":"。"}],"vi":"Anh ấy đã rời khỏi nhóm."}},{"hanzi":"微博","pinyin":"wēibó","hanViet":"VI BÁC","meaning":"blog nhỏ, mạng xã hội viết blog","pos":"Danh từ","example":{"zh":"她在微博上发帖。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"在","py":"zài"},{"c":"微","py":"wēi"},{"c":"博","py":"bó"},{"c":"上","py":"shàng"},{"c":"发","py":"fā"},{"c":"帖","py":"tiē"},{"c":"。","py":"。"}],"vi":"Cô ấy đăng bài trên blog nhỏ."}},{"hanzi":"慰问","pinyin":"wèiwèn","hanViet":"UỶ VẤN","meaning":"xoa dịu, thăm hỏi","pos":"Động từ","example":{"zh":"他们慰问了受伤的人。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"慰","py":"wèi"},{"c":"问","py":"wèn"},{"c":"了","py":"le"},{"c":"受","py":"shòu"},{"c":"伤","py":"shāng"},{"c":"的","py":"de"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Họ thăm hỏi người bị thương."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-24', 23, 'Giải trí & thể thao', '[{"hanzi":"博物馆","pinyin":"bówùguǎn","hanViet":"BÁC VẬT QUÁN","meaning":"bảo tàng","pos":"Danh từ","example":{"zh":"博物馆里有很多古物。","pinyinPerChar":[{"c":"博","py":"bó"},{"c":"物","py":"wù"},{"c":"馆","py":"guǎn"},{"c":"里","py":"lǐ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"古","py":"gǔ"},{"c":"物","py":"wù"},{"c":"。","py":"。"}],"vi":"Bảo tàng có nhiều vật cổ."}},{"hanzi":"发觉","pinyin":"fājué","hanViet":"PHÁT GIÁC","meaning":"phát hiện, nhận ra","pos":"Động từ","example":{"zh":"他发觉了问题。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"发","py":"fā"},{"c":"觉","py":"jué"},{"c":"了","py":"le"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"。","py":"。"}],"vi":"Anh ấy phát hiện ra vấn đề."}},{"hanzi":"发射","pinyin":"fāshè","hanViet":"PHÁT XẠ","meaning":"phát ra, bắn ra","pos":"Động từ","example":{"zh":"火箭发射成功。","pinyinPerChar":[{"c":"火","py":"huǒ"},{"c":"箭","py":"jiàn"},{"c":"发","py":"fā"},{"c":"射","py":"shè"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Tên lửa đã phóng thành công."}},{"hanzi":"钢琴","pinyin":"gāngqín","hanViet":"CƯƠNG CẦM","meaning":"dàn nhạc cụ bằng gỗ, phát ra âm thanh trầm","pos":"Danh từ","example":{"zh":"她每天晚上弹钢琴。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"每","py":"měi"},{"c":"天","py":"tiān"},{"c":"晚","py":"wǎn"},{"c":"上","py":"shàng"},{"c":"弹","py":"dàn"},{"c":"钢","py":"gāng"},{"c":"琴","py":"qín"},{"c":"。","py":"。"}],"vi":"Cô ấy mỗi tối tối lại đàn piano."}},{"hanzi":"歌曲","pinyin":"gēqǔ","hanViet":"CA KHÚC","meaning":"bài hát, bài ca","pos":"Danh từ","example":{"zh":"这首歌曲很好听。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"首","py":"shǒu"},{"c":"歌","py":"gē"},{"c":"曲","py":"qū"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"听","py":"tīng"},{"c":"。","py":"。"}],"vi":"Bài hát này nghe rất hay."}},{"hanzi":"进化","pinyin":"jìnhuà","hanViet":"TIẾN HOÁ","meaning":"tiến hóa, phát triển","pos":"Động từ","example":{"zh":"生物不断进化。","pinyinPerChar":[{"c":"生","py":"shēng"},{"c":"物","py":"wù"},{"c":"不","py":"bù"},{"c":"断","py":"duàn"},{"c":"进","py":"jìn"},{"c":"化","py":"huà"},{"c":"。","py":"。"}],"vi":"Sinh vật không ngừng tiến hóa."}},{"hanzi":"竞争","pinyin":"jìngzhēng","hanViet":"CẠNH TRANH","meaning":"cạnh tranh","pos":"Động từ","example":{"zh":"公司之间竞争激烈。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"之","py":"zhī"},{"c":"间","py":"jiān"},{"c":"竞","py":"jìng"},{"c":"争","py":"zhēng"},{"c":"激","py":"jī"},{"c":"烈","py":"liè"},{"c":"。","py":"。"}],"vi":"Công ty cạnh tranh gay gắt."}},{"hanzi":"看出","pinyin":"kànchū","hanViet":"KHÁN XUẤT","meaning":"nhận ra, phát hiện ra","pos":"Động từ","example":{"zh":"我看出了他的难过。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"看","py":"kàn"},{"c":"出","py":"chū"},{"c":"了","py":"le"},{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"难","py":"nán"},{"c":"过","py":"guò"},{"c":"。","py":"。"}],"vi":"Tôi nhận ra nỗi buồn của anh ấy."}},{"hanzi":"漫画","pinyin":"mànhuà","hanViet":"MẠN HOẠ","meaning":"tiểu thuyết tranh, tranh","pos":"Danh từ","example":{"zh":"他喜欢看漫画。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"看","py":"kàn"},{"c":"漫","py":"màn"},{"c":"画","py":"huà"},{"c":"。","py":"。"}],"vi":"Anh ấy thích đọc tranh."}},{"hanzi":"拍摄","pinyin":"pāishè","hanViet":"PHÁCH NHIẾP","meaning":"chụp ảnh, quay phim","pos":"Động từ","example":{"zh":"他们正在拍摄电影。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"拍","py":"pāi"},{"c":"摄","py":"shè"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"。","py":"。"}],"vi":"Họ đang quay phim."}},{"hanzi":"拼","pinyin":"pīn","hanViet":"BÍNH","meaning":"nối, hợp, cạnh tranh","pos":"Động từ","example":{"zh":"我们拼命学习。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"拼","py":"pīn"},{"c":"命","py":"mìng"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Chúng tôi học giỏi hết mình."}},{"hanzi":"琴","pinyin":"qín","hanViet":"CẦM","meaning":"đàn ghi-ta, nhạc cụ","pos":"Danh từ","example":{"zh":"他弹琴。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"弹","py":"dàn"},{"c":"琴","py":"qín"},{"c":"。","py":"。"}],"vi":"Anh ấy chơi đàn ghi-ta."}},{"hanzi":"摄像","pinyin":"shèxiàng","hanViet":"NHIẾP TƯỢNG","meaning":"chụp ảnh, quay phim","pos":"Động từ","example":{"zh":"他正在摄像这个场景。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"摄","py":"shè"},{"c":"像","py":"xiàng"},{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"场","py":"chǎng"},{"c":"景","py":"jǐng"},{"c":"。","py":"。"}],"vi":"Anh ấy đang quay cảnh này."}},{"hanzi":"摄像机","pinyin":"shèxiàngjī","hanViet":"NHIẾP TƯỢNG CƠ","meaning":"máy quay phim, máy ảnh","pos":"Danh từ","example":{"zh":"这台摄像机很贵。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"台","py":"tái"},{"c":"摄","py":"shè"},{"c":"像","py":"xiàng"},{"c":"机","py":"jī"},{"c":"很","py":"hěn"},{"c":"贵","py":"guì"},{"c":"。","py":"。"}],"vi":"Máy quay này rất đắt."}},{"hanzi":"摄影","pinyin":"shèyǐng","hanViet":"NHIẾP ẢNH","meaning":"chụp ảnh","pos":"Động từ","example":{"zh":"她喜欢摄影。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"摄","py":"shè"},{"c":"影","py":"yǐng"},{"c":"。","py":"。"}],"vi":"Cô ấy thích chụp ảnh."}},{"hanzi":"摄影师","pinyin":"shèyǐngshī","hanViet":"NHIẾP ẢNH SƯ","meaning":"nghệ sĩ chụp ảnh","pos":"Danh từ","example":{"zh":"这位摄影师很有名。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"位","py":"wèi"},{"c":"摄","py":"shè"},{"c":"影","py":"yǐng"},{"c":"师","py":"shī"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"名","py":"míng"},{"c":"。","py":"。"}],"vi":"Nghệ sĩ chụp ảnh này rất nổi tiếng."}},{"hanzi":"舞","pinyin":"wǔ","hanViet":"VŨ","meaning":"nhảy múa, biểu diễn múa","pos":"Động từ","example":{"zh":"她会跳舞。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"会","py":"huì"},{"c":"跳","py":"tiào"},{"c":"舞","py":"wǔ"},{"c":"。","py":"。"}],"vi":"Cô ấy biết nhảy múa."}},{"hanzi":"喜剧","pinyin":"xǐjù","hanViet":"HỶ KỊCH","meaning":"tiểu thuyết hài, phim hài","pos":"Danh từ","example":{"zh":"这部喜剧很有趣。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"喜","py":"xǐ"},{"c":"剧","py":"jù"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"趣","py":"qù"},{"c":"。","py":"。"}],"vi":"Phim hài này rất hay."}},{"hanzi":"戏","pinyin":"xì","hanViet":"HÍ","meaning":"kịch, vở kịch; trò chơi, trò lừa","pos":"Danh từ","example":{"zh":"他喜欢看戏。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"看","py":"kàn"},{"c":"戏","py":"xì"},{"c":"。","py":"。"}],"vi":"Anh ta thích xem kịch."}},{"hanzi":"戏剧","pinyin":"xìjù","hanViet":"HÍ KỊCH","meaning":"kịch, nghệ thuật kịch","pos":"Danh từ","example":{"zh":"戏剧让人感动。","pinyinPerChar":[{"c":"戏","py":"xì"},{"c":"剧","py":"jù"},{"c":"让","py":"ràng"},{"c":"人","py":"rén"},{"c":"感","py":"gǎn"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Kịch làm người cảm động."}},{"hanzi":"游泳池","pinyin":"yóuyǒngchí","hanViet":"DU VỊNH TRÌ","meaning":"bể bơi","pos":"Danh từ","example":{"zh":"孩子们喜欢在游泳池里玩水。","pinyinPerChar":[{"c":"孩","py":"hái"},{"c":"子","py":"zi"},{"c":"们","py":"men"},{"c":"喜","py":"xǐ"},{"c":"欢","py":"huān"},{"c":"在","py":"zài"},{"c":"游","py":"yóu"},{"c":"泳","py":"yǒng"},{"c":"池","py":"chí"},{"c":"里","py":"lǐ"},{"c":"玩","py":"wán"},{"c":"水","py":"shuǐ"},{"c":"。","py":"。"}],"vi":"Các em nhỏ thích chơi nước trong bể bơi."}},{"hanzi":"争议","pinyin":"zhēngyì","hanViet":"TRANH NGHỊ","meaning":"vấn đề tranh cãi","pos":"Danh từ","example":{"zh":"这个问题引发了争议。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"引","py":"yǐn"},{"c":"发","py":"fā"},{"c":"了","py":"le"},{"c":"争","py":"zhēng"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Vấn đề này đã gây ra tranh cãi."}},{"hanzi":"专辑","pinyin":"zhuānjí","hanViet":"CHUYÊN TẬP","meaning":"album, tập bản nhạc","pos":"Danh từ","example":{"zh":"这张专辑很受欢迎。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"张","py":"zhāng"},{"c":"专","py":"zhuān"},{"c":"辑","py":"jí"},{"c":"很","py":"hěn"},{"c":"受","py":"shòu"},{"c":"欢","py":"huān"},{"c":"迎","py":"yíng"},{"c":"。","py":"。"}],"vi":"Album này rất được nhiều người thích."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-25', 24, 'Suy nghĩ & ý kiến', '[{"hanzi":"必","pinyin":"bì","hanViet":"TẤT","meaning":"bắt buộc, chắc chắn","pos":"Động từ","example":{"zh":"你必需到场。","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"必","py":"bì"},{"c":"需","py":"xū"},{"c":"到","py":"dào"},{"c":"场","py":"chǎng"},{"c":"。","py":"。"}],"vi":"Bạn phải có mặt."}},{"hanzi":"猜","pinyin":"cāi","hanViet":"SAI","meaning":"đoán, đoán","pos":"Động từ","example":{"zh":"我猜他会来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"猜","py":"cāi"},{"c":"他","py":"tā"},{"c":"会","py":"huì"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi đoán cậu ấy sẽ đến."}},{"hanzi":"猜测","pinyin":"cāicè","hanViet":"SAI TRẮC","meaning":"đoán, suy đoán","pos":"Danh từ","example":{"zh":"他做了一次猜测。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"做","py":"zuò"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"次","py":"cì"},{"c":"猜","py":"cāi"},{"c":"测","py":"cè"},{"c":"。","py":"。"}],"vi":"Cậu ấy đã đưa ra một sự đoán."}},{"hanzi":"达成","pinyin":"dáchéng","hanViet":"ĐẠT THÀNH","meaning":"đạt được, đạt được kết quả, thỏa thuận","pos":"Động từ","example":{"zh":"他们达成了协议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"达","py":"dá"},{"c":"成","py":"chéng"},{"c":"了","py":"le"},{"c":"协","py":"xié"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Họ đã đạt được thỏa thuận."}},{"hanzi":"大致","pinyin":"dàzhì","hanViet":"ĐẠI TRÍ","meaning":"tổng hợp, sơ bộ","pos":"Tính từ","example":{"zh":"大致情况还可以。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"致","py":"zhì"},{"c":"情","py":"qíng"},{"c":"况","py":"kuàng"},{"c":"还","py":"hái"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"。","py":"。"}],"vi":"Tình hình tổng thể còn ổn."}},{"hanzi":"动机","pinyin":"dòngjī","hanViet":"ĐỘNG CƠ","meaning":"lý do, động lực, mục đích","pos":"Danh từ","example":{"zh":"他有什么动机？","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"什","py":"shén"},{"c":"么","py":"me"},{"c":"动","py":"dòng"},{"c"