INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-29', 28, 'Hành động & vận động (3)', '[{"hanzi":"起到","pinyin":"qǐdào","hanViet":"KHỞI ĐÁO","meaning":"đóng vai trò, tạo ra","pos":"Động từ","example":{"zh":"运动起到健康作用。","pinyinPerChar":[{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"起","py":"qǐ"},{"c":"到","py":"dào"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"作","py":"zuò"},{"c":"用","py":"yòng"},{"c":"。","py":"。"}],"vi":"Vận động tạo ra tác dụng sức khỏe."}},{"hanzi":"前提","pinyin":"qiántí","hanViet":"TIỀN ĐỀ","meaning":"giả định, điều kiện","pos":"Danh từ","example":{"zh":"没有前提就不能讨论。","pinyinPerChar":[{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"前","py":"qián"},{"c":"提","py":"tí"},{"c":"就","py":"jiù"},{"c":"不","py":"bù"},{"c":"能","py":"néng"},{"c":"讨","py":"tǎo"},{"c":"论","py":"lùn"},{"c":"。","py":"。"}],"vi":"Không có điều kiện thì không thể thảo luận."}},{"hanzi":"抢","pinyin":"qiǎng","hanViet":"THƯỞNG","meaning":"lấy, nắm, tranh","pos":"Động từ","example":{"zh":"他抢过那本书。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"抢","py":"qiǎng"},{"c":"过","py":"guò"},{"c":"那","py":"nà"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Anh ấy đã lấy/sở hữu cuốn sách đó."}},{"hanzi":"敲","pinyin":"qiāo","hanViet":"XAO","meaning":"vụn, đánh trống","pos":"Động từ","example":{"zh":"他敲门。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"敲","py":"qiāo"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Anh ấy vúm cửa."}},{"hanzi":"扔","pinyin":"rēng","hanViet":"NHƯNG","meaning":"ném, vứt","pos":"Động từ","example":{"zh":"她把书扔在桌上。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"把","py":"bǎ"},{"c":"书","py":"shū"},{"c":"扔","py":"rēng"},{"c":"在","py":"zài"},{"c":"桌","py":"zhuō"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Cô ấy ném sách lên bàn."}},{"hanzi":"如同","pinyin":"rútóng","hanViet":"NHƯ ĐỒNG","meaning":"giống như, như","pos":"Liên từ","example":{"zh":"他如同父亲一样努力。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"如","py":"rú"},