INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-32', 31, 'Bổ sung (2)', '[{"hanzi":"仍旧","pinyin":"réngjiù","hanViet":"NHƯNG CỰU","meaning":"vẫn, vẫn còn","pos":"Phó từ","example":{"zh":"天气仍旧很冷。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"仍","py":"réng"},{"c":"旧","py":"jiù"},{"c":"很","py":"hěn"},{"c":"冷","py":"lěng"},{"c":"。","py":"。"}],"vi":"Thời tiết vẫn rất lạnh."}},{"hanzi":"从中","pinyin":"cóngzhōng","hanViet":"TÒNG TRUNG","meaning":"từ trong, từ giữa, từ đó","pos":"Danh từ","example":{"zh":"我们从中得到了很多经验。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"从","py":"cóng"},{"c":"中","py":"zhōng"},{"c":"得","py":"dé"},{"c":"到","py":"dào"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"经","py":"jīng"},{"c":"验","py":"yàn"},{"c":"。","py":"。"}],"vi":"Chúng ta đã rút ra được nhiều kinh nghiệm từ đó."}},{"hanzi":"仔细","pinyin":"zǐxì","hanViet":"TỂ TẾ","meaning":"cẩn thận, chi tiết","pos":"Tính từ","example":{"zh":"请你仔细检查。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"你","py":"nǐ"},{"c":"仔","py":"zǎi"},{"c":"细","py":"xì"},{"c":"检","py":"jiǎn"},{"c":"查","py":"chá"},{"c":"。","py":"。"}],"vi":"Hãy kiểm tra cẩn thận."}},{"hanzi":"代理","pinyin":"dàilǐ","hanViet":"ĐẠI LÝ","meaning":"đại diện, ủy thác","pos":"Danh từ","example":{"zh":"他是代理公司。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"代","py":"dài"},{"c":"理","py":"lǐ"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"。","py":"。"}],"vi":"Anh ta là công ty đại diện."}},{"hanzi":"令","pinyin":"lìng","hanViet":"LỆNH","meaning":"kỳ, chỉ","pos":"Tính từ","example":{"zh":"今天天气很好。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Hôm nay thời tiết rất tốt."}},{"hanzi":"休闲","pinyin":"xiūxián","hanViet":"HƯU NHÀN","meaning":"Dịch vụ giải trí, thoải mái","pos":"Tính từ","example":{"zh":"这家酒店提供休闲服务。","piny