INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-33', 32, 'Bổ sung (3)', '[{"hanzi":"公认","pinyin":"gōngrèn","hanViet":"CÔNG NHẬN","meaning":"được mọi người thừa nhận","pos":"Tính từ","example":{"zh":"这件事是公认的事实。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"是","py":"shì"},{"c":"公","py":"gōng"},{"c":"认","py":"rèn"},{"c":"的","py":"de"},{"c":"事","py":"shì"},{"c":"实","py":"shí"},{"c":"。","py":"。"}],"vi":"Việc này là sự thật được mọi người thừa nhận."}},{"hanzi":"共计","pinyin":"gòngjì","hanViet":"CỘNG KẾ","meaning":"tổng cộng","pos":"Danh từ","example":{"zh":"共计三个人。","pinyinPerChar":[{"c":"共","py":"gòng"},{"c":"计","py":"jì"},{"c":"三","py":"sān"},{"c":"个","py":"gè"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Tổng cộng có ba người."}},{"hanzi":"其","pinyin":"qí","hanViet":"KỲ","meaning":"đó, của nó","pos":"Đại từ","example":{"zh":"其实很简单。","pinyinPerChar":[{"c":"其","py":"qí"},{"c":"实","py":"shí"},{"c":"很","py":"hěn"},{"c":"简","py":"jiǎn"},{"c":"单","py":"dān"},{"c":"。","py":"。"}],"vi":"Điều thực tế rất đơn giản."}},{"hanzi":"内在","pinyin":"nèizài","hanViet":"NỘI TẠI","meaning":"trong bản thân, nội tại","pos":"Tính từ","example":{"zh":"她的内在品质很重要。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"的","py":"de"},{"c":"内","py":"nèi"},{"c":"在","py":"zài"},{"c":"品","py":"pǐn"},{"c":"质","py":"zhì"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Năng lực nội tại của cô ấy rất quan trọng."}},{"hanzi":"册","pinyin":"cè","hanViet":"SÁCH","meaning":"tờ, quyển, tập","pos":"Danh từ","example":{"zh":"这是一本册子。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"本","py":"běn"},{"c":"册","py":"cè"},{"c":"子","py":"zi"},{"c":"。","py":"。"}],"vi":"Đây là một tờ tài liệu."}},{"hanzi":"再次","pinyin":"zàicì","hanViet":"TÁI THỨ","meaning":"một lần nữa","pos":"Phó từ","example":{"zh":"我再次见到他。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"再","py":"zài"},{"c":"次","py":"cì"},{"c":"见","py":"jiàn"},{"c":"到","py":"dào"},{"c":"他","py":"tā"},{"c":"。","py":"。"}],"vi":"Tôi gặp cậu ta một lần nữa."}},{"hanzi":"冒","pinyin":"mào","hanViet":"MẠO","meaning":"mạo, mạo hiểm","pos":"Động từ","example":{"zh":"他冒险去山上。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"冒","py":"mào"},{"c":"险","py":"xiǎn"},{"c":"去","py":"qù"},{"c":"山","py":"shān"},{"c":"上","py":"shàng"},{"c":"。","py":"。"}],"vi":"Anh ấy mạo hiểm đi lên núi."}},{"hanzi":"冠军","pinyin":"guànjūn","hanViet":"QUAN QUÂN","meaning":"vị tướng, người chiến thắng","pos":"Danh từ","example":{"zh":"他获得了冠军。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"获","py":"huò"},{"c":"得","py":"dé"},{"c":"了","py":"le"},{"c":"冠","py":"guān"},{"c":"军","py":"jūn"},{"c":"。","py":"。"}],"vi":"Anh ấy đã giành được huy chương."}},{"hanzi":"冲突","pinyin":"chōngtū","hanViet":"XUNG ĐỘT","meaning":"xung đột, mâu thuẫn","pos":"Danh từ","example":{"zh":"他们发生冲突。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"发","py":"fā"},{"c":"生","py":"shēng"},{"c":"冲","py":"chōng"},{"c":"突","py":"tū"},{"c":"。","py":"。"}],"vi":"Họ xảy ra xung đột."}},{"hanzi":"减轻","pinyin":"jiǎnqīng","hanViet":"GIẢM KHINH","meaning":"giảm bớt, làm nhẹ","pos":"Động từ","example":{"zh":"他减轻了负担。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"减","py":"jiǎn"},{"c":"轻","py":"qīng"},{"c":"了","py":"le"},{"c":"负","py":"fù"},{"c":"担","py":"dān"},{"c":"。","py":"。"}],"vi":"Anh ấy giảm gánh nặng."}},{"hanzi":"出于","pinyin":"chūyú","hanViet":"XUẤT Ư","meaning":"do, vì","pos":"Liên từ","example":{"zh":"他出于好意帮我。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"出","py":"chū"},{"c":"于","py":"yú"},{"c":"好","py":"hǎo"},{"c":"意","py":"yì"},{"c":"帮","py":"bāng"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Anh ấy giúp tôi vì tốt bụng."}},{"hanzi":"出汗","pinyin":"chūhàn","hanViet":"XUẤT HÃN","meaning":"đổ mồ hôi","pos":"Động từ","example":{"zh":"运动后我出汗很多。","pinyinPerChar":[{"c":"运","py":"yùn"},{"c":"动","py":"dòng"},{"c":"后","py":"hòu"},{"c":"我","py":"wǒ"},{"c":"出","py":"chū"},{"c":"汗","py":"hàn"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"。","py":"。"}],"vi":"Sau khi tập thể dục, tôi đổ mồ hôi nhiều."}},{"hanzi":"出版","pinyin":"chūbǎn","hanViet":"XUẤT BẢN","meaning":"xuất bản","pos":"Động từ","example":{"zh":"他出版了一本新书。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"出","py":"chū"},{"c":"版","py":"bǎn"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"本","py":"běn"},{"c":"新","py":"xīn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Anh ấy đã xuất bản một cuốn sách mới."}},{"hanzi":"分离","pinyin":"fēnlí","hanViet":"PHÂN LY","meaning":"tách rời, tách biệt","pos":"Động từ","example":{"zh":"他们分离了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"分","py":"fēn"},{"c":"离","py":"lí"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Họ tách biệt."}},{"hanzi":"分类","pinyin":"fēnlèi","hanViet":"PHÂN LOẠI","meaning":"phân loại","pos":"Động từ","example":{"zh":"请把书分类。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"把","py":"bǎ"},{"c":"书","py":"shū"},{"c":"分","py":"fēn"},{"c":"类","py":"lèi"},{"c":"。","py":"。"}],"vi":"Xin hãy phân loại sách."}},{"hanzi":"划分","pinyin":"huàfēn","hanViet":"HOẠCH PHÂN","meaning":"phân chia","pos":"Động từ","example":{"zh":"我们要划分任务。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"要","py":"yào"},{"c":"划","py":"huà"},{"c":"分","py":"fēn"},{"c":"任","py":"rèn"},{"c":"务","py":"wù"},{"c":"。","py":"。"}],"vi":"Chúng ta cần phân chia nhiệm vụ."}},{"hanzi":"初期","pinyin":"chūqī","hanViet":"SƠ KỲ","meaning":"giai đoạn đầu","pos":"Danh từ","example":{"zh":"项目初期需要很多资金。","pinyinPerChar":[{"c":"项","py":"xiàng"},{"c":"目","py":"mù"},{"c":"初","py":"chū"},{"c":"期","py":"qī"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"资","py":"zī"},{"c":"金","py":"jīn"},{"c":"。","py":"。"}],"vi":"Giai đoạn đầu dự án cần nhiều tiền."}},{"hanzi":"利润","pinyin":"lìrùn","hanViet":"LỢI NHUẬN","meaning":"lợi nhuận","pos":"Danh từ","example":{"zh":"公司赚了利润。","pinyinPerChar":[{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"赚","py":"zhuàn"},{"c":"了","py":"le"},{"c":"利","py":"lì"},{"c":"润","py":"rùn"},{"c":"。","py":"。"}],"vi":"Công ty kiếm được lợi nhuận."}},{"hanzi":"制约","pinyin":"zhìyuē","hanViet":"CHẾ ƯỚC","meaning":"ràng buộc, hạn chế","pos":"Động từ","example":{"zh":"法律制约行为。","pinyinPerChar":[{"c":"法","py":"fǎ"},{"c":"律","py":"lǜ"},{"c":"制","py":"zhì"},{"c":"约","py":"yuē"},{"c":"行","py":"xíng"},{"c":"为","py":"wèi"},{"c":"。","py":"。"}],"vi":"Pháp luật ràng buộc hành vi."}},{"hanzi":"剩","pinyin":"shèng","hanViet":"THẶNG","meaning":"còn lại, thừa","pos":"Động từ","example":{"zh":"还剩多少？","pinyinPerChar":[{"c":"还","py":"hái"},{"c":"剩","py":"shèng"},{"c":"多","py":"duō"},{"c":"少","py":"shǎo"},{"c":"？","py":"？"}],"vi":"Còn lại bao nhiêu?"}},{"hanzi":"剩下","pinyin":"shèngxia","hanViet":"THẶNG HẠ","meaning":"còn lại, phần còn lại","pos":"Danh từ","example":{"zh":"剩下的东西都给我。","pinyinPerChar":[{"c":"剩","py":"shèng"},{"c":"下","py":"xià"},{"c":"的","py":"de"},{"c":"东","py":"dōng"},{"c":"西","py":"xī"},{"c":"都","py":"dōu"},{"c":"给","py":"gěi"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Đồ còn lại cho tôi."}},{"hanzi":"动员","pinyin":"dòngyuán","hanViet":"ĐỘNG VIÊN","meaning":"kêu gọi, huy động, tuyển tập","pos":"Động từ","example":{"zh":"他们动员大家参加活动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"动","py":"dòng"},{"c":"员","py":"yuán"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Họ kêu gọi mọi người tham gia sự kiện."}},{"hanzi":"动态","pinyin":"dòngtài","hanViet":"ĐỘNG THÁI","meaning":"sự thay đổi, động lực, hình ảnh động","pos":"Danh từ","example":{"zh":"这部电影有动态效果。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"部","py":"bù"},{"c":"电","py":"diàn"},{"c":"影","py":"yǐng"},{"c":"有","py":"yǒu"},{"c":"动","py":"dòng"},{"c":"态","py":"tài"},{"c":"效","py":"xiào"},{"c":"果","py":"guǒ"},{"c":"。","py":"。"}],"vi":"Phim này có hiệu ứng động."}},{"hanzi":"助手","pinyin":