INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-34', 33, 'Bổ sung (4)', '[{"hanzi":"勤奋","pinyin":"qínfèn","hanViet":"CẦN PHẤN","meaning":"mạnh mẽ, chăm chỉ","pos":"Tính từ","example":{"zh":"他很勤奋。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"很","py":"hěn"},{"c":"勤","py":"qín"},{"c":"奋","py":"fèn"},{"c":"。","py":"。"}],"vi":"Anh ấy rất chăm chỉ."}},{"hanzi":"包装","pinyin":"bāozhuāng","hanViet":"BAO TRANG","meaning":"gói, bọc, làm đẹp bọc","pos":"Động từ","example":{"zh":"她把礼物包装好。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"把","py":"bǎ"},{"c":"礼","py":"lǐ"},{"c":"物","py":"wù"},{"c":"包","py":"bāo"},{"c":"装","py":"zhuāng"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Cô ấy gói quà cẩn thận."}},{"hanzi":"化石","pinyin":"huàshí","hanViet":"HOÁ THẠCH","meaning":"hóa thạch","pos":"Danh từ","example":{"zh":"这化石很古老。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"化","py":"huà"},{"c":"石","py":"shí"},{"c":"很","py":"hěn"},{"c":"古","py":"gǔ"},{"c":"老","py":"lǎo"},{"c":"。","py":"。"}],"vi":"Hóa thạch này rất cổ."}},{"hanzi":"华语","pinyin":"Huáyǔ","hanViet":"HOA NGỮ","meaning":"tiếng Trung","pos":"Danh từ","example":{"zh":"她会说华语。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"会","py":"huì"},{"c":"说","py":"shuō"},{"c":"华","py":"huá"},{"c":"语","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Cô ấy nói được tiếng Trung."}},{"hanzi":"协议","pinyin":"xiéyì","hanViet":"HIỆP NGHỊ","meaning":"Thỏa thuận, thỏa ước","pos":"Danh từ","example":{"zh":"他们签订了一份协议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"签","py":"qiān"},{"c":"订","py":"dìng"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"份","py":"fèn"},{"c":"协","py":"xié"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Họ đã ký kết một thỏa thuận."}},{"hanzi":"协议书","pinyin":"xiéyìshū","hanViet":"HIỆP NGHỊ THƯ","meaning":"Hợp đồng, văn bản thỏa thuận","pos":"Danh từ","example":{"zh":"双方签署了协议书。","pinyinPerChar":[{"c":"双","py":"shuāng"},{"c":"方","py":"fāng"},{"c":"签","py":"qiān"},{"c":"署","py":"shǔ"},{"c"