pinyinPerChar":[{"c":"即","py":"jí"},{"c":"使","py":"shǐ"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"也","py":"yě"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Dù mưa, chúng ta vẫn đi."}},{"hanzi":"厂长","pinyin":"chǎngzhǎng","hanViet":"XƯỞNG TRƯỞNG","meaning":"giám đốc nhà máy","pos":"Danh từ","example":{"zh":"厂长来了。","pinyinPerChar":[{"c":"厂","py":"chǎng"},{"c":"长","py":"zhǎng"},{"c":"来","py":"lái"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Giám đốc nhà máy đã đến."}},{"hanzi":"厅","pinyin":"tīng","hanViet":"SẢNH","meaning":"phòng, điện, hầm","pos":"Danh từ","example":{"zh":"客厅很大。","pinyinPerChar":[{"c":"客","py":"kè"},{"c":"厅","py":"tīng"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Phòng khách rất lớn."}},{"hanzi":"原先","pinyin":"yuánxiān","hanViet":"NGUYÊN TIÊN","meaning":"trước đây, ban đầu","pos":"Liên từ","example":{"zh":"原先我以为他会来，但他没有。","pinyinPerChar":[{"c":"原","py":"yuán"},{"c":"先","py":"xiān"},{"c":"我","py":"wǒ"},{"c":"以","py":"yǐ"},{"c":"为","py":"wèi"},{"c":"他","py":"tā"},{"c":"会","py":"huì"},{"c":"来","py":"lái"},{"c":"，","py":"，"},{"c":"但","py":"dàn"},{"c":"他","py":"tā"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"。","py":"。"}],"vi":"Tôi từng nghĩ anh ấy sẽ đến, nhưng anh ấy không đến."}},{"hanzi":"原始","pinyin":"yuánshǐ","hanViet":"NGUYÊN THUỶ","meaning":"nguyên thủy, ban đầu","pos":"Tính từ","example":{"zh":"这件文物非常原始。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"文","py":"wén"},{"c":"物","py":"wù"},{"c":"非","py":"fēi"},{"c":"常","py":"cháng"},{"c":"原","py":"yuán"},{"c":"始","py":"shǐ"},{"c":"。","py":"。"}],"vi":"Bộ đồ cổ này rất nguyên thủy."}},{"hanzi":"原有","pinyin":"yuányǒu","hanViet":"NGUYÊN HỮU","meaning":"có sẵn, ban đầu có","pos":"Tính từ","example":{"zh":"房子原有三间。","pinyinPerChar":[{"c":"房","py":"fáng"},{"c":"子","py":"zi"},{"c":"原","py":"yuán"},{"c":"有","py":"yǒu"},{"c":"三","py":"sān"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Nhà cũ c