,"pinyinPerChar":[{"c":"只","py":"zhǐ"},{"c":"见","py":"jiàn"},{"c":"他","py":"tā"},{"c":"走","py":"zǒu"},{"c":"进","py":"jìn"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Chỉ thấy anh ấy bước vào phòng."}},{"hanzi":"可","pinyin":"kě","hanViet":"KHẢ","meaning":"được, có thể, cũng","pos":"Tính từ","example":{"zh":"这件事可行。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"件","py":"jiàn"},{"c":"事","py":"shì"},{"c":"可","py":"kě"},{"c":"行","py":"xíng"},{"c":"。","py":"。"}],"vi":"Việc này có thể thực hiện."}},{"hanzi":"号召","pinyin":"hàozhào","hanViet":"HIỆU TRIỆU","meaning":"kêu gọi, huy động","pos":"Động từ","example":{"zh":"他号召大家参加活动。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"号","py":"hào"},{"c":"召","py":"zhào"},{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"参","py":"cān"},{"c":"加","py":"jiā"},{"c":"活","py":"huó"},{"c":"动","py":"dòng"},{"c":"。","py":"。"}],"vi":"Anh ấy kêu gọi mọi người tham gia hoạt động."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-35', 34, 'Bổ sung (5)', '[{"hanzi":"合并","pinyin":"hébìng","hanViet":"HỢP TỊNH","meaning":"gộp, hợp nhất","pos":"Động từ","example":{"zh":"两家公司合并。","pinyinPerChar":[{"c":"两","py":"liǎng"},{"c":"家","py":"jiā"},{"c":"公","py":"gōng"},{"c":"司","py":"sī"},{"c":"合","py":"hé"},{"c":"并","py":"bìng"},{"c":"。","py":"。"}],"vi":"Hai công ty đã hợp nhất."}},{"hanzi":"吨","pinyin":"dūn","hanViet":"ĐỐN","meaning":"tấn","pos":"Số từ","example":{"zh":"一吨货物。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"吨","py":"dūn"},{"c":"货","py":"huò"},{"c":"物","py":"wù"},{"c":"。","py":"。"}],"vi":"Một tấn hàng hóa."}},{"hanzi":"启动","pinyin":"qǐdòng","hanViet":"KHỞI ĐỘNG","meaning":"bắt đầu, khởi động","pos":"Động từ","example":{"zh":"启动机器。","pinyinPerChar":[{"c":"启","py":"qǐ"},{"c":"动","py":"dòng"},{"c":"机","py":"jī"},{"c":"器","py":"qì"},{"c":"。","py":"。"}],"vi":"Khởi động máy móc."}},{"hanzi":"呆","pinyin":"dāi","hanViet":"NGỐC","meaning":"ngu, lười, đứng im","pos":"Tính từ","example":{"zh":"他呆在家里。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"呆","py":"dāi"},{"c":"在","py":"zài"},{"c":"家","py":"jiā"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Anh ta đứng im ở nhà."}},{"hanzi":"品种","pinyin":"pǐnzhǒng","hanViet":"PHẨM CHỦNG","meaning":"loại, giống","pos":"Danh từ","example":{"zh":"农民种了新品种。","pinyinPerChar":[{"c":"农","py":"nóng"},{"c":"民","py":"mín"},{"c":"种","py":"zhǒng"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"品","py":"pǐn"},{"c":"种","py":"zhǒng"},{"c":"。","py":"。"}],"vi":"Nông dân trồng giống mới."}},{"hanzi":"唯一","pinyin":"wéiyī","hanViet":"DUY NHẤT","meaning":"duy nhất, chỉ có một","pos":"Tính từ","example":{"zh":"这是唯一的办法。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"唯","py":"wéi"},{"c":"一","py":"yī"},{"c":"的","py":"de"},{"c":"办","py":"bàn"},{"c":"法","py":"fǎ"},{"c":"。","py":"。"}],"vi":"Đây là cách giải quyết duy nhất."}},{"hanzi":"喷","pinyin":"pēn","hanViet":"PHUN","meaning":