INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-36', 35, 'Bổ sung (6)', '[{"hanzi":"女性","pinyin":"nǚxìng","hanViet":"TÍNH","meaning":"phụ nữ, giới nữ","pos":"Danh từ","example":{"zh":"女性在职场越来越重要。","pinyinPerChar":[{"c":"女","py":"nǚ"},{"c":"性","py":"xìng"},{"c":"在","py":"zài"},{"c":"职","py":"zhí"},{"c":"场","py":"chǎng"},{"c":"越","py":"yuè"},{"c":"来","py":"lái"},{"c":"越","py":"yuè"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Phụ nữ trong môi trường làm việc ngày càng quan trọng."}},{"hanzi":"如下","pinyin":"rúxià","hanViet":"NHƯ HẠ","meaning":"dưới đây","pos":"Liên từ","example":{"zh":"内容如下。","pinyinPerChar":[{"c":"内","py":"nèi"},{"c":"容","py":"róng"},{"c":"如","py":"rú"},{"c":"下","py":"xià"},{"c":"。","py":"。"}],"vi":"Nội dung như sau."}},{"hanzi":"如此","pinyin":"rúcǐ","hanViet":"NHƯ THỬ","meaning":"như vậy, thế này","pos":"Phó từ","example":{"zh":"问题如此严重。","pinyinPerChar":[{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"如","py":"rú"},{"c":"此","py":"cǐ"},{"c":"严","py":"yán"},{"c":"重","py":"zhòng"},{"c":"。","py":"。"}],"vi":"Vấn đề vậy nghiêm trọng."}},{"hanzi":"委托","pinyin":"wěituō","hanViet":"UỶ THÁC","meaning":"ủy thác, nhờ","pos":"Động từ","example":{"zh":"我委托他帮我办事。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"委","py":"wěi"},{"c":"托","py":"tuō"},{"c":"他","py":"tā"},{"c":"帮","py":"bāng"},{"c":"我","py":"wǒ"},{"c":"办","py":"bàn"},{"c":"事","py":"shì"},{"c":"。","py":"。"}],"vi":"Tôi nhờ anh ta giúp việc cho tôi."}},{"hanzi":"子弹","pinyin":"zǐdàn","hanViet":"TỬ ĐẠN","meaning":"đạn, viên đạn","pos":"Danh từ","example":{"zh":"枪里装满了子弹。","pinyinPerChar":[{"c":"枪","py":"qiāng"},{"c":"里","py":"lǐ"},{"c":"装","py":"zhuāng"},{"c":"满","py":"mǎn"},{"c":"了","py":"le"},{"c":"子","py":"zi"},{"c":"弹","py":"dàn"},{"c":"。","py":"。"}],"vi":"Nỏ đã đầy đạn."}},{"hanzi":"学位","pinyin":"xuéwèi","hanViet":"HỌC VỊ","meaning":"bằng cấp học thuật; trình độ học vấn","pos":"Danh từ","example":{"zh":"他获得了硕士学位。","pinyinPerChar":[{"c":"他