INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-39', 38, 'Bổ sung (9)', '[{"hanzi":"更换","pinyin":"gēnghuàn","hanViet":"CÀNG HOÁN","meaning":"thay, đổi","pos":"Động từ","example":{"zh":"他更换了新衣服。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"更","py":"gèng"},{"c":"换","py":"huàn"},{"c":"了","py":"le"},{"c":"新","py":"xīn"},{"c":"衣","py":"yī"},{"c":"服","py":"fú"},{"c":"。","py":"。"}],"vi":"Anh ấy đã thay áo mới."}},{"hanzi":"更新","pinyin":"gēngxīn","hanViet":"CÀNG TÂN","meaning":"cập nhật, làm mới","pos":"Động từ","example":{"zh":"网站需要更新信息。","pinyinPerChar":[{"c":"网","py":"wǎng"},{"c":"站","py":"zhàn"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"更","py":"gèng"},{"c":"新","py":"xīn"},{"c":"信","py":"xìn"},{"c":"息","py":"xī"},{"c":"。","py":"。"}],"vi":"Trang web cần cập nhật thông tin."}},{"hanzi":"有力","pinyin":"yǒulì","hanViet":"HỮU LỰC","meaning":"mạnh mẽ, có sức","pos":"Tính từ","example":{"zh":"他给了我一个有力的建议。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"给","py":"gěi"},{"c":"了","py":"le"},{"c":"我","py":"wǒ"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"有","py":"yǒu"},{"c":"力","py":"lì"},{"c":"的","py":"de"},{"c":"建","py":"jiàn"},{"c":"议","py":"yì"},{"c":"。","py":"。"}],"vi":"Anh ấy đưa ra một đề xuất mạnh mẽ."}},{"hanzi":"有害","pinyin":"yǒu hài","hanViet":"HỮU HẠI","meaning":"có hại","pos":"Tính từ","example":{"zh":"吸烟对健康有害。","pinyinPerChar":[{"c":"吸","py":"xī"},{"c":"烟","py":"yān"},{"c":"对","py":"duì"},{"c":"健","py":"jiàn"},{"c":"康","py":"kāng"},{"c":"有","py":"yǒu"},{"c":"害","py":"hài"},{"c":"。","py":"。"}],"vi":"Hút thuốc có hại cho sức khỏe."}},{"hanzi":"有毒","pinyin":"yǒu dú","hanViet":"HỮU ĐỘC","meaning":"có độc","pos":"Tính từ","example":{"zh":"这种植物有毒，不能吃。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"种","py":"zhǒng"},{"c":"植","py":"zhí"},{"c":"物","py":"wù"},{"c":"有","py":"yǒu"},{"c":"毒","py":"dú"},{"c":"，","py":"，"},{"c":"不","py":"bù"},{"c":"能","py":"néng"},{"c":"吃","py":"chī"},{"c":"。","py":"。"}],"vi":"Thực vật này có độc, không