INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-40', 39, 'Bổ sung (10)', '[{"hanzi":"消极","pinyin":"xiāojí","hanViet":"TIÊU CỰC","meaning":"thụ động, bi quan","pos":"Tính từ","example":{"zh":"他对工作很消极。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"对","py":"duì"},{"c":"工","py":"gōng"},{"c":"作","py":"zuò"},{"c":"很","py":"hěn"},{"c":"消","py":"xiāo"},{"c":"极","py":"jí"},{"c":"。","py":"。"}],"vi":"Anh ấy đối với công việc rất thụ động."}},{"hanzi":"消毒","pinyin":"xiāodú","hanViet":"TIÊU ĐỘC","meaning":"tiêu diệt vi khuẩn, khử trùng","pos":"Động từ","example":{"zh":"医生消毒伤口。","pinyinPerChar":[{"c":"医","py":"yī"},{"c":"生","py":"shēng"},{"c":"消","py":"xiāo"},{"c":"毒","py":"dú"},{"c":"伤","py":"shāng"},{"c":"口","py":"kǒu"},{"c":"。","py":"。"}],"vi":"Bác sĩ khử trùng vết thương."}},{"hanzi":"消费者","pinyin":"xiāofèizhě","hanViet":"TIÊU PHÍ GIẢ","meaning":"người tiêu dùng","pos":"Danh từ","example":{"zh":"消费者需要好产品。","pinyinPerChar":[{"c":"消","py":"xiāo"},{"c":"费","py":"fèi"},{"c":"者","py":"zhě"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"好","py":"hǎo"},{"c":"产","py":"chǎn"},{"c":"品","py":"pǐn"},{"c":"。","py":"。"}],"vi":"Người tiêu dùng cần sản phẩm tốt."}},{"hanzi":"消防","pinyin":"xiāofáng","hanViet":"TIÊU PHÒNG","meaning":"chống cháy, cứu hỏa","pos":"Danh từ","example":{"zh":"消防队救了很多人。","pinyinPerChar":[{"c":"消","py":"xiāo"},{"c":"防","py":"fáng"},{"c":"队","py":"duì"},{"c":"救","py":"jiù"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"人","py":"rén"},{"c":"。","py":"。"}],"vi":"Đội cứu hỏa cứu được nhiều người."}},{"hanzi":"深处","pinyin":"shēnchù","hanViet":"THÂM XỨ","meaning":"vị trí sâu, nơi ở sâu","pos":"Danh từ","example":{"zh":"我们走到深处。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"走","py":"zǒu"},{"c":"到","py":"dào"},{"c":"深","py":"shēn"},{"c":"处","py":"chù"},{"c":"。","py":"。"}],"vi":"Chúng tôi đi đến nơi sâu."}},{"hanzi":"深度","pinyin":"shēndù","hanViet":"THÂM ĐỘ","meaning":"mức độ sâu, độ sâu","p