ar":[{"c":"这","py":"zhè"},{"c":"场","py":"chǎng"},{"c":"灾","py":"zāi"},{"c":"害","py":"hài"},{"c":"很","py":"hěn"},{"c":"严","py":"yán"},{"c":"重","py":"zhòng"},{"c":"。","py":"。"}],"vi":"Tình huống thảm họa này rất nghiêm trọng."}},{"hanzi":"灾区","pinyin":"zāiqū","hanViet":"TAI KHU","meaning":"vùng thảm họa","pos":"Danh từ","example":{"zh":"救援队去灾区。","pinyinPerChar":[{"c":"救","py":"jiù"},{"c":"援","py":"yuán"},{"c":"队","py":"duì"},{"c":"去","py":"qù"},{"c":"灾","py":"zāi"},{"c":"区","py":"qū"},{"c":"。","py":"。"}],"vi":"Đội cứu trợ đi vùng thảm họa."}},{"hanzi":"灾害","pinyin":"zāihài","hanViet":"TAI HẠI","meaning":"thảm họa","pos":"Danh từ","example":{"zh":"地震是自然灾害。","pinyinPerChar":[{"c":"地","py":"dì"},{"c":"震","py":"zhèn"},{"c":"是","py":"shì"},{"c":"自","py":"zì"},{"c":"然","py":"rán"},{"c":"灾","py":"zāi"},{"c":"害","py":"hài"},{"c":"。","py":"。"}],"vi":"Động đất là thiên tai."}},{"hanzi":"烂","pinyin":"làn","hanViet":"LẠN","meaning":"hư, xấu","pos":"Tính từ","example":{"zh":"这个苹果烂了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"苹","py":"píng"},{"c":"果","py":"guǒ"},{"c":"烂","py":"làn"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Quả táo này hư."}},{"hanzi":"煤","pinyin":"méi","hanViet":"MÔI","meaning":"than","pos":"Danh từ","example":{"zh":"煤可以取暖。","pinyinPerChar":[{"c":"煤","py":"méi"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"取","py":"qǔ"},{"c":"暖","py":"nuǎn"},{"c":"。","py":"。"}],"vi":"Than có thể dùng để sưởi ấm."}},{"hanzi":"熊","pinyin":"xióng","hanViet":"HÙNG","meaning":"Gấu","pos":"Danh từ","example":{"zh":"熊很可爱。","pinyinPerChar":[{"c":"熊","py":"xióng"},{"c":"很","py":"hěn"},{"c":"可","py":"kě"},{"c":"爱","py":"ài"},{"c":"。","py":"。"}],"vi":"Gấu rất đáng yêu."}},{"hanzi":"版","pinyin":"bǎn","hanViet":"BẢN","meaning":"mặt in, phiên bản, bản","pos":"Danh từ","example":{"zh":"这本书的版很新。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"的","py":"de"},{"c":"版","py":"bǎn"},{"c":"很","py":"hěn"},{"c":"新","py":"xīn"},{"c":"。","py":"。"}],"vi":"Phiên bản của cuốn sách này rất mới."}},{"hanzi":"物业","pinyin":"wùyè","hanViet":"VẬT NGHIỆP","meaning":"dịch vụ và tài sản thuộc sở hữu của người khác, thường là chung cư","pos":"Danh từ","example":{"zh":"物业管理很重要。","pinyinPerChar":[{"c":"物","py":"wù"},{"c":"业","py":"yè"},{"c":"管","py":"guǎn"},{"c":"理","py":"lǐ"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Việc quản lý nhà chung cư rất quan trọng."}},{"hanzi":"物质","pinyin":"wùzhì","hanViet":"VẬT CHẤT","meaning":"vật chất, vật thể; vật chất","pos":"Danh từ","example":{"zh":"他追求物质生活。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"追","py":"zhuī"},{"c":"求","py":"qiú"},{"c":"物","py":"wù"},{"c":"质","py":"zhì"},{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"。","py":"。"}],"vi":"Anh ta theo đuổi cuộc sống vật chất."}},{"hanzi":"特性","pinyin":"tèxìng","hanViet":"ĐẶC TÍNH","meaning":"đặc tính, tính chất","pos":"Danh từ","example":{"zh":"这款手机有很多特性。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"款","py":"kuǎn"},{"c":"手","py":"shǒu"},{"c":"机","py":"jī"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"特","py":"tè"},{"c":"性","py":"xìng"},{"c":"。","py":"。"}],"vi":"Mô hình điện thoại này có nhiều tính năng."}},{"hanzi":"犹豫","pinyin":"yóuyù","hanViet":"DO DỰ","meaning":"do dự, ngần ngại","pos":"Động từ","example":{"zh":"他犹豫了一下才决定去。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"犹","py":"yóu"},{"c":"豫","py":"yù"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"下","py":"xià"},{"c":"才","py":"cái"},{"c":"决","py":"jué"},{"c":"定","py":"dìng"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Anh ấy do dự một chút rồi mới quyết định đi."}},{"hanzi":"献","pinyin":"xiàn","hanViet":"HIẾN","meaning":"tặng, cống hiến","pos":"Động từ","example":{"zh":"他想献出自己的钱。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"想","py":"xiǎng"},{"c":"献","py":"xiàn"},{"c":"出","py":"chū"},{"c":"自","py":"zì"},{"c":"己","py":"jǐ"},{"c":"的","py":"de"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Anh ấy muốn cống hiến tiền của mình."}},{"hanzi":"猴","pinyin":"hóu","hanViet":"HẦU","meaning":"con khỉ","pos":"Danh từ","example":{"zh":"猴子会爬树。","pinyinPerChar":[{"c":"猴","py":"hóu"},{"c":"子","py":"zi"},{"c":"会","py":"huì"},{"c":"爬","py":"pá"},{"c":"树","py":"shù"},{"c":"。","py":"。"}],"vi":"Con khỉ có thể leo cây."}},{"hanzi":"环节","pinyin":"huánjié","hanViet":"HOÀN TIẾT","meaning":"phần, khâu","pos":"Danh từ","example":{"zh":"这个环节很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"环","py":"huán"},{"c":"节","py":"jié"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Khâu này rất quan trọng."}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-41', 40, 'Bổ sung (11)', '[{"hanzi":"现有","pinyin":"xiànyǒu","hanViet":"HIỆN HỮU","meaning":"hiện có, đang có","pos":"Tính từ","example":{"zh":"现有数量不够。","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"有","py":"yǒu"},{"c":"数","py":"shù"},{"c":"量","py":"liàng"},{"c":"不","py":"bù"},{"c":"够","py":"gòu"},{"c":"。","py":"。"}],"vi":"Số lượng hiện có không đủ."}},{"hanzi":"玻璃","pinyin":"bōli","hanViet":"PHA LY","meaning":"kính","pos":"Danh từ","example":{"zh":"窗户是玻璃的。","pinyinPerChar":[{"c":"窗","py":"chuāng"},{"c":"户","py":"hù"},{"c":"是","py":"shì"},{"c":"玻","py":"bō"},{"c":"璃","py":"lí"},{"c":"的","py":"de"},{"c":"。","py":"。"}],"vi":"Cửa sổ làm bằng kính."}},{"hanzi":"用户","pinyin":"yònghù","hanViet":"DỤNG HỘ","meaning":"người dùng","pos":"Danh từ","example":{"zh":"这个网站很受用户欢迎。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"网","py":"wǎng"},{"c":"站","py":"zhàn"},{"c":"很","py":"hěn"},{"c":"受","py":"shòu"},{"c":"用","py":"yòng"},{"c":"户","py":"hù"},{"c":"欢","py":"huān"},{"c":"迎","py":"yíng"},{"c":"。","py":"。"}],"vi":"Trang web này rất được người dùng yêu thích."}},{"hanzi":"由此","pinyin":"yóu cǐ","hanViet":"DO THỬ","meaning":"từ đây, từ đó","pos":"Liên từ","example":{"zh":"由此我们可以看到问题的关键。","pinyinPerChar":[{"c":"由","py":"yóu"},{"c":"此","py":"cǐ"},{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"可","py":"kě"},{"c":"以","py":"yǐ"},{"c":"看","py":"kàn"},{"c":"到","py":"dào"},{"c":"问","py":"wèn"},{"c":"题","py":"tí"},{"c":"的","py":"de"},{"c":"关","py":"guān"},{"c":"键","py":"jiàn"},{"c":"。","py":"。"}],"vi":"Từ đây ta có thể thấy được điểm mấu chốt của vấn đề."}},{"hanzi":"甲","pinyin":"jiǎ","hanViet":"GIÁP","meaning":"mặt trước, thứ nhất, lệnh","pos":"Tính từ","example":{"zh":"甲方负责。","pinyinPerChar":[{"c":"甲","py":"jiǎ"},{"c":"方","py":"fāng"},{"c":"负","py":"fù"},{"c":"责","py":"zé"},{"c":"。","py":"。"}],"vi":"Bên A chịu trách nhiệm."}},{"hanzi":"电子版","pinyin":"diànzǐbǎn","hanViet":"ĐIỆN T