INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-42', 41, 'Bổ sung (12)', '[{"hanzi":"签证","pinyin":"qiānzhèng","hanViet":"THIÊM CHỨNG","meaning":"giấy ủy thác, visa","pos":"Danh từ","example":{"zh":"他需要签证去国外。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"需","py":"xū"},{"c":"要","py":"yào"},{"c":"签","py":"qiān"},{"c":"证","py":"zhèng"},{"c":"去","py":"qù"},{"c":"国","py":"guó"},{"c":"外","py":"wài"},{"c":"。","py":"。"}],"vi":"Anh ấy cần visa để đi nước ngoài."}},{"hanzi":"糟","pinyin":"zāo","hanViet":"TAO","meaning":"tệ, thất bại","pos":"Tính từ","example":{"zh":"天气糟糕。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"糟","py":"zāo"},{"c":"糕","py":"gāo"},{"c":"。","py":"。"}],"vi":"Thời tiết tệ."}},{"hanzi":"糟糕","pinyin":"zāogāo","hanViet":"TAO CAO","meaning":"tệ, khủng khiếp","pos":"Tính từ","example":{"zh":"天气糟糕，今天下雨了。","pinyinPerChar":[{"c":"天","py":"tiān"},{"c":"气","py":"qì"},{"c":"糟","py":"zāo"},{"c":"糕","py":"gāo"},{"c":"，","py":"，"},{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Thời tiết tệ, hôm nay mưa."}},{"hanzi":"紧紧","pinyin":"jǐnjǐn","hanViet":"KHẨN KHẨN","meaning":"chặt chẽ, gắn bó","pos":"Phó từ","example":{"zh":"她紧紧握住手。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"紧","py":"jǐn"},{"c":"紧","py":"jǐn"},{"c":"握","py":"wò"},{"c":"住","py":"zhù"},{"c":"手","py":"shǒu"},{"c":"。","py":"。"}],"vi":"Cô ấy chặt chẽ nắm lấy tay."}},{"hanzi":"约束","pinyin":"yuēshù","hanViet":"ƯỚC THÚC","meaning":"ràng buộc, giới hạn","pos":"Danh từ","example":{"zh":"这条规则有很多约束。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"条","py":"tiáo"},{"c":"规","py":"guī"},{"c":"则","py":"zé"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"约","py":"yuē"},{"c":"束","py":"shù"},{"c":"。","py":"。"}],"vi":"Quy tắc này có nhiều ràng buộc."}},{"hanzi":"线索","pinyin":"xiànsuǒ","hanViet":"TUYẾN SÁCH","meaning":"dấu chỉ, manh mối","pos":"Danh từ","example":{"z