INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-44', 43, 'Bổ sung (14)', '[{"hanzi":"道德","pinyin":"dàodé","hanViet":"ĐẠO ĐỨC","meaning":"đạo đức","pos":"Danh từ","example":{"zh":"他有很好的道德品质。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"的","py":"de"},{"c":"道","py":"dào"},{"c":"德","py":"dé"},{"c":"品","py":"pǐn"},{"c":"质","py":"zhì"},{"c":"。","py":"。"}],"vi":"Anh ấy có phẩm chất đạo đức tốt."}},{"hanzi":"邀请","pinyin":"yāoqǐng","hanViet":"YÊU THỈNH","meaning":"mời; mời gọi","pos":"Động từ","example":{"zh":"我邀请你吃饭。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"邀","py":"yāo"},{"c":"请","py":"qǐng"},{"c":"你","py":"nǐ"},{"c":"吃","py":"chī"},{"c":"饭","py":"fàn"},{"c":"。","py":"。"}],"vi":"Tôi mời bạn ăn cơm."}},{"hanzi":"部位","pinyin":"bùwèi","hanViet":"BỘ VỊ","meaning":"vị trí, bộ phận","pos":"Danh từ","example":{"zh":"这个部位很重要。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"部","py":"bù"},{"c":"位","py":"wèi"},{"c":"很","py":"hěn"},{"c":"重","py":"zhòng"},{"c":"要","py":"yào"},{"c":"。","py":"。"}],"vi":"Vị trí này rất quan trọng."}},{"hanzi":"醉","pinyin":"zuì","hanViet":"TUÝ","meaning":"say, say đắm","pos":"Tính từ","example":{"zh":"他醉了。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"醉","py":"zuì"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Anh ấy say rồi."}},{"hanzi":"锁","pinyin":"suǒ","hanViet":"TOẢ","meaning":"khóa, chốt","pos":"Động từ","example":{"zh":"请锁门。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"锁","py":"suǒ"},{"c":"门","py":"mén"},{"c":"。","py":"。"}],"vi":"Vui lòng khóa cửa."}},{"hanzi":"闯","pinyin":"chuǎng","hanViet":"SẤM","meaning":"xâm nhập, làm mất trật tự","pos":"Động từ","example":{"zh":"他闯进了房间。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"闯","py":"chuǎng"},{"c":"进","py":"jìn"},{"c":"了","py":"le"},{"c":"房","py":"fáng"},{"c":"间","py":"jiān"},{"c":"。","py":"。"}],"vi":"Anh ấy xâm nhập vào phòng."}},{"hanzi":"阅览室","pinyin":"yuèlǎnshì","hanViet":"